import type { CausalLink, CausalPath } from "./causal.js";
import type { EntityRef, EntityType, EpistemicPrincipalRef } from "./entity.js";
import type { EvidenceSpan } from "./evidence.js";
import type { NarraMemId } from "./ids.js";
import type { FutureImpact, NarrativeThread } from "./narrative.js";
import type { EpistemicState, Proposition } from "./perspective.js";
import type { StateAssertion } from "./state.js";
import type { SourceOrder, TemporalExtent } from "./time.js";

export type RecallPurpose = "continuation" | "npc_decision" | "qa" | "audit" | "reconstruction";

export type RecallCheckpoint =
  | { readonly kind: "source_order"; readonly value: SourceOrder }
  | { readonly kind: "game_tick"; readonly value: number };

export type PerspectiveScope =
  | {
      readonly kind: "principal";
      readonly principal: EpistemicPrincipalRef;
      readonly consumer: "character_generation" | "narrator_generation";
    }
  | {
      readonly kind: "objective";
      readonly consumer: "rules_engine" | "audit";
    };

export interface UntrustedSceneInput {
  readonly trust_boundary: "untrusted_evidence";
  readonly content: string;
}

export interface CurrentSceneContext {
  readonly raw_input?: UntrustedSceneInput;
  readonly participant_ids: readonly EntityRef[];
  /** Objects explicitly identified by the host; never inferred from raw_input keywords. */
  readonly object_ids?: readonly EntityRef[];
  readonly focalizer_id?: EntityRef;
  readonly location_id?: EntityRef;
  readonly story_time?: TemporalExtent;
  readonly perceived_event_refs?: readonly NarraMemId<"event">[];
}

export interface RecallQuery {
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly checkpoint: RecallCheckpoint;
  readonly purpose: RecallPurpose;
  readonly current_scene: CurrentSceneContext;
  readonly requested_perspective: PerspectiveScope;
  readonly task_goals?: readonly string[];
  readonly token_budget: number;
  readonly latency_budget_ms?: number;
  readonly max_agent_steps?: number;
}

export interface EpisodeExcerpt {
  readonly episode_id: NarraMemId<"episode">;
  readonly title: string;
  readonly reconstruction_gist: string;
  readonly event_refs: readonly NarraMemId<"event">[];
  readonly evidence: readonly EvidenceSpan[];
}

/** Minimal Entity labels that are safe for the requested Recall perspective. */
export interface RecallEntityContext {
  readonly entity_id: EntityRef;
  readonly entity_type: EntityType;
  readonly labels: readonly string[];
}

export interface ContradictionNotice {
  readonly code: string;
  readonly record_refs: readonly NarraMemId[];
  readonly description: string;
}

export interface EvidenceGap {
  readonly code: string;
  readonly about_refs: readonly NarraMemId[];
  readonly description: string;
}

export interface RecallBundle {
  readonly delivery: "consumer_safe";
  readonly bundle_id: NarraMemId<"recall_bundle">;
  readonly based_on_revision_id: NarraMemId<"source_revision">;
  readonly perspective: PerspectiveScope;
  /** ID-to-label context for Entity references already selected into this consumer-safe Bundle. */
  readonly perspective_safe_entities?: readonly RecallEntityContext[];
  readonly current_constraints: readonly StateAssertion[];
  readonly perspective_safe_beliefs: readonly EpistemicState[];
  readonly perspective_safe_uncertainties: readonly EpistemicState[];
  /** Consumer-safe claims referenced by the selected EpistemicState records. */
  readonly perspective_safe_propositions?: readonly Proposition[];
  readonly immediate_context: readonly EpisodeExcerpt[];
  readonly causal_antecedents: readonly CausalPath[];
  /** Consumer-safe CausalLink payloads referenced by causal_antecedents. */
  readonly causal_details?: readonly CausalLink[];
  readonly experience_echoes: readonly EpisodeExcerpt[];
  readonly active_threads: readonly NarrativeThread[];
  readonly matched_impacts: readonly FutureImpact[];
  readonly visible_contradictions: readonly ContradictionNotice[];
  readonly visible_evidence_gaps: readonly EvidenceGap[];
}

export const RECALL_BUNDLE_SELECTION_SECTIONS = [
  "current_constraints",
  "perspective_safe_beliefs",
  "perspective_safe_uncertainties",
  "immediate_context",
  "causal_antecedents",
  "experience_echoes",
  "active_threads",
  "matched_impacts",
  "visible_contradictions",
  "visible_evidence_gaps",
] as const;

export type RecallBundleSelectionSection = (typeof RECALL_BUNDLE_SELECTION_SECTIONS)[number];

export interface RecallBundleSelection {
  readonly section: RecallBundleSelectionSection;
  readonly index: number;
}

export type RecallGoalCoverage = "supported" | "partial" | "unsupported";

export interface RecallGoalSelection {
  readonly goal_index: number;
  readonly coverage: RecallGoalCoverage;
  readonly selections: readonly RecallBundleSelection[];
}

/**
 * Untrusted, selection-only proposal. It cannot carry free-form facts, private Trace data, or writes.
 */
export interface RecallConsumptionProposal {
  readonly schema_version: "0.1.0";
  readonly delivery: "executor_private_selection_proposal";
  readonly producer: "deterministic" | "llm" | "agent" | "hybrid";
  readonly bundle_id: NarraMemId<"recall_bundle">;
  readonly based_on_revision_id: NarraMemId<"source_revision">;
  readonly goal_count: number;
  readonly goal_selections: readonly RecallGoalSelection[];
}

/** Ephemeral consumer-safe selection plan. It is never a memory record and cannot mutate state. */
export interface RecallConsumptionPlan {
  readonly schema_version: "0.1.0";
  readonly delivery: "consumer_safe_ephemeral_selection_plan";
  readonly bundle_id: NarraMemId<"recall_bundle">;
  readonly based_on_revision_id: NarraMemId<"source_revision">;
  readonly goal_count: number;
  readonly goal_selections: readonly RecallGoalSelection[];
  readonly persistent_state_unchanged: true;
}

export interface SupportPath {
  readonly target_ref: NarraMemId;
  readonly evidence_refs: readonly NarraMemId<"evidence">[];
  readonly dependency_refs: readonly NarraMemId[];
  readonly causal_link_refs: readonly NarraMemId<"causal_link">[];
}

export const REJECTION_REASONS = [
  "wrong_memory_space",
  "wrong_branch",
  "after_checkpoint",
  "stale_revision",
  "invalidated_dependency",
  "perspective_hidden",
  "unsupported",
  "contradicted",
  "low_relevance",
  "duplicate",
  "pollution_budget",
] as const;

export type RejectionReasonCode = (typeof REJECTION_REASONS)[number];

export interface RecallRejection {
  readonly record_id: NarraMemId;
  readonly reason: RejectionReasonCode;
}

export interface RecallTrace {
  readonly delivery: "executor_private_never_render";
  readonly trace_id: NarraMemId<"recall_trace">;
  readonly bundle_id: NarraMemId<"recall_bundle">;
  readonly support_paths: readonly SupportPath[];
  readonly withheld_record_ids: readonly NarraMemId[];
  readonly rejection_reasons: readonly RecallRejection[];
  readonly private_contradictions: readonly ContradictionNotice[];
  readonly unsupported_gaps: readonly EvidenceGap[];
  readonly assembly_stats: {
    readonly token_count: number;
    readonly candidates_seen: number;
    readonly records_included: number;
    readonly agent_steps: number;
    readonly stop_reason: string;
  };
}
