import type {
  NarrativeExtractionCandidateBatch,
  NarrativeIncrementalExtractionCandidateBatch,
} from "@narramem/core-domain";
import type { NarrativeIncrementalExtractionStage } from "@narramem/core-validator";

import type { TavernGenerationParameters } from "./contracts.js";
import type { TavernExtractionResponseQualityAudit } from "./extraction-quality-contracts.js";
import type {
  TavernIncrementalSemanticCommitResult,
  TavernPrepareExtractionRequest,
  TavernPrepareIncrementalExtractionRequest,
  TavernSemanticCommitResult,
} from "./semantic-archive-contracts.js";

export const TAVERN_EXTRACTION_JOB_VERSION = "0.9.0" as const;
export const TAVERN_EXTRACTION_MODEL_ADAPTER_VERSION = "0.5.0" as const;
export const TAVERN_INCREMENTAL_EXTRACTION_MODEL_ADAPTER_VERSION = "0.1.0" as const;

export type TavernExtractionModelFamily = "gemini-3.1-pro-preview" | "mimo-v2.5-pro" | "kimi-k3";

export type TavernExtractionOutputStrategy =
  | "canonical_candidate_v030"
  | "flat_draft_v010_quarantine_v020"
  | "incremental_candidate_v010";

export type TavernExtractionOutputSchema =
  | "narrative_extraction_candidate_batch_v030"
  | "flat_narrative_extraction_draft";

export type TavernIncrementalExtractionOutputSchema =
  "narrative_incremental_extraction_candidate_batch";

export type TavernRuntimePromptInputSchema =
  | "narrative_extraction_model_input"
  | "narrative_incremental_extraction_model_input"
  | "flat_narrative_lifecycle_model_input"
  | "flat_narrative_lifecycle_model_input_v020";

export type TavernRuntimePromptOutputSchema =
  | TavernExtractionOutputSchema
  | TavernIncrementalExtractionOutputSchema
  | "flat_narrative_lifecycle_draft"
  | "flat_narrative_lifecycle_draft_v020";

interface TavernExtractionModelAdapterBase {
  readonly adapter_version: typeof TAVERN_EXTRACTION_MODEL_ADAPTER_VERSION;
  readonly adapter_id: string;
  readonly family: TavernExtractionModelFamily;
  readonly prompt_asset_ref: string;
  readonly prompt_body_sha256: string;
  readonly request_parameters: TavernGenerationParameters;
  readonly status: "candidate";
}

export type TavernExtractionModelAdapter = TavernExtractionModelAdapterBase &
  (
    | {
        readonly output_strategy: "canonical_candidate_v030";
        readonly output_schema: "narrative_extraction_candidate_batch_v030";
      }
    | {
        readonly output_strategy: "flat_draft_v010_quarantine_v020";
        readonly output_schema: "flat_narrative_extraction_draft";
      }
  );

export interface TavernIncrementalExtractionModelAdapter {
  readonly adapter_version: typeof TAVERN_INCREMENTAL_EXTRACTION_MODEL_ADAPTER_VERSION;
  readonly adapter_id: string;
  readonly family: TavernExtractionModelFamily;
  readonly prompt_asset_ref: string;
  readonly prompt_body_sha256: string;
  readonly request_parameters: TavernGenerationParameters;
  readonly output_strategy: "incremental_candidate_v010";
  readonly output_schema: TavernIncrementalExtractionOutputSchema;
  readonly status: "candidate";
}

/** Browser-ready asset emitted by the build from one registered Markdown body. */
export interface TavernRuntimePromptAsset {
  readonly prompt_asset_ref: string;
  readonly prompt_id: string;
  readonly semantic_version: string;
  readonly status: "candidate" | "active";
  readonly body: string;
  readonly body_sha256: string;
  readonly message_role: "system";
  readonly position: "independent_model_call.system";
  readonly variables: readonly [];
  readonly input_schema: TavernRuntimePromptInputSchema;
  readonly output_schema: TavernRuntimePromptOutputSchema;
  readonly provider_scope: `model-family:${TavernExtractionModelFamily}`;
}

export interface TavernExtractionResponseRecoveryConfig {
  readonly continuation_max_calls: number;
  readonly continuation_prompt_asset_ref: string;
  readonly continuation_prompt_body: string;
  readonly schema_repair_max_calls: number;
  readonly schema_repair_prompt_asset_ref: string;
  readonly schema_repair_prompt_body: string;
  readonly schema_repair_output_prompt_asset_ref: string;
  readonly schema_repair_output_prompt_body: string;
}

export interface TavernSemanticStagePromptAsset {
  readonly stage: NarrativeIncrementalExtractionStage;
  readonly prompt_asset_ref: string;
  readonly prompt_body: string;
  readonly prompt_body_sha256: string;
}

export interface TavernIncrementalPartitionAudit {
  readonly partition_version: "0.1.0";
  readonly total_record_count: number;
  readonly accepted_record_count: number;
  readonly quarantined_record_count: number;
  readonly repaired_record_count: number;
  readonly quarantine: readonly {
    readonly kind: string;
    readonly target_key: string;
    readonly diagnostic_codes: readonly string[];
    readonly diagnostic_paths: readonly string[];
  }[];
}

interface TavernExtractionJobRequestBase {
  readonly job_id: string;
  /** Optional safe token that creates a new durable user-requested attempt round. */
  readonly retry_round_id?: string;
  readonly requested_model_id: string;
  readonly proxy_preset?: string;
  readonly runtime_prompt_assets: readonly TavernRuntimePromptAsset[];
  /** Four registered final-user Prompts enable semantic staging for incremental extraction. */
  readonly semantic_stage_prompt_assets?: readonly TavernSemanticStagePromptAsset[];
  readonly allow_candidate_prompt: boolean;
  /** Exact-source recovery budget. Only deterministic response rejection may consume another attempt. */
  readonly max_attempts: number;
  readonly response_recovery?: TavernExtractionResponseRecoveryConfig;
  /**
   * One-shot, user-explicit authorization to continue an identical durable task
   * whose last dispatched attempt is known to have been cancelled. Cold starts
   * and ordinary observer events must omit this field.
   */
  readonly cancelled_attempt_recovery?: "explicit_runtime_rearm";
  readonly compiled_at: string;
  readonly writer_id: string;
  readonly build_id: string;
}

export type TavernExtractionJobRequest = TavernExtractionJobRequestBase &
  (
    | {
        /** Frozen full-chat path retained for replay; product Observer uses incremental. */
        readonly mode?: "full";
        readonly prepare: TavernPrepareExtractionRequest;
      }
    | {
        readonly mode: "incremental";
        readonly prepare: TavernPrepareIncrementalExtractionRequest;
      }
  );

export interface TavernExtractionJobAudit {
  readonly job_version: typeof TAVERN_EXTRACTION_JOB_VERSION;
  readonly job_id: string;
  readonly adapter_id: string;
  readonly requested_model_id: string;
  readonly model_identity_assurance: "requested_not_attested";
  readonly prompt_asset_ref: string;
  readonly prompt_body_sha256: string;
  readonly output_strategy: TavernExtractionOutputStrategy;
  readonly output_schema: TavernExtractionOutputSchema | TavernIncrementalExtractionOutputSchema;
  readonly parameters_sha256: string;
  readonly max_attempts: number;
}

export interface TavernIncrementalExtractionBacklogAudit {
  readonly audit_version: "0.1.0";
  readonly total_message_count: number;
  readonly consumer_safe_covered_message_count_before: number;
  readonly semantic_covered_message_count_after: number;
  readonly remaining_message_count: number;
  readonly chunk_sequence: number;
  readonly novel_message_count: number;
  readonly context_message_count: number;
  readonly model_input_utf8_bytes: number;
  readonly response_utf8_bytes: number;
  readonly attempt_count: number;
  readonly elapsed_ms: number;
  /** Host transport does not attest billable usage; never invent a monetary estimate. */
  readonly estimated_cost_usd: null;
  readonly cost_status: "UNAVAILABLE_NO_ATTESTED_PROVIDER_USAGE";
}

export type TavernExtractionJobResult =
  | {
      readonly status: "ALREADY_CURRENT";
      readonly audit: TavernExtractionJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly semantic_task_fingerprint: string;
    }
  | {
      readonly status: "LIFECYCLE_PENDING";
      readonly audit: TavernExtractionJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly semantic_task_fingerprint: string;
    }
  | {
      readonly status: "REPAIR_PENDING";
      readonly audit: TavernExtractionJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly semantic_task_fingerprint: string;
      readonly incremental_partition: TavernIncrementalPartitionAudit;
    }
  | {
      readonly status: "COMMITTED";
      readonly audit: TavernExtractionJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly response_sha256: string;
      readonly response_utf8_bytes: number;
      readonly attempt_count: number;
      readonly response_quality: TavernExtractionResponseQualityAudit;
      readonly incremental_backlog?: TavernIncrementalExtractionBacklogAudit;
      readonly candidate_batch:
        | NarrativeExtractionCandidateBatch
        | NarrativeIncrementalExtractionCandidateBatch;
      readonly commit: TavernSemanticCommitResult | TavernIncrementalSemanticCommitResult;
      readonly incremental_partition?: TavernIncrementalPartitionAudit;
    }
  | {
      readonly status: "PARTIAL_COMMITTED";
      readonly audit: TavernExtractionJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly response_sha256: string;
      readonly response_utf8_bytes: number;
      readonly attempt_count: number;
      readonly response_quality: TavernExtractionResponseQualityAudit;
      readonly incremental_backlog: TavernIncrementalExtractionBacklogAudit;
      readonly incremental_partition: TavernIncrementalPartitionAudit;
      readonly candidate_batch: NarrativeIncrementalExtractionCandidateBatch;
      readonly commit: TavernIncrementalSemanticCommitResult;
    }
  | {
      readonly status: "CANCELLED" | "SUPERSEDED";
      readonly job_id: string;
      readonly reason: string;
      readonly host_cancel_requested: boolean;
    }
  | {
      readonly status: "STALE";
      readonly job_id: string;
      readonly reason: "STALE_TASK" | "SOURCE_CHANGED_DURING_COMMIT";
    };

export interface TavernExtractionCancellationReport {
  readonly reason: string;
  readonly generation_id: string | null;
  readonly host_cancel_requested: boolean;
}

export class TavernExtractionJobError extends Error {
  constructor(
    readonly code:
      | "INVALID_REQUEST"
      | "UNSUPPORTED_MODEL"
      | "PROMPT_ASSET_INVALID"
      | "CANDIDATE_PROMPT_NOT_ALLOWED"
      | "HOST_GENERATION_UNAVAILABLE"
      | "GENERATION_FAILED"
      | "GENERATION_TOOL_CALLS"
      | "RESPONSE_JSON_INVALID"
      | "RESPONSE_SCHEMA_INVALID"
      | "ATTEMPTS_EXHAUSTED"
      | "ATTEMPT_STATUS_UNKNOWN"
      | "ATTEMPT_LEDGER_BLOCKED",
    message: string,
    readonly diagnostic_codes: readonly string[] = [],
  ) {
    super(message);
    this.name = "TavernExtractionJobError";
  }
}

export type { TavernExtractionResponseQualityAudit } from "./extraction-quality-contracts.js";
