import type { TavernEventSubscription, TavernHostPort } from "./contracts.js";
import {
  TAVERN_INTERACTION_PERFORMANCE_EVENT_NAMES,
  TAVERN_INTERACTION_PERFORMANCE_VERSION,
  type TavernInteractionBarrierTiming,
  type TavernInteractionDurationSummary,
  type TavernInteractionGenerationType,
  TavernInteractionPerformanceError,
  type TavernInteractionPerformanceListener,
  type TavernInteractionPerformanceRuntime,
  type TavernInteractionPerformanceSample,
  type TavernInteractionPerformanceSnapshot,
} from "./interaction-performance-contracts.js";
import type { TavernRecallGenerationBarrierReport } from "./recall-generation-barrier-contracts.js";

interface ActiveMeasurement {
  readonly sequence: number;
  readonly generation_type: TavernInteractionGenerationType;
  sent_at: number | null;
  readonly started_at: number;
  first_token_at: number | null;
  completion_at: number | null;
  recall_barrier: TavernInteractionBarrierTiming | null;
}

const MAX_RETAINED_SAMPLES = 1_000;

function duration(later: number | null, earlier: number | null): number | null {
  if (later === null || earlier === null || later < earlier) return null;
  return later - earlier;
}

function summarize(values: readonly number[]): TavernInteractionDurationSummary {
  if (values.length === 0) return { samples: 0, p50_ms: null, p95_ms: null, max_ms: null };
  const sorted = [...values].sort((left, right) => left - right);
  const percentile = (fraction: number) =>
    sorted[Math.max(0, Math.ceil(sorted.length * fraction) - 1)] as number;
  return {
    samples: sorted.length,
    p50_ms: percentile(0.5),
    p95_ms: percentile(0.95),
    max_ms: sorted.at(-1) as number,
  };
}

function generationType(value: unknown): TavernInteractionGenerationType {
  switch (value) {
    case undefined:
    case "normal":
      return "normal";
    case "regenerate":
    case "swipe":
    case "quiet":
    case "impersonate":
    case "continue":
      return value;
    default:
      return "unknown";
  }
}

export function createBrowserTavernInteractionPerformanceRuntime(): TavernInteractionPerformanceRuntime {
  return { now_ms: () => globalThis.performance?.now() ?? Date.now() };
}

/**
 * Bounded, volatile timing probe. Event payload text and stream content are
 * deliberately ignored; only monotonic durations and coarse lifecycle labels
 * are retained in page memory.
 */
export class TavernInteractionPerformanceProbe {
  private lifecycle: "idle" | "running" | "stopped" | "disposed" = "idle";
  private pendingSentAt: number | null = null;
  private active: ActiveMeasurement | null = null;
  private nextSequence = 1;
  private readonly samples: TavernInteractionPerformanceSample[] = [];
  private readonly subscriptions: TavernEventSubscription[] = [];
  private readonly listeners = new Set<TavernInteractionPerformanceListener>();

  constructor(
    private readonly port: TavernHostPort,
    private readonly maxSamples = 200,
    private readonly runtime: TavernInteractionPerformanceRuntime = createBrowserTavernInteractionPerformanceRuntime(),
  ) {
    if (!Number.isInteger(maxSamples) || maxSamples < 1 || maxSamples > MAX_RETAINED_SAMPLES) {
      throw new TavernInteractionPerformanceError(
        "INVALID_CONFIG",
        `Interaction performance max_samples must be 1-${MAX_RETAINED_SAMPLES}`,
      );
    }
  }

  start(): boolean {
    this.assertNotDisposed();
    if (this.lifecycle === "running") return false;
    try {
      for (const eventName of TAVERN_INTERACTION_PERFORMANCE_EVENT_NAMES) {
        this.subscriptions.push(
          this.port.subscribe(eventName, (...args) => this.handleEvent(eventName, args)),
        );
      }
    } catch (error) {
      this.stopSubscriptions();
      throw new TavernInteractionPerformanceError(
        "SUBSCRIPTION_FAILED",
        error instanceof Error ? error.message : "Failed to subscribe interaction events",
      );
    }
    this.lifecycle = "running";
    return true;
  }

  stop(): boolean {
    this.assertNotDisposed();
    const wasRunning = this.lifecycle === "running";
    if (this.active !== null) this.finish("RUNTIME_STOPPED");
    this.pendingSentAt = null;
    this.lifecycle = "stopped";
    this.stopSubscriptions();
    return wasRunning;
  }

  dispose(): boolean {
    if (this.lifecycle === "disposed") return false;
    if (this.lifecycle === "running") this.stop();
    this.lifecycle = "disposed";
    this.pendingSentAt = null;
    this.active = null;
    this.stopSubscriptions();
    this.listeners.clear();
    return true;
  }

  clearSamples(): void {
    this.assertNotDisposed();
    this.samples.length = 0;
  }

  subscribeSamples(listener: TavernInteractionPerformanceListener): TavernEventSubscription {
    this.assertNotDisposed();
    this.listeners.add(listener);
    return { stop: () => this.listeners.delete(listener) };
  }

  recordRecallReport(report: TavernRecallGenerationBarrierReport): void {
    if (
      this.lifecycle !== "running" ||
      this.active === null ||
      (report.status !== "INJECTION_INSTALLED" && report.status !== "DEGRADED_NO_INJECTION")
    ) {
      return;
    }
    if (!Number.isFinite(report.elapsed_ms) || report.elapsed_ms < 0) return;
    this.active.recall_barrier = {
      status: report.status,
      elapsed_ms: report.elapsed_ms,
      trigger: report.trigger,
      ...(report.status === "DEGRADED_NO_INJECTION" ? { degradation_reason: report.reason } : {}),
    };
  }

  getSnapshot(): TavernInteractionPerformanceSnapshot {
    const completedUserTurns = this.samples.filter(
      (sample) => sample.trigger === "USER_MESSAGE" && sample.outcome === "ENDED",
    );
    const userTurnFirstToken = completedUserTurns
      .map((sample) => sample.generation_started_to_first_token_ms)
      .filter((value): value is number => value !== null);
    const postCommitFirstToken = completedUserTurns
      .map((sample) => sample.sent_to_first_token_ms)
      .filter((value): value is number => value !== null);
    const userTurnCompletion = completedUserTurns
      .map((sample) => sample.generation_started_to_completion_ms)
      .filter((value): value is number => value !== null);
    const postCommitCompletion = completedUserTurns
      .map((sample) => sample.sent_to_completion_ms)
      .filter((value): value is number => value !== null);
    const barrier = completedUserTurns
      .map((sample) => sample.recall_barrier?.elapsed_ms ?? null)
      .filter((value): value is number => value !== null);
    return {
      schema_version: TAVERN_INTERACTION_PERFORMANCE_VERSION,
      lifecycle: this.lifecycle,
      max_samples: this.maxSamples,
      active_generation: this.active !== null,
      retained_samples: this.samples.map((sample) => ({
        ...sample,
        recall_barrier: sample.recall_barrier === null ? null : { ...sample.recall_barrier },
      })),
      aggregate: {
        completed_samples: this.samples.filter((sample) => sample.outcome === "ENDED").length,
        user_triggered_samples: this.samples.filter((sample) => sample.trigger === "USER_MESSAGE")
          .length,
        user_turn_first_token: summarize(userTurnFirstToken),
        post_commit_first_token: summarize(postCommitFirstToken),
        user_turn_completion: summarize(userTurnCompletion),
        post_commit_completion: summarize(postCommitCompletion),
        recall_barrier: summarize(barrier),
        degraded_no_injection_samples: completedUserTurns.filter(
          (sample) => sample.recall_barrier?.status === "DEGRADED_NO_INJECTION",
        ).length,
      },
      content_recorded: false,
      draft_input_observed: false,
      browser_persistent_storage_used: false,
    };
  }

  private handleEvent(eventName: string, args: readonly unknown[]): void {
    if (this.lifecycle !== "running") return;
    switch (eventName) {
      case "message_sent":
        if (
          this.active !== null &&
          this.active.sent_at === null &&
          this.active.first_token_at === null &&
          this.active.completion_at === null
        ) {
          // SillyTavern emits generation_started before it commits the user's
          // message and emits message_sent. Attach that later event to the
          // already-active generation without inspecting its payload.
          this.active.sent_at = this.readNow();
        } else {
          // Also tolerate compatible hosts that emit message_sent first.
          this.pendingSentAt = this.readNow();
        }
        return;
      case "generation_started":
        if (args[2] === true) return;
        if (this.active !== null) this.finish("SUPERSEDED_BY_NEW_GENERATION");
        this.active = {
          sequence: this.nextSequence++,
          generation_type: generationType(args[0]),
          sent_at: this.pendingSentAt,
          started_at: this.readNow(),
          first_token_at: null,
          completion_at: null,
          recall_barrier: null,
        };
        this.pendingSentAt = null;
        return;
      case "stream_token_received":
        if (this.active !== null && this.active.first_token_at === null) {
          this.active.first_token_at = this.readNow();
        }
        return;
      case "message_received":
        if (this.active !== null && this.active.completion_at === null) {
          this.active.completion_at = this.readNow();
        }
        return;
      case "generation_stopped":
        if (this.active !== null) this.finish("STOPPED");
        return;
      case "generation_ended":
        if (this.active !== null) this.finish("ENDED");
        return;
      case "chat_id_changed":
        this.pendingSentAt = null;
        if (this.active !== null) this.finish("CHAT_CHANGED");
        return;
    }
  }

  private finish(outcome: TavernInteractionPerformanceSample["outcome"]): void {
    const active = this.active;
    if (active === null) return;
    const finishedAt = this.readNow();
    this.active = null;
    const sample: TavernInteractionPerformanceSample = Object.freeze({
      schema_version: TAVERN_INTERACTION_PERFORMANCE_VERSION,
      sequence: active.sequence,
      trigger: active.sent_at === null ? "OTHER" : "USER_MESSAGE",
      generation_type: active.generation_type,
      outcome,
      streaming_first_token_observed: active.first_token_at !== null,
      sent_to_generation_started_ms: duration(active.started_at, active.sent_at),
      generation_started_to_first_token_ms: duration(active.first_token_at, active.started_at),
      sent_to_first_token_ms: duration(active.first_token_at, active.sent_at),
      generation_started_to_completion_ms: duration(active.completion_at, active.started_at),
      sent_to_completion_ms: duration(active.completion_at, active.sent_at),
      total_generation_lifecycle_ms: Math.max(0, finishedAt - active.started_at),
      recall_barrier:
        active.recall_barrier === null ? null : Object.freeze({ ...active.recall_barrier }),
      content_recorded: false,
      draft_input_observed: false,
      browser_persistent_storage_used: false,
    });
    this.samples.push(sample);
    if (this.samples.length > this.maxSamples)
      this.samples.splice(0, this.samples.length - this.maxSamples);
    for (const listener of [...this.listeners]) {
      try {
        listener(sample);
      } catch {
        // Measurement listeners cannot affect generation.
      }
    }
  }

  private readNow(): number {
    const value = this.runtime.now_ms();
    if (!Number.isFinite(value) || value < 0) {
      throw new TavernInteractionPerformanceError(
        "INVALID_RUNTIME",
        "Interaction performance runtime now_ms must return a finite non-negative number",
      );
    }
    return value;
  }

  private stopSubscriptions(): void {
    while (this.subscriptions.length > 0) this.subscriptions.pop()?.stop();
  }

  private assertNotDisposed(): void {
    if (this.lifecycle === "disposed") {
      throw new TavernInteractionPerformanceError(
        "DISPOSED",
        "Interaction performance probe is disposed",
      );
    }
  }
}
