import type {
  CandidateCausalCauseRef,
  CandidateClaimArgument,
  CandidateEntityRef,
  CandidateEvidenceQuote,
  CandidatePrincipalRef,
  FlatDraftCausalNodeRef,
  FlatDraftClaimArgument,
  FlatDraftEntityRef,
  FlatDraftKnownValue,
  FlatDraftQuote,
  FlatNarrativeExtractionDraft,
  NarrativeExtractionCandidateBatch,
  TemporalExtent,
} from "@narramem/core-domain";
import { parseNarraMemId } from "@narramem/core-domain";

export class FlatNarrativeDraftTranslationError extends Error {
  constructor(
    readonly code: "KNOWN_ENTITY_REF_INVALID" | "STATE_UNKNOWN_BOTH",
    message: string,
  ) {
    super(message);
    this.name = "FlatNarrativeDraftTranslationError";
  }
}

const quote = (value: FlatDraftQuote): CandidateEvidenceQuote => ({
  evidence_id: value.evidence_id,
  quote: value.quote,
  occurrence: value.occurrence,
  support_role: "direct",
});

function entityRef(value: FlatDraftEntityRef): CandidateEntityRef {
  if (value.source === "candidate") {
    return { kind: "candidate_entity", candidate_key: value.key };
  }
  const entityId = parseNarraMemId("entity", value.key);
  if (entityId === undefined) {
    throw new FlatNarrativeDraftTranslationError(
      "KNOWN_ENTITY_REF_INVALID",
      `Flat Draft known ref is not an Entity ID: ${value.key}`,
    );
  }
  return { kind: "existing_entity", entity_id: entityId };
}

function principalRef(value: FlatDraftEntityRef): CandidatePrincipalRef {
  if (value.source === "candidate") {
    return { kind: "candidate_entity", candidate_key: value.key };
  }
  const entityId = parseNarraMemId("entity", value.key);
  if (entityId === undefined) {
    throw new FlatNarrativeDraftTranslationError(
      "KNOWN_ENTITY_REF_INVALID",
      `Flat Draft known principal is not an Entity ID: ${value.key}`,
    );
  }
  return {
    kind: "existing_principal",
    principal: { kind: "entity", entity_id: entityId },
  };
}

const knownValue = (value: FlatDraftKnownValue) =>
  value.known
    ? ({ status: "known", value: value.value } as const)
    : ({ status: "unknown" } as const);

function claimArgument(value: FlatDraftClaimArgument): CandidateClaimArgument {
  switch (value.kind) {
    case "entity":
      return { kind: "entity", entity: entityRef(value.entity) };
    case "event":
      return { kind: "event", event_candidate_key: value.key };
    case "state":
      return { kind: "state_delta", state_candidate_key: value.key };
    case "literal":
      return { kind: "literal", value: value.value };
  }
}

function causalRef(value: FlatDraftCausalNodeRef): CandidateCausalCauseRef {
  switch (value.kind) {
    case "event":
      return { kind: "event", event_candidate_key: value.key };
    case "state":
      return { kind: "state_delta", state_candidate_key: value.key };
    case "epistemic":
      return { kind: "epistemic_state", epistemic_candidate_key: value.key };
  }
}

/**
 * Deterministically converts a shallow explicit-only adapter IR to the one
 * canonical Candidate contract. No IDs, facts, keys, quotes, causality, or
 * uncertainty are invented; only structural wrappers and trusted defaults are
 * supplied. The canonical Wire and semantic validators must still run next.
 */
export function translateFlatNarrativeExtractionDraft(
  draft: FlatNarrativeExtractionDraft,
  defaultStoryTime: TemporalExtent,
): NarrativeExtractionCandidateBatch {
  return {
    contract_version: "0.3.0",
    source_revision_id: draft.source_revision_id,
    entities: draft.entities.map((entity) => ({
      candidate_key: entity.key,
      entity_type: entity.type,
      canonical_label: entity.label,
      aliases: entity.aliases,
      evidence_quotes: entity.quotes.map(quote),
      support_level: "explicit",
    })),
    scenes: draft.scenes.map((scene) => ({
      candidate_key: scene.key,
      source_evidence_ids: scene.evidence_ids,
      story_time: defaultStoryTime,
      location_refs: scene.locations.map(entityRef),
      participant_refs: scene.participants.map(entityRef),
      focalizers: scene.focalizers.map(principalRef),
      atmosphere_labels: scene.atmosphere,
      boundary_reason: scene.boundary_reason,
      support_level: "explicit",
    })),
    events: draft.events.map((event) => ({
      candidate_key: event.key,
      scene_candidate_key: event.scene_key,
      event_type: event.type,
      actor_refs: event.actors.map(entityRef),
      patient_refs: event.patients.map(entityRef),
      action_or_occurrence: event.description,
      location_refs: event.locations.map(entityRef),
      story_time: defaultStoryTime,
      intentionality: event.intentionality,
      evidence_quotes: event.quotes.map(quote),
      support_level: "explicit",
    })),
    state_transitions: draft.states.map((state) => {
      if (!state.before.known && !state.after.known) {
        throw new FlatNarrativeDraftTranslationError(
          "STATE_UNKNOWN_BOTH",
          `Flat Draft State ${state.key} has unknown before and after`,
        );
      }
      const subject =
        state.subject.kind === "entity"
          ? ({ kind: "entity", entity: entityRef(state.subject.entity) } as const)
          : state.subject.kind === "relation"
            ? ({
                kind: "relation",
                relation_type: state.subject.relation_type,
                participants: state.subject.participants.map(entityRef),
              } as const)
            : ({ kind: "world", scope_key: state.subject.scope_key } as const);
      return {
        candidate_key: state.key,
        subject,
        state_key: state.state_key,
        operation: state.operation,
        before_state: knownValue(state.before),
        after_state: knownValue(state.after),
        cooccurring_event_keys: state.event_keys,
        valid_from: defaultStoryTime,
        evidence_quotes: state.quotes.map(quote),
        support_level: "explicit" as const,
      };
    }),
    epistemic_states: draft.epistemics.map((epistemic) => {
      const target =
        epistemic.target.kind === "event"
          ? ({ kind: "event", event_candidate_key: epistemic.target.key } as const)
          : epistemic.target.kind === "state"
            ? ({ kind: "state", state_candidate_key: epistemic.target.key } as const)
            : ({
                kind: "claim",
                claim: {
                  predicate: epistemic.target.claim.predicate,
                  arguments: epistemic.target.claim.arguments.map(claimArgument),
                },
              } as const);
      return {
        candidate_key: epistemic.key,
        holder: principalRef(epistemic.holder),
        target,
        mode: epistemic.mode,
        certainty: epistemic.certainty,
        ...(epistemic.acquired_via === undefined ? {} : { acquired_via: epistemic.acquired_via }),
        ...(epistemic.source_entity === undefined
          ? {}
          : { source_entity: entityRef(epistemic.source_entity) }),
        source_event_keys: epistemic.source_event_keys,
        valid_time: defaultStoryTime,
        evidence_quotes: epistemic.quotes.map(quote),
        support_level: "explicit" as const,
      };
    }),
    causal_links: draft.causals.map((causal) => ({
      candidate_key: causal.key,
      cause_refs: causal.causes.map(causalRef),
      effect_refs: causal.effects.map(causalRef),
      relation: causal.relation,
      mechanism: causal.mechanism,
      attribution:
        causal.attribution.kind === "narrator"
          ? ({ kind: "narrator_claim" } as const)
          : ({
              kind: "character_belief",
              holder: principalRef(causal.attribution.holder),
            } as const),
      necessity: causal.necessity,
      strength: causal.strength,
      evidence_quotes: causal.quotes.map(quote),
      support_level: "explicit" as const,
    })),
    unresolved_items: draft.unresolved_items,
  };
}
