export const TAVERN_HOST_PORT_VERSION = "0.2.0" as const;
export const TAVERN_HOST_CAPABILITY_REPORT_VERSION = "0.1.0" as const;

export type TavernMessageRole = "system" | "assistant" | "user";
export type TavernJsonPrimitive = string | number | boolean | null;
export type TavernJsonValue =
  | TavernJsonPrimitive
  | readonly TavernJsonValue[]
  | { readonly [key: string]: TavernJsonValue };

export interface TavernHostVersions {
  readonly silly_tavern: string;
  readonly integration: "native_extension";
}

export interface TavernHostIdentity {
  readonly character_id: string | null;
  readonly character_name: string | null;
  readonly chat_id: string | null;
}

export interface TavernNarrativeProjectionSnapshot {
  readonly text: string;
  readonly strategy:
    | "raw_selected_content"
    | "assistant_last_complete_content_block"
    | "assistant_configured_content_block_without_html_comments";
  readonly raw_start_code_point: number;
  readonly raw_end_code_point: number;
}

export interface TavernMessageSnapshot {
  readonly message_id: number;
  readonly name: string;
  readonly role: TavernMessageRole;
  readonly is_hidden: boolean;
  readonly message?: string;
  readonly narrative_projection?: TavernNarrativeProjectionSnapshot;
  readonly data?: Readonly<Record<string, unknown>>;
  readonly extra?: Readonly<Record<string, unknown>>;
  readonly swipe_id?: number;
  readonly swipes?: readonly string[];
  readonly swipes_data?: readonly Readonly<Record<string, unknown>>[];
  readonly swipes_info?: readonly Readonly<Record<string, unknown>>[];
}

export interface TavernReadMessagesRequest {
  readonly include_swipes: boolean;
}

export interface TavernWorldbookEntry {
  readonly uid: number;
  readonly name: string;
  readonly enabled: boolean;
  readonly content: string;
  readonly strategy: {
    readonly type: "constant" | "selective";
    readonly keys: readonly string[];
    readonly keys_secondary: {
      readonly logic: "and_any" | "and_all" | "not_all" | "not_any";
      readonly keys: readonly string[];
    };
    readonly scan_depth: "same_as_global" | number;
  };
  readonly position: {
    readonly type: "after_character_definition" | "at_depth";
    readonly role: TavernMessageRole;
    readonly depth: number;
    readonly order: number;
  };
  readonly probability: number;
  readonly recursion: {
    readonly prevent_incoming: boolean;
    readonly prevent_outgoing: boolean;
    readonly delay_until: null | number;
  };
  readonly effect: {
    readonly sticky: null | number;
    readonly cooldown: null | number;
    readonly delay: null | number;
  };
  readonly extra?: Readonly<Record<string, unknown>>;
}

export type TavernWorldbookEntryDraft = Omit<TavernWorldbookEntry, "uid">;

export interface TavernInjectionRequest {
  readonly id: string;
  readonly position: "in_chat" | "none";
  readonly depth: number;
  readonly role: TavernMessageRole;
  readonly content: string;
  readonly should_scan: boolean;
  readonly once: boolean;
  readonly prompt_asset_ref: string;
}

export interface TavernInjectionHandle {
  remove(): void;
}

export interface TavernRolePrompt {
  readonly role: TavernMessageRole;
  readonly content: string;
}

export interface TavernJsonSchemaRequest {
  readonly name: string;
  readonly description?: string;
  readonly value: Readonly<Record<string, unknown>>;
  readonly strict: boolean;
}

export interface TavernGenerationParameters {
  readonly max_tokens: number;
  readonly temperature?: number;
  readonly top_p?: number;
  readonly top_k?: number;
}

/**
 * NarraMem checks the exact model selected in SillyTavern before dispatch. The
 * host still cannot attest an aggregator's backend identity, so downstream
 * audit must retain `requested_not_attested`.
 */
export interface TavernGenerationTarget {
  readonly requested_model_id: string;
  readonly proxy_preset?: string;
  readonly parameters: TavernGenerationParameters;
  readonly identity_assurance: "requested_not_attested";
}

export interface TavernStructuredGenerationRequest {
  readonly generation_id: string;
  readonly target: TavernGenerationTarget;
  readonly messages: readonly TavernRolePrompt[];
  readonly prompt_asset_refs: readonly string[];
  readonly json_schema: TavernJsonSchemaRequest;
  /** Continuation suffix calls must not be forced through a JSON-object response formatter. */
  readonly response_format?: "structured_json" | "text_fragment";
  readonly should_silence: true;
  readonly should_stream: false;
  readonly max_chat_history: 0;
}

export interface TavernToolCall {
  readonly id: string;
  readonly name: string;
  readonly arguments_json: string;
  readonly thought_signature?: string;
}

export type TavernStructuredGenerationResult =
  | { readonly kind: "text"; readonly content: string }
  | {
      readonly kind: "tool_calls";
      readonly content: string;
      readonly tool_calls: readonly TavernToolCall[];
      readonly reasoning_signature?: string;
    };

export interface TavernEventSubscription {
  stop(): void;
}

export interface TavernHostPort {
  readonly port_version: typeof TAVERN_HOST_PORT_VERSION;
  getVersions(): TavernHostVersions;
  getCurrentIdentity(): TavernHostIdentity;
  readCurrentMessages(request: TavernReadMessagesRequest): readonly TavernMessageSnapshot[];
  subscribe(
    event_name: string,
    listener: (...args: readonly unknown[]) => void | Promise<void>,
  ): TavernEventSubscription;
  emitCustomEvent(event_name: string, ...args: readonly unknown[]): Promise<void>;
  listWorldbooks(): readonly string[];
  readWorldbook(name: string): Promise<readonly TavernWorldbookEntry[]>;
  createWorldbook(name: string): Promise<boolean>;
  replaceWorldbook(name: string, entries: readonly TavernWorldbookEntry[]): Promise<void>;
  appendWorldbookEntries(
    name: string,
    entries: readonly TavernWorldbookEntryDraft[],
  ): Promise<{
    readonly worldbook: readonly TavernWorldbookEntry[];
    readonly new_entries: readonly TavernWorldbookEntry[];
  }>;
  deleteWorldbook(name: string): Promise<boolean>;
  withWorldbookExclusiveLock?<T>(lock_name: string, operation: () => Promise<T>): Promise<T>;
  installInjection?(request: TavernInjectionRequest): TavernInjectionHandle;
  generateStructured?(
    request: TavernStructuredGenerationRequest,
  ): Promise<TavernStructuredGenerationResult>;
  cancelGeneration?(generation_id: string): boolean;
}

export type TavernHostCapabilityId =
  | "versions.read"
  | "identity.read"
  | "messages.read_current"
  | "messages.include_swipes"
  | "events.custom_roundtrip"
  | "worldbooks.list"
  | "worldbooks.scratch_roundtrip"
  | "worldbooks.extra_roundtrip"
  | "injection.install_remove"
  | "generation.structured_raw"
  | "generation.cancel_by_id";

export type TavernCapabilityStatus = "verified" | "failed" | "unavailable" | "skipped";

export interface TavernCapabilityFinding {
  readonly capability_id: TavernHostCapabilityId;
  readonly status: TavernCapabilityStatus;
  readonly evidence: readonly string[];
  readonly issue?: string;
}

export type TavernCapabilityProbeMode = "read_only" | "scratch_mutation";

export interface TavernGenerationProbe {
  readonly request: TavernStructuredGenerationRequest;
  readonly expected_nonce: string;
}

export interface TavernInjectionProbe {
  readonly request: TavernInjectionRequest;
}

export interface TavernHostCapabilityLabOptions {
  readonly probe_id: string;
  readonly observed_at: string;
  readonly mode: TavernCapabilityProbeMode;
  readonly require_active_chat: boolean;
  readonly scratch_worldbook_name?: string;
  readonly injection_probe?: TavernInjectionProbe;
  readonly generation_probe?: TavernGenerationProbe;
}

export interface TavernHostCapabilityReport {
  readonly schema_version: typeof TAVERN_HOST_CAPABILITY_REPORT_VERSION;
  readonly probe_id: string;
  readonly observed_at: string;
  readonly mode: TavernCapabilityProbeMode;
  readonly versions?: TavernHostVersions;
  readonly identity?: TavernHostIdentity;
  readonly findings: readonly TavernCapabilityFinding[];
  readonly scratch: {
    readonly book_name?: string;
    readonly created: boolean;
    readonly cleaned_up: boolean;
  };
  readonly external_model_calls: number;
  readonly decision:
    | "READ_ONLY_CAPABILITIES_VERIFIED"
    | "SCRATCH_CAPABILITIES_VERIFIED"
    | "CAPABILITY_GAPS_FOUND";
  readonly browser_storage_used: false;
  readonly user_worldbooks_modified: false;
}
