export const CHARACTER_IDENTITY_FIELD = "narramem_identity";
export const CHARACTER_IDENTITY_VERSION = "0.1.0";

export interface NarraMemCharacterIdentity {
  readonly version: typeof CHARACTER_IDENTITY_VERSION;
  readonly character_id: string;
}

export interface TavernCharacterIdentityContext {
  readonly characters: readonly unknown[];
  readonly characterId: string | number | null | undefined;
  writeExtensionField(characterId: string | number, key: string, value: unknown): Promise<void>;
}

type UnknownRecord = Record<string, unknown>;

const CHARACTER_ID_PATTERN =
  /^nmc_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/u;

function asObject(value: unknown): UnknownRecord | null {
  return typeof value === "object" && value !== null ? (value as UnknownRecord) : null;
}

export function activeCharacter(context: TavernCharacterIdentityContext): UnknownRecord | null {
  const rawId = context.characterId;
  if (rawId === null || rawId === undefined || rawId === "") return null;
  const index = typeof rawId === "number" ? rawId : Number.parseInt(String(rawId), 10);
  if (!Number.isInteger(index) || index < 0) return null;
  return asObject(context.characters[index]);
}

export function readCharacterIdentity(character: unknown): NarraMemCharacterIdentity | null {
  const data = asObject(asObject(character)?.data);
  const extensions = asObject(data?.extensions);
  const identity = asObject(extensions?.[CHARACTER_IDENTITY_FIELD]);
  if (
    identity?.version !== CHARACTER_IDENTITY_VERSION ||
    typeof identity.character_id !== "string" ||
    !CHARACTER_ID_PATTERN.test(identity.character_id)
  ) {
    return null;
  }
  return identity as unknown as NarraMemCharacterIdentity;
}

function creationTimestamp(character: UnknownRecord): number {
  const raw = character.date_added ?? character.create_date;
  if (typeof raw === "number" && Number.isFinite(raw)) return raw;
  if (typeof raw !== "string" || raw.trim().length === 0) return Number.POSITIVE_INFINITY;
  const numeric = Number(raw);
  if (Number.isFinite(numeric)) return numeric;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
}

function compareCreationOrder(
  left: { readonly character: UnknownRecord; readonly index: number },
  right: { readonly character: UnknownRecord; readonly index: number },
): number {
  const timestampOrder = creationTimestamp(left.character) - creationTimestamp(right.character);
  return timestampOrder === 0 || Number.isNaN(timestampOrder)
    ? left.index - right.index
    : timestampOrder;
}

export async function ensureActiveCharacterIdentity(
  context: TavernCharacterIdentityContext,
  createUuid?: () => string,
): Promise<string | null> {
  const current = activeCharacter(context);
  if (current === null) return null;
  const currentIndex = Number(context.characterId);
  const existing = readCharacterIdentity(current);
  if (existing !== null) {
    const duplicates = context.characters
      .map((character, index) => ({ character: asObject(character), index }))
      .filter(
        (item): item is { character: UnknownRecord; index: number } =>
          item.character !== null &&
          readCharacterIdentity(item.character)?.character_id === existing.character_id,
      )
      .sort(compareCreationOrder);
    if (duplicates.length === 1 || duplicates[0]?.index === currentIndex) {
      return existing.character_id;
    }
  }
  const uuid = createUuid?.() ?? globalThis.crypto?.randomUUID?.();
  if (uuid === undefined) {
    throw new Error("Web Crypto randomUUID is required for stable NarraMem character identity");
  }
  const characterId = `nmc_${uuid}`;
  if (!CHARACTER_ID_PATTERN.test(characterId)) {
    throw new Error("Stable NarraMem character identity factory returned an invalid UUID v4");
  }
  const identity: NarraMemCharacterIdentity = {
    version: CHARACTER_IDENTITY_VERSION,
    character_id: characterId,
  };
  await context.writeExtensionField(currentIndex, CHARACTER_IDENTITY_FIELD, identity);
  return identity.character_id;
}
