export type MemoryGenerationTransportStatus = "running" | "success" | "failed";

/**
 * A successful model transport only means one extraction/lifecycle request returned.
 * The Observer report remains the sole authority for declaring the whole memory task complete.
 */
export function memoryTaskStatusAfterGeneration(
  status: MemoryGenerationTransportStatus,
): "running" | "failed" {
  return status === "failed" ? "failed" : "running";
}
