import type {
  CandidateClaimArgument,
  CandidateEntityRef,
  CandidateEvidenceQuote,
  CandidatePrincipalRef,
  CandidateStateSubjectRef,
  EvidenceItem,
  ExtractionCandidateBatch,
  NarraMemId,
  NarrativeExtractionCandidateBatch,
  NarrativeExtractionCandidateBatchV020,
} from "@narramem/core-domain";

import { validateWireValue } from "./wire-schema-registry.js";

export interface ExtractionCandidateValidationContext {
  readonly active_revision_id: NarraMemId<"source_revision">;
  readonly evidence_items: readonly EvidenceItem[];
  readonly known_entity_ids: readonly NarraMemId<"entity">[];
}

export interface ExtractionCandidateIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export interface ExtractionCandidateValidationReport {
  readonly validator_version: "0.1.0";
  readonly accepted: boolean;
  readonly issues: readonly ExtractionCandidateIssue[];
}

function issue(code: string, path: string, message: string): ExtractionCandidateIssue {
  return { code, path, message };
}

function quoteOccurrenceExists(text: string, quote: string, requestedOccurrence: number): boolean {
  let searchFrom = 0;
  let occurrence = 0;
  while (searchFrom <= text.length) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) {
      return false;
    }
    if (occurrence === requestedOccurrence) {
      return true;
    }
    occurrence += 1;
    searchFrom = index + Math.max(1, quote.length);
  }
  return false;
}

function validateEvidenceQuote(
  quote: CandidateEvidenceQuote,
  path: string,
  evidenceById: ReadonlyMap<string, EvidenceItem>,
  activeRevisionId: NarraMemId<"source_revision">,
): ExtractionCandidateIssue[] {
  const evidence = evidenceById.get(quote.evidence_id);
  if (evidence === undefined || evidence.revision_id !== activeRevisionId) {
    return [
      issue(
        "CANDIDATE_EVIDENCE_NOT_CURRENT",
        path,
        "Candidate quote must reference evidence in the active frozen revision",
      ),
    ];
  }
  if (evidence.raw_content.kind !== "text") {
    return [
      issue(
        "CANDIDATE_QUOTE_REQUIRES_TEXT",
        path,
        "Text quotes cannot anchor structured Evidence; use a later structured selector compiler",
      ),
    ];
  }
  if (!quoteOccurrenceExists(evidence.raw_content.text, quote.quote, quote.occurrence ?? 0)) {
    return [
      issue(
        "CANDIDATE_QUOTE_NOT_FOUND",
        path,
        "Candidate quote and occurrence must exactly match active Evidence text",
      ),
    ];
  }
  return [];
}

function referencedCandidateEntityKey(
  reference: CandidateEntityRef | CandidatePrincipalRef,
): string | undefined {
  return reference.kind === "candidate_entity" ? reference.candidate_key : undefined;
}

function referencedExistingEntityId(
  reference: CandidateEntityRef | CandidatePrincipalRef,
): NarraMemId<"entity"> | undefined {
  if (reference.kind === "existing_entity") {
    return reference.entity_id;
  }
  if (reference.kind === "existing_principal" && reference.principal.kind === "entity") {
    return reference.principal.entity_id;
  }
  return undefined;
}

function validateEntityReferences(
  references: readonly (CandidateEntityRef | CandidatePrincipalRef)[],
  path: string,
  candidateEntityKeys: ReadonlySet<string>,
  knownEntityIds: ReadonlySet<string>,
): ExtractionCandidateIssue[] {
  const issues: ExtractionCandidateIssue[] = [];
  references.forEach((reference, index) => {
    const candidateKey = referencedCandidateEntityKey(reference);
    if (candidateKey !== undefined && !candidateEntityKeys.has(candidateKey)) {
      issues.push(
        issue(
          "CANDIDATE_ENTITY_REF_UNKNOWN",
          `${path}/${index}`,
          "Local candidate entity reference must resolve inside the same batch",
        ),
      );
    }
    const entityId = referencedExistingEntityId(reference);
    if (entityId !== undefined && !knownEntityIds.has(entityId)) {
      issues.push(
        issue(
          "EXISTING_ENTITY_REF_UNKNOWN",
          `${path}/${index}`,
          "Existing entity reference must already exist in the trusted entity catalog",
        ),
      );
    }
  });
  return issues;
}

function validateSupportLevel(
  candidate: {
    readonly support_level: "explicit" | "strongly_implied" | "ambiguous";
    readonly uncertainty?: string;
  },
  path: string,
): ExtractionCandidateIssue[] {
  if (candidate.support_level === "ambiguous" && candidate.uncertainty === undefined) {
    return [
      issue(
        "AMBIGUITY_NOT_EXPLAINED",
        path,
        "An ambiguous candidate must state what remains uncertain",
      ),
    ];
  }
  return [];
}

export interface NarrativeExtractionCandidateValidationReport {
  readonly validator_version: "0.2.0" | "0.3.0";
  readonly accepted: boolean;
  readonly issues: readonly ExtractionCandidateIssue[];
}

function stateSubjectEntityRefs(subject: CandidateStateSubjectRef): readonly CandidateEntityRef[] {
  if (subject.kind === "entity") return [subject.entity];
  return subject.kind === "relation" ? subject.participants : [];
}

function claimEntityRefs(
  arguments_: readonly CandidateClaimArgument[],
): readonly CandidateEntityRef[] {
  return arguments_.flatMap((argument) => (argument.kind === "entity" ? [argument.entity] : []));
}

function candidateEndpointKey(reference: {
  readonly kind: "event" | "state_delta" | "epistemic_state";
  readonly event_candidate_key?: string;
  readonly state_candidate_key?: string;
  readonly epistemic_candidate_key?: string;
}): string {
  if (reference.kind === "event") return `event:${reference.event_candidate_key ?? ""}`;
  if (reference.kind === "state_delta") return `state:${reference.state_candidate_key ?? ""}`;
  return `epistemic:${reference.epistemic_candidate_key ?? ""}`;
}

function validateNarrativeExtractionCandidateBatchVersion(
  value: unknown,
  context: ExtractionCandidateValidationContext,
  schemaName: "narrative_extraction_candidate_batch" | "narrative_extraction_candidate_batch_v030",
  validatorVersion: "0.2.0" | "0.3.0",
): NarrativeExtractionCandidateValidationReport {
  const schemaResult = validateWireValue(schemaName, value);
  if (!schemaResult.valid) {
    const details = schemaResult.errors
      .slice(0, 12)
      .map((error) => `${error.instancePath || "/"} ${error.message ?? "is invalid"}`)
      .join("; ");
    return {
      validator_version: validatorVersion,
      accepted: false,
      issues: [issue("NARRATIVE_EXTRACTION_SCHEMA_INVALID", "/", details)],
    };
  }

  const batch = value as NarrativeExtractionCandidateBatch | NarrativeExtractionCandidateBatchV020;
  const baseReport = validateExtractionCandidateBatch(
    {
      contract_version: "0.1.0",
      source_revision_id: batch.source_revision_id,
      entities: batch.entities,
      scenes: batch.scenes,
      events: batch.events,
      unresolved_items: [],
    },
    context,
  );
  const issues: ExtractionCandidateIssue[] = [...baseReport.issues];
  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const knownEntityIds = new Set<string>(context.known_entity_ids);
  const entityKeys = new Set(batch.entities.map((candidate) => candidate.candidate_key));
  const eventKeys = new Set(batch.events.map((candidate) => candidate.candidate_key));
  const stateKeys = new Set(batch.state_transitions.map((candidate) => candidate.candidate_key));
  const epistemicKeys = new Set(batch.epistemic_states.map((candidate) => candidate.candidate_key));
  const allKeys = [
    ...batch.entities.map((candidate) => candidate.candidate_key),
    ...batch.scenes.map((candidate) => candidate.candidate_key),
    ...batch.events.map((candidate) => candidate.candidate_key),
    ...batch.state_transitions.map((candidate) => candidate.candidate_key),
    ...batch.epistemic_states.map((candidate) => candidate.candidate_key),
    ...batch.causal_links.map((candidate) => candidate.candidate_key),
  ];
  if (new Set(allKeys).size !== allKeys.length) {
    issues.push(
      issue(
        "NARRATIVE_CANDIDATE_KEY_DUPLICATE",
        "/",
        `Candidate keys must be unique across every v${validatorVersion} narrative candidate kind`,
      ),
    );
  }

  const validateQuotes = (quotes: readonly CandidateEvidenceQuote[], path: string): void => {
    quotes.forEach((quote, index) => {
      issues.push(
        ...validateEvidenceQuote(
          quote,
          `${path}/${index}`,
          evidenceById,
          context.active_revision_id,
        ),
      );
    });
  };
  const requireDirect = (quotes: readonly CandidateEvidenceQuote[], path: string): void => {
    if (!quotes.some((quote) => quote.support_role === "direct")) {
      issues.push(
        issue(
          "NARRATIVE_DIRECT_SUPPORT_MISSING",
          path,
          "State, epistemic, and causal candidates require an exact direct-support quote",
        ),
      );
    }
  };
  const validateEventKeys = (keys: readonly string[], path: string): void => {
    keys.forEach((key, index) => {
      if (!eventKeys.has(key)) {
        issues.push(
          issue(
            "NARRATIVE_EVENT_REF_UNKNOWN",
            `${path}/${index}`,
            "Narrative candidate Event references must resolve inside the same batch",
          ),
        );
      }
    });
  };

  batch.state_transitions.forEach((candidate, index) => {
    const path = `/state_transitions/${index}`;
    issues.push(...validateSupportLevel(candidate, path));
    if (candidate.before_state.status === "unknown" && candidate.after_state.status === "unknown") {
      issues.push(
        issue(
          "STATE_VALUES_BOTH_UNKNOWN",
          path,
          "A state candidate cannot fabricate a transition when both before and after are unknown",
        ),
      );
    }
    issues.push(
      ...validateEntityReferences(
        stateSubjectEntityRefs(candidate.subject),
        `${path}/subject`,
        entityKeys,
        knownEntityIds,
      ),
    );
    validateEventKeys(candidate.cooccurring_event_keys, `${path}/cooccurring_event_keys`);
    validateQuotes(candidate.evidence_quotes, `${path}/evidence_quotes`);
    requireDirect(candidate.evidence_quotes, `${path}/evidence_quotes`);
  });

  batch.epistemic_states.forEach((candidate, index) => {
    const path = `/epistemic_states/${index}`;
    issues.push(...validateSupportLevel(candidate, path));
    issues.push(
      ...validateEntityReferences(
        [
          candidate.holder,
          ...(candidate.source_entity === undefined ? [] : [candidate.source_entity]),
        ],
        `${path}/principals`,
        entityKeys,
        knownEntityIds,
      ),
    );
    if (candidate.target.kind === "event" && !eventKeys.has(candidate.target.event_candidate_key)) {
      issues.push(
        issue(
          "EPISTEMIC_EVENT_REF_UNKNOWN",
          `${path}/target/event_candidate_key`,
          "Epistemic Event target must resolve inside the same batch",
        ),
      );
    }
    if (candidate.target.kind === "state" && !stateKeys.has(candidate.target.state_candidate_key)) {
      issues.push(
        issue(
          "EPISTEMIC_STATE_REF_UNKNOWN",
          `${path}/target/state_candidate_key`,
          "Epistemic State target must resolve inside the same batch",
        ),
      );
    }
    if (candidate.target.kind === "claim") {
      issues.push(
        ...validateEntityReferences(
          claimEntityRefs(candidate.target.claim.arguments),
          `${path}/target/claim/entity_refs`,
          entityKeys,
          knownEntityIds,
        ),
      );
      candidate.target.claim.arguments.forEach((argument, argumentIndex) => {
        if (argument.kind === "event" && !eventKeys.has(argument.event_candidate_key)) {
          issues.push(
            issue(
              "CLAIM_EVENT_REF_UNKNOWN",
              `${path}/target/claim/arguments/${argumentIndex}`,
              "Claim Event reference must resolve inside the same batch",
            ),
          );
        }
        if (argument.kind === "state_delta" && !stateKeys.has(argument.state_candidate_key)) {
          issues.push(
            issue(
              "CLAIM_STATE_REF_UNKNOWN",
              `${path}/target/claim/arguments/${argumentIndex}`,
              "Claim State reference must resolve inside the same batch",
            ),
          );
        }
      });
    }
    validateEventKeys(candidate.source_event_keys, `${path}/source_event_keys`);
    if (
      validatorVersion === "0.3.0" &&
      candidate.mode !== "unknown_to" &&
      candidate.source_event_keys.length === 0
    ) {
      issues.push(
        issue(
          "EPISTEMIC_SOURCE_EVENT_MISSING",
          `${path}/source_event_keys`,
          "Only unknown_to may omit an acquisition/source Event",
        ),
      );
    }
    validateQuotes(candidate.evidence_quotes, `${path}/evidence_quotes`);
    requireDirect(candidate.evidence_quotes, `${path}/evidence_quotes`);
  });

  batch.causal_links.forEach((candidate, index) => {
    const path = `/causal_links/${index}`;
    if (candidate.support_level !== "explicit") {
      issues.push(
        issue(
          "CAUSAL_NOT_EXPLICIT",
          `${path}/support_level`,
          "Tavern causal candidates must be explicitly stated; implication and co-occurrence are insufficient",
        ),
      );
    }
    if (candidate.mechanism.trim().length < 8) {
      issues.push(
        issue(
          "CAUSAL_MECHANISM_INSUFFICIENT",
          `${path}/mechanism`,
          "An explicit causal candidate must explain the supported mechanism",
        ),
      );
    }
    const validateEndpoint = (
      reference: (typeof candidate.cause_refs)[number],
      endpointPath: string,
    ): void => {
      const valid =
        (reference.kind === "event" && eventKeys.has(reference.event_candidate_key)) ||
        (reference.kind === "state_delta" && stateKeys.has(reference.state_candidate_key)) ||
        (reference.kind === "epistemic_state" &&
          epistemicKeys.has(reference.epistemic_candidate_key));
      if (!valid) {
        issues.push(
          issue(
            "CAUSAL_ENDPOINT_UNKNOWN",
            endpointPath,
            "Causal endpoints must resolve inside the same narrative candidate batch",
          ),
        );
      }
    };
    candidate.cause_refs.forEach((reference, refIndex) => {
      validateEndpoint(reference, `${path}/cause_refs/${refIndex}`);
    });
    candidate.effect_refs.forEach((reference, refIndex) => {
      validateEndpoint(reference, `${path}/effect_refs/${refIndex}`);
    });
    const causeSet = new Set(candidate.cause_refs.map(candidateEndpointKey));
    if (candidate.effect_refs.some((reference) => causeSet.has(candidateEndpointKey(reference)))) {
      issues.push(
        issue(
          "CAUSAL_SELF_LOOP",
          path,
          "The same candidate record cannot be both cause and effect in one CausalLink",
        ),
      );
    }
    if (candidate.attribution.kind === "character_belief") {
      issues.push(
        ...validateEntityReferences(
          [candidate.attribution.holder],
          `${path}/attribution/holder`,
          entityKeys,
          knownEntityIds,
        ),
      );
    }
    validateQuotes(candidate.evidence_quotes, `${path}/evidence_quotes`);
    requireDirect(candidate.evidence_quotes, `${path}/evidence_quotes`);
  });

  const allKeySet = new Set(allKeys);
  batch.unresolved_items.forEach((item, index) => {
    item.evidence_ids.forEach((evidenceId, evidenceIndex) => {
      const evidence = evidenceById.get(evidenceId);
      if (evidence === undefined || evidence.revision_id !== context.active_revision_id) {
        issues.push(
          issue(
            "UNRESOLVED_EVIDENCE_UNKNOWN",
            `/unresolved_items/${index}/evidence_ids/${evidenceIndex}`,
            "Unresolved items may only cite active supplied Evidence",
          ),
        );
      }
    });
    item.related_candidate_keys.forEach((key, keyIndex) => {
      if (!allKeySet.has(key)) {
        issues.push(
          issue(
            "UNRESOLVED_CANDIDATE_UNKNOWN",
            `/unresolved_items/${index}/related_candidate_keys/${keyIndex}`,
            "Unresolved item candidate references must resolve inside the same batch",
          ),
        );
      }
    });
  });

  return { validator_version: validatorVersion, accepted: issues.length === 0, issues };
}

/** Validates the frozen v0.2 boundary for historical replay only. */
export function validateNarrativeExtractionCandidateBatchV020(
  value: unknown,
  context: ExtractionCandidateValidationContext,
): NarrativeExtractionCandidateValidationReport {
  return validateNarrativeExtractionCandidateBatchVersion(
    value,
    context,
    "narrative_extraction_candidate_batch",
    "0.2.0",
  );
}

/** Validates the current v0.3 narrative-memory candidate boundary. */
export function validateNarrativeExtractionCandidateBatch(
  value: unknown,
  context: ExtractionCandidateValidationContext,
): NarrativeExtractionCandidateValidationReport {
  return validateNarrativeExtractionCandidateBatchVersion(
    value,
    context,
    "narrative_extraction_candidate_batch_v030",
    "0.3.0",
  );
}

export function validateExtractionCandidateBatch(
  value: unknown,
  context: ExtractionCandidateValidationContext,
): ExtractionCandidateValidationReport {
  const schemaResult = validateWireValue("extraction_candidate_batch", value);
  if (!schemaResult.valid) {
    const details = schemaResult.errors
      .slice(0, 12)
      .map((error) => `${error.instancePath || "/"} ${error.message ?? "is invalid"}`)
      .join("; ");
    return {
      validator_version: "0.1.0",
      accepted: false,
      issues: [issue("EXTRACTION_SCHEMA_INVALID", "/", details)],
    };
  }

  const batch = value as ExtractionCandidateBatch;
  const issues: ExtractionCandidateIssue[] = [];
  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const knownEntityIds = new Set<string>(context.known_entity_ids);
  const candidateEntityKeys = new Set(batch.entities.map((item) => item.candidate_key));
  const sceneKeys = new Set(batch.scenes.map((item) => item.candidate_key));
  const allKeys = [
    ...batch.entities.map((item) => item.candidate_key),
    ...batch.scenes.map((item) => item.candidate_key),
    ...batch.events.map((item) => item.candidate_key),
  ];

  if (batch.source_revision_id !== context.active_revision_id) {
    issues.push(
      issue(
        "EXTRACTION_REVISION_STALE",
        "/source_revision_id",
        "Candidate batch must echo the active frozen source revision",
      ),
    );
  }
  if (new Set(allKeys).size !== allKeys.length) {
    issues.push(
      issue(
        "CANDIDATE_KEY_DUPLICATE",
        "/",
        "Candidate keys must be unique across entities, scenes, and events",
      ),
    );
  }

  batch.entities.forEach((candidate, index) => {
    const path = `/entities/${index}`;
    issues.push(...validateSupportLevel(candidate, path));
    candidate.evidence_quotes.forEach((quote, quoteIndex) => {
      issues.push(
        ...validateEvidenceQuote(
          quote,
          `${path}/evidence_quotes/${quoteIndex}`,
          evidenceById,
          context.active_revision_id,
        ),
      );
    });
  });

  batch.scenes.forEach((candidate, index) => {
    const path = `/scenes/${index}`;
    issues.push(...validateSupportLevel(candidate, path));
    candidate.source_evidence_ids.forEach((evidenceId, evidenceIndex) => {
      const evidence = evidenceById.get(evidenceId);
      if (evidence === undefined || evidence.revision_id !== context.active_revision_id) {
        issues.push(
          issue(
            "SCENE_EVIDENCE_NOT_CURRENT",
            `${path}/source_evidence_ids/${evidenceIndex}`,
            "Scene boundaries may only reference Evidence in the active frozen revision",
          ),
        );
      }
    });
    issues.push(
      ...validateEntityReferences(
        [...candidate.location_refs, ...candidate.participant_refs, ...candidate.focalizers],
        `${path}/entity_refs`,
        candidateEntityKeys,
        knownEntityIds,
      ),
    );
  });

  batch.events.forEach((candidate, index) => {
    const path = `/events/${index}`;
    issues.push(...validateSupportLevel(candidate, path));
    if (!sceneKeys.has(candidate.scene_candidate_key)) {
      issues.push(
        issue(
          "EVENT_SCENE_REF_UNKNOWN",
          `${path}/scene_candidate_key`,
          "Event candidate must belong to a Scene candidate in the same batch",
        ),
      );
    }
    if (!candidate.evidence_quotes.some((quote) => quote.support_role === "direct")) {
      issues.push(
        issue(
          "EVENT_DIRECT_SUPPORT_MISSING",
          `${path}/evidence_quotes`,
          "Event candidates require at least one exact direct-support quote",
        ),
      );
    }
    candidate.evidence_quotes.forEach((quote, quoteIndex) => {
      issues.push(
        ...validateEvidenceQuote(
          quote,
          `${path}/evidence_quotes/${quoteIndex}`,
          evidenceById,
          context.active_revision_id,
        ),
      );
    });
    issues.push(
      ...validateEntityReferences(
        [...candidate.actor_refs, ...candidate.patient_refs, ...candidate.location_refs],
        `${path}/entity_refs`,
        candidateEntityKeys,
        knownEntityIds,
      ),
    );
  });

  const allKeySet = new Set(allKeys);
  batch.unresolved_items.forEach((item, index) => {
    item.evidence_ids.forEach((evidenceId, evidenceIndex) => {
      if (!evidenceById.has(evidenceId)) {
        issues.push(
          issue(
            "UNRESOLVED_EVIDENCE_UNKNOWN",
            `/unresolved_items/${index}/evidence_ids/${evidenceIndex}`,
            "Unresolved items may only cite supplied Evidence",
          ),
        );
      }
    });
    item.related_candidate_keys.forEach((candidateKey, keyIndex) => {
      if (!allKeySet.has(candidateKey)) {
        issues.push(
          issue(
            "UNRESOLVED_CANDIDATE_UNKNOWN",
            `/unresolved_items/${index}/related_candidate_keys/${keyIndex}`,
            "Unresolved item candidate references must resolve inside the same batch",
          ),
        );
      }
    });
  });

  return { validator_version: "0.1.0", accepted: issues.length === 0, issues };
}
