import type { NarraMemId } from "@narramem/core-domain";
import type {
  TavernPrincipalBindingInspection,
  TavernRecallReadOnlyQueryResult,
} from "@narramem/tavern-adapter";

export const NARRAMEM_CHECKPOINT_EVALUATION_CONTROL_SYMBOL =
  "narramem.tavern-checkpoint-evaluation-control.v1" as const;
export const TAVERN_CHECKPOINT_EVALUATION_CONTROL_VERSION = "0.1.0" as const;

const SAFE_REQUEST_ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/u;
const SAFE_CHECKPOINT_ID = /^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/u;
const SOURCE_CHECKSUM = /^[a-f0-9]{64}$/u;

export interface TavernCheckpointEvaluationRequest {
  readonly request_id: string;
  readonly checkpoint_id: string;
  /** Kept only on the current Promise stack; never written to diagnostics or authoritative Source. */
  readonly query_text: string;
  /** Exact active Entity label from the external Gold renderer. */
  readonly principal_external_label: string;
  readonly expected_authoritative_source_checksum: string;
}

export interface TavernCheckpointEvaluationResult {
  readonly control_version: typeof TAVERN_CHECKPOINT_EVALUATION_CONTROL_VERSION;
  readonly request_id: string;
  readonly checkpoint_id: string;
  readonly principal_entity_id: NarraMemId<"entity">;
  readonly content_recorded: false;
  readonly recall: TavernRecallReadOnlyQueryResult;
}

export interface TavernCheckpointEvaluationAudit {
  readonly request_id: string;
  readonly checkpoint_id: string;
  readonly ok: boolean;
  readonly principal_candidate_count: number;
  readonly error_name: string | null;
  readonly content_recorded: false;
}

export interface TavernCheckpointEvaluationControlState {
  readonly control_version: typeof TAVERN_CHECKPOINT_EVALUATION_CONTROL_VERSION;
  readonly request_in_flight: boolean;
  readonly completed_request_count: number;
  readonly failed_request_count: number;
  readonly content_recorded: false;
  readonly result_retained: false;
  readonly dom_bridge_used: false;
}

export interface TavernCheckpointEvaluationRuntimePort {
  inspectPrincipalBinding(): Promise<TavernPrincipalBindingInspection>;
  assembleReadOnlyQuery(request: {
    readonly query_text: string;
    readonly expected_authoritative_source_checksum: string;
    readonly principal_entity_id: NarraMemId<"entity">;
  }): Promise<TavernRecallReadOnlyQueryResult>;
}

export interface TavernCheckpointEvaluationControlHandle {
  readonly control_version: typeof TAVERN_CHECKPOINT_EVALUATION_CONTROL_VERSION;
  getState(): TavernCheckpointEvaluationControlState;
  run(request: TavernCheckpointEvaluationRequest): Promise<TavernCheckpointEvaluationResult>;
}

export class TavernCheckpointEvaluationControlError extends Error {
  constructor(
    readonly code:
      | "INVALID_REQUEST"
      | "RUNTIME_UNAVAILABLE"
      | "REQUEST_IN_FLIGHT"
      | "PRINCIPAL_NOT_UNIQUE",
    message: string,
  ) {
    super(message);
    this.name = "TavernCheckpointEvaluationControlError";
  }
}

function validateRequest(request: TavernCheckpointEvaluationRequest): void {
  if (
    !SAFE_REQUEST_ID.test(request.request_id) ||
    !SAFE_CHECKPOINT_ID.test(request.checkpoint_id) ||
    request.query_text.trim().length === 0 ||
    request.query_text.length > 8_192 ||
    request.principal_external_label.trim().length === 0 ||
    request.principal_external_label.length > 256 ||
    !SOURCE_CHECKSUM.test(request.expected_authoritative_source_checksum)
  ) {
    throw new TavernCheckpointEvaluationControlError(
      "INVALID_REQUEST",
      "Checkpoint evaluation request is malformed",
    );
  }
}

function labelMatches(
  candidate: TavernPrincipalBindingInspection["candidates"][number],
  externalLabel: string,
): boolean {
  return candidate.canonical_label === externalLabel || candidate.aliases.includes(externalLabel);
}

export class TavernCheckpointEvaluationControl implements TavernCheckpointEvaluationControlHandle {
  readonly control_version = TAVERN_CHECKPOINT_EVALUATION_CONTROL_VERSION;
  private requestInFlight = false;
  private completedRequestCount = 0;
  private failedRequestCount = 0;

  constructor(
    private readonly getRuntime: () => TavernCheckpointEvaluationRuntimePort | null,
    private readonly onAudit?: (audit: TavernCheckpointEvaluationAudit) => void,
  ) {}

  getState(): TavernCheckpointEvaluationControlState {
    return {
      control_version: this.control_version,
      request_in_flight: this.requestInFlight,
      completed_request_count: this.completedRequestCount,
      failed_request_count: this.failedRequestCount,
      content_recorded: false,
      result_retained: false,
      dom_bridge_used: false,
    };
  }

  async run(request: TavernCheckpointEvaluationRequest): Promise<TavernCheckpointEvaluationResult> {
    validateRequest(request);
    if (this.requestInFlight) {
      throw new TavernCheckpointEvaluationControlError(
        "REQUEST_IN_FLIGHT",
        "Only one checkpoint evaluation may run at a time",
      );
    }
    const runtime = this.getRuntime();
    if (runtime === null) {
      throw new TavernCheckpointEvaluationControlError(
        "RUNTIME_UNAVAILABLE",
        "Checkpoint evaluation requires the installed product runtime",
      );
    }
    this.requestInFlight = true;
    let principalCandidateCount = 0;
    try {
      const inspection = await runtime.inspectPrincipalBinding();
      const candidates = inspection.candidates.filter((candidate) =>
        labelMatches(candidate, request.principal_external_label),
      );
      principalCandidateCount = candidates.length;
      const principal = candidates[0];
      if (candidates.length !== 1 || principal === undefined) {
        throw new TavernCheckpointEvaluationControlError(
          "PRINCIPAL_NOT_UNIQUE",
          "External principal label must resolve to exactly one active character Entity",
        );
      }
      const recall = await runtime.assembleReadOnlyQuery({
        query_text: request.query_text,
        expected_authoritative_source_checksum: request.expected_authoritative_source_checksum,
        principal_entity_id: principal.entity_id,
      });
      this.completedRequestCount += 1;
      this.onAudit?.({
        request_id: request.request_id,
        checkpoint_id: request.checkpoint_id,
        ok: true,
        principal_candidate_count: principalCandidateCount,
        error_name: null,
        content_recorded: false,
      });
      return {
        control_version: this.control_version,
        request_id: request.request_id,
        checkpoint_id: request.checkpoint_id,
        principal_entity_id: principal.entity_id,
        content_recorded: false,
        recall,
      };
    } catch (error) {
      this.failedRequestCount += 1;
      this.onAudit?.({
        request_id: request.request_id,
        checkpoint_id: request.checkpoint_id,
        ok: false,
        principal_candidate_count: principalCandidateCount,
        error_name: error instanceof Error ? error.name : "UnknownError",
        content_recorded: false,
      });
      throw error;
    } finally {
      this.requestInFlight = false;
    }
  }
}
