function tokenCost(value: unknown): number {
  return Math.max(1, Math.ceil([...JSON.stringify(value)].length / 4));
}

function normalizeLabel(value: string): string {
  return value.normalize("NFKC").trim().toLocaleLowerCase();
}

function groundedEntityIds(
  rawInput: string | undefined,
  entities: readonly Entity[],
): ReadonlySet<NarraMemId<"entity">> {
  if (rawInput === undefined || rawInput.length === 0) return new Set();
  const normalizedInput = rawInput.normalize("NFKC").toLocaleLowerCase();
  const result = new Set<NarraMemId<"entity">>();
  for (const entity of entities) {
    const labels = [entity.canonical_label, ...entity.aliases.map((alias) => alias.label)];
    if (
      labels.some((label) => {
        const normalized = normalizeLabel(label);
        if ([...normalized].length < 2) return false;
        if (/^[a-z0-9 _-]+$/u.test(normalized)) {
          const escaped = normalized.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
          return new RegExp(`(?:^|[^a-z0-9])${escaped}(?:$|[^a-z0-9])`, "u").test(normalizedInput);
        }
        if (normalizedInput.includes(normalized)) return true;
        if (entity.entity_type !== "object" && entity.entity_type !== "place") return false;
        const characters = [...normalized];
        if (characters.length < 3 || !/^\p{Script=Han}+$/u.test(normalized)) return false;
        for (let length = characters.length - 1; length >= 2; length -= 1) {
          const prefix = characters.slice(0, length).join("");
          const suffix = characters.slice(-length).join("");
          if (normalizedInput.includes(prefix) || normalizedInput.includes(suffix)) return true;
        }
        return false;
      })
    ) {
      result.add(entity.entity_id);
    }
  }
  return result;
}

function referencedEntityIds(value: unknown): NarraMemId<"entity">[] {
  const result = new Set<NarraMemId<"entity">>();
  const visit = (candidate: unknown): void => {
    if (typeof candidate === "string") {
      if (getNarraMemIdKind(candidate) === "entity") {
        result.add(candidate as NarraMemId<"entity">);
      }
      return;
    }
    if (Array.isArray(candidate)) {
      for (const item of candidate) visit(item);
      return;
    }
    if (typeof candidate !== "object" || candidate === null) return;
    for (const item of Object.values(candidate)) visit(item);
  };
  visit(value);
  return [...result].sort();
}

function perspectiveSafeEntityContext(
  entity: Entity,
  principalId: NarraMemId<"entity">,
  visibleEntityIds: ReadonlySet<NarraMemId<"entity">>,
  visibleEvidenceIds: ReadonlySet<NarraMemId<"evidence">>,
): RecallEntityContext | null {
  const evidenceIsVisible = (
    spans: readonly { readonly evidence_id: NarraMemId<"evidence"> }[],
  ): boolean => spans.length > 0 && spans.every((span) => visibleEvidenceIds.has(span.evidence_id));
  const labels: string[] = [];
  if (
    entity.entity_id === principalId ||
    visibleEntityIds.has(entity.entity_id) ||
    evidenceIsVisible(entity.identity_evidence)
  ) {
    labels.push(entity.canonical_label);
  }
  for (const alias of entity.aliases) {
    const perspectiveAllowed =
      alias.perspective === undefined ||
      (alias.perspective.kind === "entity" && alias.perspective.entity_id === principalId);
    if (perspectiveAllowed && evidenceIsVisible(alias.evidence)) labels.push(alias.label);
  }
  const uniqueLabels = [...new Set(labels.map((label) => label.trim()).filter(Boolean))];
  if (uniqueLabels.length === 0) return null;
  return {
    entity_id: entity.entity_id,
    entity_type: entity.entity_type,
    labels: uniqueLabels,
  };
}

function eventVisibleToPrincipal(
  event: EventAtom,
  principalId: NarraMemId<"entity">,
  principalScenes: readonly Scene[],
  knownEventIds: ReadonlySet<NarraMemId<"event">>,
): boolean {
  if (
    event.actor_ids.includes(principalId) ||
    (event.patient_ids ?? []).includes(principalId) ||
    knownEventIds.has(event.event_id)
  ) {
    return true;
  }
  return principalScenes.some(
    (scene) =>
      scene.source_range.start.ordinal <= event.source_range.start.ordinal &&
      scene.source_range.end.ordinal >= event.source_range.end.ordinal,
  );
}

function activeThread(thread: NarrativeThread): boolean {
  return ["latent", "open", "armed", "triggered"].includes(thread.state);
}

function recallableImpact(impact: FutureImpact): boolean {
  return ["armed", "matched"].includes(impact.state);
}

function recordValues<T>(
  records: readonly TavernArchiveRecord[],
  recordKind: string,
  schemaName: Parameters<typeof validateWireValue>[0],
  idOf: (value: T) => NarraMemId,
): T[] {
  const values: T[] = [];
  const seen = new Set<NarraMemId>();
  for (const record of records) {
    if (record.record_kind !== recordKind) continue;
    const report = validateWireValue(schemaName, record.payload);
    if (!report.valid) {
      throw new TavernRecallError(
        "ARCHIVE_CORRUPT",
        `${recordKind} failed Core wire validation: ${report.errors[0]?.message ?? "invalid"}`,
      );
    }
    const value = record.payload as unknown as T;
    const id = idOf(value);
    if (record.record_id !== id || seen.has(id)) {
      throw new TavernRecallError("ARCHIVE_CORRUPT", `Duplicate or mismatched ${recordKind} ID`);
    }
    seen.add(id);
    values.push(value);
  }
  return values;
}

function singleRecord<T>(
  records: readonly TavernArchiveRecord[],
  recordKind: string,
  schemaName: Parameters<typeof validateWireValue>[0],
  idOf: (value: T) => NarraMemId,
): T {
  const values = recordValues(records, recordKind, schemaName, idOf);
  if (values.length !== 1) {
    throw new TavernRecallError(
      "ARCHIVE_CORRUPT",
      `Active archive requires exactly one ${recordKind}`,
    );
  }
  return values[0] as T;
}

function optionalSingleRecord<T>(
  records: readonly TavernArchiveRecord[],
  recordKind: string,
  schemaName: Parameters<typeof validateWireValue>[0],
  idOf: (value: T) => NarraMemId,
): T | null {
  const values = recordValues(records, recordKind, schemaName, idOf);
  if (values.length > 1) {
    throw new TavernRecallError("ARCHIVE_CORRUPT", `Active archive has duplicate ${recordKind}`);
  }
  return values[0] ?? null;
}

function parseCorpus(
  records: readonly TavernArchiveRecord[],
  consumerSafeLifecycleRevisionId?: NarraMemId<"source_revision">,
): RecallCorpus {
  const memorySpace = singleRecord(
    records,
    "core_memory_space_v1",
    "memory_space",
    (value: { readonly memory_space_id: NarraMemId<"memory_space"> }) => value.memory_space_id,
  );
  const revision = singleRecord<SourceRevision>(
    records,
    "core_source_revision_v1",
    "source_revision",
    (value) => value.revision_id,
  );
  const evidence = recordValues<EvidenceItem>(
    records,
    "core_evidence_v1",
    "evidence_item",
    (value) => value.evidence_id,
  );
  const entities = recordValues<Entity>(
    records,
    "core_entity_v1",
    "entity",
    (value) => value.entity_id,
  );
  const scenes = recordValues<Scene>(records, "core_scene_v1", "scene", (value) => value.scene_id);
  const events = recordValues<EventAtom>(
    records,
    "core_event_v1",
    "event_atom",
    (value) => value.event_id,
  );
  const episodes = recordValues<Episode>(
    records,
    "core_episode_v1",
    "episode",
    (value) => value.episode_id,
  );
  const stateAssertions = recordValues<StateAssertion>(
    records,
    "core_state_assertion_v1",
    "state_assertion",
    (value) => value.assertion_id,
  );
  const stateDeltas = recordValues<StateDelta>(
    records,
    "core_state_delta_v1",
    "state_delta",
    (value) => value.delta_id,
  );
  const currentStateView = optionalSingleRecord<CurrentStateView>(
    records,
    "core_current_state_view_v1",
    "current_state_view",
    (value) => value.view_id,
  );
  const propositions = recordValues<Proposition>(
    records,
    "core_proposition_v1",
    "proposition",
    (value) => value.proposition_id,
  );
  const epistemicStates = recordValues<EpistemicState>(
    records,
    "core_epistemic_state_v1",
    "epistemic_state",
    (value) => value.epistemic_id,
  );
  const causalLinks = recordValues<CausalLink>(
    records,
    "core_causal_link_v1",
    "causal_link",
    (value) => value.causal_id,
  );
  const narrativeThreads = recordValues<NarrativeThread>(
    records,
    "core_narrative_thread_v1",
    "narrative_thread",
    (value) => value.thread_id,
  );
  const futureImpacts = recordValues<FutureImpact>(
    records,
    "core_future_impact_v1",
    "future_impact",
    (value) => value.impact_id,
  );
  const typedMemorySpace = memorySpace as {
    readonly memory_space_id: NarraMemId<"memory_space">;
    readonly branch_id: NarraMemId<"branch">;
    readonly active_source_revision_id: NarraMemId<"source_revision">;
  };
  if (
    revision.memory_space_id !== typedMemorySpace.memory_space_id ||
    revision.branch_id !== typedMemorySpace.branch_id ||
    revision.revision_id !== typedMemorySpace.active_source_revision_id
  ) {
    throw new TavernRecallError("ARCHIVE_CORRUPT", "MemorySpace and SourceRevision disagree");
  }
  const activeEvidence = new Set(evidence.map((item) => item.evidence_id));
  const semanticScoped = [
    ...entities,
    ...scenes,
    ...events,
    ...episodes,
    ...stateAssertions,
    ...stateDeltas,
    ...(currentStateView === null ? [] : [currentStateView]),
    ...propositions,
    ...epistemicStates,
    ...causalLinks,
  ];
  if (
    semanticScoped.some(
      (record) =>
        record.memory_space_id !== typedMemorySpace.memory_space_id ||
        record.branch_id !== typedMemorySpace.branch_id ||
        record.derivation.input_revision_id !== revision.revision_id ||
        record.derivation.evidence_refs.some((id) => !activeEvidence.has(id)),
    )
  ) {
    throw new TavernRecallError(
      "ARCHIVE_CORRUPT",
      "A semantic record is stale, foreign, or has inactive Evidence",
    );
  }
  const lifecycleRevisionId = consumerSafeLifecycleRevisionId ?? revision.revision_id;
  if (
    [...narrativeThreads, ...futureImpacts].some(
      (record) =>
        record.memory_space_id !== typedMemorySpace.memory_space_id ||
        record.branch_id !== typedMemorySpace.branch_id ||
        record.derivation.input_revision_id !== lifecycleRevisionId ||
        record.derivation.evidence_refs.some((id) => !activeEvidence.has(id)),
    )
  ) {
    throw new TavernRecallError(
      "ARCHIVE_CORRUPT",
      "A lifecycle record is stale, foreign, or has inactive Evidence",
    );
  }
  if (currentStateView !== null && currentStateView.source_revision_id !== revision.revision_id) {
    throw new TavernRecallError("ARCHIVE_CORRUPT", "CurrentStateView belongs to another revision");
  }
  return {
    memory_space_id: typedMemorySpace.memory_space_id,
    branch_id: typedMemorySpace.branch_id,
    revision,
    evidence,
    entities,
    scenes,
    events,
    episodes,
    state_assertions: stateAssertions,
    state_deltas: stateDeltas,
    current_state_view: currentStateView,
    propositions,
    epistemic_states: epistemicStates,
    causal_links: causalLinks,
    narrative_threads: narrativeThreads,
    future_impacts: futureImpacts,
  };
}

function restrictCorpusToConsumerSafePrefix(
  corpus: RecallCorpus,
  safeEndOrdinal: number,
): RecallCorpus {
  const evidence = corpus.evidence.filter((item) => item.source_order.ordinal <= safeEndOrdinal);
  const evidenceById = new Map(evidence.map((item) => [item.evidence_id, item]));
  const safeEvidenceIds = new Set(evidenceById.keys());
  const entities = corpus.entities.flatMap((entity): Entity[] => {
    const identityEvidence = entity.identity_evidence.filter((span) =>
      safeEvidenceIds.has(span.evidence_id),
    );
    if (identityEvidence.length === 0) return [];
    const latestIdentity = [...identityEvidence]
      .map((span) => evidenceById.get(span.evidence_id))
      .filter((item): item is EvidenceItem => item !== undefined)
      .sort(
        (left, right) =>
          left.source_order.ordinal - right.source_order.ordinal ||
          left.source_order.component - right.source_order.component,
      )
      .at(-1);
    const safeCanonicalLabel = latestIdentity?.speaker_or_emitter?.label ?? entity.canonical_label;
    const aliases = entity.aliases.flatMap((alias) => {
      const aliasEvidence = alias.evidence.filter((span) => safeEvidenceIds.has(span.evidence_id));
      return aliasEvidence.length === 0 || alias.label === safeCanonicalLabel
        ? []
        : [{ ...alias, evidence: aliasEvidence }];
    });
    return [
      {
        ...entity,
        canonical_label: safeCanonicalLabel,
        aliases,
        identity_evidence: identityEvidence,
        derivation: {
          ...entity.derivation,
          evidence_refs: entity.derivation.evidence_refs.filter((id) => safeEvidenceIds.has(id)),
        },
      },
    ];
  });
  const recordEntries = [
    ...entities.map((record) => [record.entity_id, record] as const),
    ...corpus.scenes.map((record) => [record.scene_id, record] as const),
    ...corpus.events.map((record) => [record.event_id, record] as const),
    ...corpus.episodes.map((record) => [record.episode_id, record] as const),
    ...corpus.state_assertions.map((record) => [record.assertion_id, record] as const),
    ...corpus.state_deltas.map((record) => [record.delta_id, record] as const),
    ...corpus.propositions.map((record) => [record.proposition_id, record] as const),
    ...corpus.epistemic_states.map((record) => [record.epistemic_id, record] as const),
    ...corpus.causal_links.map((record) => [record.causal_id, record] as const),
    ...corpus.narrative_threads.map((record) => [record.thread_id, record] as const),
    ...corpus.future_impacts.map((record) => [record.impact_id, record] as const),
    ...(corpus.current_state_view === null
      ? []
      : ([[corpus.current_state_view.view_id, corpus.current_state_view]] as const)),
  ];
  const allIds = new Set<NarraMemId>(recordEntries.map(([id]) => id));
  const selectedIds = new Set<NarraMemId>(entities.map((entity) => entity.entity_id));
  for (const [id, record] of recordEntries) {
    if (getNarraMemIdKind(id) === "entity" || getNarraMemIdKind(id) === "current_state_view") {
      continue;
    }
    if (record.derivation.evidence_refs.every((evidenceId) => safeEvidenceIds.has(evidenceId))) {
      selectedIds.add(id);
    }
  }
  let changed = true;
  while (changed) {
    changed = false;
    for (const [id, record] of recordEntries) {
      if (!selectedIds.has(id)) continue;
      if (
        record.derivation.dependency_refs.some(
          (dependencyId) => allIds.has(dependencyId) && !selectedIds.has(dependencyId),
        )
      ) {
        selectedIds.delete(id);
        changed = true;
      }
    }
  }
  const selected = <T extends { readonly derivation: unknown }>(
    values: readonly T[],
    idOf: (value: T) => NarraMemId,
  ): T[] => values.filter((value) => selectedIds.has(idOf(value)));
  const safeCutoff = evidence
    .map((item) => item.source_order)
    .sort((left, right) => left.ordinal - right.ordinal || left.component - right.component)
    .at(-1) ?? { ordinal: safeEndOrdinal, component: 0 };
  return {
    ...corpus,
    revision: { ...corpus.revision, source_cutoff: safeCutoff },
    evidence,
    entities: entities.filter((entity) => selectedIds.has(entity.entity_id)),
    scenes: selected(corpus.scenes, (record) => record.scene_id),
    events: selected(corpus.events, (record) => record.event_id),
    episodes: selected(corpus.episodes, (record) => record.episode_id),
    state_assertions: selected(corpus.state_assertions, (record) => record.assertion_id),
    state_deltas: selected(corpus.state_deltas, (record) => record.delta_id),
    current_state_view: null,
    propositions: selected(corpus.propositions, (record) => record.proposition_id),
    epistemic_states: selected(corpus.epistemic_states, (record) => record.epistemic_id),
    causal_links: selected(corpus.causal_links, (record) => record.causal_id),
    narrative_threads: selected(corpus.narrative_threads, (record) => record.thread_id),
    future_impacts: selected(corpus.future_impacts, (record) => record.impact_id),
  };
}

function classifySourceAlignment(
  reconciliation: TavernSourceReconciliationResult,
  committed: TavernSourceSnapshot,
  policy: TavernRecallSourcePolicy,
): TavernRecallSourceAlignment {
  if (reconciliation.status === "UNCHANGED") {
    return {
      mode: "EXACT",
      committed_message_count: committed.messages.length,
      live_tail_message_count: 0,
      current_source_checksum: committed.checksum,
    };
  }
  const boundary = reconciliation.dirty_boundary;
  if (
    policy === "ALLOW_APPEND_ONLY_LIVE_TAIL" &&
    reconciliation.status === "CHANGED" &&
    boundary?.reason === "append" &&
    boundary.from_index === committed.messages.length &&
    boundary.invalidated_source_unit_ids.length === 0 &&
    reconciliation.snapshot.messages.length > committed.messages.length
  ) {
    return {
      mode: "APPEND_ONLY_LIVE_TAIL",
      committed_message_count: committed.messages.length,
      live_tail_message_count: reconciliation.snapshot.messages.length - committed.messages.length,
      current_source_checksum: reconciliation.snapshot.checksum,
    };
  }
  throw new TavernRecallError(
    "SOURCE_CHANGED",
    "Current chat is neither exact committed source nor an append-only live tail",
  );
}

function restrictAlignmentToConsumerSafePrefix(
  alignment: TavernRecallSourceAlignment,
  currentMessageCount: number,
  safeMessageCount: number,
  policy: TavernRecallSourcePolicy,
): TavernRecallSourceAlignment {
  if (
    policy !== "ALLOW_APPEND_ONLY_LIVE_TAIL" ||
    safeMessageCount < 1 ||
    safeMessageCount >= currentMessageCount
  ) {
    throw new TavernRecallError(
      "SEMANTIC_COVERAGE_MISMATCH",
      "Recall cannot expose a semantic chunk beyond consumer-safe lifecycle coverage",
    );
  }
  return {
    mode: "APPEND_ONLY_LIVE_TAIL",
    committed_message_count: safeMessageCount,
    live_tail_message_count: currentMessageCount - safeMessageCount,
    current_source_checksum: alignment.current_source_checksum,
  };
}

function principalCandidateIds(corpus: RecallCorpus): ReadonlySet<NarraMemId<"entity">> {
  const ids = new Set<NarraMemId<"entity">>();
  const addPrincipal = (principal: {
    readonly kind: string;
    readonly entity_id?: NarraMemId<"entity">;
  }): void => {
    if (principal.kind === "entity" && principal.entity_id !== undefined)
      ids.add(principal.entity_id);
  };
  for (const scene of corpus.scenes) {
    for (const id of scene.participant_ids) ids.add(id);
    for (const principal of scene.focalizers) addPrincipal(principal);
  }
  for (const event of corpus.events) {
    for (const id of [...event.actor_ids, ...(event.patient_ids ?? [])]) ids.add(id);
  }
  for (const assertion of corpus.state_assertions) addPrincipal(assertion.subject);
  for (const epistemic of corpus.epistemic_states) addPrincipal(epistemic.holder);
  for (const causal of corpus.causal_links) {
    if (causal.holder !== undefined) addPrincipal(causal.holder);
  }
  for (const thread of corpus.narrative_threads) {
    for (const id of thread.participant_ids) ids.add(id);
  }
  for (const impact of corpus.future_impacts) {
    for (const id of impact.target_refs) {
      if (getNarraMemIdKind(id) === "entity") ids.add(id as NarraMemId<"entity">);
    }
  }
  return ids;
}

function resolvePrincipal(
  corpus: RecallCorpus,
  port: TavernHostPort,
  requestedId?: NarraMemId<"entity">,
): Entity {
  if (requestedId !== undefined) {
    const selected = corpus.entities.find(
      (entity) => entity.entity_id === requestedId && entity.entity_type === "character",
    );
    if (selected === undefined) {
      throw new TavernRecallError(
        "PRINCIPAL_UNRESOLVED",
        "Explicit principal is absent or is not a character Entity",
      );
    }
    return selected;
  }
  const characterName = port.getCurrentIdentity().character_name;
  if (characterName === null || characterName.trim().length === 0) {
    throw new TavernRecallError("PRINCIPAL_UNRESOLVED", "Current character name is unavailable");
  }
  const target = normalizeLabel(characterName);
  const eligibleIds = principalCandidateIds(corpus);
  const candidates = corpus.entities.filter(
    (entity) =>
      entity.entity_type === "character" &&
      eligibleIds.has(entity.entity_id) &&
      [entity.canonical_label, ...entity.aliases.map((alias) => alias.label)].some(
        (label) => normalizeLabel(label) === target,
      ),
  );
  if (candidates.length !== 1) {
    throw new TavernRecallError(
      "PRINCIPAL_UNRESOLVED",
      `Current character must resolve to exactly one Entity; found ${candidates.length}`,
    );
  }
  return candidates[0] as Entity;
}

function isPrincipalScene(scene: Scene, principalId: NarraMemId<"entity">): boolean {
  return scene.focalizers.some(
    (focalizer) => focalizer.kind === "entity" && focalizer.entity_id === principalId,
  );
}

function episodeEvents(
  episode: Episode,
  eventsById: ReadonlyMap<NarraMemId<"event">, EventAtom>,
): EventAtom[] {
  return episode.event_ids.map((eventId) => {
    const event = eventsById.get(eventId);
    if (event === undefined) {
      throw new TavernRecallError("ARCHIVE_CORRUPT", "Episode references a missing EventAtom");
    }
    return event;
  });
}

function episodeScenes(
  episode: Episode,
  scenesById: ReadonlyMap<NarraMemId<"scene">, Scene>,
): Scene[] {
  return episode.scene_ids.map((sceneId) => {
    const scene = scenesById.get(sceneId);
    if (scene === undefined) {
      throw new TavernRecallError("ARCHIVE_CORRUPT", "Episode references a missing Scene");
    }
    return scene;
  });
}

function principalHolds(state: EpistemicState, principalId: NarraMemId<"entity">): boolean {
  return state.holder.kind === "entity" && state.holder.entity_id === principalId;
}

function propositionRecordRef(proposition: Proposition): NarraMemId | undefined {
  const argument = proposition.claim.arguments.find((item) => item.kind === "record");
  return argument?.kind === "record" ? argument.record_id : undefined;
}

function causalEndpointId(
  reference: CausalLink["cause_refs"][number] | CausalEffectRef,
): NarraMemId | undefined {
  if (reference.kind === "event") return reference.event_id;
  if (reference.kind === "state_assertion") return reference.assertion_id;
  if (reference.kind === "state_delta") return reference.delta_id;
  if (reference.kind === "epistemic_state") return reference.epistemic_id;
  if (reference.kind === "proposition") return reference.proposition_id;
  if (reference.kind === "narrative_thread") return reference.thread_id;
  return undefined;
}

function causalPath(link: CausalLink): CausalPath | null {
  const start = link.cause_refs[0];
  const end = link.effect_refs[0];
  if (start === undefined || end === undefined) return null;
  return { start_ref: start, end_ref: end, link_refs: [link.causal_id] };
}

function recordSupportPath(
  record: {
    readonly derivation: {
      readonly evidence_refs: readonly NarraMemId<"evidence">[];
      readonly dependency_refs: readonly NarraMemId[];
    };
  },
  targetRef: NarraMemId,
  causalLinkRefs: readonly NarraMemId<"causal_link">[] = [],
): SupportPath {
  return {
    target_ref: targetRef,
    evidence_refs: record.derivation.evidence_refs,
    dependency_refs: record.derivation.dependency_refs,
    causal_link_refs: causalLinkRefs,
  };
}

function excerpt(episode: Episode): EpisodeExcerpt {
  return {
    episode_id: episode.episode_id,
    title: episode.title,
    reconstruction_gist: episode.reconstruction_gist,
    event_refs: episode.event_ids,
    evidence: episode.evidence,
  };
}

function supportPath(episode: Episode): SupportPath {
  return {
    target_ref: episode.episode_id,
    evidence_refs: episode.derivation.evidence_refs,
    dependency_refs: episode.derivation.dependency_refs,
    causal_link_refs: episode.causal_refs,
  };
}

function uniqueByCanonicalValue<T>(values: readonly T[]): T[] {
  const seen = new Set<string>();
  return values.filter((value) => {
    const key = canonicalJson(value);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function visibleEpisodeProjection(
  episode: Episode,
  visibleEvents: readonly EventAtom[],
): { readonly excerpt: EpisodeExcerpt; readonly support_path: SupportPath } {
  if (visibleEvents.length === episode.event_ids.length) {
    return { excerpt: excerpt(episode), support_path: supportPath(episode) };
  }
  const firstAction = visibleEvents[0]?.action_or_occurrence;
  if (firstAction === undefined) {
    throw new TavernRecallError("ARCHIVE_CORRUPT", "A visible Episode projection has no EventAtom");
  }
  return {
    excerpt: {
      episode_id: episode.episode_id,
      title: [...firstAction].slice(0, 80).join(""),
      reconstruction_gist: visibleEvents.map((event) => event.action_or_occurrence).join(" "),
      event_refs: visibleEvents.map((event) => event.event_id),
      evidence: uniqueByCanonicalValue(visibleEvents.flatMap((event) => event.evidence)),
    },
    support_path: {
      target_ref: episode.episode_id,
      evidence_refs: uniqueByCanonicalValue(
        visibleEvents.flatMap((event) => event.derivation.evidence_refs),
      ),
      dependency_refs: uniqueByCanonicalValue(
        visibleEvents.flatMap((event) => [event.event_id, ...event.derivation.dependency_refs]),
      ),
      causal_link_refs: [],
    },
  };
}

async function assemble(
  corpus: RecallCorpus,
  principal: Entity,
  latestRawInput: string | undefined,
  tokenBudget: number,
  sourceAlignment: TavernRecallSourceAlignment,
): Promise<{
  readonly query: RecallQuery;
  readonly bundle: RecallBundle;
  readonly trace: RecallTrace;
}> {
  const scenesById = new Map(corpus.scenes.map((scene) => [scene.scene_id, scene]));
  const eventsById = new Map(corpus.events.map((event) => [event.event_id, event]));
  const propositionsById = new Map(
    corpus.propositions.map((proposition) => [proposition.proposition_id, proposition]),
  );
  const principalEpistemics = corpus.epistemic_states.filter((state) =>
    principalHolds(state, principal.entity_id),
  );
  const knownEventIds = new Set<NarraMemId<"event">>();
  for (const state of principalEpistemics) {
    if (state.mode === "unknown_to") continue;
    const proposition = propositionsById.get(state.proposition_id);
    if (proposition?.claim.predicate !== "event_occurred") continue;
    const recordRef = propositionRecordRef(proposition);
    if (getNarraMemIdKind(recordRef) === "event") {
      knownEventIds.add(recordRef as NarraMemId<"event">);
    }
  }
  const principalScenes = corpus.scenes.filter((scene) =>
    isPrincipalScene(scene, principal.entity_id),
  );
  const visibleEventIds = new Set(
    corpus.events
      .filter((event) =>
        eventVisibleToPrincipal(event, principal.entity_id, principalScenes, knownEventIds),
      )
      .map((event) => event.event_id),
  );
  const visibleDeltaIds = new Set(
    corpus.state_deltas
      .filter((delta) => {
        const eventRefs = [...(delta.caused_by ?? []), ...(delta.cooccurs_with ?? [])];
        return eventRefs.length > 0 && eventRefs.every((eventId) => visibleEventIds.has(eventId));
      })
      .map((delta) => delta.delta_id),
  );
  const visibleThreadIds = new Set(
    corpus.narrative_threads
      .filter(
        (thread) =>
          thread.participant_ids.includes(principal.entity_id) &&
          thread.opened_by.length > 0 &&
          thread.opened_by.every((eventId) => visibleEventIds.has(eventId)),
      )
      .map((thread) => thread.thread_id),
  );
  const entityTypes = new Map(
    corpus.entities.map((entity) => [entity.entity_id, entity.entity_type]),
  );
  const mentionedEntities = groundedEntityIds(latestRawInput, corpus.entities);
  const visible: Array<Omit<EpisodeCandidate, "score">> = [];
  const withheld: NarraMemId[] = [];
  const rejections: RecallRejection[] = [];
  for (const episode of corpus.episodes) {
    const scenes = episodeScenes(episode, scenesById);
    const events = episodeEvents(episode, eventsById);
    const visibleEvents = events.filter((event) => visibleEventIds.has(event.event_id));
    for (const event of events) {
      if (visibleEventIds.has(event.event_id)) continue;
      withheld.push(event.event_id);
      rejections.push({ record_id: event.event_id, reason: "perspective_hidden" });
    }
    if (visibleEvents.length === 0) {
      withheld.push(episode.episode_id);
      rejections.push({ record_id: episode.episode_id, reason: "perspective_hidden" });
      continue;
    }
    const visibleScenes = scenes.filter((scene) =>
      visibleEvents.some(
        (event) =>
          scene.source_range.start.ordinal <= event.source_range.start.ordinal &&
          scene.source_range.end.ordinal >= event.source_range.end.ordinal,
      ),
    );
    const projection = visibleEpisodeProjection(episode, visibleEvents);
    visible.push({
      episode,
      ...projection,
      scenes: visibleScenes,
      events: visibleEvents,
      max_ordinal: Math.max(...visibleEvents.map((event) => event.source_range.end.ordinal)),
    });
  }
  const visibleEvidenceIds = new Set<NarraMemId<"evidence">>(
    visible.flatMap((candidate) => [
      ...candidate.events.flatMap((event) => [
        ...event.derivation.evidence_refs,
        ...event.evidence.map((span) => span.evidence_id),
      ]),
      ...candidate.scenes.flatMap((scene) => scene.derivation.evidence_refs),
    ]),
  );
  const visibleEntityIds = new Set<NarraMemId<"entity">>([
    principal.entity_id,
    ...visible.flatMap((candidate) =>
      candidate.events.flatMap((event) => [
        ...event.actor_ids,
        ...(event.patient_ids ?? []),
        ...(event.location_ids ?? []),
      ]),
    ),
  ]);
  visible.sort(
    (left, right) =>
      right.max_ordinal - left.max_ordinal ||
      left.episode.episode_id.localeCompare(right.episode.episode_id),
  );
  const latest = visible[0];
  const latestScene = latest?.scenes.at(-1);
  const latestEvents = latest?.events ?? [];
  const latestStoryTime = latestEvents.at(-1)?.story_time;
  const latestEventEntityIds = latestEvents.flatMap((event) => [
    ...event.actor_ids,
    ...(event.patient_ids ?? []),
  ]);
  const currentParticipants = new Set(
    latestEventEntityIds.filter((entityId) => {
      const type = entityTypes.get(entityId);
      return type === "character" || type === "group";
    }),
  );
  currentParticipants.add(principal.entity_id);
  const currentObjects = new Set(
    latestEvents
      .flatMap((event) => [
        ...event.actor_ids,
        ...(event.patient_ids ?? []),
        ...(event.location_ids ?? []),
      ])
      .filter((entityId) => entityTypes.get(entityId) === "object"),
  );
  const currentLocations = new Set(
    [
      ...latestEvents.flatMap((event) => event.location_ids ?? []),
      ...(latestScene?.location_ids ?? []),
    ].filter((entityId) => entityTypes.get(entityId) === "place"),
  );
  for (const entityId of mentionedEntities) {
    const type = entityTypes.get(entityId);
    if (type === "character" || type === "group") currentParticipants.add(entityId);
    if (type === "object") currentObjects.add(entityId);
    if (type === "place") currentLocations.add(entityId);
  }
  const mentionedLocations = [...mentionedEntities]
    .filter((entityId) => entityTypes.get(entityId) === "place")
    .sort();
  const currentLocation = mentionedLocations[0] ?? [...currentLocations].sort()[0];
  const currentEventTypes = new Set(latestEvents.map((event) => event.event_type));
  const appendOnlyTail = sourceAlignment.mode === "APPEND_ONLY_LIVE_TAIL";
  const query: RecallQuery = {
    memory_space_id: corpus.memory_space_id,
    branch_id: corpus.branch_id,
    checkpoint: { kind: "source_order", value: corpus.revision.source_cutoff },
    purpose: "continuation",
    current_scene: {
      ...(latestRawInput === undefined
        ? {}
        : { raw_input: { trust_boundary: "untrusted_evidence", content: latestRawInput } }),
      participant_ids: [...currentParticipants].sort(),
      ...(currentObjects.size === 0 ? {} : { object_ids: [...currentObjects].sort() }),
      focalizer_id: principal.entity_id,
      ...(currentLocation === undefined ? {} : { location_id: currentLocation }),
      ...(latestStoryTime === undefined ? {} : { story_time: latestStoryTime }),
      ...(latest === undefined || appendOnlyTail
        ? {}
        : { perceived_event_refs: latest.excerpt.event_refs }),
    },
    requested_perspective: {
      kind: "principal",
      principal: { kind: "entity", entity_id: principal.entity_id },
      consumer: "character_generation",
    },
    token_budget: tokenBudget,
    max_agent_steps: 0,
  };

  const immediateCandidates: EpisodeCandidate[] =
    latest === undefined || appendOnlyTail
      ? []
      : [
          {
            episode: latest.episode,
            excerpt: latest.excerpt,
            support_path: latest.support_path,
            scenes: latest.scenes,
            events: latest.events,
            max_ordinal: latest.max_ordinal,
            score: Number.MAX_SAFE_INTEGER,
          },
        ];
  const echoCandidates: EpisodeCandidate[] = visible
    .slice(latest === undefined || appendOnlyTail ? 0 : 1)
    .map((candidate) => {
      const participants = new Set(
        candidate.events
          .flatMap((event) => [...event.actor_ids, ...(event.patient_ids ?? [])])
          .filter((entityId) => {
            const type = entityTypes.get(entityId);
            return type === "character" || type === "group";
          }),
      );
      participants.delete(principal.entity_id);
      const participantOverlap = [...participants].filter((id) =>
        currentParticipants.has(id),
      ).length;
      const locationOverlap = [
        ...candidate.events.flatMap((event) => event.location_ids ?? []),
        ...candidate.scenes.flatMap((scene) => scene.location_ids),
      ]
        .filter((entityId) => entityTypes.get(entityId) === "place")
        .some((id) => currentLocations.has(id));
      const objectOverlap = candidate.events.some((event) =>
        [...event.actor_ids, ...(event.patient_ids ?? []), ...(event.location_ids ?? [])].some(
          (id) => currentObjects.has(id),
        ),
      );
      const eventTypeOverlap = candidate.events.some((event) =>
        currentEventTypes.has(event.event_type),
      );
      return {
        episode: candidate.episode,
        excerpt: candidate.excerpt,
        support_path: candidate.support_path,
        scenes: candidate.scenes,
        events: candidate.events,
        max_ordinal: candidate.max_ordinal,
        score:
          participantOverlap * 40 +
          (locationOverlap ? 30 : 0) +
          (objectOverlap ? 60 : 0) +
          (eventTypeOverlap ? 20 : 0),
      };
    })
    .filter((candidate) => {
      if (candidate.score > 0) return true;
      rejections.push({ record_id: candidate.episode.episode_id, reason: "low_relevance" });
      return false;
    })
    .sort(
      (left, right) =>
        right.score - left.score ||
        right.max_ordinal - left.max_ordinal ||
        left.episode.episode_id.localeCompare(right.episode.episode_id),
    );

  const currentAssertionIds = new Set(corpus.current_state_view?.assertion_refs ?? []);
  const assertionsById = new Map(
    corpus.state_assertions.map((assertion) => [assertion.assertion_id, assertion]),
  );
  const epistemicStateAssertions = new Set<NarraMemId<"state_assertion">>();
  for (const state of principalEpistemics) {
    if (state.mode !== "knows" && state.mode !== "perceived") continue;
    const proposition = propositionsById.get(state.proposition_id);
    if (proposition?.claim.predicate !== "state_holds") continue;
    const recordRef = propositionRecordRef(proposition);
    if (getNarraMemIdKind(recordRef) === "state_assertion") {
      epistemicStateAssertions.add(recordRef as NarraMemId<"state_assertion">);
    }
  }
  const candidateConstraints = (appendOnlyTail ? [] : [...currentAssertionIds])
    .filter((assertionId) => epistemicStateAssertions.has(assertionId))
    .map((assertionId) => {
      const assertion = assertionsById.get(assertionId);
      if (assertion === undefined) {
        throw new TavernRecallError(
          "ARCHIVE_CORRUPT",
          "CurrentStateView references a missing StateAssertion",
        );
      }
      return assertion;
    })
    .sort((left, right) => left.assertion_id.localeCompare(right.assertion_id));
  const uncertaintyModes = new Set(["suspects", "doubts", "disbelieves", "unknown_to"]);
  const sortedEpistemics = (appendOnlyTail ? [] : [...principalEpistemics]).sort((left, right) =>
    left.epistemic_id.localeCompare(right.epistemic_id),
  );

  const currentConstraints: StateAssertion[] = [];
  const safeBeliefs: EpistemicState[] = [];
  const safeUncertainties: EpistemicState[] = [];
  const safePropositions: Proposition[] = [];
  const immediateContext: EpisodeExcerpt[] = [];
  const experienceEchoes: EpisodeExcerpt[] = [];
  const causalAntecedents: CausalPath[] = [];
  const causalDetails: CausalLink[] = [];
  const activeThreads: NarrativeThread[] = [];
  const matchedImpacts: FutureImpact[] = [];
  const supportPaths: SupportPath[] = [];
  const perspectiveSafeEntities: RecallEntityContext[] = [];
  const selectedEntityIds = new Set<NarraMemId<"entity">>();
  const entityContextsById = new Map(
    corpus.entities.flatMap((entity) => {
      const context = perspectiveSafeEntityContext(
        entity,
        principal.entity_id,
        visibleEntityIds,
        visibleEvidenceIds,
      );
      return context === null ? [] : [[entity.entity_id, context] as const];
    }),
  );
  const unsupportedGaps: Array<RecallTrace["unsupported_gaps"][number]> = [];
  let usedTokens = 0;
  let budgetRejected = false;
  const addEntityContexts = (sources: readonly unknown[]): RecallEntityContext[] => {
    const ids = new Set(sources.flatMap((source) => referencedEntityIds(source)));
    return [...ids]
      .filter((entityId) => !selectedEntityIds.has(entityId))
      .map((entityId) => entityContextsById.get(entityId))
      .filter((context): context is RecallEntityContext => context !== undefined)
      .sort((left, right) => left.entity_id.localeCompare(right.entity_id));
  };
  const consume = (
    value: unknown,
    rejectedIds: readonly NarraMemId[],
    entitySources: readonly unknown[] = [value],
  ): boolean => {
    const newEntityContexts = addEntityContexts(entitySources);
    const cost =
      tokenCost(value) + newEntityContexts.reduce((sum, item) => sum + tokenCost(item), 0);
    if (usedTokens + cost <= tokenBudget) {
      usedTokens += cost;
      for (const context of newEntityContexts) {
        selectedEntityIds.add(context.entity_id);
        perspectiveSafeEntities.push(context);
      }
      return true;
    }
    budgetRejected = true;
    for (const recordId of rejectedIds) {
      rejections.push({ record_id: recordId, reason: "pollution_budget" });
    }
    return false;
  };
  const principalContext = entityContextsById.get(principal.entity_id);
  if (principalContext !== undefined && tokenCost(principalContext) <= tokenBudget) {
    usedTokens += tokenCost(principalContext);
    selectedEntityIds.add(principal.entity_id);
    perspectiveSafeEntities.push(principalContext);
  }
  for (const assertion of candidateConstraints) {
    if (!consume(assertion, [assertion.assertion_id])) continue;
    currentConstraints.push(assertion);
    supportPaths.push(recordSupportPath(assertion, assertion.assertion_id));
  }
  const selectedPropositionIds = new Set<NarraMemId<"proposition">>();
  for (const state of sortedEpistemics) {
    const proposition = propositionsById.get(state.proposition_id);
    if (proposition === undefined) {
      throw new TavernRecallError(
        "ARCHIVE_CORRUPT",
        "EpistemicState references a missing Proposition",
      );
    }
    const discloseProposition = state.mode !== "unknown_to";
    const newProposition =
      discloseProposition && !selectedPropositionIds.has(proposition.proposition_id)
        ? proposition
        : undefined;
    if (
      !consume(newProposition === undefined ? state : { state, proposition: newProposition }, [
        state.epistemic_id,
        ...(newProposition === undefined ? [] : [newProposition.proposition_id]),
      ])
    ) {
      continue;
    }
    const target = uncertaintyModes.has(state.mode) ? safeUncertainties : safeBeliefs;
    target.push(state);
    supportPaths.push(recordSupportPath(state, state.epistemic_id));
    if (newProposition !== undefined) {
      selectedPropositionIds.add(newProposition.proposition_id);
      safePropositions.push(newProposition);
      supportPaths.push(recordSupportPath(newProposition, newProposition.proposition_id));
    } else if (!discloseProposition) {
      withheld.push(proposition.proposition_id);
      rejections.push({ record_id: proposition.proposition_id, reason: "perspective_hidden" });
    }
  }
  const triggerCorpus = {
    revision_id: corpus.revision.revision_id,
    events: corpus.events,
    state_assertions: corpus.state_assertions,
    current_state_view: corpus.current_state_view,
    narrative_threads: corpus.narrative_threads,
    current_state_is_current: !appendOnlyTail,
    checkpoint_includes_current_scene: !appendOnlyTail,
  } as const;
  const queryEntityIds = new Set([
    ...query.current_scene.participant_ids,
    ...(query.current_scene.object_ids ?? []),
    ...(query.current_scene.focalizer_id === undefined ? [] : [query.current_scene.focalizer_id]),
  ]);
  const relatedEpisodeEventIds = new Set(
    [...immediateCandidates, ...echoCandidates].flatMap(
      (candidate) => candidate.excerpt.event_refs,
    ),
  );
  const threadCandidates = corpus.narrative_threads
    .flatMap((thread) => {
      if (!activeThread(thread)) {
        rejections.push({ record_id: thread.thread_id, reason: "low_relevance" });
        return [];
      }
      if (!visibleThreadIds.has(thread.thread_id)) {
        withheld.push(thread.thread_id);
        rejections.push({ record_id: thread.thread_id, reason: "perspective_hidden" });
        return [];
      }
      const evaluations = thread.trigger_rules.map((rule) =>
        evaluateTavernNarrativeTriggerRule(rule, query, triggerCorpus),
      );
      const triggerMatched = evaluations.some((evaluation) => evaluation.result === "eligible");
      const alreadyTriggered = thread.state === "triggered";
      const openingOverlap = thread.opened_by.filter((eventId) =>
        relatedEpisodeEventIds.has(eventId),
      ).length;
      if (!triggerMatched && !alreadyTriggered && openingOverlap === 0) {
        const unknown = evaluations.some((evaluation) => evaluation.result === "unknown");
        rejections.push({
          record_id: thread.thread_id,
          reason: unknown ? "unsupported" : "low_relevance",
        });
        if (unknown) {
          unsupportedGaps.push({
            code: "TAVERN_RECALL_NARRATIVE_THREAD_TRIGGER_UNKNOWN",
            about_refs: [thread.thread_id],
            description:
              "A NarrativeThread trigger could not be resolved from the current structured scene.",
          });
        }
        return [];
      }
      const participantOverlap = thread.participant_ids.filter((entityId) =>
        queryEntityIds.has(entityId),
      ).length;
      return [
        {
          thread,
          score:
            (triggerMatched ? 100 : 0) +
            (alreadyTriggered ? 80 : 0) +
            openingOverlap * 60 +
            participantOverlap * 20,
        },
      ];
    })
    .sort(
      (left, right) =>
        right.score - left.score || left.thread.thread_id.localeCompare(right.thread.thread_id),
    );
  for (const candidate of threadCandidates) {
    if (!consume(candidate.thread, [candidate.thread.thread_id])) continue;
    activeThreads.push(candidate.thread);
    supportPaths.push(recordSupportPath(candidate.thread, candidate.thread.thread_id));
  }
  const priorityScore = {
    background: 50,
    normal: 100,
    important: 200,
    must_consider: 400,
  } as const;
  const impactCandidates = corpus.future_impacts
    .flatMap((impact) => {
      if (!recallableImpact(impact)) {
        rejections.push({ record_id: impact.impact_id, reason: "low_relevance" });
        return [];
      }
      const originVisible =
        impact.origin_refs.length > 0 &&
        impact.origin_refs.every((originRef) => {
          const kind = getNarraMemIdKind(originRef);
          if (kind === "event") return visibleEventIds.has(originRef as NarraMemId<"event">);
          if (kind === "state_delta") {
            return visibleDeltaIds.has(originRef as NarraMemId<"state_delta">);
          }
          return (
            kind === "narrative_thread" &&
            visibleThreadIds.has(originRef as NarraMemId<"narrative_thread">)
          );
        });
      if (!originVisible) {
        withheld.push(impact.impact_id);
        rejections.push({ record_id: impact.impact_id, reason: "perspective_hidden" });
        return [];
      }
      if (
        impact.expires_when !== undefined &&
        evaluateTavernNarrativeTriggerRule(impact.expires_when, query, triggerCorpus).result ===
          "eligible"
      ) {
        rejections.push({ record_id: impact.impact_id, reason: "contradicted" });
        return [];
      }
      const evaluation = evaluateTavernFutureImpact(impact, query, triggerCorpus);
      if (evaluation.result === "unknown") {
        rejections.push({ record_id: impact.impact_id, reason: "unsupported" });
        unsupportedGaps.push({
          code: "TAVERN_RECALL_FUTURE_IMPACT_TRIGGER_UNKNOWN",
          about_refs: [impact.impact_id],
          description:
            "A FutureImpact trigger could not be resolved from the current structured scene.",
        });
        return [];
      }
      if (evaluation.result === "ineligible") {
        rejections.push({ record_id: impact.impact_id, reason: "low_relevance" });
        return [];
      }
      return [{ impact, score: priorityScore[impact.priority] }];
    })
    .sort(
      (left, right) =>
        right.score - left.score || left.impact.impact_id.localeCompare(right.impact.impact_id),
    );
  for (const candidate of impactCandidates) {
    if (!consume(candidate.impact, [candidate.impact.impact_id])) continue;
    matchedImpacts.push(candidate.impact);
    supportPaths.push(recordSupportPath(candidate.impact, candidate.impact.impact_id));
  }
  const includeEpisode = (candidate: EpisodeCandidate, target: EpisodeExcerpt[]): void => {
    if (
      !consume(
        candidate.excerpt,
        [candidate.episode.episode_id],
        [candidate.excerpt, candidate.events],
      )
    )
      return;
    target.push(candidate.excerpt);
    supportPaths.push(candidate.support_path);
  };
  for (const candidate of immediateCandidates) includeEpisode(candidate, immediateContext);
  for (const candidate of echoCandidates) includeEpisode(candidate, experienceEchoes);

  const includedExcerpts = [...immediateContext, ...experienceEchoes];
  const includedEpisodeIds = new Set(includedExcerpts.map((item) => item.episode_id));
  const visibleOutcomeIds = visible
    .filter((candidate) => includedEpisodeIds.has(candidate.episode.episode_id))
    .flatMap((candidate) => candidate.episode.outcome_refs)
    .filter((deltaId) => visibleDeltaIds.has(deltaId));
  const accessibleRecordIds = new Set<NarraMemId>([
    ...includedExcerpts.flatMap((item) => item.event_refs),
    ...visibleOutcomeIds,
    ...currentConstraints.map((assertion) => assertion.assertion_id),
    ...safeBeliefs.map((state) => state.epistemic_id),
    ...safeUncertainties.map((state) => state.epistemic_id),
    ...safePropositions.map((proposition) => proposition.proposition_id),
    ...activeThreads.map((thread) => thread.thread_id),
  ]);
  for (const link of [...corpus.causal_links].sort((left, right) =>
    left.causal_id.localeCompare(right.causal_id),
  )) {
    const holderVisible =
      link.scope === "character_belief" &&
      link.holder?.kind === "entity" &&
      link.holder.entity_id === principal.entity_id;
    const endpointIds = [...link.cause_refs, ...link.effect_refs]
      .map(causalEndpointId)
      .filter((recordId): recordId is NarraMemId => recordId !== undefined);
    if (!holderVisible || endpointIds.some((recordId) => !accessibleRecordIds.has(recordId))) {
      withheld.push(link.causal_id);
      rejections.push({ record_id: link.causal_id, reason: "perspective_hidden" });
      continue;
    }
    const path = causalPath(link);
    if (path === null) continue;
    if (!consume({ path, detail: link }, [link.causal_id])) continue;
    causalAntecedents.push(path);
    causalDetails.push(link);
    supportPaths.push(recordSupportPath(link, link.causal_id, [link.causal_id]));
  }

  const stableKey = await checksumJson({
    query,
    revision_id: corpus.revision.revision_id,
    immediate_episode_ids: immediateContext.map((item) => item.episode_id),
    echo_episode_ids: experienceEchoes.map((item) => item.episode_id),
    state_assertion_ids: currentConstraints.map((item) => item.assertion_id),
    epistemic_ids: [...safeBeliefs, ...safeUncertainties].map((item) => item.epistemic_id),
    proposition_ids: safePropositions.map((item) => item.proposition_id),
    causal_ids: causalDetails.map((item) => item.causal_id),
    thread_ids: activeThreads.map((item) => item.thread_id),
    impact_ids: matchedImpacts.map((item) => item.impact_id),
    entity_ids: perspectiveSafeEntities.map((item) => item.entity_id),
  });
  const bundleId = await createDeterministicNarraMemId(
    "recall_bundle",
    `tavern-recall:${stableKey}`,
  );
  const bundle: RecallBundle = {
    delivery: "consumer_safe",
    bundle_id: bundleId,
    based_on_revision_id: corpus.revision.revision_id,
    perspective: query.requested_perspective,
    perspective_safe_entities: perspectiveSafeEntities,
    current_constraints: currentConstraints,
    perspective_safe_beliefs: safeBeliefs,
    perspective_safe_uncertainties: safeUncertainties,
    perspective_safe_propositions: safePropositions,
    immediate_context: immediateContext,
    causal_antecedents: causalAntecedents,
    causal_details: causalDetails,
    experience_echoes: experienceEchoes,
    active_threads: activeThreads,
    matched_impacts: matchedImpacts,
    visible_contradictions: [],
    visible_evidence_gaps: [],
  };
  const trace: RecallTrace = {
    delivery: "executor_private_never_render",
    trace_id: await createDeterministicNarraMemId(
      "recall_trace",
      `tavern-recall:${stableKey}:trace`,
    ),
    bundle_id: bundleId,
    support_paths: supportPaths,
    withheld_record_ids: [...withheld].sort(),
    rejection_reasons: rejections,
    private_contradictions: [],
    unsupported_gaps: unsupportedGaps,
    assembly_stats: {
      token_count: usedTokens,
      candidates_seen:
        corpus.episodes.length +
        corpus.state_assertions.length +
        corpus.epistemic_states.length +
        corpus.propositions.length +
        corpus.causal_links.length +
        corpus.narrative_threads.length +
        corpus.future_impacts.length,
      records_included:
        currentConstraints.length +
        safeBeliefs.length +
        safeUncertainties.length +
        safePropositions.length +
        immediateContext.length +
        experienceEchoes.length +
        causalDetails.length +
        activeThreads.length +
        matchedImpacts.length,
      agent_steps: 0,
      stop_reason: budgetRejected ? "token_budget_exhausted" : "deterministic_complete",
    },
  };
  for (const [schemaName, value] of [
    ["recall_query", query],
    ["recall_bundle", bundle],
    ["recall_trace", trace],
  ] as const) {
    const report = validateWireValue(schemaName, value);
    if (!report.valid) {
      throw new TavernRecallError(
        "OUTPUT_SCHEMA_INVALID",
        `${schemaName}: ${report.errors[0]?.message ?? "invalid"}`,
      );
    }
  }
  return { query, bundle, trace };
}

export class TavernRecallService {
  private readonly registry: TavernMemoryRegistry;

  constructor(
    private readonly port: TavernHostPort,
    private readonly segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
  ) {
    this.registry = new TavernMemoryRegistry(port);
  }

  async assemble(request: TavernRecallAssemblyRequest): Promise<TavernRecallAssemblyResult> {
    return this.assembleInternal(request, undefined);
  }

  async assembleReadOnlyQuery(
    request: TavernRecallReadOnlyQueryRequest,
  ): Promise<TavernRecallReadOnlyQueryResult> {
    if (request.query_text.trim().length === 0) {
      throw new TavernRecallError("INVALID_INPUT", "Read-only Recall query must not be empty");
    }
    if (!/^[a-f0-9]{64}$/u.test(request.expected_authoritative_source_checksum)) {
      throw new TavernRecallError(
        "INVALID_INPUT",
        "Read-only Recall requires one lowercase SHA-256 authoritative Source checksum",
      );
    }
    const {
      query_text: queryText,
      expected_authoritative_source_checksum: expectedSourceChecksum,
      ...assemblyRequest
    } = request;
    const recall = await this.assembleInternal(
      { ...assemblyRequest, source_policy: "EXACT_ONLY" },
      queryText,
    );
    if (
      recall.source_alignment.mode !== "EXACT" ||
      recall.source_alignment.live_tail_message_count !== 0 ||
      recall.source_alignment.current_source_checksum !== expectedSourceChecksum
    ) {
      throw new TavernRecallError(
        "SOURCE_CHANGED",
        "Read-only Recall authoritative Source does not match the expected exact checkpoint",
      );
    }
    return {
      read_only_query_version: TAVERN_RECALL_READ_ONLY_QUERY_VERSION,
      authoritative_source_checksum: expectedSourceChecksum,
      authoritative_source_unchanged: true,
      recall,
    };
  }

  private async assembleInternal(
    request: TavernRecallAssemblyRequest,
    readOnlyQueryText: string | undefined,
  ): Promise<TavernRecallAssemblyResult> {
    if (
      !Number.isInteger(request.token_budget) ||
      request.token_budget < MIN_TOKEN_BUDGET ||
      request.token_budget > MAX_TOKEN_BUDGET
    ) {
      throw new TavernRecallError(
        "INVALID_INPUT",
        `Recall token budget must be ${MIN_TOKEN_BUDGET}-${MAX_TOKEN_BUDGET}`,
      );
    }
    const resolution = await this.registry.resolveCurrentMemorySetForBoundedRead();
    if (resolution.status !== "EXACT" || resolution.selected === null) {
      throw new TavernRecallError(
        "MEMORY_SET_NOT_EXACT",
        `Recall requires EXACT Memory Set resolution, received ${resolution.status}`,
      );
    }
    const candidate = resolution.selected;
    const memorySetId = candidate.control.memory_set_id;
    const store = new TavernWorldbookSnapshotStore(this.port, {
      memory_set_id: memorySetId,
      control_book_name: candidate.control_book_name,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${memorySetId}__`,
      initial_identity_anchor: candidate.control.identity_anchor,
      max_records_per_segment: this.segmentLimits.max_records_per_segment,
      max_segment_utf8_bytes: this.segmentLimits.max_segment_utf8_bytes,
    });
    const control = candidate.control;
    if (control.active_view === null || control.pending_transaction !== null) {
      throw new TavernRecallError(
        "NO_ACTIVE_VIEW",
        "Recall requires one committed active view and no pending transaction",
      );
    }
    const records = await store.readActiveSnapshot();
    const sourceSnapshot = await reconstructTavernSourceSnapshot(records, memorySetId);
    if (
      sourceSnapshot.source_revision !== control.active_view.source_revision ||
      sourceSnapshot.checksum !== control.active_view.source_checksum
    ) {
      throw new TavernRecallError("ARCHIVE_CORRUPT", "Source manifest disagrees with Control");
    }
    const manifest = readTavernSemanticManifestFromArchive(records);
    if (manifest === null) {
      throw new TavernRecallError(
        "SEMANTIC_COVERAGE_MISSING",
        "Active source has no semantic coverage",
      );
    }
    const sourcePolicy = request.source_policy ?? "EXACT_ONLY";
    const incrementalCoverage = readTavernIncrementalSemanticCoverageFromArchive(records);
    if (incrementalCoverage !== null) {
      await recoverTavernIncrementalSemanticCoverage(incrementalCoverage, sourceSnapshot);
      if (
        incrementalCoverage.semantic_head.source_revision_id !== manifest.source_revision_id ||
        incrementalCoverage.semantic_head.source_checksum !== manifest.source_checksum ||
        incrementalCoverage.semantic_head.semantic_changeset_id !== manifest.changeset_id
      ) {
        throw new TavernRecallError(
          "SEMANTIC_COVERAGE_MISMATCH",
          "Semantic manifest and incremental coverage head disagree",
        );
      }
      const safe = incrementalCoverage.consumer_safe_head;
      if (safe === null) {
        throw new TavernRecallError(
          "SEMANTIC_COVERAGE_MISSING",
          "Incremental semantic coverage has not completed its first lifecycle commit",
        );
      }
      const lifecycleManifest = readTavernNarrativeLifecycleManifestFromArchive(records);
      if (
        lifecycleManifest === null ||
        lifecycleManifest.lifecycle_changeset_id !== safe.lifecycle_changeset_id ||
        lifecycleManifest.semantic_changeset_id !== safe.semantic_changeset_id
      ) {
        throw new TavernRecallError(
          "SEMANTIC_COVERAGE_MISMATCH",
          "Consumer-safe coverage is not backed by the active lifecycle manifest",
        );
      }
    }
    const safeHead = incrementalCoverage?.consumer_safe_head ?? null;
    const hasConsumerUnsafeTail =
      safeHead !== null && safeHead.covered_message_count < sourceSnapshot.messages.length;
    let corpus = parseCorpus(
      records,
      incrementalCoverage?.stage === "semantic_committed" ||
        incrementalCoverage?.stage === "partial_semantic_committed"
        ? safeHead?.source_revision_id
        : undefined,
    );
    const expected = request.expected_semantic_coverage;
    const expectedProvenance = safeHead?.semantic_provenance ?? manifest;
    const coverageMismatches = [
      ...(manifest.source_revision_id === corpus.revision.revision_id ? [] : ["revision"]),
      ...(corpus.revision.snapshot_fingerprint.value === manifest.source_checksum
        ? []
        : ["source_checksum"]),
      ...(expectedProvenance.model_id === expected.requested_model_id ? [] : ["model"]),
      ...(expectedProvenance.model_identity_assurance === expected.model_identity_assurance
        ? []
        : ["model_identity"]),
      ...(expectedProvenance.prompt_contract_version === expected.prompt_asset_ref
        ? []
        : ["prompt_contract"]),
      ...(expectedProvenance.prompt_body_sha256.value === expected.prompt_body_sha256
        ? []
        : ["prompt_body"]),
      ...(expectedProvenance.parameters_hash.value === expected.parameters_sha256
        ? []
        : ["parameters"]),
    ];
    if (coverageMismatches.length > 0) {
      throw new TavernRecallError(
        "SEMANTIC_COVERAGE_MISMATCH",
        `Semantic coverage does not match current source and exact extractor route: ${coverageMismatches.join(",")}`,
      );
    }
    let semanticSourceSnapshot: TavernSourceSnapshot;
    if (manifest.source_checksum === sourceSnapshot.checksum) {
      semanticSourceSnapshot = sourceSnapshot;
    } else {
      const carriedBase = readTavernCarriedSemanticBaseFromArchive(records);
      if (
        sourcePolicy !== "ALLOW_APPEND_ONLY_LIVE_TAIL" ||
        carriedBase === null ||
        carriedBase.memory_set_id !== memorySetId ||
        carriedBase.source_checksum !== manifest.source_checksum ||
        carriedBase.source_revision >= sourceSnapshot.source_revision ||
        carriedBase.message_count >= sourceSnapshot.messages.length
      ) {
        throw new TavernRecallError(
          "SEMANTIC_COVERAGE_MISMATCH",
          "Semantic coverage is not an authenticated append-only source prefix",
        );
      }
      semanticSourceSnapshot = {
        schema_version: sourceSnapshot.schema_version,
        memory_set_id: sourceSnapshot.memory_set_id,
        scope: sourceSnapshot.scope,
        source_revision: carriedBase.source_revision,
        messages: sourceSnapshot.messages.slice(0, carriedBase.message_count),
        root_chain_hash: carriedBase.root_chain_hash,
        checksum: carriedBase.source_checksum,
      };
      try {
        await verifyTavernSourceSnapshot(semanticSourceSnapshot);
      } catch (error) {
        throw new TavernRecallError(
          "SEMANTIC_COVERAGE_MISMATCH",
          `Carried semantic source prefix failed integrity verification: ${
            error instanceof Error ? error.message : String(error)
          }`,
        );
      }
    }
    const before = await reconcileTavernSourceSnapshot(this.port, {
      memory_set_id: memorySetId,
      previous_snapshot: semanticSourceSnapshot,
      observed_hints: [],
      ...(request.normalize_semantic_metadata === undefined
        ? {}
        : { normalize_semantic_metadata: request.normalize_semantic_metadata }),
    });
    let sourceAlignment = classifySourceAlignment(before, semanticSourceSnapshot, sourcePolicy);
    if (
      safeHead !== null &&
      (incrementalCoverage?.stage === "semantic_committed" ||
        incrementalCoverage?.stage === "partial_semantic_committed" ||
        hasConsumerUnsafeTail)
    ) {
      const safeMessage = sourceSnapshot.messages[safeHead.covered_message_count - 1];
      if (safeMessage === undefined) {
        throw new TavernRecallError(
          "SEMANTIC_COVERAGE_MISMATCH",
          "Consumer-safe coverage ends outside the active Source",
        );
      }
      corpus = restrictCorpusToConsumerSafePrefix(corpus, safeMessage.message_id_at_capture);
      sourceAlignment = restrictAlignmentToConsumerSafePrefix(
        sourceAlignment,
        before.status === "CHANGED"
          ? before.snapshot.messages.length
          : semanticSourceSnapshot.messages.length,
        safeHead.covered_message_count,
        sourcePolicy,
      );
    }
    const principal = resolvePrincipal(
      corpus,
      this.port,
      request.principal_entity_id ?? control.identity_anchor.principal_binding?.principal_entity_id,
    );
    const currentSnapshot = before.status === "CHANGED" ? before.snapshot : semanticSourceSnapshot;
    const latestRawInput =
      readOnlyQueryText ??
      [...currentSnapshot.messages].reverse().find((message) => message.narrative_text !== null)
        ?.narrative_text;
    const assembled = await assemble(
      corpus,
      principal,
      latestRawInput ?? undefined,
      request.token_budget,
      sourceAlignment,
    );
    const finalControl = await store.readControl();
    const after = await reconcileTavernSourceSnapshot(this.port, {
      memory_set_id: memorySetId,
      previous_snapshot: semanticSourceSnapshot,
      observed_hints: [],
      ...(request.normalize_semantic_metadata === undefined
        ? {}
        : { normalize_semantic_metadata: request.normalize_semantic_metadata }),
    });
    let finalSourceAlignment = classifySourceAlignment(after, semanticSourceSnapshot, sourcePolicy);
    if (
      safeHead !== null &&
      (incrementalCoverage?.stage === "semantic_committed" ||
        incrementalCoverage?.stage === "partial_semantic_committed" ||
        hasConsumerUnsafeTail)
    ) {
      finalSourceAlignment = restrictAlignmentToConsumerSafePrefix(
        finalSourceAlignment,
        after.status === "CHANGED"
          ? after.snapshot.messages.length
          : semanticSourceSnapshot.messages.length,
        safeHead.covered_message_count,
        sourcePolicy,
      );
    }
    if (
      canonicalJson(finalSourceAlignment) !== canonicalJson(sourceAlignment) ||
      finalControl.checksum !== control.checksum ||
      finalControl.active_view?.view_id !== control.active_view.view_id ||
      finalControl.pending_transaction !== null
    ) {
      throw new TavernRecallError("SOURCE_CHANGED", "Source or active view changed during Recall");
    }
    if (
      getNarraMemIdKind(assembled.bundle.bundle_id) !== "recall_bundle" ||
      canonicalJson(assembled.bundle.perspective) !==
        canonicalJson(assembled.query.requested_perspective)
    ) {
      throw new TavernRecallError("OUTPUT_SCHEMA_INVALID", "Recall output identity mismatch");
    }
    return {
      recall_version: TAVERN_RECALL_ENGINE_VERSION,
      memory_set_id: memorySetId,
      control_checksum: control.checksum,
      active_view_id: control.active_view.view_id,
      source_checksum: semanticSourceSnapshot.checksum,
      source_alignment: sourceAlignment,
      principal,
      ...assembled,
    };
  }
}
