import type { RecallBundle } from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";

import {
  TAVERN_RECALL_PROMPT_ADAPTER_VERSION,
  type TavernRecallPromptAdapter,
  type TavernRecallPromptBuildResult,
  TavernRecallPromptError,
  type TavernRenderedRecallPrompt,
  type TavernRuntimeRecallPromptAsset,
} from "./recall-prompt-contracts.js";
import { canonicalJson, sha256HexUtf8 } from "./worldbook-codec.js";

const PROMPT_REF_PATTERN = /^(NM-P[0-9]{4})@([0-9]+\.[0-9]+\.[0-9]+)$/u;
const RECALL_VARIABLE = "{{NARRAMEM:RECALL_CONTEXT_JSON}}";
const ANY_VARIABLE_PATTERN = /\{\{NARRAMEM:[A-Z0-9_]+\}\}/gu;

export const TAVERN_RECALL_PROMPT_ADAPTERS: readonly TavernRecallPromptAdapter[] = [
  {
    adapter_version: TAVERN_RECALL_PROMPT_ADAPTER_VERSION,
    adapter_id: "tavern-gemini-3.1-pro-preview-recall-consumer@0.4.0",
    family: "gemini-3.1-pro-preview",
    prompt_asset_ref: "NM-P0010@0.4.0",
    prompt_body_sha256: "1e7fd150dda16f881e816c484f19157a56a0027ee833800cb34741c39f7a048c",
    status: "candidate",
  },
  {
    adapter_version: TAVERN_RECALL_PROMPT_ADAPTER_VERSION,
    adapter_id: "tavern-mimo-v2.5-pro-recall-consumer@0.2.0",
    family: "mimo-v2.5-pro",
    prompt_asset_ref: "NM-P0011@0.2.0",
    prompt_body_sha256: "f5e94fe8e8aaa0626f92bb551449f12771dbdb360704b314151578fd611170f1",
    status: "candidate",
  },
  {
    adapter_version: TAVERN_RECALL_PROMPT_ADAPTER_VERSION,
    adapter_id: "tavern-kimi-k3-recall-consumer@0.2.0",
    family: "kimi-k3",
    prompt_asset_ref: "NM-P0012@0.2.0",
    prompt_body_sha256: "94363aaf885bd1bf3f4dbf27e2dc8aa312eb30409669388796b1e457374bf3d3",
    status: "candidate",
  },
] as const;

export function resolveTavernRecallPromptAdapter(
  compatibilityRoute: string,
): TavernRecallPromptAdapter {
  if (compatibilityRoute.length === 0 || compatibilityRoute !== compatibilityRoute.trim()) {
    throw new TavernRecallPromptError(
      "UNSUPPORTED_MODEL",
      "Tavern Recall compatibility route must be a non-empty value",
    );
  }
  const matches = TAVERN_RECALL_PROMPT_ADAPTERS.filter(
    (adapter) => adapter.family === compatibilityRoute,
  );
  if (matches.length !== 1) {
    throw new TavernRecallPromptError(
      "UNSUPPORTED_MODEL",
      `No Tavern Recall Prompt adapter for compatibility route: ${compatibilityRoute}`,
    );
  }
  return matches[0] as TavernRecallPromptAdapter;
}

export async function buildTavernRuntimeRecallPromptAsset(
  compatibilityRoute: string,
  body: string,
): Promise<TavernRecallPromptBuildResult> {
  const adapter = resolveTavernRecallPromptAdapter(compatibilityRoute);
  const refMatch = PROMPT_REF_PATTERN.exec(adapter.prompt_asset_ref);
  const variables = body.match(ANY_VARIABLE_PATTERN) ?? [];
  if (
    refMatch === null ||
    body.startsWith("\uFEFF") ||
    body.includes("\r") ||
    variables.length !== 1 ||
    variables[0] !== RECALL_VARIABLE ||
    (await sha256HexUtf8(body)) !== adapter.prompt_body_sha256
  ) {
    throw new TavernRecallPromptError(
      "PROMPT_ASSET_INVALID",
      `Build-time Recall Prompt body does not match ${adapter.prompt_asset_ref}`,
    );
  }
  const promptId = refMatch[1];
  const semanticVersion = refMatch[2];
  if (promptId === undefined || semanticVersion === undefined) {
    throw new TavernRecallPromptError(
      "PROMPT_ASSET_INVALID",
      `Invalid Recall Prompt ref: ${adapter.prompt_asset_ref}`,
    );
  }
  const asset: TavernRuntimeRecallPromptAsset = {
    prompt_asset_ref: adapter.prompt_asset_ref,
    prompt_id: promptId,
    semantic_version: semanticVersion,
    status: adapter.status,
    body,
    body_sha256: adapter.prompt_body_sha256,
    message_role: "system",
    position: "tavern_main_generation.in_chat",
    variables: ["RECALL_CONTEXT_JSON"],
    input_schema: "recall_bundle",
    provider_scope: `model-family:${adapter.family}`,
  };
  return { asset, compatibility_route: adapter.family };
}

function encodeRecallData(bundle: RecallBundle): string {
  return canonicalJson(bundle)
    .replaceAll("&", "\\u0026")
    .replaceAll("<", "\\u003c")
    .replaceAll(">", "\\u003e");
}

export function renderTavernRecallPrompt(
  asset: TavernRuntimeRecallPromptAsset,
  bundle: RecallBundle,
): TavernRenderedRecallPrompt {
  const report = validateWireValue("recall_bundle", bundle);
  if (!report.valid || bundle.delivery !== "consumer_safe") {
    throw new TavernRecallPromptError(
      "RECALL_BUNDLE_INVALID",
      report.errors[0]?.message ?? "Recall injection requires a consumer-safe Bundle",
    );
  }
  const variables = asset.body.match(ANY_VARIABLE_PATTERN) ?? [];
  if (variables.length !== 1 || variables[0] !== RECALL_VARIABLE) {
    throw new TavernRecallPromptError(
      "PROMPT_ASSET_INVALID",
      "Recall Prompt asset must contain exactly the registered variable",
    );
  }
  return {
    prompt_asset_ref: asset.prompt_asset_ref,
    body_sha256: asset.body_sha256,
    bundle_id: bundle.bundle_id,
    content: asset.body.replace(RECALL_VARIABLE, encodeRecallData(bundle)),
  };
}
