import type {
  ExtractionModelEvidence,
  NarrativeIncrementalExtractionModelInput,
} from "@narramem/core-domain";

import { validateWireValue } from "./wire-schema-registry.js";

export interface NarrativeIncrementalInputIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export interface NarrativeIncrementalInputValidationReport {
  readonly validator_version: "0.1.0";
  readonly accepted: boolean;
  readonly issues: readonly NarrativeIncrementalInputIssue[];
}

function issue(code: string, path: string, message: string): NarrativeIncrementalInputIssue {
  return { code, path, message };
}

function compareEvidenceOrder(
  left: ExtractionModelEvidence,
  right: ExtractionModelEvidence,
): number {
  return (
    left.source_order.ordinal - right.source_order.ordinal ||
    left.source_order.component - right.source_order.component
  );
}

function validateEvidenceOrder(
  evidenceItems: readonly ExtractionModelEvidence[],
  path: string,
): NarrativeIncrementalInputIssue[] {
  const issues: NarrativeIncrementalInputIssue[] = [];
  for (let index = 1; index < evidenceItems.length; index += 1) {
    const previous = evidenceItems[index - 1];
    const current = evidenceItems[index];
    if (
      previous !== undefined &&
      current !== undefined &&
      compareEvidenceOrder(previous, current) > 0
    ) {
      issues.push(
        issue(
          "INCREMENTAL_EVIDENCE_ORDER_INVALID",
          `${path}/${index}/source_order`,
          "Evidence must be supplied in non-decreasing source order",
        ),
      );
    }
  }
  return issues;
}

/**
 * Validates the trusted, bounded input assembled before an incremental model call.
 * JSON Schema owns its wire shape; these checks enforce relationships between its
 * coverage boundary and the supplied Evidence arrays.
 */
export function validateNarrativeIncrementalExtractionModelInput(
  value: unknown,
): NarrativeIncrementalInputValidationReport {
  const schemaResult = validateWireValue("narrative_incremental_extraction_model_input", value);
  if (!schemaResult.valid) {
    const details = schemaResult.errors
      .slice(0, 12)
      .map((error) => `${error.instancePath || "/"} ${error.message ?? "is invalid"}`)
      .join("; ");
    return {
      validator_version: "0.1.0",
      accepted: false,
      issues: [issue("INCREMENTAL_INPUT_SCHEMA_INVALID", "/", details)],
    };
  }

  const input = value as NarrativeIncrementalExtractionModelInput;
  const boundary = input.coverage_boundary;
  const issues: NarrativeIncrementalInputIssue[] = [];

  if (
    boundary.context_start_ordinal > boundary.novel_start_ordinal ||
    boundary.novel_start_ordinal > boundary.novel_end_ordinal
  ) {
    issues.push(
      issue(
        "INCREMENTAL_COVERAGE_BOUNDARY_INVALID",
        "/coverage_boundary",
        "Coverage ordinals must satisfy context_start_ordinal <= novel_start_ordinal <= novel_end_ordinal",
      ),
    );
  }

  input.context_evidence.forEach((evidence, index) => {
    if (
      evidence.source_order.ordinal < boundary.context_start_ordinal ||
      evidence.source_order.ordinal >= boundary.novel_start_ordinal
    ) {
      issues.push(
        issue(
          "INCREMENTAL_CONTEXT_EVIDENCE_OUT_OF_RANGE",
          `/context_evidence/${index}/source_order/ordinal`,
          "Context Evidence must be inside the context prefix and strictly before novel_start_ordinal",
        ),
      );
    }
  });

  input.novel_evidence.forEach((evidence, index) => {
    if (
      evidence.source_order.ordinal < boundary.novel_start_ordinal ||
      evidence.source_order.ordinal > boundary.novel_end_ordinal
    ) {
      issues.push(
        issue(
          "INCREMENTAL_NOVEL_EVIDENCE_OUT_OF_RANGE",
          `/novel_evidence/${index}/source_order/ordinal`,
          "Novel Evidence must be inside the inclusive novel coverage interval",
        ),
      );
    }
  });

  const evidenceIds = new Set<string>();
  for (const [path, evidenceItems] of [
    ["/context_evidence", input.context_evidence],
    ["/novel_evidence", input.novel_evidence],
  ] as const) {
    evidenceItems.forEach((evidence, index) => {
      if (evidenceIds.has(evidence.evidence_id)) {
        issues.push(
          issue(
            "INCREMENTAL_EVIDENCE_DUPLICATE",
            `${path}/${index}/evidence_id`,
            "An Evidence ID may appear only once across context and novel input",
          ),
        );
      }
      evidenceIds.add(evidence.evidence_id);
    });
    issues.push(...validateEvidenceOrder(evidenceItems, path));
  }

  return { validator_version: "0.1.0", accepted: issues.length === 0, issues };
}
