import type { NarraMemId } from "@narramem/core-domain";
import type { ExplicitCausalCompletenessFinding } from "@narramem/narrative-compiler";

import { createDeterministicNarraMemId } from "./core-source-projection.js";
import type { TavernSemanticManifestPayload } from "./semantic-archive-contracts.js";
import { canonicalJson, sha256HexUtf8 } from "./worldbook-codec.js";

export const TAVERN_CAUSAL_AUDIT_TASK_MAPPING_VERSION = "0.1.0" as const;

export function createTavernCausalAuditAgentTaskId(
  seed: Pick<TavernCausalAuditTaskSeed, "memory_set_id" | "task_seed_id">,
): Promise<NarraMemId<"investigation">> {
  return createDeterministicNarraMemId(
    "investigation",
    `tavern-causal-audit-agent:${seed.memory_set_id}:${seed.task_seed_id}`,
  );
}

/**
 * Cold-readable seed projected from semantic_manifest_v4. It is not an active
 * Agent task and cannot trigger a model call until a future scheduler persists
 * a separate budgeted execution record.
 */
export interface TavernCausalAuditTaskSeed {
  readonly mapping_version: typeof TAVERN_CAUSAL_AUDIT_TASK_MAPPING_VERSION;
  readonly task_seed_id: string;
  readonly memory_set_id: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly semantic_task_fingerprint: string;
  readonly source_response_sha256: string;
  readonly policy_version: string;
  readonly finding: ExplicitCausalCompletenessFinding;
  readonly execution_policy: "not_scheduled";
  readonly persistent_source: "semantic_manifest_v4";
}

export async function projectTavernCausalAuditTaskSeeds(
  memorySetId: string,
  manifest: TavernSemanticManifestPayload | null,
): Promise<readonly TavernCausalAuditTaskSeed[]> {
  if (memorySetId.length === 0 || memorySetId !== memorySetId.trim()) {
    throw new TypeError("memorySetId must be a non-empty exact identifier");
  }
  if (manifest === null || manifest.quality_audit === null) return [];
  const audit = manifest.quality_audit;
  const seeds = await Promise.all(
    audit.causal_completeness.findings.map(async (finding) => {
      const fingerprint = await sha256HexUtf8(
        canonicalJson({
          mapping_version: TAVERN_CAUSAL_AUDIT_TASK_MAPPING_VERSION,
          memory_set_id: memorySetId,
          source_revision_id: manifest.source_revision_id,
          source_checksum: manifest.source_checksum,
          semantic_task_fingerprint: manifest.task_fingerprint,
          source_response_sha256: audit.source_response_sha256,
          policy_version: audit.causal_completeness.policy_version,
          finding,
        }),
      );
      return {
        mapping_version: TAVERN_CAUSAL_AUDIT_TASK_MAPPING_VERSION,
        task_seed_id: `tavern_causal_audit_seed_${fingerprint}`,
        memory_set_id: memorySetId,
        source_revision_id: manifest.source_revision_id,
        source_checksum: manifest.source_checksum,
        semantic_task_fingerprint: manifest.task_fingerprint,
        source_response_sha256: audit.source_response_sha256,
        policy_version: audit.causal_completeness.policy_version,
        finding,
        execution_policy: "not_scheduled" as const,
        persistent_source: "semantic_manifest_v4" as const,
      };
    }),
  );
  return seeds.sort(
    (left, right) =>
      left.finding.evidence_id.localeCompare(right.finding.evidence_id) ||
      left.finding.start_code_point - right.finding.start_code_point ||
      left.task_seed_id.localeCompare(right.task_seed_id),
  );
}
