import type { CausalLink } from "./causal.js";
import type { Confidence } from "./confidence.js";
import type { Entity, IdentityClaim } from "./entity.js";
import type { EvidenceItem } from "./evidence.js";
import type { Episode, EventAtom, SalienceAssessment, Scene } from "./experience.js";
import type { HashDigest } from "./hash.js";
import type { NarraMemId } from "./ids.js";
import type { Interpretation } from "./interpretation.js";
import type { JsonValue } from "./json.js";
import type { SourceRevision } from "./memory-space.js";
import type { FutureImpact, NarrativeThread } from "./narrative.js";
import type { EpistemicState, InformationTransfer, Proposition } from "./perspective.js";
import type { DerivationMeta } from "./records.js";
import type { CurrentStateView, StateAssertion, StateDelta } from "./state.js";

export const DERIVED_RECORD_KINDS = [
  "scene",
  "episode",
  "event",
  "entity",
  "identity_claim",
  "salience_assessment",
  "state_assertion",
  "state_delta",
  "current_state_view",
  "proposition",
  "epistemic_state",
  "information_transfer",
  "causal_link",
  "narrative_thread",
  "future_impact",
  "interpretation",
  "recall_cue",
] as const;

export type DerivedRecordKind = (typeof DERIVED_RECORD_KINDS)[number];
export type DerivedRecordId = NarraMemId<DerivedRecordKind>;

export const MODEL_INVALIDATABLE_RECORD_KINDS = [
  "scene",
  "episode",
  "event",
  "salience_assessment",
  "state_assertion",
  "state_delta",
  "current_state_view",
  "proposition",
  "epistemic_state",
  "information_transfer",
  "causal_link",
  "narrative_thread",
  "future_impact",
  "interpretation",
  "recall_cue",
] as const;

export type ModelInvalidatableRecordKind = (typeof MODEL_INVALIDATABLE_RECORD_KINDS)[number];
export type ModelInvalidatableRecordId = NarraMemId<ModelInvalidatableRecordKind>;

export type DerivedRecord =
  | Scene
  | Episode
  | EventAtom
  | Entity
  | IdentityClaim
  | SalienceAssessment
  | StateAssertion
  | StateDelta
  | CurrentStateView
  | Proposition
  | EpistemicState
  | InformationTransfer
  | CausalLink
  | NarrativeThread
  | FutureImpact
  | Interpretation
  | RecallCue;

export interface RecallCue {
  readonly cue_id: NarraMemId<"recall_cue">;
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly cue_kind:
    | "entity"
    | "time"
    | "place"
    | "object"
    | "emotion"
    | "thread"
    | "state"
    | "causal_gap"
    | "motif"
    | "lexical"
    | "semantic";
  readonly value: JsonValue;
  readonly target_refs: readonly DerivedRecordId[];
  readonly provenance_refs: readonly NarraMemId[];
  readonly projection_only: true;
  readonly confidence: Confidence;
  readonly derivation: DerivationMeta;
}

export const CHANGE_PRODUCERS = [
  "source_reconciler",
  "deterministic",
  "llm",
  "agent",
  "hybrid",
] as const;

export type ChangeProducer = (typeof CHANGE_PRODUCERS)[number];
export type ModelChangeProducer = Extract<ChangeProducer, "llm" | "agent" | "hybrid">;

export interface AddDerivedOperation {
  readonly op: "add_derived";
  readonly record: DerivedRecord;
}

export interface SupersedeDerivedOperation {
  readonly op: "supersede_derived";
  readonly target_id: ModelInvalidatableRecordId;
  readonly replacement: DerivedRecord;
  readonly reason: string;
}

export interface InvalidateDerivedOperation {
  readonly op: "invalidate_derived";
  readonly target_id: ModelInvalidatableRecordId;
  readonly reason: string;
  readonly evidence_refs: readonly NarraMemId<"evidence">[];
}

export interface ProjectionJobOperation {
  readonly op: "request_projection";
  readonly projection:
    | "current_state"
    | "dependency"
    | "graph"
    | "fulltext"
    | "vector"
    | "recall_cue";
  readonly target_refs: readonly NarraMemId[];
}

export type ModelProposalOperation =
  | AddDerivedOperation
  | SupersedeDerivedOperation
  | InvalidateDerivedOperation
  | ProjectionJobOperation;

export interface DeleteDerivedClosureOperation {
  readonly op: "delete_derived_closure";
  readonly target_ids: readonly DerivedRecordId[];
  readonly root_evidence_ids: readonly NarraMemId<"evidence">[];
  readonly closure_hash: HashDigest;
}

export type SourceReconcilerOperation =
  | { readonly op: "add_source_revision"; readonly revision: SourceRevision }
  | { readonly op: "add_evidence"; readonly evidence: EvidenceItem }
  | { readonly op: "remove_evidence"; readonly evidence_id: NarraMemId<"evidence"> }
  | {
      readonly op: "remove_source_revision";
      readonly revision_id: NarraMemId<"source_revision">;
    }
  | DeleteDerivedClosureOperation
  | ModelProposalOperation;

export interface UnresolvedItem {
  readonly code: string;
  readonly question: string;
  readonly related_refs: readonly NarraMemId[];
  readonly required_evidence: string;
}

interface ChangeSetProposalBase {
  readonly stage: "proposal";
  readonly changeset_id: NarraMemId<"change_set">;
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly based_on_revision_id: NarraMemId<"source_revision">;
  readonly unresolved_items: readonly UnresolvedItem[];
  readonly created_at: string;
}

export interface ModelChangeSetProposal extends ChangeSetProposalBase {
  readonly producer: ModelChangeProducer;
  readonly operations: readonly ModelProposalOperation[];
}

export interface DeterministicChangeSetProposal extends ChangeSetProposalBase {
  readonly producer: "deterministic";
  readonly operations: readonly (ModelProposalOperation | DeleteDerivedClosureOperation)[];
}

export interface SourceReconcilerChangeSetProposal extends ChangeSetProposalBase {
  readonly producer: "source_reconciler";
  readonly operations: readonly SourceReconcilerOperation[];
}

export type ChangeSetProposal =
  | ModelChangeSetProposal
  | DeterministicChangeSetProposal
  | SourceReconcilerChangeSetProposal;

export const VALIDATION_SEVERITIES = ["info", "warning", "error"] as const;

export type ValidationSeverity = (typeof VALIDATION_SEVERITIES)[number];

export interface ValidationIssue {
  readonly code: string;
  readonly severity: ValidationSeverity;
  readonly operation_index?: number;
  readonly record_ref?: NarraMemId;
  readonly message: string;
}

export interface ValidationReport {
  readonly validator_version: string;
  readonly checked_revision_id: NarraMemId<"source_revision">;
  readonly accepted: boolean;
  readonly issues: readonly ValidationIssue[];
}

export interface AuthorizedChangeSet {
  readonly stage: "authorized";
  readonly changeset_id: NarraMemId<"change_set">;
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly based_on_revision_id: NarraMemId<"source_revision">;
  readonly producer: ChangeProducer;
  readonly operations: readonly SourceReconcilerOperation[];
  readonly validation_report: ValidationReport & { readonly accepted: true };
  readonly authorization: {
    readonly committer_version: string;
    readonly policy_hash: HashDigest;
    readonly authorized_at: string;
  };
}

export const PRODUCER_OPERATION_POLICY = {
  source_reconciler: [
    "add_source_revision",
    "add_evidence",
    "remove_evidence",
    "remove_source_revision",
    "delete_derived_closure",
    "add_derived",
    "supersede_derived",
    "invalidate_derived",
    "request_projection",
  ],
  deterministic: [
    "delete_derived_closure",
    "add_derived",
    "supersede_derived",
    "invalidate_derived",
    "request_projection",
  ],
  llm: ["add_derived", "supersede_derived", "invalidate_derived", "request_projection"],
  agent: ["add_derived", "supersede_derived", "invalidate_derived", "request_projection"],
  hybrid: ["add_derived", "supersede_derived", "invalidate_derived", "request_projection"],
} as const satisfies Readonly<Record<ChangeProducer, readonly SourceReconcilerOperation["op"][]>>;

export function isOperationAllowedForProducer(
  producer: ChangeProducer,
  operation: SourceReconcilerOperation["op"],
): boolean {
  return (PRODUCER_OPERATION_POLICY[producer] as readonly string[]).includes(operation);
}
