import { Ajv2020, type ErrorObject, type ValidateFunction } from "ajv/dist/2020.js";
import type { FormatsPlugin } from "ajv-formats";
import * as addFormatsModule from "ajv-formats";

import {
  createWireSchemaReference,
  NARRAMEM_WIRE_SCHEMA_CATALOG,
  WIRE_SCHEMA_NAMES,
  type WireSchemaName,
} from "./wire-schema-catalog.js";

const ajv = new Ajv2020({ allErrors: true, strict: true });
const addFormats = (addFormatsModule as unknown as { readonly default: FormatsPlugin }).default;
addFormats(ajv);
ajv.addSchema(NARRAMEM_WIRE_SCHEMA_CATALOG);

const validators = new Map<WireSchemaName, ValidateFunction>();

for (const name of WIRE_SCHEMA_NAMES) {
  validators.set(name, ajv.compile(createWireSchemaReference(name)));
}

export interface WireValidationResult {
  readonly schema_name: WireSchemaName;
  readonly valid: boolean;
  readonly errors: readonly ErrorObject[];
}

export function getCompiledWireSchemaNames(): readonly WireSchemaName[] {
  return WIRE_SCHEMA_NAMES;
}

export function validateWireValue(
  schemaName: WireSchemaName,
  value: unknown,
): WireValidationResult {
  const validate = validators.get(schemaName);
  if (validate === undefined) {
    throw new Error(`Wire schema was not compiled: ${schemaName}`);
  }

  const valid = validate(value);
  return {
    schema_name: schemaName,
    valid,
    errors: valid ? [] : [...(validate.errors ?? [])],
  };
}
