import type { RecallBundle } from "@narramem/core-domain";

import type { TavernExtractionModelFamily } from "./extraction-job-contracts.js";

export const TAVERN_RECALL_PROMPT_ADAPTER_VERSION = "0.2.0" as const;

export interface TavernRecallPromptAdapter {
  readonly adapter_version: typeof TAVERN_RECALL_PROMPT_ADAPTER_VERSION;
  readonly adapter_id: string;
  readonly family: TavernExtractionModelFamily;
  readonly prompt_asset_ref: string;
  readonly prompt_body_sha256: string;
  readonly status: "candidate";
}

export interface TavernRuntimeRecallPromptAsset {
  readonly prompt_asset_ref: string;
  readonly prompt_id: string;
  readonly semantic_version: string;
  readonly status: "candidate" | "active";
  readonly body: string;
  readonly body_sha256: string;
  readonly message_role: "system";
  readonly position: "tavern_main_generation.in_chat";
  readonly variables: readonly ["RECALL_CONTEXT_JSON"];
  readonly input_schema: "recall_bundle";
  readonly provider_scope: `model-family:${TavernExtractionModelFamily}`;
}

export interface TavernRecallPromptBuildResult {
  readonly asset: TavernRuntimeRecallPromptAsset;
  readonly compatibility_route: TavernExtractionModelFamily;
}

export interface TavernRenderedRecallPrompt {
  readonly prompt_asset_ref: string;
  readonly body_sha256: string;
  readonly bundle_id: RecallBundle["bundle_id"];
  readonly content: string;
}

export class TavernRecallPromptError extends Error {
  constructor(
    readonly code: "UNSUPPORTED_MODEL" | "PROMPT_ASSET_INVALID" | "RECALL_BUNDLE_INVALID",
    message: string,
  ) {
    super(message);
    this.name = "TavernRecallPromptError";
  }
}
