export const TAVERN_EXTRACTION_ATTEMPT_LEDGER_VERSION = "0.1.0" as const;
export const TAVERN_EXTRACTION_ATTEMPT_LEDGER_FORMAT =
  "narramem.tavern-extraction-attempt-ledger" as const;

export type TavernExtractionAttemptStatus =
  | "dispatched"
  | "retryable_failure"
  | "terminal_failure"
  | "committed"
  | "cancelled"
  | "superseded"
  | "unknown_after_dispatch";

export type TavernExtractionAttemptTaskStatus =
  | "ready"
  | "in_flight"
  | "committed"
  | "exhausted"
  | "terminal_failure"
  | "cancelled"
  | "suspended_unknown";

export interface TavernExtractionAttemptRecord {
  readonly attempt_number: number;
  readonly generation_id: string;
  readonly status: TavernExtractionAttemptStatus;
  readonly dispatched_at: string;
  readonly settled_at?: string;
  readonly elapsed_ms?: number;
  readonly response_sha256?: string;
  readonly response_utf8_bytes?: number;
  readonly error_code?: string;
  readonly diagnostic_codes?: readonly string[];
  readonly host_cancel_requested?: boolean;
}

export interface TavernExtractionAttemptTaskDescriptor {
  readonly operation_fingerprint: string;
  readonly semantic_task_fingerprint: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly model_input_sha256: string;
  readonly requested_model_id: string;
  readonly prompt_asset_ref: string;
  readonly prompt_body_sha256: string;
  readonly parameters_sha256: string;
  readonly max_attempts: number;
  readonly created_at: string;
}

export interface TavernExtractionAttemptTaskRecord extends TavernExtractionAttemptTaskDescriptor {
  readonly status: TavernExtractionAttemptTaskStatus;
  readonly attempts: readonly TavernExtractionAttemptRecord[];
  readonly updated_at: string;
}

export interface TavernExtractionAttemptLedgerPayload {
  readonly format: typeof TAVERN_EXTRACTION_ATTEMPT_LEDGER_FORMAT;
  readonly schema_version: typeof TAVERN_EXTRACTION_ATTEMPT_LEDGER_VERSION;
  readonly memory_set_id: string;
  readonly tasks: readonly TavernExtractionAttemptTaskRecord[];
  readonly checksum: string;
}

export type TavernExtractionAttemptFailureStatus = Extract<
  TavernExtractionAttemptStatus,
  "retryable_failure" | "terminal_failure" | "cancelled" | "superseded" | "unknown_after_dispatch"
>;

export class TavernExtractionAttemptLedgerError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "STORE_CORRUPT"
      | "STORE_NOT_FOUND"
      | "WRITE_CONFLICT"
      | "TASK_NOT_FOUND"
      | "TASK_IDENTITY_MISMATCH"
      | "INVALID_TRANSITION",
    message: string,
  ) {
    super(message);
    this.name = "TavernExtractionAttemptLedgerError";
  }
}
