import type {
  CausalLink,
  Entity,
  EpistemicState,
  EventAtom,
  FutureImpact,
  NarraMemId,
  NarrativeThread,
  Scene,
  SourceRevision,
  StateAssertion,
} from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";

import type { TavernHostPort } from "./contracts.js";
import { TavernMemoryRegistry } from "./memory-registry.js";
import {
  TAVERN_PRINCIPAL_BINDING_SERVICE_VERSION,
  type TavernBindPrincipalRequest,
  type TavernPrincipalBindingCandidate,
  TavernPrincipalBindingError,
  type TavernPrincipalBindingInspection,
} from "./principal-binding-contracts.js";
import { readTavernSemanticManifestFromArchive } from "./semantic-archive.js";
import { TavernWorldbookSnapshotStore } from "./worldbook-snapshot-store.js";
import type {
  TavernArchiveRecord,
  TavernControlPayload,
  TavernPrincipalEntityBinding,
} from "./worldbook-store-contracts.js";

const ARCHIVE_BOOK_PREFIX = "NarraMem__ARCHIVE__";

function normalizeLabel(value: string): string {
  return value.normalize("NFKC").trim().toLocaleLowerCase();
}

function validateRecord<T>(
  records: readonly TavernArchiveRecord[],
  recordKind: string,
  schemaName: Parameters<typeof validateWireValue>[0],
  idOf: (value: T) => NarraMemId,
): readonly T[] {
  const result: T[] = [];
  const seen = new Set<NarraMemId>();
  for (const record of records) {
    if (record.record_kind !== recordKind) continue;
    const report = validateWireValue(schemaName, record.payload);
    if (!report.valid) {
      throw new TavernPrincipalBindingError(
        "ARCHIVE_CORRUPT",
        `${recordKind} failed Core validation`,
      );
    }
    const value = record.payload as unknown as T;
    const id = idOf(value);
    if (record.record_id !== id || seen.has(id)) {
      throw new TavernPrincipalBindingError(
        "ARCHIVE_CORRUPT",
        `${recordKind} has a duplicate or mismatched ID`,
      );
    }
    seen.add(id);
    result.push(value);
  }
  return result;
}

function candidate(entity: Entity): TavernPrincipalBindingCandidate {
  return {
    entity_id: entity.entity_id,
    canonical_label: entity.canonical_label,
    aliases: entity.aliases.map((alias) => alias.label),
  };
}

function activePrincipalEntityIds(records: readonly TavernArchiveRecord[]): ReadonlySet<string> {
  const ids = new Set<string>();
  const addPrincipal = (principal: {
    readonly kind: string;
    readonly entity_id?: string;
  }): void => {
    if (principal.kind === "entity" && principal.entity_id !== undefined)
      ids.add(principal.entity_id);
  };
  for (const scene of validateRecord<Scene>(
    records,
    "core_scene_v1",
    "scene",
    (value) => value.scene_id,
  )) {
    for (const id of scene.participant_ids) ids.add(id);
    for (const principal of scene.focalizers) addPrincipal(principal);
  }
  for (const event of validateRecord<EventAtom>(
    records,
    "core_event_v1",
    "event_atom",
    (value) => value.event_id,
  )) {
    for (const id of [...event.actor_ids, ...(event.patient_ids ?? [])]) ids.add(id);
  }
  for (const assertion of validateRecord<StateAssertion>(
    records,
    "core_state_assertion_v1",
    "state_assertion",
    (value) => value.assertion_id,
  )) {
    addPrincipal(assertion.subject);
  }
  for (const epistemic of validateRecord<EpistemicState>(
    records,
    "core_epistemic_state_v1",
    "epistemic_state",
    (value) => value.epistemic_id,
  )) {
    addPrincipal(epistemic.holder);
  }
  for (const causal of validateRecord<CausalLink>(
    records,
    "core_causal_link_v1",
    "causal_link",
    (value) => value.causal_id,
  )) {
    if (causal.holder !== undefined) addPrincipal(causal.holder);
  }
  for (const thread of validateRecord<NarrativeThread>(
    records,
    "core_narrative_thread_v1",
    "narrative_thread",
    (value) => value.thread_id,
  )) {
    for (const id of thread.participant_ids) ids.add(id);
  }
  for (const impact of validateRecord<FutureImpact>(
    records,
    "core_future_impact_v1",
    "future_impact",
    (value) => value.impact_id,
  )) {
    for (const id of impact.target_refs) ids.add(id);
  }
  return ids;
}

function matchesCharacterName(entity: Entity, characterName: string | null): boolean {
  if (characterName === null || characterName.trim().length === 0) return false;
  const target = normalizeLabel(characterName);
  return [entity.canonical_label, ...entity.aliases.map((alias) => alias.label)].some(
    (label) => normalizeLabel(label) === target,
  );
}

export function selectAutomaticTavernPrincipalCandidate(
  characterName: string | null,
  candidates: readonly TavernPrincipalBindingCandidate[],
): NarraMemId<"entity"> | null {
  if (characterName === null || characterName.trim().length === 0) return null;
  const target = normalizeLabel(characterName);
  const matches = candidates.filter((item) =>
    [item.canonical_label, ...item.aliases].some((label) => normalizeLabel(label) === target),
  );
  return matches.length === 1 ? (matches[0]?.entity_id ?? null) : null;
}

interface BindingContext {
  readonly control: TavernControlPayload;
  readonly store: TavernWorldbookSnapshotStore;
  readonly records: readonly TavernArchiveRecord[];
  readonly entities: readonly Entity[];
  readonly revision: SourceRevision | null;
  readonly host_character_id: string;
  readonly host_character_name: string | null;
}

export class TavernPrincipalBindingService {
  private readonly registry: TavernMemoryRegistry;

  constructor(
    private readonly port: TavernHostPort,
    private readonly segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
  ) {
    this.registry = new TavernMemoryRegistry(port);
  }

  async inspect(): Promise<TavernPrincipalBindingInspection> {
    const context = await this.context();
    return this.inspectContext(context);
  }

  async bind(request: TavernBindPrincipalRequest): Promise<TavernPrincipalBindingInspection> {
    const context = await this.context();
    if (
      context.control.checksum !== request.expected_control_checksum ||
      context.control.active_view?.view_id !== request.expected_active_view_id
    ) {
      throw new TavernPrincipalBindingError("STALE_BASE", "Principal binding base changed");
    }
    if (
      readTavernSemanticManifestFromArchive(context.records) === null ||
      context.revision === null
    ) {
      throw new TavernPrincipalBindingError(
        "SEMANTIC_COVERAGE_MISSING",
        "Principal binding requires committed semantic coverage",
      );
    }
    const selected = context.entities.find(
      (entity) =>
        entity.entity_id === request.principal_entity_id && entity.entity_type === "character",
    );
    if (selected === undefined) {
      throw new TavernPrincipalBindingError(
        "INVALID_CANDIDATE",
        "Selected principal is absent or is not a character Entity",
      );
    }
    if (
      request.binding_mode === "automatic_exact_label" &&
      !matchesCharacterName(selected, context.host_character_name)
    ) {
      throw new TavernPrincipalBindingError(
        "CONFIRMATION_REQUIRED",
        "A non-matching character Entity requires explicit user confirmation",
      );
    }
    const binding: TavernPrincipalEntityBinding = {
      binding_version: "0.1.0",
      host_character_id: context.host_character_id,
      principal_entity_id: selected.entity_id,
      principal_entity_label: selected.canonical_label,
      binding_mode: request.binding_mode,
      bound_at_source_revision_id: context.revision.revision_id,
    };
    const updated = await context.store.updateIdentityAnchor({
      expected_control_checksum: context.control.checksum,
      next_identity_anchor: {
        ...context.control.identity_anchor,
        principal_binding: binding,
      },
    });
    return this.inspectContext({ ...context, control: updated });
  }

  async bindAutomaticallyIfUnambiguous(): Promise<TavernPrincipalBindingInspection> {
    const inspection = await this.inspect();
    if (inspection.status !== "AUTO_BIND_AVAILABLE" || inspection.automatic_candidate_id === null) {
      return inspection;
    }
    return this.bind({
      expected_control_checksum: inspection.control_checksum,
      expected_active_view_id: inspection.active_view_id,
      principal_entity_id: inspection.automatic_candidate_id,
      binding_mode: "automatic_exact_label",
    });
  }

  private async context(): Promise<BindingContext> {
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (resolution.status !== "EXACT" || resolution.selected === null) {
      throw new TavernPrincipalBindingError(
        "MEMORY_SET_NOT_EXACT",
        `Principal binding requires EXACT Memory Set resolution, received ${resolution.status}`,
      );
    }
    const selected = resolution.selected;
    const control = selected.control;
    if (control.active_view === null || control.pending_transaction !== null) {
      throw new TavernPrincipalBindingError(
        "NO_ACTIVE_VIEW",
        "Principal binding requires a committed active view and no pending transaction",
      );
    }
    const memorySetId = control.memory_set_id;
    const store = new TavernWorldbookSnapshotStore(this.port, {
      memory_set_id: memorySetId,
      control_book_name: selected.control_book_name,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${memorySetId}__`,
      initial_identity_anchor: control.identity_anchor,
      max_records_per_segment: this.segmentLimits.max_records_per_segment,
      max_segment_utf8_bytes: this.segmentLimits.max_segment_utf8_bytes,
    });
    const records = await store.readActiveSnapshot();
    const finalControl = await store.readControl();
    if (
      finalControl.checksum !== control.checksum ||
      finalControl.active_view?.view_id !== control.active_view.view_id ||
      finalControl.pending_transaction !== null
    ) {
      throw new TavernPrincipalBindingError(
        "STALE_BASE",
        "Memory Set Control changed while principal candidates were read",
      );
    }
    const principalIds = activePrincipalEntityIds(records);
    const entities = validateRecord<Entity>(
      records,
      "core_entity_v1",
      "entity",
      (value) => value.entity_id,
    ).filter((entity) => entity.entity_type === "character" && principalIds.has(entity.entity_id));
    const revisions = validateRecord<SourceRevision>(
      records,
      "core_source_revision_v1",
      "source_revision",
      (value) => value.revision_id,
    );
    if (revisions.length > 1) {
      throw new TavernPrincipalBindingError(
        "ARCHIVE_CORRUPT",
        "Active archive has duplicate SourceRevision records",
      );
    }
    const identity = this.port.getCurrentIdentity();
    const hostCharacterId = control.identity_anchor.character_locator.host_character_id;
    if (identity.character_id !== hostCharacterId) {
      throw new TavernPrincipalBindingError(
        "MEMORY_SET_NOT_EXACT",
        "Active host character no longer matches the Memory Set anchor",
      );
    }
    return {
      control: finalControl,
      store,
      records,
      entities,
      revision: revisions[0] ?? null,
      host_character_id: hostCharacterId,
      host_character_name: identity.character_name,
    };
  }

  private inspectContext(context: BindingContext): TavernPrincipalBindingInspection {
    const hasCoverage = readTavernSemanticManifestFromArchive(context.records) !== null;
    const binding = context.control.identity_anchor.principal_binding ?? null;
    const candidates = context.entities
      .map(candidate)
      .sort((left, right) => left.canonical_label.localeCompare(right.canonical_label));
    const bound =
      binding === null
        ? undefined
        : context.entities.find((entity) => entity.entity_id === binding.principal_entity_id);
    const automaticCandidateId = selectAutomaticTavernPrincipalCandidate(
      context.host_character_name,
      candidates,
    );
    const status = !hasCoverage
      ? "SEMANTIC_COVERAGE_MISSING"
      : binding !== null
        ? bound === undefined
          ? "STALE_BINDING"
          : "BOUND"
        : automaticCandidateId !== null
          ? "AUTO_BIND_AVAILABLE"
          : "CONFIRMATION_REQUIRED";
    return {
      binding_service_version: TAVERN_PRINCIPAL_BINDING_SERVICE_VERSION,
      status,
      memory_set_id: context.control.memory_set_id,
      control_checksum: context.control.checksum,
      active_view_id: context.control.active_view?.view_id ?? "",
      host_character_id: context.host_character_id,
      host_character_name: context.host_character_name,
      binding,
      automatic_candidate_id: status === "AUTO_BIND_AVAILABLE" ? automaticCandidateId : null,
      candidates,
    };
  }
}
