import type { NarraMemId } from "@narramem/core-domain";

import type { TavernPrincipalEntityBinding } from "./worldbook-store-contracts.js";

export const TAVERN_PRINCIPAL_BINDING_SERVICE_VERSION = "0.1.0" as const;

export interface TavernPrincipalBindingCandidate {
  readonly entity_id: NarraMemId<"entity">;
  readonly canonical_label: string;
  readonly aliases: readonly string[];
}

export type TavernPrincipalBindingStatus =
  | "BOUND"
  | "AUTO_BIND_AVAILABLE"
  | "CONFIRMATION_REQUIRED"
  | "STALE_BINDING"
  | "SEMANTIC_COVERAGE_MISSING";

export interface TavernPrincipalBindingInspection {
  readonly binding_service_version: typeof TAVERN_PRINCIPAL_BINDING_SERVICE_VERSION;
  readonly status: TavernPrincipalBindingStatus;
  readonly memory_set_id: string;
  readonly control_checksum: string;
  readonly active_view_id: string;
  readonly host_character_id: string;
  readonly host_character_name: string | null;
  readonly binding: TavernPrincipalEntityBinding | null;
  readonly automatic_candidate_id: NarraMemId<"entity"> | null;
  readonly candidates: readonly TavernPrincipalBindingCandidate[];
}

export interface TavernBindPrincipalRequest {
  readonly expected_control_checksum: string;
  readonly expected_active_view_id: string;
  readonly principal_entity_id: NarraMemId<"entity">;
  readonly binding_mode: "automatic_exact_label" | "user_confirmed";
}

export class TavernPrincipalBindingError extends Error {
  constructor(
    readonly code:
      | "MEMORY_SET_NOT_EXACT"
      | "NO_ACTIVE_VIEW"
      | "SEMANTIC_COVERAGE_MISSING"
      | "ARCHIVE_CORRUPT"
      | "INVALID_CANDIDATE"
      | "CONFIRMATION_REQUIRED"
      | "STALE_BASE",
    message: string,
  ) {
    super(message);
    this.name = "TavernPrincipalBindingError";
  }
}
