import type { NarraMemId } from "./ids.js";

export interface SourceOrder {
  readonly ordinal: number;
  readonly component: number;
}

export function isSourceOrder(value: unknown): value is SourceOrder {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const candidate = value as Partial<SourceOrder>;
  return (
    Number.isSafeInteger(candidate.ordinal) &&
    (candidate.ordinal ?? -1) >= 0 &&
    Number.isSafeInteger(candidate.component) &&
    (candidate.component ?? -1) >= 0
  );
}

export function compareSourceOrder(left: SourceOrder, right: SourceOrder): -1 | 0 | 1 {
  if (left.ordinal !== right.ordinal) {
    return left.ordinal < right.ordinal ? -1 : 1;
  }

  if (left.component === right.component) {
    return 0;
  }

  return left.component < right.component ? -1 : 1;
}

export const TEMPORAL_GRANULARITIES = [
  "instant",
  "scene",
  "day",
  "chapter",
  "era",
  "unknown",
] as const;

export type TemporalGranularity = (typeof TEMPORAL_GRANULARITIES)[number];

export const TEMPORAL_CERTAINTIES = ["exact", "bounded", "relative", "unknown"] as const;

export type TemporalCertainty = (typeof TEMPORAL_CERTAINTIES)[number];

export interface TemporalPoint {
  readonly calendar_id: string;
  readonly value: string;
  readonly ordinal?: number;
}

export interface UncertainInterval {
  readonly start?: TemporalPoint;
  readonly end?: TemporalPoint;
  readonly start_inclusive: boolean;
  readonly end_inclusive: boolean;
}

export const TEMPORAL_RELATION_KINDS = [
  "before",
  "after",
  "overlaps",
  "contains",
  "during",
  "meets",
  "starts",
  "finishes",
] as const;

export type TemporalRelationKind = (typeof TEMPORAL_RELATION_KINDS)[number];

export interface TemporalRelation {
  readonly relation: TemporalRelationKind;
  readonly target_ref: NarraMemId;
}

export interface TemporalExtent {
  readonly story_interval?: UncertainInterval;
  readonly sequence_index?: number;
  readonly relative_to?: readonly TemporalRelation[];
  readonly granularity: TemporalGranularity;
  readonly certainty: TemporalCertainty;
}

export function isIsoInstant(value: unknown): value is string {
  if (typeof value !== "string") {
    return false;
  }

  const timestamp = Date.parse(value);
  return Number.isFinite(timestamp) && value.includes("T");
}
