import type { NarrativeIncrementalExtractionCandidateBatch } from "@narramem/core-domain";
import {
  type NarrativeIncrementalCandidateValidationContext,
  validateNarrativeIncrementalExtractionCandidateBatch,
  validateWireValue,
} from "@narramem/core-validator";

export const TAVERN_INCREMENTAL_CANDIDATE_PARTITION_VERSION = "0.1.0" as const;

export const TAVERN_INCREMENTAL_CANDIDATE_KINDS = [
  "entities",
  "scenes",
  "events",
  "state_transitions",
  "epistemic_states",
  "causal_links",
] as const;

export type TavernIncrementalCandidateKind = (typeof TAVERN_INCREMENTAL_CANDIDATE_KINDS)[number];

type CandidateRecord =
  NarrativeIncrementalExtractionCandidateBatch[TavernIncrementalCandidateKind][number];

interface CandidateSlot {
  readonly kind: TavernIncrementalCandidateKind;
  readonly source_index: number;
  readonly target_key: string;
  readonly candidate_key: string | null;
  readonly value: unknown;
}

export interface TavernIncrementalCandidateQuarantineItem {
  readonly kind: TavernIncrementalCandidateKind;
  readonly source_index: number;
  /** Stable repair selector. Valid candidate keys are used verbatim; malformed keys use a slot selector. */
  readonly target_key: string;
  readonly candidate_key: string | null;
  readonly value: unknown;
  readonly diagnostic_codes: readonly string[];
  readonly diagnostic_paths: readonly string[];
}

export interface TavernIncrementalCandidatePartition {
  readonly partition_version: typeof TAVERN_INCREMENTAL_CANDIDATE_PARTITION_VERSION;
  readonly source_revision_id: NarrativeIncrementalExtractionCandidateBatch["source_revision_id"];
  readonly accepted_batch: NarrativeIncrementalExtractionCandidateBatch;
  readonly accepted_target_keys: readonly string[];
  readonly quarantined: readonly TavernIncrementalCandidateQuarantineItem[];
  readonly total_record_count: number;
}

export interface TavernIncrementalCandidateForcedQuarantine {
  readonly candidate_key: string;
  readonly diagnostic_codes: readonly string[];
  readonly diagnostic_paths: readonly string[];
}

export class TavernIncrementalCandidatePartitionError extends Error {
  constructor(
    readonly code: "BATCH_SHELL_INVALID" | "SOURCE_REVISION_MISMATCH" | "ACCEPTED_REGRESSION",
    message: string,
    readonly diagnostic_codes: readonly string[] = [],
  ) {
    super(message);
    this.name = "TavernIncrementalCandidatePartitionError";
  }
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

function candidateKey(value: unknown): string | null {
  if (!isObject(value) || typeof value.candidate_key !== "string") return null;
  const key = value.candidate_key.trim();
  return key.length === 0 ? null : key;
}

function targetKey(kind: TavernIncrementalCandidateKind, index: number, value: unknown): string {
  return candidateKey(value) ?? `slot:${kind}:${index}`;
}

function emptyBatch(
  sourceRevisionId: NarrativeIncrementalExtractionCandidateBatch["source_revision_id"],
): NarrativeIncrementalExtractionCandidateBatch {
  return {
    contract_version: "0.1.0",
    source_revision_id: sourceRevisionId,
    entities: [],
    scenes: [],
    events: [],
    state_transitions: [],
    epistemic_states: [],
    causal_links: [],
    unresolved_items: [],
  };
}

function batchFromSlots(
  sourceRevisionId: NarrativeIncrementalExtractionCandidateBatch["source_revision_id"],
  slots: readonly CandidateSlot[],
  unresolvedItems: readonly NarrativeIncrementalExtractionCandidateBatch["unresolved_items"][number][],
): NarrativeIncrementalExtractionCandidateBatch {
  const batch = emptyBatch(sourceRevisionId);
  const mutable = {
    entities: [] as CandidateRecord[],
    scenes: [] as CandidateRecord[],
    events: [] as CandidateRecord[],
    state_transitions: [] as CandidateRecord[],
    epistemic_states: [] as CandidateRecord[],
    causal_links: [] as CandidateRecord[],
  };
  for (const slot of slots) mutable[slot.kind].push(slot.value as CandidateRecord);
  return {
    ...batch,
    entities: mutable.entities as NarrativeIncrementalExtractionCandidateBatch["entities"],
    scenes: mutable.scenes as NarrativeIncrementalExtractionCandidateBatch["scenes"],
    events: mutable.events as NarrativeIncrementalExtractionCandidateBatch["events"],
    state_transitions:
      mutable.state_transitions as NarrativeIncrementalExtractionCandidateBatch["state_transitions"],
    epistemic_states:
      mutable.epistemic_states as NarrativeIncrementalExtractionCandidateBatch["epistemic_states"],
    causal_links:
      mutable.causal_links as NarrativeIncrementalExtractionCandidateBatch["causal_links"],
    unresolved_items: unresolvedItems,
  };
}

function diagnosticCode(keyword: string, path: string): string {
  const normalized = path
    .split("/")
    .filter((part) => part.length > 0)
    .join(".");
  return `WIRE.${keyword}:${normalized.length === 0 ? "record" : normalized}`;
}

function pushDiagnostic(
  diagnostics: Map<string, { codes: Set<string>; paths: Set<string> }>,
  target: string,
  code: string,
  path: string,
): void {
  const current = diagnostics.get(target) ?? { codes: new Set<string>(), paths: new Set<string>() };
  current.codes.add(code);
  current.paths.add(path);
  diagnostics.set(target, current);
}

function issueSlot(issuePath: string, slots: readonly CandidateSlot[]): CandidateSlot | null {
  const match =
    /^\/(entities|scenes|events|state_transitions|epistemic_states|causal_links)\/(\d+)(?:\/|$)/u.exec(
      issuePath,
    );
  if (match === null) return null;
  const kind = match[1] as TavernIncrementalCandidateKind;
  const index = Number.parseInt(match[2] ?? "-1", 10);
  return slots.filter((slot) => slot.kind === kind)[index] ?? null;
}

function validateUnresolvedItems(
  sourceRevisionId: NarrativeIncrementalExtractionCandidateBatch["source_revision_id"],
  raw: readonly unknown[],
): readonly NarrativeIncrementalExtractionCandidateBatch["unresolved_items"][number][] {
  return raw.flatMap((value) => {
    const report = validateWireValue("narrative_incremental_extraction_candidate_batch", {
      ...emptyBatch(sourceRevisionId),
      unresolved_items: [value],
    });
    return report.valid
      ? [value as NarrativeIncrementalExtractionCandidateBatch["unresolved_items"][number]]
      : [];
  });
}

/**
 * Produces the maximal dependency-closed valid subset of one parseable incremental response.
 * Invalid siblings are retained verbatim for targeted repair and never poison accepted records.
 */
export function partitionNarrativeIncrementalCandidateBatch(
  value: unknown,
  context: NarrativeIncrementalCandidateValidationContext,
): TavernIncrementalCandidatePartition {
  if (
    !isObject(value) ||
    value.contract_version !== "0.1.0" ||
    typeof value.source_revision_id !== "string" ||
    !TAVERN_INCREMENTAL_CANDIDATE_KINDS.every((kind) => Array.isArray(value[kind])) ||
    !Array.isArray(value.unresolved_items)
  ) {
    throw new TavernIncrementalCandidatePartitionError(
      "BATCH_SHELL_INVALID",
      "Incremental response must expose the version, revision, and all candidate arrays",
      ["INCREMENTAL_BATCH_SHELL_INVALID"],
    );
  }
  if (value.source_revision_id !== context.active_revision_id) {
    throw new TavernIncrementalCandidatePartitionError(
      "SOURCE_REVISION_MISMATCH",
      "Incremental response belongs to a different Source revision",
      ["EXTRACTION_REVISION_STALE"],
    );
  }
  const sourceRevisionId =
    value.source_revision_id as NarrativeIncrementalExtractionCandidateBatch["source_revision_id"];
  const allSlots = TAVERN_INCREMENTAL_CANDIDATE_KINDS.flatMap((kind) =>
    (value[kind] as readonly unknown[]).map((record, sourceIndex) => ({
      kind,
      source_index: sourceIndex,
      target_key: targetKey(kind, sourceIndex, record),
      candidate_key: candidateKey(record),
      value: record,
    })),
  );
  const diagnostics = new Map<string, { codes: Set<string>; paths: Set<string> }>();
  const wireValid: CandidateSlot[] = [];
  for (const slot of allSlots) {
    const report = validateWireValue("narrative_incremental_extraction_candidate_batch", {
      ...emptyBatch(sourceRevisionId),
      [slot.kind]: [slot.value],
    });
    if (report.valid) {
      wireValid.push(slot);
      continue;
    }
    for (const error of report.errors.slice(0, 12)) {
      const path = error.instancePath.length === 0 ? `/${slot.kind}/0` : error.instancePath;
      pushDiagnostic(diagnostics, slot.target_key, diagnosticCode(error.keyword, path), path);
    }
  }

  const byCandidateKey = new Map<string, CandidateSlot[]>();
  for (const slot of wireValid) {
    if (slot.candidate_key === null) continue;
    const duplicates = byCandidateKey.get(slot.candidate_key) ?? [];
    duplicates.push(slot);
    byCandidateKey.set(slot.candidate_key, duplicates);
  }
  const duplicateTargets = new Set<string>();
  for (const duplicates of byCandidateKey.values()) {
    if (duplicates.length < 2) continue;
    for (const slot of duplicates) {
      duplicateTargets.add(slot.target_key);
      pushDiagnostic(
        diagnostics,
        slot.target_key,
        "INCREMENTAL_CANDIDATE_KEY_DUPLICATE",
        `/${slot.kind}/${slot.source_index}/candidate_key`,
      );
    }
  }

  let remaining = wireValid.filter((slot) => !duplicateTargets.has(slot.target_key));
  const wireValidUnresolvedItems = validateUnresolvedItems(
    sourceRevisionId,
    value.unresolved_items as readonly unknown[],
  );
  for (;;) {
    const candidate = batchFromSlots(sourceRevisionId, remaining, []);
    const report = validateNarrativeIncrementalExtractionCandidateBatch(candidate, context);
    if (report.accepted) break;
    const rejectedTargets = new Set<string>();
    for (const issue of report.issues) {
      const slot = issueSlot(issue.path, remaining);
      if (slot === null) {
        if (issue.path === "/source_revision_id") {
          throw new TavernIncrementalCandidatePartitionError(
            "SOURCE_REVISION_MISMATCH",
            issue.message,
            [issue.code],
          );
        }
        continue;
      }
      rejectedTargets.add(slot.target_key);
      pushDiagnostic(diagnostics, slot.target_key, issue.code, issue.path);
    }
    if (rejectedTargets.size === 0) {
      throw new TavernIncrementalCandidatePartitionError(
        "BATCH_SHELL_INVALID",
        `Incremental dependency partition could not localize: ${report.issues
          .map((item) => item.code)
          .join(",")}`,
        report.issues.map((item) => item.code),
      );
    }
    remaining = remaining.filter((slot) => !rejectedTargets.has(slot.target_key));
  }

  const acceptedTargets = new Set(remaining.map((slot) => slot.target_key));
  const acceptedCandidateKeys = new Set(
    remaining.flatMap((slot) => (slot.candidate_key === null ? [] : [slot.candidate_key])),
  );
  const knownEvidenceIds = new Set(context.evidence_items.map((item) => item.evidence_id));
  const unresolvedItems = wireValidUnresolvedItems.filter(
    (item) =>
      item.evidence_ids.every((evidenceId) => knownEvidenceIds.has(evidenceId)) &&
      item.related_candidate_keys.every((key) => acceptedCandidateKeys.has(key)),
  );
  const quarantined = allSlots
    .filter((slot) => !acceptedTargets.has(slot.target_key))
    .map((slot) => {
      const item = diagnostics.get(slot.target_key) ?? {
        codes: new Set(["DEPENDENCY_CLOSURE_BLOCKED"]),
        paths: new Set([`/${slot.kind}/${slot.source_index}`]),
      };
      return {
        kind: slot.kind,
        source_index: slot.source_index,
        target_key: slot.target_key,
        candidate_key: slot.candidate_key,
        value: slot.value,
        diagnostic_codes: [...item.codes].sort(),
        diagnostic_paths: [...item.paths].sort(),
      };
    });
  return {
    partition_version: TAVERN_INCREMENTAL_CANDIDATE_PARTITION_VERSION,
    source_revision_id: sourceRevisionId,
    accepted_batch: batchFromSlots(sourceRevisionId, remaining, unresolvedItems),
    accepted_target_keys: [...acceptedTargets].sort(),
    quarantined,
    total_record_count: allSlots.length,
  };
}

function recordsFromPartition(
  partition: TavernIncrementalCandidatePartition,
): Record<TavernIncrementalCandidateKind, unknown[]> {
  const records = Object.fromEntries(
    TAVERN_INCREMENTAL_CANDIDATE_KINDS.map((kind) => [kind, [...partition.accepted_batch[kind]]]),
  ) as Record<TavernIncrementalCandidateKind, unknown[]>;
  for (const item of partition.quarantined) records[item.kind].push(item.value);
  return records;
}

const DEPENDENCY_ONLY_DIAGNOSTIC_CODES = new Set([
  "DEPENDENCY_CLOSURE_BLOCKED",
  "CANDIDATE_ENTITY_REF_UNKNOWN",
  "EVENT_SCENE_REF_UNKNOWN",
  "NARRATIVE_EVENT_REF_UNKNOWN",
  "EPISTEMIC_EVENT_REF_UNKNOWN",
  "EPISTEMIC_STATE_REF_UNKNOWN",
  "CLAIM_EVENT_REF_UNKNOWN",
  "CLAIM_STATE_REF_UNKNOWN",
  "CAUSAL_ENDPOINT_UNKNOWN",
  "UNRESOLVED_CANDIDATE_UNKNOWN",
  "INCREMENTAL_CANDIDATE_ENTITY_REF_UNKNOWN",
  "INCREMENTAL_CAUSAL_ENDPOINT_UNKNOWN",
  "INCREMENTAL_UNRESOLVED_CANDIDATE_UNKNOWN",
]);

function isDependencyOnlyQuarantine(item: TavernIncrementalCandidateQuarantineItem): boolean {
  return (
    item.diagnostic_codes.length > 0 &&
    item.diagnostic_codes.every((code) => DEPENDENCY_ONLY_DIAGNOSTIC_CODES.has(code))
  );
}

/**
 * Moves compiler/Core-invalid candidates and their newly unclosed dependants out
 * of an otherwise candidate-valid accepted closure. No model call is involved.
 */
export function quarantineNarrativeIncrementalCandidateTargets(
  current: TavernIncrementalCandidatePartition,
  findings: readonly TavernIncrementalCandidateForcedQuarantine[],
  context: NarrativeIncrementalCandidateValidationContext,
): TavernIncrementalCandidatePartition {
  const byKey = new Map(
    findings
      .filter((finding) => finding.candidate_key.length > 0)
      .map((finding) => [finding.candidate_key, finding]),
  );
  if (byKey.size === 0) return current;
  const records = recordsFromPartition(current);
  const forced: TavernIncrementalCandidateQuarantineItem[] = [];
  for (const kind of TAVERN_INCREMENTAL_CANDIDATE_KINDS) {
    records[kind] = records[kind].filter((record, sourceIndex) => {
      const key = candidateKey(record);
      const finding = key === null ? undefined : byKey.get(key);
      if (finding === undefined) return true;
      forced.push({
        kind,
        source_index: sourceIndex,
        target_key: key as string,
        candidate_key: key,
        value: record,
        diagnostic_codes: [...new Set(finding.diagnostic_codes)].sort(),
        diagnostic_paths:
          finding.diagnostic_paths.length === 0
            ? [`/${kind}/${sourceIndex}`]
            : [...new Set(finding.diagnostic_paths)].sort(),
      });
      return false;
    });
  }
  if (forced.length === 0) return current;
  const next = partitionNarrativeIncrementalCandidateBatch(
    {
      contract_version: "0.1.0",
      source_revision_id: current.source_revision_id,
      ...records,
      unresolved_items: current.accepted_batch.unresolved_items,
    },
    context,
  );
  const forcedKeys = new Set(forced.map((item) => item.target_key));
  return {
    ...next,
    quarantined: [
      ...forced,
      ...next.quarantined.filter((item) => !forcedKeys.has(item.target_key)),
    ],
    total_record_count: current.total_record_count,
  };
}

/** Applies only named replacement targets, then re-evaluates the full saved dependency graph. */
export function applyNarrativeIncrementalCandidateRepair(
  current: TavernIncrementalCandidatePartition,
  repairValue: unknown,
  context: NarrativeIncrementalCandidateValidationContext,
): TavernIncrementalCandidatePartition {
  if (!isObject(repairValue)) {
    throw new TavernIncrementalCandidatePartitionError(
      "BATCH_SHELL_INVALID",
      "Targeted repair response is not a JSON object",
      ["REPAIR_BATCH_SHELL_INVALID"],
    );
  }
  if (
    typeof repairValue.source_revision_id === "string" &&
    repairValue.source_revision_id !== current.source_revision_id
  ) {
    throw new TavernIncrementalCandidatePartitionError(
      "SOURCE_REVISION_MISMATCH",
      "Targeted repair response belongs to a different Source revision",
      ["REPAIR_SOURCE_REVISION_STALE"],
    );
  }
  const allowed = new Set(current.quarantined.map((item) => item.candidate_key).filter(Boolean));
  const repairRecords = TAVERN_INCREMENTAL_CANDIDATE_KINDS.flatMap((kind) => {
    const values = repairValue[kind];
    return Array.isArray(values) ? values.map((value) => ({ kind, value })) : [];
  });
  const acceptedKeys = new Set(
    TAVERN_INCREMENTAL_CANDIDATE_KINDS.flatMap((kind) =>
      current.accepted_batch[kind].map((record) => record.candidate_key),
    ),
  );
  const replacements = new Map<string, { kind: TavernIncrementalCandidateKind; value: unknown }>();
  for (const repair of repairRecords) {
    const key = candidateKey(repair.value);
    if (key === null || acceptedKeys.has(key) || !allowed.has(key)) continue;
    replacements.set(key, repair);
  }
  const records = recordsFromPartition(current);
  for (const kind of TAVERN_INCREMENTAL_CANDIDATE_KINDS) {
    records[kind] = records[kind].map((record) => {
      const key = candidateKey(record);
      const replacement = key === null ? undefined : replacements.get(key);
      return replacement?.kind === kind ? replacement.value : record;
    });
  }
  let next = partitionNarrativeIncrementalCandidateBatch(
    {
      contract_version: "0.1.0",
      source_revision_id: current.source_revision_id,
      ...records,
      unresolved_items: current.accepted_batch.unresolved_items,
    },
    context,
  );
  const unrepairedExplicitFailures = current.quarantined.flatMap((item) => {
    if (
      item.candidate_key === null ||
      replacements.has(item.candidate_key) ||
      isDependencyOnlyQuarantine(item)
    ) {
      return [];
    }
    return [
      {
        candidate_key: item.candidate_key,
        diagnostic_codes: item.diagnostic_codes,
        diagnostic_paths: item.diagnostic_paths,
      },
    ];
  });
  next = quarantineNarrativeIncrementalCandidateTargets(next, unrepairedExplicitFailures, context);
  const nextAccepted = new Set(next.accepted_target_keys);
  const lost = current.accepted_target_keys.filter((target) => !nextAccepted.has(target));
  if (lost.length > 0) {
    throw new TavernIncrementalCandidatePartitionError(
      "ACCEPTED_REGRESSION",
      `Targeted repair attempted to invalidate accepted records: ${lost.join(",")}`,
      ["REPAIR_ACCEPTED_REGRESSION"],
    );
  }
  return next;
}

export function createNarrativeIncrementalRepairMaterial(
  partition: TavernIncrementalCandidatePartition,
  context: NarrativeIncrementalCandidateValidationContext,
): Readonly<Record<string, unknown>> {
  const acceptedKeys = new Set(partition.accepted_target_keys);
  const requiredEvidenceIds = new Set<string>();
  for (const item of partition.quarantined) {
    if (!isObject(item.value)) continue;
    const serialized = JSON.stringify(item.value);
    for (const evidence of context.evidence_items) {
      if (serialized.includes(evidence.evidence_id)) requiredEvidenceIds.add(evidence.evidence_id);
    }
  }
  return {
    contract: "narramem.incremental-targeted-repair/0.1.0",
    source_revision_id: partition.source_revision_id,
    targets: partition.quarantined.map((item) => ({
      target_key: item.target_key,
      kind: item.kind,
      candidate_key: item.candidate_key,
      rejected_record: item.value,
      diagnostic_codes: item.diagnostic_codes,
      diagnostic_paths: item.diagnostic_paths,
    })),
    accepted_dependency_summary: TAVERN_INCREMENTAL_CANDIDATE_KINDS.flatMap((kind) =>
      partition.accepted_batch[kind]
        .filter((record) => acceptedKeys.has(record.candidate_key))
        .map((record) => ({ kind, candidate_key: record.candidate_key })),
    ),
    necessary_evidence: context.evidence_items.filter((evidence) =>
      requiredEvidenceIds.has(evidence.evidence_id),
    ),
    output_rule: {
      contract_version: "0.1.0",
      source_revision_id: partition.source_revision_id,
      allowed_candidate_keys: partition.quarantined.flatMap((item) =>
        item.candidate_key === null ? [] : [item.candidate_key],
      ),
      forbidden_candidate_keys: partition.accepted_target_keys,
      non_target_arrays_must_be_empty: true,
    },
  };
}
