import type {
  HashDigest,
  NarraMemId,
  NarrativeIncrementalCoverageBoundary,
} from "@narramem/core-domain";

import type { TavernSourceSnapshot } from "./source-snapshot-contracts.js";
import type { TavernArchiveRecord } from "./worldbook-store-contracts.js";

export const TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_VERSION = "0.2.0" as const;
export const TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_ID =
  "incremental_semantic_coverage" as const;
export const TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_KIND =
  "incremental_semantic_coverage_v2" as const;

export interface TavernCoverageModelProvenance {
  readonly model_id: string;
  readonly model_identity_assurance: "requested_not_attested";
  readonly prompt_contract_version: string;
  readonly prompt_body_sha256: HashDigest;
  readonly parameters_hash: HashDigest;
  readonly validator_version: string;
}

export interface TavernIncrementalSemanticCoverageHead {
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly source_revision: number;
  readonly source_checksum: string;
  readonly source_message_count_at_commit: number;
  readonly chunk_sequence: number;
  readonly covered_message_count: number;
  readonly covered_prefix_chain_hash: string;
  readonly last_covered_source_unit_id: string;
  readonly last_covered_content_fingerprint: string;
  readonly context_start_ordinal: number;
  readonly novel_start_ordinal: number;
  readonly novel_end_ordinal: number;
  readonly previous_semantic_corpus_sha256: string | null;
  readonly semantic_corpus_sha256: string;
  readonly semantic_changeset_id: NarraMemId<"change_set">;
  readonly provenance: TavernCoverageModelProvenance;
}

/** The only prefix that Recall and other consumers may treat as fully committed. */
export interface TavernIncrementalConsumerSafeCoverageHead {
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly source_revision: number;
  readonly source_checksum: string;
  readonly chunk_sequence: number;
  readonly covered_message_count: number;
  readonly covered_prefix_chain_hash: string;
  readonly last_covered_source_unit_id: string;
  readonly last_covered_content_fingerprint: string;
  readonly semantic_corpus_sha256: string;
  readonly semantic_changeset_id: NarraMemId<"change_set">;
  readonly lifecycle_changeset_id: NarraMemId<"change_set">;
  readonly semantic_provenance: TavernCoverageModelProvenance;
  readonly lifecycle_provenance: TavernCoverageModelProvenance;
}

export interface TavernIncrementalSemanticCoveragePayload {
  readonly version: typeof TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_VERSION;
  readonly memory_set_id: string;
  readonly stage: "partial_semantic_committed" | "semantic_committed" | "lifecycle_committed";
  readonly semantic_head: TavernIncrementalSemanticCoverageHead;
  readonly consumer_safe_head: TavernIncrementalConsumerSafeCoverageHead | null;
}

export interface TavernSemanticCoverageCommitRequest {
  readonly source_snapshot: TavernSourceSnapshot;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly boundary: NarrativeIncrementalCoverageBoundary;
  readonly previous_cursor: TavernIncrementalSemanticCoveragePayload | null;
  readonly semantic_corpus_sha256: string;
  readonly semantic_changeset_id: NarraMemId<"change_set">;
  readonly provenance: TavernCoverageModelProvenance;
  readonly completion?: "complete" | "partial_repair_pending";
}

export interface TavernLifecycleCoverageCommitRequest {
  readonly source_snapshot: TavernSourceSnapshot;
  readonly cursor: TavernIncrementalSemanticCoveragePayload;
  readonly lifecycle_changeset_id: NarraMemId<"change_set">;
  readonly provenance: TavernCoverageModelProvenance;
}

export interface TavernIncrementalCoverageRecoveryResult {
  readonly cursor: TavernIncrementalSemanticCoveragePayload;
  readonly source_compatibility: "CURRENT" | "APPEND_COMPATIBLE";
  readonly next_action: "RUN_REPAIR" | "RUN_LIFECYCLE" | "RUN_NEXT_SEMANTIC_CHUNK" | "CAUGHT_UP";
  readonly semantic_covered_message_count: number;
  readonly consumer_safe_covered_message_count: number;
}

export interface TavernIncrementalCoverageArchiveRecoveryRequest {
  readonly records: readonly TavernArchiveRecord[];
  readonly source_snapshot: TavernSourceSnapshot;
}

export class TavernIncrementalSemanticCoverageError extends Error {
  constructor(
    readonly code: "INVALID_INPUT" | "CURSOR_CORRUPT" | "SOURCE_DIVERGED" | "STAGE_CONFLICT",
    message: string,
  ) {
    super(message);
    this.name = "TavernIncrementalSemanticCoverageError";
  }
}
