export interface MemorySetResolutionReport {
  readonly status: string;
  readonly sync?: unknown;
}

/**
 * A SillyTavern chat id is NarraMem's canonical timeline identity.
 *
 * Candidate anchors belong to another chat id (for example the parent of a
 * newly created branch). They must not be attached implicitly: doing so would
 * merge two timelines. Until a separate, explicit migration workflow exists,
 * the product-safe automatic decision is to create a new Memory Set for both
 * an empty match and a candidate-only match.
 */
export function reportRequiresAutomaticCreate(report: MemorySetResolutionReport): boolean {
  if (report.status !== "ACTION_REQUIRED") return false;
  if (typeof report.sync !== "object" || report.sync === null) return false;
  const requiredAction = (report.sync as { readonly required_action?: unknown }).required_action;
  return requiredAction === "CREATE_MEMORY_SET" || requiredAction === "CONFIRM_ANCHOR_CANDIDATE";
}
