import type { TavernJsonValue, TavernMessageRole } from "./contracts.js";

export const TAVERN_SOURCE_SNAPSHOT_VERSION = "0.2.0" as const;

export type TavernMutationHint =
  | "message_sent"
  | "message_received"
  | "message_edited"
  | "message_updated"
  | "message_deleted"
  | "swipe_changed"
  | "swipe_deleted"
  | "reroll"
  | "chat_loaded"
  | "unknown";

export interface TavernSourceScope {
  readonly character_id: string;
  readonly chat_id: string;
}

export interface TavernSourceMessage {
  readonly source_unit_id: string;
  readonly message_id_at_capture: number;
  readonly role: TavernMessageRole;
  readonly speaker_name: string;
  readonly is_hidden: boolean;
  readonly narrative_text: string | null;
  readonly narrative_text_hash: string | null;
  readonly narrative_projection: {
    readonly strategy:
      | "hidden"
      | "raw_selected_content"
      | "assistant_last_complete_content_block"
      | "assistant_configured_content_block_without_html_comments";
    readonly raw_start_code_point: number | null;
    readonly raw_end_code_point: number | null;
  };
  readonly selected_content_hash: string;
  readonly has_swipes: boolean;
  readonly semantic_metadata: TavernJsonValue;
  readonly content_fingerprint: string;
  readonly chain_hash: string;
}

export interface TavernSourceSnapshot {
  readonly schema_version: typeof TAVERN_SOURCE_SNAPSHOT_VERSION;
  readonly memory_set_id: string;
  readonly scope: TavernSourceScope;
  readonly source_revision: number;
  readonly messages: readonly TavernSourceMessage[];
  readonly root_chain_hash: string;
  readonly checksum: string;
}

export type TavernDirtyReason =
  | "initial_snapshot"
  | "append"
  | "edit_or_update"
  | "delete"
  | "swipe_or_reroll"
  | "scope_rebind"
  | "mixed"
  | "unknown_change";

export interface TavernDirtyBoundary {
  readonly reason: TavernDirtyReason;
  readonly observed_hints: readonly TavernMutationHint[];
  readonly from_index: number;
  readonly previous_message_id: number | null;
  readonly current_message_id: number | null;
  readonly previous_message_count: number;
  readonly current_message_count: number;
  readonly invalidated_source_unit_ids: readonly string[];
  readonly requires_tail_rebuild: true;
}

export interface TavernSourceReconciliationResult {
  readonly status: "INITIAL" | "UNCHANGED" | "CHANGED";
  readonly snapshot: TavernSourceSnapshot;
  readonly dirty_boundary: TavernDirtyBoundary | null;
}

export interface TavernSemanticMetadataInput {
  readonly message_id: number;
  readonly role: TavernMessageRole;
  readonly speaker_name: string;
  readonly is_hidden: boolean;
  readonly current_data: Readonly<Record<string, unknown>> | null;
  readonly current_extra: Readonly<Record<string, unknown>> | null;
  readonly selected_swipe_data: Readonly<Record<string, unknown>> | null;
  readonly selected_swipe_info: Readonly<Record<string, unknown>> | null;
}

export type TavernSemanticMetadataNormalizer = (
  input: TavernSemanticMetadataInput,
) => TavernJsonValue;

export interface TavernSourceReconciliationRequest {
  readonly memory_set_id: string;
  readonly previous_snapshot: TavernSourceSnapshot | null;
  readonly observed_hints: readonly TavernMutationHint[];
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
  readonly confirmed_scope_rebind?: {
    readonly expected_previous_scope: TavernSourceScope;
    readonly expected_previous_checksum: string;
  };
}

export class TavernSourceSnapshotError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "NO_ACTIVE_CHAT"
      | "SCOPE_CHANGED"
      | "HOST_SNAPSHOT_MISMATCH"
      | "PREVIOUS_SNAPSHOT_CORRUPT",
    message: string,
  ) {
    super(message);
    this.name = "TavernSourceSnapshotError";
  }
}
