function taskFailureDetail(errorCode: string, errorMessage?: string): string {
  const message = errorMessage ?? "";
  if (message.includes("RESPONSE_SCHEMA_INVALID") || errorCode === "RESPONSE_SCHEMA_INVALID") {
    return "模型已返回完整 JSON，但没有通过严格 Schema；可开启自动结构修复后点击手动修复。";
  }
  if (message.includes("RESPONSE_JSON_INVALID") || errorCode === "RESPONSE_JSON_INVALID") {
    return "模型响应不是完整 JSON；若输出在中途截断，可开启自动续接后点击手动修复。";
  }
  if (errorCode === "REQUEST_TIMEOUT") return "Memory API 请求超时，未提交记忆，也不会隐藏楼层。";
  if (errorCode === "CONFIGURATION_MISMATCH") {
    return "页面配置已变化，旧运行时请求已在本地阻止；没有调用模型。";
  }
  if (errorCode === "REQUEST_REJECTED") {
    const classification = message.match(/provider returned an error \(([^)]+)\)/u)?.[1];
    return classification === undefined
      ? "Memory API 或上游拒绝了请求，未提交记忆。"
      : `Provider 拒绝：${classification}；未提交记忆。`;
  }
  if (message.includes("provider failures") || errorCode === "GENERATION_FAILED") {
    return "Memory API 调用失败；未提交记忆，也不会隐藏楼层。";
  }
  if (errorCode === "ATTEMPTS_EXHAUSTED") {
    const rejection = message.match(/last rejection:\s*([A-Z][A-Z0-9_]{2,})/u)?.[1];
    const codes = message
      .match(/\[codes:\s*([A-Z0-9_,.:\s-]+)\]/u)?.[1]
      ?.split(",")
      .map((value) => value.trim())
      .filter((value) => /^[A-Z][A-Z0-9_.:-]{2,}$/u.test(value))
      .slice(0, 6);
    const safeLastRejection = [rejection, ...(codes ?? [])]
      .filter(
        (value, index, values): value is string =>
          value !== undefined && values.indexOf(value) === index,
      )
      .join(" / ");
    return safeLastRejection.length > 0
      ? `本轮调用次数已用完；最后拒绝：${safeLastRejection}。可手动开启新一轮。`
      : "本轮调用次数已用完；没有取得安全的最后拒绝类型，可查看诊断后再手动开启新一轮。";
  }
  return "任务未提交记忆；可查看诊断日志中的安全错误分类。";
}
