interface TavernAutomaticPrincipalBinding {
  refresh(): Promise<void>;
}

function createAutomaticPrincipalBinding(
  getRuntime: () => TavernExtensionRuntimeHandle | null,
): TavernAutomaticPrincipalBinding {
  let refreshing = false;

  const refresh = async (): Promise<void> => {
    if (refreshing) return;
    refreshing = true;
    try {
      const runtime = getRuntime();
      if (runtime === null) return;
      let next = await runtime.inspectPrincipalBinding();
      if (next.status === "AUTO_BIND_AVAILABLE" && next.automatic_candidate_id !== null) {
        next = await runtime.bindPrincipal({
          expected_control_checksum: next.control_checksum,
          expected_active_view_id: next.active_view_id,
          principal_entity_id: next.automatic_candidate_id,
          binding_mode: "automatic_exact_label",
        });
      }
      if (next.status === "CONFIRMATION_REQUIRED" || next.status === "STALE_BINDING") {
        recordDiagnostic("principal_identity_ambiguous_fail_closed", {
          status: next.status,
          candidate_count: next.candidates.length,
          content_recorded: false,
        });
      }
    } catch (error) {
      recordDiagnostic("principal_identity_automatic_resolution_failed", {
        error_name: error instanceof Error ? error.name : "UnknownError",
        content_recorded: false,
      });
    } finally {
      refreshing = false;
    }
  };
  return { refresh };
}

function requireEventName(eventTypes: Readonly<Record<string, string>>, key: string): string {
  const name = eventTypes[key];
  if (typeof name !== "string" || name.length === 0) {
    throw new Error(`SillyTavern event type is unavailable: ${key}`);
  }
  return name;
}

async function readSillyTavernVersion(): Promise<string> {
  try {
    const response = await fetch("/version", { cache: "no-cache" });
    if (!response.ok) return "unknown";
    const data = (await response.json()) as { readonly pkgVersion?: unknown };
    return typeof data.pkgVersion === "string" && data.pkgVersion.length > 0
      ? data.pkgVersion
      : "unknown";
  } catch {
    return "unknown";
  }
}

function makeBindings(
  sillyTavernVersion: string,
  settingsStore: NarraMemBetaSettingsStore,
  memoryApiClient: NarraMemMemoryApiClient,
  onGenerationState: (state: {
    readonly status: "running" | "success" | "failed";
    readonly generation_id: string;
    readonly error_type?: string;
    readonly error_code?: string;
    readonly error_message?: string;
  }) => void,
): SillyTavernExtensionBindings {
  const context = getContext();
  return {
    silly_tavern_version: sillyTavernVersion,
    get_character_id: () =>
      readCharacterIdentity(activeCharacter(getContext()))?.character_id ?? null,
    get_character_name: () => {
      const name = activeCharacter(getContext())?.name;
      return typeof name === "string" ? name : null;
    },
    get_chat_id: () => getContext().getCurrentChatId(),
    get_chat: () => getContext().chat,
    get_narrative_content_tag: () => settingsStore.get().narrative_content_tag,
    get_current_api: () => "openai",
    get_current_model_id: () => activeMemoryApiProfile(settingsStore.get()).model,
    event_source: context.eventSource,
    get_worldbook_names: () => world_names ?? [],
    load_world_info: loadWorldInfo,
    load_world_info_fresh: async (name) => {
      worldInfoCache.delete(name);
      return loadWorldInfo(name);
    },
    create_world_info: (name) => createNewWorldInfo(name, { interactive: false }),
    save_world_info: (name, data) => saveWorldInfo(name, data, true),
    delete_world_info: deleteWorldInfo,
    with_worldbook_lock: async (lockName, operation) => {
      if (navigator.locks === undefined) {
        throw new Error("Web Locks API is required for cross-tab NarraMem worldbook writes");
      }
      return navigator.locks.request(
        `narramem-worldbook:${lockName}`,
        { mode: "exclusive" },
        operation,
      );
    },
    new_world_info_entry_template: newWorldInfoEntryTemplate,
    set_extension_prompt: (id, content, position, depth, shouldScan, role) =>
      getContext().setExtensionPrompt(id, content, position, depth, shouldScan, role),
    generate_raw: async (request, audit) => {
      const startedAt = performance.now();
      const transport = memoryApiClient.getTransportDescriptor();
      onGenerationState({ status: "running", generation_id: audit.generation_id });
      console.info(
        `[NarraMem] memory generation start: ${audit.generation_id} | ${transport.source} | ${transport.model}`,
      );
      recordDiagnostic("memory_generation_start", {
        generation_id: audit.generation_id,
        transport_source: transport.source,
        transport_model_id: transport.model,
        runtime_model_id: audit.requested_model_id,
        route_matches_runtime: transport.model === audit.requested_model_id,
      });
      try {
        const content = await memoryApiClient.generate(request, audit.requested_model_id);
        const elapsedMs = Math.round(performance.now() - startedAt);
        const responseSha256 = await sha256HexUtf8(content);
        const responseUtf8Bytes = new TextEncoder().encode(content).byteLength;
        console.info(
          `[NarraMem] memory generation complete: ${audit.generation_id} | ${elapsedMs}ms | ${responseUtf8Bytes} bytes | sha256:${responseSha256}`,
        );
        recordDiagnostic("memory_generation_complete", {
          generation_id: audit.generation_id,
          elapsed_ms: elapsedMs,
          response_utf8_bytes: responseUtf8Bytes,
          response_sha256: responseSha256,
        });
        onGenerationState({ status: "success", generation_id: audit.generation_id });
        return content;
      } catch (error) {
        const errorType = error instanceof Error ? error.name : "UnknownError";
        const errorCode =
          error instanceof NarraMemMemoryApiError ? error.code : "GENERATION_FAILED";
        console.error(
          `[NarraMem] memory generation failed: ${audit.generation_id} | ${errorType} | ${errorCode}`,
        );
        recordDiagnostic("memory_generation_failed", {
          generation_id: audit.generation_id,
          error_name: errorType,
          error_code: errorCode,
          ...(error instanceof NarraMemMemoryApiError && error.http_status !== null
            ? { http_status: error.http_status }
            : {}),
          ...(error instanceof NarraMemMemoryApiError && error.provider_code !== null
            ? { provider_code: error.provider_code }
            : {}),
          ...(error instanceof NarraMemMemoryApiError && error.provider_type !== null
            ? { provider_type: error.provider_type }
            : {}),
          ...(error instanceof NarraMemMemoryApiError && error.provider_reason !== null
            ? { provider_reason: error.provider_reason }
            : {}),
          ...(error instanceof NarraMemMemoryApiError && error.provider_reason_redacted
            ? { provider_reason_redacted: true }
            : {}),
          ...(error instanceof NarraMemMemoryApiError && error.provider_reason_category !== null
            ? { provider_reason_category: error.provider_reason_category }
            : {}),
          content_recorded: false,
        });
        onGenerationState({
          status: "failed",
          generation_id: audit.generation_id,
          error_type: errorType,
          error_code: errorCode,
          ...(error instanceof NarraMemMemoryApiError ? { error_message: error.message } : {}),
        });
        throw error;
      }
    },
  };
}

function logObserverReport(report: TavernObserverCycleReport): void {
  recordDiagnostic("observer_cycle", {
    status: report.status,
    sequence: report.batch.sequence,
    extraction_requested: report.batch.extraction_requested,
    ...(report.status === "EXTRACTION_FINISHED"
      ? {
          extraction_status: report.extraction.status,
          lifecycle_status: report.lifecycle?.status ?? null,
          ...(report.extraction.status === "COMMITTED" &&
          report.extraction.incremental_backlog !== undefined
            ? { incremental_backlog: report.extraction.incremental_backlog }
            : {}),
        }
      : {}),
    ...(report.status === "EXTRACTION_PARTIAL"
      ? {
          extraction_status: report.extraction.status,
          incremental_partition: report.extraction.incremental_partition,
        }
      : {}),
    ...(report.status === "FAILED"
      ? {
          phase: report.phase,
          extraction_status: report.extraction?.status ?? null,
          error_name: report.error_name,
          error_code: report.error_code ?? null,
          error_message:
            report.error_message.length > 320
              ? `${report.error_message.slice(0, 320)}…`
              : report.error_message,
        }
      : {}),
  });
  console.info(
    `[NarraMem] observer cycle: ${JSON.stringify({
      status: report.status,
      sequence: report.batch.sequence,
      hints: report.batch.observed_hints,
      extraction_requested: report.batch.extraction_requested,
      ...(report.status === "EXTRACTION_FINISHED"
        ? {
            extraction_status: report.extraction.status,
            lifecycle_status: report.lifecycle?.status ?? null,
            ...(report.extraction.status === "COMMITTED" &&
            report.extraction.incremental_backlog !== undefined
              ? { incremental_backlog: report.extraction.incremental_backlog }
              : {}),
          }
        : {}),
      ...(report.status === "EXTRACTION_PARTIAL"
        ? {
            extraction_status: report.extraction.status,
            incremental_partition: report.extraction.incremental_partition,
          }
        : {}),
      ...(report.status === "ACTION_REQUIRED"
        ? {
            required_action: report.sync.required_action,
            candidate_count: report.sync.resolution.candidates.length,
          }
        : {}),
      ...(report.status === "FAILED"
        ? {
            phase: report.phase,
            extraction_status: report.extraction?.status ?? null,
            error_name: report.error_name,
            error_code: report.error_code ?? null,
            error_message:
              report.error_message.length > 320
                ? `${report.error_message.slice(0, 320)}…`
                : report.error_message,
          }
        : {}),
    })}`,
  );
}

function logRecallReport(report: TavernRecallGenerationBarrierReport): void {
  const timedReport =
    report.status === "INJECTION_INSTALLED" || report.status === "DEGRADED_NO_INJECTION";
  recordDiagnostic("recall_barrier", {
    status: report.status,
    ...(timedReport
      ? { sequence: report.sequence, elapsed_ms: report.elapsed_ms }
      : "sequence" in report
        ? { sequence: report.sequence }
        : {}),
    ...(timedReport
      ? {
          performance_target_ms: RECALL_PERFORMANCE_TARGET_MS,
          performance_target_exceeded: report.elapsed_ms > RECALL_PERFORMANCE_TARGET_MS,
          functional_deadline_ms: RECALL_FUNCTIONAL_DEADLINE_MS,
        }
      : {}),
    ...(report.status === "INJECTION_INSTALLED"
      ? {
          source_alignment: report.source_alignment,
          live_tail_message_count: report.live_tail_message_count,
          injection_depth: report.injection_depth,
          bundle_id: report.bundle_id,
          immediate_context_count: report.immediate_context_count,
          causal_antecedent_count: report.causal_antecedent_count,
          experience_echo_count: report.experience_echo_count,
          active_thread_count: report.active_thread_count,
          matched_impact_count: report.matched_impact_count,
          perspective_safe_entity_count: report.perspective_safe_entity_count,
          rejection_reason_counts: report.rejection_reason_counts,
        }
      : {}),
    ...(report.status === "DEGRADED_NO_INJECTION"
      ? {
          reason: report.reason,
          error_name: report.error_name,
          error_code: report.error_code ?? null,
        }
      : {}),
  });
  console.info(
    `[NarraMem] recall barrier: ${JSON.stringify({
      status: report.status,
      ...(timedReport
        ? { sequence: report.sequence, elapsed_ms: report.elapsed_ms }
        : "sequence" in report
          ? { sequence: report.sequence }
          : {}),
      ...(timedReport
        ? {
            performance_target_ms: RECALL_PERFORMANCE_TARGET_MS,
            performance_target_exceeded: report.elapsed_ms > RECALL_PERFORMANCE_TARGET_MS,
            functional_deadline_ms: RECALL_FUNCTIONAL_DEADLINE_MS,
          }
        : {}),
      ...(report.status === "INJECTION_INSTALLED"
        ? {
            source_alignment: report.source_alignment,
            live_tail_message_count: report.live_tail_message_count,
            bundle_id: report.bundle_id,
            immediate_context_count: report.immediate_context_count,
            causal_antecedent_count: report.causal_antecedent_count,
            experience_echo_count: report.experience_echo_count,
            active_thread_count: report.active_thread_count,
            matched_impact_count: report.matched_impact_count,
            perspective_safe_entity_count: report.perspective_safe_entity_count,
            rejection_reason_counts: report.rejection_reason_counts,
          }
        : {}),
      ...(report.status === "DEGRADED_NO_INJECTION"
        ? {
            reason: report.reason,
            error_name: report.error_name,
            error_code: report.error_code ?? null,
            error_message:
              (report.error_message?.length ?? 0) > 320
                ? `${(report.error_message ?? "").slice(0, 320)}…`
                : (report.error_message ?? null),
          }
        : {}),
    })}`,
  );
}

