function compactActivatedWorldInfo(entries: readonly unknown[]): readonly unknown[] {
  const result: unknown[] = [];
  for (const entry of entries) {
    if (typeof entry === "string") {
      if (entry.length > 0) result.push(entry);
      continue;
    }
    if (entry === null || typeof entry !== "object" || Array.isArray(entry)) continue;
    const value = entry as Readonly<Record<string, unknown>>;
    if (typeof value.content !== "string" || value.content.length === 0) continue;
    result.push({
      content: value.content,
      ...(Number.isInteger(value.depth) ? { depth: value.depth } : {}),
      ...(typeof value.role === "string" || Number.isInteger(value.role)
        ? { role: value.role }
        : {}),
      ...(typeof value.position === "string" || Number.isInteger(value.position)
        ? { position: value.position }
        : {}),
    });
  }
  return result;
}

async function readHostPromptMaterials(): Promise<Readonly<Record<string, unknown>>> {
  const context = getContext();
  const card = context.getCharacterCardFields();
  const worldInfoScanMessages = context.chat.filter((message) => message.is_system !== true);
  const chatForWorldInfo = worldInfoScanMessages
    .map((message) => {
      const text = String(message.mes ?? "");
      return world_info_include_names ? `${String(message.name ?? "")}: ${text}` : text;
    })
    .reverse();
  const worldInfo = await getWorldInfoPrompt(chatForWorldInfo, context.maxContext, true, {
    personaDescription: card.persona,
    characterDescription: card.description,
    characterPersonality: card.personality,
    characterDepthPrompt: card.charDepthPrompt,
    scenario: card.scenario,
    creatorNotes: card.creatorNotes,
    trigger: "normal",
  });
  const materials = {
    character_card: {
      name: context.name2,
      description: card.description,
      personality: card.personality,
      scenario: card.scenario,
      system: card.system,
      post_history_instructions: card.jailbreak,
      depth_prompt: card.charDepthPrompt,
      creator_notes: card.creatorNotes,
      example_dialogue: card.mesExamples,
      first_message: card.firstMessage,
      alternate_greetings: card.alternateGreetings,
      character_version: card.version,
    },
    user_persona: { name: context.name1, description: card.persona },
    world_info: {
      before: worldInfo.worldInfoBefore,
      after: worldInfo.worldInfoAfter,
      examples: compactActivatedWorldInfo(worldInfo.worldInfoExamples),
      depth: compactActivatedWorldInfo(worldInfo.worldInfoDepth),
      author_note_before: compactActivatedWorldInfo(worldInfo.anBefore),
      author_note_after: compactActivatedWorldInfo(worldInfo.anAfter),
      outlets: worldInfo.outletEntries,
    },
  };
  const sectionAudit = await Promise.all(
    Object.entries(materials).map(async ([section, value]) => {
      const serialized = JSON.stringify(value);
      return {
        section,
        utf8_bytes: new TextEncoder().encode(serialized).byteLength,
        sha256: await sha256HexUtf8(serialized),
      };
    }),
  );
  recordDiagnostic("host_material_snapshot", {
    character_source: "SillyTavern.getCharacterCardFields",
    persona_source: "SillyTavern.getCharacterCardFields.persona",
    world_info_source: "SillyTavern.getWorldInfoPrompt.dry_run",
    world_info_scan_message_count: worldInfoScanMessages.length,
    world_info_include_names,
    sections: sectionAudit,
    content_recorded: false,
  });
  return materials;
}

async function bootstrap(): Promise<void> {
  const version = await readSillyTavernVersion();
  recordDiagnostic("bootstrap", { silly_tavern_version: version });
  const context = getContext();
  const settingsOwnerToken = globalThis.crypto.randomUUID();
  (globalThis as typeof globalThis & Record<PropertyKey, unknown>)[SETTINGS_OWNER_SYMBOL] =
    settingsOwnerToken;
  await ensureActiveCharacterIdentity(context);
  const settingsStore = new NarraMemBetaSettingsStore({
    extensionSettings: context.extensionSettings,
    saveSettingsDebounced: () => context.saveSettingsDebounced(),
    canPersist: () =>
      (globalThis as typeof globalThis & Record<PropertyKey, unknown>)[SETTINGS_OWNER_SYMBOL] ===
      settingsOwnerToken,
  });
  let taskState: NarraMemTaskDisplayState = {
    status: "idle",
    stage: "idle",
    error_type: null,
    error_code: null,
    error_detail: null,
    last_failure_at: null,
    round_attempts: 0,
    round_max_calls: settingsStore.get().retry_count + 1,
    semantic_stage_index: null,
    semantic_stage_name: null,
    recovery_calls: 0,
    cumulative_calls: 0,
    manual_retry_available: false,
  };
  let settingsPanel: NarraMemBetaSettingsPanel | null = null;
  const memoryProgressToast = installMemoryProgressToast();
  let manualRetryRound = 0;
  let activeRetryRoundId: string | undefined;
  let activeMemoryTaskPrefix: string | null = null;
  const recoveryGenerationIds = new Set<string>();
  const refreshTaskDisplay = (): void => {
    memoryProgressToast.update(activeMemoryTaskPrefix, taskState);
    void settingsPanel?.refreshStatus();
  };
  const memoryApiClient = new NarraMemMemoryApiClient({
    fetch: (input, init) => globalThis.fetch(input, init),
    getRequestHeaders,
    getSettings: () => settingsStore.get(),
    getHostMaterials: readHostPromptMaterials,
    onRequestEnvelopeAudit: (audit) => recordDiagnostic("memory_request_envelope", audit),
    setProfileCredentialSecretId: (profileId, credentialSecretId) => {
      settingsStore.updateProfile(profileId, { credential_secret_id: credentialSecretId });
    },
  });
  const updateGenerationState = (state: {
    readonly status: "running" | "success" | "failed";
    readonly generation_id: string;
    readonly error_type?: string;
    readonly error_code?: string;
    readonly error_message?: string;
  }): void => {
    const taskPrefix = memoryTaskKeyFromGenerationId(state.generation_id);
    if (taskPrefix !== null && taskPrefix !== activeMemoryTaskPrefix) {
      activeMemoryTaskPrefix = taskPrefix;
      recoveryGenerationIds.clear();
    }
    if (
      state.status === "running" &&
      /_(?:continuation|schema_repair|targeted_repair)_[0-9]+$/u.test(state.generation_id)
    ) {
      recoveryGenerationIds.add(state.generation_id);
    }
    const attempt = Number.parseInt(/_a([0-9]+)$/u.exec(state.generation_id)?.[1] ?? "0", 10);
    const semanticStageIndex = Number.parseInt(
      /_s([1-4])_a[0-9]+$/u.exec(state.generation_id)?.[1] ?? "0",
      10,
    );
    const semanticStageName =
      semanticStageIndex === 1
        ? "实体／场景"
        : semanticStageIndex === 2
          ? "事件"
          : semanticStageIndex === 3
            ? "状态／认知"
            : semanticStageIndex === 4
              ? "因果／未决"
              : null;
    const stage = state.generation_id.includes("_lifecycle_") ? "lifecycle" : "extraction";
    taskState = {
      ...taskState,
      status: memoryTaskStatusAfterGeneration(state.status),
      stage,
      error_type: state.status === "failed" ? (state.error_type ?? "UnknownError") : null,
      error_code: state.status === "failed" ? (state.error_code ?? "GENERATION_FAILED") : null,
      error_detail:
        state.status === "failed"
          ? taskFailureDetail(state.error_code ?? "GENERATION_FAILED", state.error_message)
          : null,
      last_failure_at:
        state.status === "failed" ? new Date().toISOString() : taskState.last_failure_at,
      round_attempts:
        semanticStageIndex !== 0 && semanticStageIndex !== taskState.semantic_stage_index
          ? attempt
          : Math.max(taskState.round_attempts, attempt),
      round_max_calls: activeRetryRoundId === undefined ? settingsStore.get().retry_count + 1 : 1,
      semantic_stage_index:
        semanticStageIndex === 0 ? taskState.semantic_stage_index : semanticStageIndex,
      semantic_stage_name: semanticStageName ?? taskState.semantic_stage_name,
      recovery_calls: recoveryGenerationIds.size,
      cumulative_calls: memoryApiClient.getSessionDispatches(),
      manual_retry_available: false,
    };
    refreshTaskDisplay();
  };
  const port = createSillyTavernExtensionHostPort(
    makeBindings(version, settingsStore, memoryApiClient, updateGenerationState),
  );
  const memoryRegistry = new TavernMemoryRegistry(port);
  let deletedChatCleanupTail: Promise<void> = Promise.resolve();
  const diagnosticControl = new TavernExtensionDiagnosticControl(port, 200, null);
  (globalThis as typeof globalThis & Record<PropertyKey, unknown>)[
    Symbol.for(NARRAMEM_EXTENSION_DIAGNOSTIC_CONTROL_SYMBOL)
  ] = diagnosticControl;
  installDiagnosticCommandBridge(diagnosticControl);
  recordDiagnostic("diagnostic_control_ready", {
    control_version: diagnosticControl.control_version,
    product_runtime_count: 1,
    content_recorded: false,
  });
  let runtime: TavernExtensionRuntimeHandle | null = null;
  const checkpointEvaluationControl = new TavernCheckpointEvaluationControl(
    () => runtime,
    (audit) => recordDiagnostic("checkpoint_evaluation", { ...audit }),
  );
  (globalThis as typeof globalThis & Record<PropertyKey, unknown>)[
    Symbol.for(NARRAMEM_CHECKPOINT_EVALUATION_CONTROL_SYMBOL)
  ] = checkpointEvaluationControl;
  recordDiagnostic("checkpoint_evaluation_control_ready", {
    control_version: checkpointEvaluationControl.control_version,
    transport: "in_memory_symbol_only",
    product_recall_service_count: 1,
    content_recorded: false,
    dom_bridge_used: false,
  });
  let installedModel: string | null = null;
  let installedSignature: string | null = null;
  let automaticCreatePending = false;
  let reconfigureTail: Promise<void> = Promise.resolve();
  let floorVisibilityTail: Promise<void> = Promise.resolve();
  const automaticPrincipalBinding = createAutomaticPrincipalBinding(() => runtime);

  const scheduleCompletedFloorVisibility = (report: TavernObserverCycleReport): void => {
    const contextNow = getContext();
    const plan = planFloorVisibility(report, contextNow.chat);
    if (plan === null) return;
    const chatId = contextNow.getCurrentChatId();
    const applyLatestVisibility = async (): Promise<void> => {
      const latestContext = getContext();
      if (chatId === null || latestContext.getCurrentChatId() !== chatId) return;
      const latestPlan = planFloorVisibility(report, latestContext.chat);
      if (latestPlan === null) return;
      const result = await applyFloorVisibilityPlan(
        latestContext.chat,
        latestPlan,
        hideChatMessageRange,
      );
      recordDiagnostic("completed_memory_floors_hidden", {
        covered_message_count: latestPlan.covered_message_count,
        hidden_through_message_id: result.hidden_through,
        protected_ai_floor_count: latestPlan.protected_ai_message_ids.length,
        unhidden_ai_count: result.unhidden_ai_count,
        content_recorded: false,
      });
    };
    floorVisibilityTail = floorVisibilityTail
      .then(applyLatestVisibility, applyLatestVisibility)
      .catch((error: unknown) => {
        recordDiagnostic("completed_memory_floor_hiding_failed", {
          error_name: error instanceof Error ? error.name : "UnknownError",
          content_recorded: false,
        });
        logError(error);
      });
  };

  const reconfigure = async (): Promise<void> => {
    let settings = settingsStore.get();
    let compatibilityRoute: ReturnType<typeof memoryPromptCompatibilityRoute>;
    try {
      compatibilityRoute = memoryPromptCompatibilityRoute(settings);
    } catch (error) {
      taskState = {
        ...taskState,
        status: "failed",
        stage: "idle",
        error_type: error instanceof Error ? error.name : "UnknownError",
        error_code: "PROMPT_ROUTE_REQUIRED",
        error_detail: "当前模型没有可用的 NarraMem Prompt，请选择匹配模型或在高级设置中明确覆盖。",
        last_failure_at: new Date().toISOString(),
        manual_retry_available: false,
      };
      refreshTaskDisplay();
      return;
    }
    const transportModelId = activeMemoryApiProfile(settings).model;
    let credentialConfigured = false;
    try {
      credentialConfigured = (await memoryApiClient.status()).credential_configured;
      settings = settingsStore.get();
    } catch (error) {
      recordDiagnostic("memory_api_backend_unavailable", {
        error_name: error instanceof Error ? error.name : "UnknownError",
        content_recorded: false,
      });
    }
    const signature = JSON.stringify({
      settings,
      credential_configured: credentialConfigured,
      retry_round_id: activeRetryRoundId ?? null,
    });
    const controlledFixtureActive = await hasCurrentTavernCausalAuditPositiveFixture(port);
    if (runtime !== null && installedSignature === signature) {
      if (controlledFixtureActive && diagnosticControl.getState().arm !== "paused") {
        diagnosticControl.pause();
        recordDiagnostic("controlled_fixture_auto_quiesce", {
          fixture_version: "0.2.0",
          trigger: "chat_reconfigure",
          content_recorded: false,
        });
      }
      return;
    }
    diagnosticControl.setRuntime(null);
    runtime?.dispose();
    runtime = null;
    installedModel = null;
    installedSignature = null;
    if (!memoryApiConfigured(settings, credentialConfigured)) {
      console.info("[NarraMem] Memory Runtime paused until independent API settings are complete");
      return;
    }
    const prompts = MODEL_PROMPTS[compatibilityRoute];
    if (prompts === undefined) {
      console.warn(
        `[NarraMem] Unsupported Prompt route; memory runtime paused: ${compatibilityRoute}`,
      );
      return;
    }
    if (controlledFixtureActive) {
      diagnosticControl.pause();
      recordDiagnostic("controlled_fixture_auto_quiesce", {
        fixture_version: "0.2.0",
        trigger: "runtime_install",
        content_recorded: false,
      });
    }
    let nextRuntime: TavernExtensionRuntimeHandle | null = null;
    nextRuntime = await installTavernExtensionRuntime({
      host_port: port,
      config: {
        installation_id: "narramem",
        replace_existing: true,
        segment_limits: {
          max_records_per_segment: 64,
          max_segment_utf8_bytes: 350_000,
        },
        observer: {
          debounce_ms: 750,
          max_sync_attempts: 2,
          minimum_ai_floor_count_before_first_extraction: 5,
          ai_floor_batch_size: 5,
          writer_id: WRITER_ID,
          build_id: EXTENSION_BUILD_ID,
          exclusive_recovery_confirmed: false,
          extraction: {
            requested_model_id: transportModelId,
            compatibility_route: compatibilityRoute,
            ...(activeRetryRoundId === undefined ? {} : { retry_round_id: activeRetryRoundId }),
            prompt_body: prompts.extraction,
            semantic_stage_prompt_assets: [
              {
                stage: "foundation",
                prompt_asset_ref: "NM-P0036@0.1.0",
                prompt_body: foundationStagePrompt,
                prompt_body_sha256:
                  "8ccab2c8253ef6c5d064f826e99b02817391e8c28ca6d792bbf21e007d403b26",
              },
              {
                stage: "events",
                prompt_asset_ref: "NM-P0037@0.1.0",
                prompt_body: eventsStagePrompt,
                prompt_body_sha256:
                  "06d46ec1f98b09b173188ecdb37dd84c560e0a1c1f6d932041ed36f93445335d",
              },
              {
                stage: "state_epistemic",
                prompt_asset_ref: "NM-P0038@0.1.0",
                prompt_body: stateEpistemicStagePrompt,
                prompt_body_sha256:
                  "2cee63d67a940ee14afa21068f781865a1dc319a171ae8284ad2979840cb5c35",
              },
              {
                stage: "causal",
                prompt_asset_ref: "NM-P0039@0.1.0",
                prompt_body: causalStagePrompt,
                prompt_body_sha256:
                  "b15dff101972c3c89a64800017b6497c67158bde4364d17d75be04ccfc903f32",
              },
            ],
            allow_candidate_prompt: true,
            max_attempts: activeRetryRoundId === undefined ? settings.retry_count + 1 : 1,
            response_recovery: {
              continuation_max_calls: settings.continuation_enabled
                ? settings.continuation_max_calls
                : 0,
              continuation_prompt_asset_ref: "NM-P0033@0.1.0",
              continuation_prompt_body: continuationPrompt,
              schema_repair_max_calls: settings.schema_repair_enabled
                ? settings.schema_repair_max_calls
                : 0,
              schema_repair_prompt_asset_ref: "NM-P0034@0.2.0",
              schema_repair_prompt_body: schemaRepairPrompt,
              schema_repair_output_prompt_asset_ref: "NM-P0035@0.1.0",
              schema_repair_output_prompt_body: schemaRepairOutputPrompt,
            },
            prepare: {
              // First run starts at five AI floors; later runs add five AI floors.
              // The opening assistant floor means the first batch can contain nine
              // messages while every later batch normally contains ten.
              chunk_message_limit: 10,
              context_message_limit: 2,
              event_type_vocabulary: [],
              default_story_time: {
                granularity: "scene",
                certainty: "relative",
                sequence_index: 0,
              },
            },
          },
          ...(prompts.lifecycle === undefined
            ? {}
            : {
                lifecycle: {
                  requested_model_id: transportModelId,
                  compatibility_route: compatibilityRoute,
                  ...(activeRetryRoundId === undefined
                    ? {}
                    : { retry_round_id: activeRetryRoundId }),
                  prompt_body: prompts.lifecycle,
                  allow_candidate_prompt: true,
                  max_attempts: activeRetryRoundId === undefined ? settings.retry_count + 1 : 1,
                },
              }),
        },
        recall: {
          token_budget: 4096,
          latest_ai_floor_count: 4,
          max_prepare_ms: RECALL_FUNCTIONAL_DEADLINE_MS,
          prompt_body: prompts.recall,
        },
        interaction_performance: { max_samples: 200 },
      },
      on_report: (report) => {
        logObserverReport(report);
        if (report.status === "EXTRACTION_FINISHED") {
          const completedManualRound = activeRetryRoundId !== undefined;
          taskState = {
            ...taskState,
            status: "success",
            stage: report.lifecycle === undefined ? "extraction" : "lifecycle",
            error_type: null,
            error_code: null,
            error_detail: null,
            cumulative_calls: memoryApiClient.getSessionDispatches(),
            manual_retry_available: false,
          };
          refreshTaskDisplay();
          void automaticPrincipalBinding.refresh();
          scheduleCompletedFloorVisibility(report);
          if (completedManualRound) {
            activeRetryRoundId = undefined;
            installedSignature = null;
            queueMicrotask(scheduleReconfigure);
          }
        }
        if (report.status === "EXTRACTION_PARTIAL") {
          const partition = report.extraction.incremental_partition;
          const completedManualRound = activeRetryRoundId !== undefined;
          taskState = {
            ...taskState,
            status: "partial",
            stage: "extraction",
            error_type: "IncrementalRepairPending",
            error_code: "REPAIR_PENDING",
            error_detail: `已接受 ${partition.accepted_record_count}/${partition.total_record_count} 条；仍有 ${partition.quarantined_record_count} 条待修。正确记录已保存，待修记录不会触发生命周期或隐藏楼层。`,
            last_failure_at: report.completed_at,
            cumulative_calls: memoryApiClient.getSessionDispatches(),
            manual_retry_available: true,
          };
          refreshTaskDisplay();
          if (completedManualRound) {
            activeRetryRoundId = undefined;
            installedSignature = null;
            queueMicrotask(scheduleReconfigure);
          }
        }
        if (report.status === "FAILED") {
          const completedManualRound = activeRetryRoundId !== undefined;
          const reportedErrorCode = report.error_code ?? "TASK_FAILED";
          const preserveProviderFailure =
            taskState.error_code === "REQUEST_REJECTED" &&
            taskState.error_detail !== null &&
            (reportedErrorCode === "ATTEMPTS_EXHAUSTED" ||
              (reportedErrorCode === "GENERATION_FAILED" &&
                report.error_message.includes("provider failures")));
          taskState = {
            ...taskState,
            status: "failed",
            stage:
              report.phase === "SOURCE_SYNC"
                ? "source_sync"
                : report.phase === "LIFECYCLE"
                  ? "lifecycle"
                  : "extraction",
            error_type: preserveProviderFailure ? taskState.error_type : report.error_name,
            error_code: preserveProviderFailure ? taskState.error_code : reportedErrorCode,
            error_detail: preserveProviderFailure
              ? taskState.error_detail
              : taskFailureDetail(reportedErrorCode, report.error_message),
            last_failure_at: report.completed_at,
            cumulative_calls: memoryApiClient.getSessionDispatches(),
            manual_retry_available: true,
          };
          refreshTaskDisplay();
          if (completedManualRound) {
            activeRetryRoundId = undefined;
            installedSignature = null;
            queueMicrotask(scheduleReconfigure);
          }
        }
        if (
          report.status !== "ACTION_REQUIRED" ||
          !reportRequiresAutomaticCreate(report) ||
          automaticCreatePending
        )
          return;
        const activeRuntime = nextRuntime;
        if (activeRuntime === null) return;
        automaticCreatePending = true;
        void activeRuntime
          .resolveMemorySet({
            kind: "CREATE_MEMORY_SET",
            character_revision_hash: null,
            ...(report.sync.required_action === "CONFIRM_ANCHOR_CANDIDATE"
              ? {
                  expected_anchor_candidates: report.sync.resolution.candidates.map(
                    (candidate) => ({
                      control_book_name: candidate.control_book_name,
                      expected_control_checksum: candidate.control.checksum,
                    }),
                  ),
                }
              : {}),
          })
          .catch(logError)
          .finally(() => {
            automaticCreatePending = false;
          });
      },
      on_recall_report: logRecallReport,
      on_interaction_performance_sample: (sample) => {
        logInteractionPerformanceSample(sample);
        diagnosticControl.notifyRuntimePerformanceSample();
      },
    });
    runtime = nextRuntime;
    diagnosticControl.setRuntime(nextRuntime);
    installedModel = transportModelId;
    installedSignature = signature;
    recordDiagnostic("runtime_active", {
      transport_model_id: transportModelId,
      prompt_compatibility_route: compatibilityRoute,
    });
    console.info(`[NarraMem] Native extension runtime active: ${transportModelId}`);
    await automaticPrincipalBinding.refresh();
  };

  const scheduleReconfigure = (): void => {
    reconfigureTail = reconfigureTail.then(reconfigure, reconfigure);
    void reconfigureTail.catch(logError);
  };

  const runManualRetry = async (): Promise<void> => {
    if (taskState.status === "running") throw new Error("记忆任务仍在运行");
    manualRetryRound += 1;
    activeRetryRoundId = `manual_${Date.now().toString(36)}_${manualRetryRound}`;
    taskState = {
      status: "running",
      stage: "source_sync",
      error_type: null,
      error_code: null,
      error_detail: null,
      last_failure_at: taskState.last_failure_at,
      round_attempts: 0,
      round_max_calls: 1,
      semantic_stage_index: null,
      semantic_stage_name: null,
      recovery_calls: 0,
      cumulative_calls: memoryApiClient.getSessionDispatches(),
      manual_retry_available: false,
    };
    refreshTaskDisplay();
    const retry = async (): Promise<void> => {
      installedSignature = null;
      await reconfigure();
      if (runtime === null) {
        throw new Error("NarraMem 运行时尚未就绪，请检查 API、模型与 Prompt 配置");
      }
      await runtime.flushNow();
    };
    reconfigureTail = reconfigureTail.then(retry, retry);
    try {
      await reconfigureTail;
    } catch (error) {
      taskState = {
        ...taskState,
        status: "failed",
        error_type: error instanceof Error ? error.name : "UnknownError",
        error_code: "MANUAL_RETRY_START_FAILED",
        error_detail: "手动修复轮次没有成功启动，请检查 API、模型与 Prompt 配置。",
        last_failure_at: new Date().toISOString(),
        cumulative_calls: memoryApiClient.getSessionDispatches(),
        manual_retry_available: true,
      };
      refreshTaskDisplay();
      throw error;
    }
  };

  settingsPanel = installNarraMemBetaSettingsPanel({
    version: "0.4.0-beta.25",
    port,
    settingsStore,
    apiClient: memoryApiClient,
    getRuntimeState: () => ({
      runtime_active: runtime !== null,
      transport_model_id: installedModel,
      diagnostic_arm: diagnosticControl.getState().arm,
    }),
    getTaskState: () => ({
      ...taskState,
      cumulative_calls: memoryApiClient.getSessionDispatches(),
    }),
    getDiagnostics: () => [...((globalThis as DiagnosticHost).__NARRAMEM_DIAGNOSTICS__ ?? [])],
    onConfigurationChanged: scheduleReconfigure,
    onManualRetry: runManualRetry,
  });

  const installMessageQuickEntry = (messageId?: unknown): void => {
    const selector =
      typeof messageId === "number" && Number.isSafeInteger(messageId) && messageId >= 0
        ? `#chat .mes[mesid="${messageId}"]`
        : "#chat .mes";
    for (const message of document.querySelectorAll<HTMLElement>(selector)) {
      const actions = message.querySelector<HTMLElement>(".extraMesButtons");
      if (actions === null || actions.querySelector(`.${MESSAGE_QUICK_ENTRY_CLASS}`) !== null)
        continue;
      const quickEntry = document.createElement("div");
      quickEntry.className = `mes_button fa-solid fa-brain ${MESSAGE_QUICK_ENTRY_CLASS}`;
      quickEntry.title = "打开 NarraMem 叙忆";
      quickEntry.setAttribute("aria-label", "打开 NarraMem 叙忆");
      quickEntry.setAttribute("role", "button");
      quickEntry.tabIndex = 0;
      const openPanel = (event: Event): void => {
        event.preventDefault();
        event.stopPropagation();
        settingsPanel?.open();
      };
      quickEntry.addEventListener("click", openPanel);
      quickEntry.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") openPanel(event);
      });
      actions.append(quickEntry);
    }
  };

  let quickEntryInstallQueued = false;
  const scheduleQuickEntryInstall = (): void => {
    if (quickEntryInstallQueued) return;
    quickEntryInstallQueued = true;
    globalThis.requestAnimationFrame(() => {
      quickEntryInstallQueued = false;
      installMessageQuickEntry();
    });
  };

  context.eventSource.on(
    requireEventName(context.eventTypes, "CHARACTER_MESSAGE_RENDERED"),
    installMessageQuickEntry,
  );
  context.eventSource.on(
    requireEventName(context.eventTypes, "USER_MESSAGE_RENDERED"),
    installMessageQuickEntry,
  );
  const chat = document.querySelector<HTMLElement>("#chat");
  if (chat !== null) {
    const quickEntryObserver = new MutationObserver(scheduleQuickEntryInstall);
    quickEntryObserver.observe(chat, { childList: true, subtree: true });
  }
  scheduleQuickEntryInstall();
  globalThis.setTimeout(scheduleQuickEntryInstall, 500);

  const reconfigureForChatChange = async (): Promise<void> => {
    await new Promise<void>((resolve) => globalThis.setTimeout(resolve, 250));
    await ensureActiveCharacterIdentity(getContext());
    const previousRuntime = runtime;
    await reconfigure();
    if (runtime !== null && runtime === previousRuntime) {
      if (diagnosticControl.getState().arm === "runtime") {
        runtime.stop("host_chat_changed");
        runtime.start();
        recordDiagnostic("runtime_chat_restarted", {
          requested_model_id: installedModel,
        });
        console.info(`[NarraMem] Runtime restarted for active chat: ${installedModel}`);
      } else {
        runtime.stop("host_chat_changed_non_runtime_arm");
        recordDiagnostic("runtime_chat_restart_suppressed", {
          requested_model_id: installedModel,
          diagnostic_arm: diagnosticControl.getState().arm,
        });
      }
    }
    await automaticPrincipalBinding.refresh();
    installMessageQuickEntry();
    await settingsPanel?.refreshStatus();
  };

  const scheduleChatReconfigure = (): void => {
    reconfigureTail = reconfigureTail.then(reconfigureForChatChange, reconfigureForChatChange);
    void reconfigureTail.catch(logError);
  };

  context.eventSource.on(
    requireEventName(context.eventTypes, "CHAT_CHANGED"),
    scheduleChatReconfigure,
  );
  const scheduleDeletedChatCleanup = (deletedChatId: unknown): void => {
    if (typeof deletedChatId !== "string" || deletedChatId.trim().length === 0) {
      recordDiagnostic("deleted_chat_memory_cleanup_skipped", {
        reason: "INVALID_CHAT_ID",
        content_recorded: false,
      });
      return;
    }
    const normalizedChatId = deletedChatId.replace(/\.jsonl$/iu, "");
    const characterId = port.getCurrentIdentity().character_id;
    const cleanup = async (): Promise<void> => {
      const result = await memoryRegistry.deleteMemorySetForChat({
        chat_id: normalizedChatId,
        ...(characterId === null ? {} : { character_id: characterId }),
      });
      recordDiagnostic("deleted_chat_memory_cleanup", {
        status: result.status,
        deleted_worldbook_count: result.deleted_worldbook_names.length,
        ...(result.status === "DELETED" ? { memory_set_id: result.memory_set_id } : {}),
        ...(result.status === "AMBIGUOUS"
          ? { ambiguous_candidate_count: result.candidate_memory_set_ids.length }
          : {}),
        content_recorded: false,
      });
    };
    deletedChatCleanupTail = deletedChatCleanupTail.then(cleanup, cleanup);
    void deletedChatCleanupTail.catch((error: unknown) => {
      recordDiagnostic("deleted_chat_memory_cleanup_failed", {
        error_name: error instanceof Error ? error.name : "UnknownError",
        error_code:
          error instanceof Error && "code" in error && typeof error.code === "string"
            ? error.code
            : "DELETE_FAILED",
        content_recorded: false,
      });
      logError(error);
    });
  };
  context.eventSource.on(
    requireEventName(context.eventTypes, "CHAT_DELETED"),
    scheduleDeletedChatCleanup,
  );
  const groupChatDeletedEvent = context.eventTypes.GROUP_CHAT_DELETED;
  if (typeof groupChatDeletedEvent === "string" && groupChatDeletedEvent.length > 0) {
    context.eventSource.on(groupChatDeletedEvent, scheduleDeletedChatCleanup);
  }
  scheduleReconfigure();
}

const context = getContext();
let bootstrapStarted = false;
const startBootstrap = (): void => {
  if (bootstrapStarted) return;
  bootstrapStarted = true;
  void bootstrap().catch(logError);
};
recordDiagnostic("module_loaded", { document_ready_state: document.readyState });
context.eventSource.on(requireEventName(context.eventTypes, "APP_READY"), startBootstrap);
if (document.readyState === "complete") {
  queueMicrotask(startBootstrap);
} else {
  globalThis.addEventListener("load", startBootstrap, { once: true });
}
