const JOB_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/;
const SHA256_PATTERN = /^[0-9a-f]{64}$/;
const PROMPT_ASSET_REF_PATTERN = /^NM-P[0-9]{4}@[0-9]+\.[0-9]+\.[0-9]+$/;
const SEMANTIC_STAGE_ORDER = [
  "foundation",
  "events",
  "state_epistemic",
  "causal",
] as const satisfies readonly NarrativeIncrementalExtractionStage[];

