function assertRequest(request: TavernExtractionJobRequest): void {
  if (!JOB_ID_PATTERN.test(request.job_id)) {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "job_id must be 1-80 ASCII letters, digits, underscore, or hyphen",
    );
  }
  if (request.retry_round_id !== undefined && !JOB_ID_PATTERN.test(request.retry_round_id)) {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "retry_round_id must be 1-80 ASCII letters, digits, underscore, or hyphen",
    );
  }
  if (request.writer_id.length === 0 || request.build_id.length === 0) {
    throw new TavernExtractionJobError("INVALID_REQUEST", "writer_id and build_id cannot be empty");
  }
  if (
    !Number.isSafeInteger(request.max_attempts) ||
    request.max_attempts < 1 ||
    request.max_attempts > 3
  ) {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "max_attempts must be an integer from 1 to 3",
    );
  }
  const recovery = request.response_recovery;
  if (
    recovery !== undefined &&
    (!Number.isInteger(recovery.continuation_max_calls) ||
      recovery.continuation_max_calls < 0 ||
      recovery.continuation_max_calls > 3 ||
      !Number.isInteger(recovery.schema_repair_max_calls) ||
      recovery.schema_repair_max_calls < 0 ||
      recovery.schema_repair_max_calls > 3 ||
      !PROMPT_ASSET_REF_PATTERN.test(recovery.continuation_prompt_asset_ref) ||
      !PROMPT_ASSET_REF_PATTERN.test(recovery.schema_repair_prompt_asset_ref) ||
      recovery.continuation_prompt_body.length === 0 ||
      recovery.schema_repair_prompt_body.length === 0 ||
      !PROMPT_ASSET_REF_PATTERN.test(recovery.schema_repair_output_prompt_asset_ref) ||
      recovery.schema_repair_output_prompt_body.length === 0 ||
      recovery.continuation_prompt_body.includes("\r") ||
      recovery.schema_repair_prompt_body.includes("\r") ||
      recovery.schema_repair_output_prompt_body.includes("\r"))
  ) {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "Response recovery requires registered literal Prompt bodies and independent 0-3 call limits",
    );
  }
  if (
    request.proxy_preset !== undefined &&
    (request.proxy_preset.length === 0 || request.proxy_preset !== request.proxy_preset.trim())
  ) {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "proxy_preset must be a non-empty exact name when provided",
    );
  }
  if (
    request.cancelled_attempt_recovery !== undefined &&
    request.cancelled_attempt_recovery !== "explicit_runtime_rearm"
  ) {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "cancelled_attempt_recovery must be the explicit Runtime re-arm capability",
    );
  }
  if (request.semantic_stage_prompt_assets !== undefined && request.mode !== "incremental") {
    throw new TavernExtractionJobError(
      "INVALID_REQUEST",
      "Semantic stage Prompts are only valid for incremental extraction",
    );
  }
}

async function verifyPromptAsset(
  asset: TavernRuntimePromptAsset,
  expectedRef: string,
  expectedHash: string,
  expectedFamily: string,
  expectedInputSchema: TavernRuntimePromptAsset["input_schema"],
  expectedOutputSchema: TavernExtractionOutputSchema | TavernIncrementalExtractionOutputSchema,
  allowCandidate: boolean,
): Promise<void> {
  const actualRef = `${asset.prompt_id}@${asset.semantic_version}`;
  if (
    asset.prompt_asset_ref !== actualRef ||
    actualRef !== expectedRef ||
    asset.message_role !== "system" ||
    asset.position !== "independent_model_call.system" ||
    asset.variables.length !== 0 ||
    asset.input_schema !== expectedInputSchema ||
    asset.output_schema !== expectedOutputSchema ||
    asset.provider_scope !== `model-family:${expectedFamily}` ||
    asset.body_sha256 !== expectedHash
  ) {
    throw new TavernExtractionJobError(
      "PROMPT_ASSET_INVALID",
      `Runtime Prompt descriptor does not match exact adapter route ${expectedRef}`,
    );
  }
  if (asset.status === "candidate" && !allowCandidate) {
    throw new TavernExtractionJobError(
      "CANDIDATE_PROMPT_NOT_ALLOWED",
      `Candidate Prompt ${expectedRef} requires explicit experimental opt-in`,
    );
  }
  if (
    asset.body.length === 0 ||
    asset.body.startsWith("\uFEFF") ||
    asset.body.includes("\r") ||
    asset.body.includes("{{NARRAMEM:") ||
    !SHA256_PATTERN.test(asset.body_sha256)
  ) {
    throw new TavernExtractionJobError(
      "PROMPT_ASSET_INVALID",
      `Runtime Prompt body is not a literal variable-free registered asset: ${expectedRef}`,
    );
  }
  const actualHash = await sha256HexUtf8(asset.body);
  if (actualHash !== asset.body_sha256) {
    throw new TavernExtractionJobError(
      "PROMPT_ASSET_INVALID",
      `Runtime Prompt body hash mismatch: ${expectedRef}`,
    );
  }
}

async function verifySemanticStagePromptAssets(
  assets: readonly TavernSemanticStagePromptAsset[] | undefined,
): Promise<ReadonlyMap<NarrativeIncrementalExtractionStage, TavernSemanticStagePromptAsset>> {
  if (assets === undefined) return new Map();
  if (assets.length !== SEMANTIC_STAGE_ORDER.length) {
    throw new TavernExtractionJobError(
      "PROMPT_ASSET_INVALID",
      "Staged extraction requires exactly four registered stage Prompts",
    );
  }
  const result = new Map<NarrativeIncrementalExtractionStage, TavernSemanticStagePromptAsset>();
  for (const asset of assets) {
    if (
      !SEMANTIC_STAGE_ORDER.includes(asset.stage) ||
      result.has(asset.stage) ||
      !PROMPT_ASSET_REF_PATTERN.test(asset.prompt_asset_ref) ||
      asset.prompt_body.length === 0 ||
      asset.prompt_body.startsWith("\uFEFF") ||
      asset.prompt_body.includes("\r") ||
      asset.prompt_body.includes("{{NARRAMEM:") ||
      !SHA256_PATTERN.test(asset.prompt_body_sha256) ||
      (await sha256HexUtf8(asset.prompt_body)) !== asset.prompt_body_sha256
    ) {
      throw new TavernExtractionJobError(
        "PROMPT_ASSET_INVALID",
        `Invalid semantic stage Prompt: ${asset.prompt_asset_ref}`,
      );
    }
    result.set(asset.stage, asset);
  }
  return result;
}

function stageIndex(stage: NarrativeIncrementalExtractionStage): number {
  return SEMANTIC_STAGE_ORDER.indexOf(stage);
}

function nextSemanticStage(
  stage: NarrativeIncrementalExtractionStage,
): NarrativeIncrementalExtractionStage | null {
  return SEMANTIC_STAGE_ORDER[stageIndex(stage) + 1] ?? null;
}

function partitionRecords(
  partition: TavernIncrementalCandidatePartition,
): Record<
  "entities" | "scenes" | "events" | "state_transitions" | "epistemic_states" | "causal_links",
  unknown[]
> {
  const records = {
    entities: [...partition.accepted_batch.entities] as unknown[],
    scenes: [...partition.accepted_batch.scenes] as unknown[],
    events: [...partition.accepted_batch.events] as unknown[],
    state_transitions: [...partition.accepted_batch.state_transitions] as unknown[],
    epistemic_states: [...partition.accepted_batch.epistemic_states] as unknown[],
    causal_links: [...partition.accepted_batch.causal_links] as unknown[],
  };
  for (const item of partition.quarantined) records[item.kind].push(item.value);
  return records;
}

function parseStagedIncrementalCandidateBatch(
  content: string,
  stage: NarrativeIncrementalExtractionStage,
  accumulated: TavernIncrementalCandidatePartition | null,
  context: NarrativeIncrementalCandidateValidationContext,
  responseSha256: string,
): ParsedIncrementalCandidateBatch {
  let value: unknown;
  try {
    value = JSON.parse(content) as unknown;
  } catch {
    throw new TavernExtractionJobError(
      "RESPONSE_JSON_INVALID",
      `Semantic stage ${stage} did not return one complete JSON value`,
    );
  }
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      `Semantic stage ${stage} returned a non-object JSON value`,
      ["STAGE_BATCH_SHELL_INVALID"],
    );
  }
  const object = value as Record<string, unknown>;
  const allowed = new Set<string>(
    stage === "foundation"
      ? ["entities", "scenes"]
      : stage === "events"
        ? ["events"]
        : stage === "state_epistemic"
          ? ["state_transitions", "epistemic_states"]
          : ["causal_links", "unresolved_items"],
  );
  const arrays = [
    "entities",
    "scenes",
    "events",
    "state_transitions",
    "epistemic_states",
    "causal_links",
    "unresolved_items",
  ] as const;
  const violated = arrays.find(
    (name) => !allowed.has(name) && Array.isArray(object[name]) && object[name].length > 0,
  );
  if (violated !== undefined) {
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      `Semantic stage ${stage} wrote forbidden array ${violated}`,
      [`STAGE_SCOPE_INVALID:${stage}:${violated}`],
    );
  }
  const previous =
    accumulated === null
      ? {
          entities: [],
          scenes: [],
          events: [],
          state_transitions: [],
          epistemic_states: [],
          causal_links: [],
        }
      : partitionRecords(accumulated);
  const merged = {
    contract_version: object.contract_version,
    source_revision_id: object.source_revision_id,
    entities: allowed.has("entities") ? object.entities : previous.entities,
    scenes: allowed.has("scenes") ? object.scenes : previous.scenes,
    events: allowed.has("events") ? object.events : previous.events,
    state_transitions: allowed.has("state_transitions")
      ? object.state_transitions
      : previous.state_transitions,
    epistemic_states: allowed.has("epistemic_states")
      ? object.epistemic_states
      : previous.epistemic_states,
    causal_links: allowed.has("causal_links") ? object.causal_links : previous.causal_links,
    unresolved_items: allowed.has("unresolved_items")
      ? object.unresolved_items
      : (accumulated?.accepted_batch.unresolved_items ?? []),
  };
  let partition: TavernIncrementalCandidatePartition;
  try {
    partition = partitionNarrativeIncrementalCandidateBatch(merged, context);
  } catch (error) {
    if (!(error instanceof TavernIncrementalCandidatePartitionError)) throw error;
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      error.message,
      error.diagnostic_codes,
    );
  }
  return parsedIncrementalPartition(partition, context, responseSha256);
}

interface ParsedCandidateBatch {
  readonly candidate_batch: NarrativeExtractionCandidateBatch;
  readonly quality_audit: TavernExtractionResponseQualityAudit;
}

interface ParsedIncrementalCandidateBatch {
  readonly candidate_batch: NarrativeIncrementalExtractionCandidateBatch;
  readonly quality_audit: TavernExtractionResponseQualityAudit;
  readonly partition: TavernIncrementalCandidatePartition;
}

function wireSchemaDiagnosticCodes(
  errors: ReturnType<typeof validateWireValue>["errors"],
): readonly string[] {
  return errors.slice(0, 8).map((error) => {
    const path =
      error.instancePath.length === 0
        ? "root"
        : error.instancePath
            .split("/")
            .filter((part) => part.length > 0)
            .join(".");
    const missing =
      error.keyword === "required" && typeof error.params.missingProperty === "string"
        ? `.${error.params.missingProperty.replace(/[^A-Za-z0-9_.:-]/gu, "_")}`
        : "";
    return `WIRE.${error.keyword}:${path}${missing}`;
  });
}

function looksLikeTruncatedJson(content: string): boolean {
  const source = content.trimStart();
  if (!(source.startsWith("{") || source.startsWith("["))) return false;
  const stack: string[] = [];
  let inString = false;
  let escaped = false;
  for (const character of source) {
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (character === "\\") {
        escaped = true;
      } else if (character === '"') {
        inString = false;
      }
      continue;
    }
    if (character === '"') {
      inString = true;
    } else if (character === "{" || character === "[") {
      stack.push(character);
    } else if (character === "}" || character === "]") {
      const expected = character === "}" ? "{" : "[";
      if (stack.pop() !== expected) return false;
    }
  }
  return inString || escaped || stack.length > 0;
}

function qualityUnresolvedItems(
  quarantine: FlatDraftQuarantineResult | null,
  completeness: ExplicitCausalCompletenessReport,
): readonly ExtractionUnresolvedItem[] {
  const quarantined =
    quarantine?.findings.flatMap((finding) =>
      finding.code === "FLAT_DRAFT_UNRESOLVED_REFERENCE_REMOVED" ||
      finding.code === "FLAT_DRAFT_NONCONTIGUOUS_QUOTE_SPLIT"
        ? []
        : [
            {
              code: finding.code.toLocaleLowerCase("en-US"),
              question: `${finding.message}: ${finding.candidate_kind}:${finding.candidate_key}`,
              evidence_ids: finding.evidence_ids,
              related_candidate_keys: [],
              required_evidence:
                "Re-extract the quarantined atom with a valid local contract; do not infer a replacement value.",
            },
          ],
    ) ?? [];
  const causal = completeness.findings.map((finding) => ({
    code: "explicit_causal_cue_uncovered",
    question: `Evidence contains an uncovered explicit causal cue '${finding.cue}' at code points ${finding.start_code_point}..${finding.end_code_point}.`,
    evidence_ids: [finding.evidence_id],
    related_candidate_keys: [],
    required_evidence:
      "A focused causal audit must identify supported endpoints and attribution, or explicitly classify the cue as non-narrative.",
  }));
  return [...quarantined, ...causal];
}

function parseCandidateBatch(
  content: string,
  adapter: TavernExtractionModelAdapter,
  defaultStoryTime: TemporalExtent,
  evidenceItems: readonly EvidenceItem[],
  responseSha256: string,
): ParsedCandidateBatch {
  let value: unknown;
  try {
    value = JSON.parse(content) as unknown;
  } catch {
    throw new TavernExtractionJobError(
      "RESPONSE_JSON_INVALID",
      "Extraction model response was not one plain JSON value",
    );
  }
  const report = validateWireValue(adapter.output_schema, value);
  if (!report.valid) {
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      `Extraction response failed ${adapter.output_schema} Wire Schema: ${report.errors[0]?.message ?? "unknown error"}`,
      wireSchemaDiagnosticCodes(report.errors),
    );
  }
  if (adapter.output_strategy === "canonical_candidate_v030") {
    const candidate = value as NarrativeExtractionCandidateBatch;
    const completeness = evaluateNarrativeCandidateCausalCompleteness(candidate, evidenceItems);
    return {
      candidate_batch: {
        ...candidate,
        unresolved_items: [
          ...candidate.unresolved_items,
          ...qualityUnresolvedItems(null, completeness),
        ],
      },
      quality_audit: {
        quality_audit_version: "0.1.0",
        source_response_sha256: responseSha256,
        flat_draft_quarantine: null,
        causal_completeness: completeness,
      },
    };
  }
  const quarantine = quarantineFlatNarrativeExtractionDraft(
    value as FlatNarrativeExtractionDraft,
    evidenceItems,
  );
  let candidate: NarrativeExtractionCandidateBatch;
  try {
    candidate = translateFlatNarrativeExtractionDraft(quarantine.draft, defaultStoryTime);
  } catch (error) {
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      error instanceof Error ? error.message : "Flat Draft translation failed",
    );
  }
  const completeness = evaluateFlatDraftCausalCompleteness(quarantine.draft, evidenceItems);
  candidate = {
    ...candidate,
    unresolved_items: [
      ...candidate.unresolved_items,
      ...qualityUnresolvedItems(quarantine, completeness),
    ],
  };
  const canonicalReport = validateWireValue("narrative_extraction_candidate_batch_v030", candidate);
  if (!canonicalReport.valid) {
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      `Translated Candidate failed Wire Schema: ${canonicalReport.errors[0]?.message ?? "unknown error"}`,
    );
  }
  return {
    candidate_batch: candidate,
    quality_audit: {
      quality_audit_version: "0.1.0",
      source_response_sha256: responseSha256,
      flat_draft_quarantine: {
        version: quarantine.quarantine_version,
        findings: quarantine.findings,
      },
      causal_completeness: completeness,
    },
  };
}

function parseIncrementalCandidateBatch(
  content: string,
  context: NarrativeIncrementalCandidateValidationContext,
  responseSha256: string,
): ParsedIncrementalCandidateBatch {
  let value: unknown;
  try {
    value = JSON.parse(content) as unknown;
  } catch {
    throw new TavernExtractionJobError(
      "RESPONSE_JSON_INVALID",
      "Incremental extraction model response was not one plain JSON value",
    );
  }
  let partition: TavernIncrementalCandidatePartition;
  try {
    partition = partitionNarrativeIncrementalCandidateBatch(value, context);
  } catch (error) {
    if (!(error instanceof TavernIncrementalCandidatePartitionError)) throw error;
    throw new TavernExtractionJobError(
      "RESPONSE_SCHEMA_INVALID",
      error.message,
      error.diagnostic_codes,
    );
  }
  return parsedIncrementalPartition(partition, context, responseSha256);
}

function parsedIncrementalPartition(
  partition: TavernIncrementalCandidatePartition,
  context: NarrativeIncrementalCandidateValidationContext,
  responseSha256: string,
): ParsedIncrementalCandidateBatch {
  const candidate = partition.accepted_batch;
  const completeness = evaluateExplicitCausalCompleteness(
    context.evidence_items,
    candidate.causal_links.flatMap((causal) => causal.evidence_quotes),
  );
  return {
    candidate_batch: {
      ...candidate,
      unresolved_items: [
        ...candidate.unresolved_items,
        ...qualityUnresolvedItems(null, completeness),
      ],
    },
    quality_audit: {
      quality_audit_version: "0.1.0",
      source_response_sha256: responseSha256,
      flat_draft_quarantine: null,
      causal_completeness: completeness,
    },
    partition,
  };
}

function structuredSchemaName(
  schema: TavernExtractionOutputSchema | TavernIncrementalExtractionOutputSchema,
): string {
  if (schema === "flat_narrative_extraction_draft") {
    return "narramem_flat_narrative_extraction_draft_0_1_0";
  }
  return schema === "narrative_incremental_extraction_candidate_batch"
    ? "narramem_narrative_incremental_extraction_candidate_batch_0_1_0"
    : "narramem_narrative_extraction_candidate_batch_0_3_0";
}

function partitionAudit(
  partition: TavernIncrementalCandidatePartition,
  initialAcceptedCount = partition.accepted_target_keys.length,
): TavernIncrementalPartitionAudit {
  return {
    partition_version: partition.partition_version,
    total_record_count: partition.total_record_count,
    accepted_record_count: partition.accepted_target_keys.length,
    quarantined_record_count: partition.quarantined.length,
    repaired_record_count: Math.max(
      0,
      partition.accepted_target_keys.length - initialAcceptedCount,
    ),
    quarantine: partition.quarantined.map((item) => ({
      kind: item.kind,
      target_key: item.target_key,
      diagnostic_codes: item.diagnostic_codes,
      diagnostic_paths: item.diagnostic_paths,
    })),
  };
}

export async function createTavernExtractionJobAudit(
  request: TavernExtractionJobRequest,
): Promise<TavernExtractionJobAudit> {
  assertRequest(request);
  const incremental = request.mode === "incremental";
  if (request.runtime_prompt_assets.length !== 1) {
    throw new TavernExtractionJobError(
      "PROMPT_ASSET_INVALID",
      "Exactly one runtime Prompt compatibility asset is required",
    );
  }
  const promptAsset = request.runtime_prompt_assets[0] as TavernRuntimePromptAsset;
  const compatibilityRoute = promptAsset.provider_scope.replace(/^model-family:/u, "");
  let adapter: TavernExtractionModelAdapter | TavernIncrementalExtractionModelAdapter;
  try {
    adapter = incremental
      ? resolveTavernIncrementalExtractionModelAdapter(compatibilityRoute)
      : resolveTavernExtractionModelAdapter(compatibilityRoute);
  } catch (error) {
    throw new TavernExtractionJobError(
      "UNSUPPORTED_MODEL",
      error instanceof Error ? error.message : "Unsupported Prompt compatibility route",
    );
  }
  if (promptAsset.prompt_asset_ref !== adapter.prompt_asset_ref) {
    throw new TavernExtractionJobError(
      "PROMPT_ASSET_INVALID",
      `Compatibility route requires runtime Prompt asset: ${adapter.prompt_asset_ref}`,
    );
  }
  await verifyPromptAsset(
    promptAsset,
    adapter.prompt_asset_ref,
    adapter.prompt_body_sha256,
    adapter.family,
    incremental
      ? "narrative_incremental_extraction_model_input"
      : "narrative_extraction_model_input",
    adapter.output_schema,
    request.allow_candidate_prompt,
  );
  const semanticStagePrompts = await verifySemanticStagePromptAssets(
    request.semantic_stage_prompt_assets,
  );
  const recoveryAudit =
    request.response_recovery === undefined
      ? null
      : {
          continuation_max_calls: request.response_recovery.continuation_max_calls,
          continuation_prompt_asset_ref: request.response_recovery.continuation_prompt_asset_ref,
          continuation_prompt_body_sha256: await sha256HexUtf8(
            request.response_recovery.continuation_prompt_body,
          ),
          schema_repair_max_calls: request.response_recovery.schema_repair_max_calls,
          schema_repair_prompt_asset_ref: request.response_recovery.schema_repair_prompt_asset_ref,
          schema_repair_prompt_body_sha256: await sha256HexUtf8(
            request.response_recovery.schema_repair_prompt_body,
          ),
          schema_repair_output_prompt_asset_ref:
            request.response_recovery.schema_repair_output_prompt_asset_ref,
          schema_repair_output_prompt_body_sha256: await sha256HexUtf8(
            request.response_recovery.schema_repair_output_prompt_body,
          ),
        };
  const parametersSha256 = await sha256HexUtf8(
    canonicalJson({
      adapter_id: adapter.adapter_id,
      requested_model_id: request.requested_model_id,
      compatibility_route: adapter.family,
      proxy_preset: request.proxy_preset ?? null,
      request_parameters: adapter.request_parameters,
      prompt_asset_ref: adapter.prompt_asset_ref,
      prompt_body_sha256: promptAsset.body_sha256,
      output_strategy: adapter.output_strategy,
      output_schema: adapter.output_schema,
      response_recovery: recoveryAudit,
      semantic_stage_prompts: [...semanticStagePrompts.values()].map((asset) => ({
        stage: asset.stage,
        prompt_asset_ref: asset.prompt_asset_ref,
        prompt_body_sha256: asset.prompt_body_sha256,
      })),
    }),
  );
  return {
    job_version: TAVERN_EXTRACTION_JOB_VERSION,
    job_id: request.job_id,
    adapter_id: adapter.adapter_id,
    requested_model_id: request.requested_model_id,
    model_identity_assurance: "requested_not_attested",
    prompt_asset_ref: adapter.prompt_asset_ref,
    prompt_body_sha256: promptAsset.body_sha256,
    output_strategy: adapter.output_strategy,
    output_schema: adapter.output_schema,
    parameters_sha256: parametersSha256,
    max_attempts: request.max_attempts,
  };
}

export class TavernExtractionJobRunner {
  private readonly semantic: TavernSemanticArchiveService;
  private queue: Promise<void> = Promise.resolve();
  private latestSequence = 0;
  private latestReason = "initial";
  private active: ActiveGeneration | null = null;

  constructor(
    private readonly port: TavernHostPort,
    segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
  ) {
    this.semantic = new TavernSemanticArchiveService(port, segmentLimits);
  }

  runLatest(request: TavernExtractionJobRequest): Promise<TavernExtractionJobResult> {
    const sequence = this.supersede("newer_extraction_job").sequence;
    const result = this.queue.then(
      () => this.execute(sequence, request),
      () => this.execute(sequence, request),
    );
    this.queue = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  invalidateCurrent(reason: string): TavernExtractionCancellationReport {
    if (reason.trim().length === 0) {
      throw new TavernExtractionJobError("INVALID_REQUEST", "Cancellation reason cannot be empty");
    }
    return this.supersede(reason).report;
  }

  private supersede(reason: string): {
    readonly sequence: number;
    readonly report: TavernExtractionCancellationReport;
  } {
    this.latestSequence += 1;
    this.latestReason = reason;
    const generationId = this.active?.generation_id ?? null;
    const hostCancelRequested =
      generationId === null ? false : (this.port.cancelGeneration?.(generationId) ?? false);
    this.active?.cancel_local(reason, hostCancelRequested);
    return {
      sequence: this.latestSequence,
      report: {
        reason,
        generation_id: generationId,
        host_cancel_requested: hostCancelRequested,
      },
    };
  }

  private cancellation(sequence: number, jobId: string): TavernExtractionJobResult | null {
    if (sequence === this.latestSequence) return null;
    return {
      status: this.latestReason === "newer_extraction_job" ? "SUPERSEDED" : "CANCELLED",
      job_id: jobId,
      reason: this.latestReason,
      host_cancel_requested: false,
    };
  }

  private async execute(
    sequence: number,
    request: TavernExtractionJobRequest,
  ): Promise<TavernExtractionJobResult> {
    const jobStartedAtMs = Date.now();
    const queuedCancellation = this.cancellation(sequence, request.job_id);
    if (queuedCancellation !== null) return queuedCancellation;
    assertRequest(request);

    const incremental = request.mode === "incremental";
    if (request.runtime_prompt_assets.length !== 1) {
      throw new TavernExtractionJobError(
        "PROMPT_ASSET_INVALID",
        "Exactly one runtime Prompt compatibility asset is required",
      );
    }
    const promptAsset = request.runtime_prompt_assets[0] as TavernRuntimePromptAsset;
    const compatibilityRoute = promptAsset.provider_scope.replace(/^model-family:/u, "");
    let adapter: TavernExtractionModelAdapter | TavernIncrementalExtractionModelAdapter;
    try {
      adapter = incremental
        ? resolveTavernIncrementalExtractionModelAdapter(compatibilityRoute)
        : resolveTavernExtractionModelAdapter(compatibilityRoute);
    } catch (error) {
      throw new TavernExtractionJobError(
        "UNSUPPORTED_MODEL",
        error instanceof Error ? error.message : "Unsupported Prompt compatibility route",
      );
    }
    if (promptAsset.prompt_asset_ref !== adapter.prompt_asset_ref) {
      throw new TavernExtractionJobError(
        "PROMPT_ASSET_INVALID",
        `Compatibility route requires runtime Prompt asset: ${adapter.prompt_asset_ref}`,
      );
    }
    await verifyPromptAsset(
      promptAsset,
      adapter.prompt_asset_ref,
      adapter.prompt_body_sha256,
      adapter.family,
      incremental
        ? "narrative_incremental_extraction_model_input"
        : "narrative_extraction_model_input",
      adapter.output_schema,
      request.allow_candidate_prompt,
    );
    const semanticStagePrompts = await verifySemanticStagePromptAssets(
      request.semantic_stage_prompt_assets,
    );
    const stagedIncremental = incremental && semanticStagePrompts.size > 0;

    const audit = await createTavernExtractionJobAudit(request);
    const parametersSha256 = audit.parameters_sha256;

    let fullTask: TavernExtractionTask | null = null;
    let incrementalTask: TavernIncrementalExtractionTask | null = null;
    let pendingRepairState: TavernIncrementalRepairState | null = null;
    let pendingStageState: TavernIncrementalStageState | null = null;
    if (request.mode === "incremental") {
      try {
        incrementalTask = await this.semantic.prepareIncrementalExtraction(request.prepare);
      } catch (error) {
        if (
          error instanceof TavernSemanticArchiveError &&
          (error.code === "NO_UNCOVERED_SOURCE" ||
            error.code === "LIFECYCLE_PENDING" ||
            error.code === "REPAIR_PENDING")
        ) {
          const baseTask = await this.semantic.prepareExtraction(request.prepare);
          const manifest = baseTask.existing_semantic_manifest;
          if (manifest === null) throw error;
          if (error.code === "REPAIR_PENDING") {
            const stageStore = new TavernIncrementalStageWorldbookStore(
              this.port,
              baseTask.candidate.control.memory_set_id,
            );
            const repairStore = new TavernIncrementalRepairWorldbookStore(
              this.port,
              baseTask.candidate.control.memory_set_id,
            );
            pendingStageState = stagedIncremental ? await stageStore.read() : null;
            const savedRepairState = await repairStore.read();
            if (savedRepairState !== null) pendingRepairState = savedRepairState;
            if (
              (pendingRepairState === null && pendingStageState === null) ||
              (pendingRepairState?.source_revision_id ?? pendingStageState?.source_revision_id) !==
                baseTask.core_source.source_revision.revision_id ||
              (pendingRepairState?.source_checksum ?? pendingStageState?.source_checksum) !==
                baseTask.source_snapshot.checksum
            ) {
              throw new TavernExtractionJobError(
                "ATTEMPT_LEDGER_BLOCKED",
                "Partial semantic coverage has no matching durable stage or repair state",
              );
            }
            if (pendingRepairState !== null && request.retry_round_id === undefined) {
              return {
                status: "REPAIR_PENDING",
                audit,
                memory_set_id: baseTask.candidate.control.memory_set_id,
                source_revision_id: baseTask.core_source.source_revision.revision_id,
                semantic_task_fingerprint: pendingRepairState.semantic_task_fingerprint,
                incremental_partition: partitionAudit(pendingRepairState.partition),
              };
            }
            const resumeState: TavernIncrementalRepairState = pendingRepairState ?? {
              ...(pendingStageState as TavernIncrementalStageState),
              format: TAVERN_INCREMENTAL_REPAIR_STORE_FORMAT,
              schema_version: TAVERN_INCREMENTAL_REPAIR_STORE_VERSION,
            };
            incrementalTask = await this.semantic.prepareIncrementalRepair(
              request.prepare,
              resumeState,
            );
          } else {
            return {
              status: error.code === "LIFECYCLE_PENDING" ? "LIFECYCLE_PENDING" : "ALREADY_CURRENT",
              audit,
              memory_set_id: baseTask.candidate.control.memory_set_id,
              source_revision_id: baseTask.core_source.source_revision.revision_id,
              semantic_task_fingerprint: manifest.task_fingerprint,
            };
          }
        } else throw error;
      }
    } else {
      fullTask = await this.semantic.prepareExtraction(request.prepare);
    }
    const baseTask = incrementalTask?.base_task ?? fullTask;
    if (baseTask === null) {
      throw new TavernExtractionJobError("INVALID_REQUEST", "Extraction task was not prepared");
    }
    if (incrementalTask !== null && pendingRepairState === null) {
      const obsoleteRepairStore = new TavernIncrementalRepairWorldbookStore(
        this.port,
        baseTask.candidate.control.memory_set_id,
      );
      if ((await obsoleteRepairStore.read()) !== null) await obsoleteRepairStore.clear();
    }
    if (incrementalTask !== null && stagedIncremental && pendingStageState === null) {
      const obsoleteStageStore = new TavernIncrementalStageWorldbookStore(
        this.port,
        baseTask.candidate.control.memory_set_id,
      );
      if ((await obsoleteStageStore.read()) !== null) await obsoleteStageStore.clear();
    }
    const semanticStage: NarrativeIncrementalExtractionStage | null = stagedIncremental
      ? (pendingStageState?.next_stage ?? "foundation")
      : null;
    const semanticStagePrompt =
      semanticStage === null ? null : (semanticStagePrompts.get(semanticStage) ?? null);
    if (semanticStage !== null && semanticStagePrompt === null) {
      throw new TavernExtractionJobError(
        "PROMPT_ASSET_INVALID",
        `Missing semantic stage Prompt for ${semanticStage}`,
      );
    }
    const semanticTaskFingerprint = incrementalTask?.task_fingerprint ?? baseTask.task_fingerprint;
    const modelInput = incrementalTask?.model_input ?? baseTask.core_source.model_input;
    const incrementalValidationContext: NarrativeIncrementalCandidateValidationContext | null =
      incrementalTask === null
        ? null
        : {
            active_revision_id: baseTask.core_source.source_revision.revision_id,
            evidence_items: baseTask.core_source.evidence_items,
            known_entity_ids: incrementalTask.model_input.known_entities.map(
              (entity) => entity.entity_id,
            ),
            novel_evidence_ids: incrementalTask.model_input.novel_evidence.map(
              (evidence) => evidence.evidence_id,
            ),
            existing_semantic_context: incrementalTask.model_input.existing_semantic_context,
          };
    const modelInputSha256 = incrementalTask?.model_input_sha256 ?? baseTask.model_input_sha256;
    const coverageKeySha256 = incrementalTask?.coverage_key_sha256 ?? baseTask.coverage_key_sha256;
    const automaticRetryCallsUsed = pendingStageState?.automatic_retry_calls_used ?? 0;
    const effectiveMaxAttempts =
      semanticStage === null
        ? request.max_attempts
        : request.retry_round_id === undefined
          ? 1 + Math.max(0, request.max_attempts - 1 - automaticRetryCallsUsed)
          : 1;
    const preparedCancellation = this.cancellation(sequence, request.job_id);
    if (preparedCancellation !== null) return preparedCancellation;
    const operationFingerprint = await sha256HexUtf8(
      canonicalJson({
        operation_contract: incremental
          ? "narramem.tavern-incremental-extraction-operation/0.1.0"
          : "narramem.tavern-extraction-operation/0.1.0",
        semantic_task_fingerprint: semanticTaskFingerprint,
        source_revision_id: baseTask.core_source.source_revision.revision_id,
        source_checksum: baseTask.source_snapshot.checksum,
        model_input_sha256: modelInputSha256,
        requested_model_id: request.requested_model_id,
        prompt_asset_ref: adapter.prompt_asset_ref,
        prompt_body_sha256: promptAsset.body_sha256,
        parameters_sha256: parametersSha256,
        max_attempts: request.max_attempts,
        retry_round_id: request.retry_round_id ?? null,
        semantic_stage: semanticStage,
        semantic_stage_prompt_asset_ref: semanticStagePrompt?.prompt_asset_ref ?? null,
        semantic_stage_prompt_body_sha256: semanticStagePrompt?.prompt_body_sha256 ?? null,
        accumulated_partition_checksum: pendingStageState?.checksum ?? null,
      }),
    );
    const attemptStore = new TavernExtractionAttemptWorldbookStore(
      this.port,
      baseTask.candidate.control.memory_set_id,
    );
    const existing = baseTask.existing_semantic_manifest;
    if (
      incrementalTask === null &&
      existing !== null &&
      existing.source_revision_id === baseTask.core_source.source_revision.revision_id &&
      existing.source_checksum === baseTask.source_snapshot.checksum &&
      existing.coverage_key_sha256 === coverageKeySha256 &&
      existing.model_id === request.requested_model_id &&
      existing.model_identity_assurance === "requested_not_attested" &&
      existing.prompt_contract_version === adapter.prompt_asset_ref &&
      existing.prompt_body_sha256.value === promptAsset.body_sha256 &&
      existing.parameters_hash.value === parametersSha256
    ) {
      await attemptStore.reconcileCommittedIfPresent(
        operationFingerprint,
        new Date().toISOString(),
      );
      return {
        status: "ALREADY_CURRENT",
        audit,
        memory_set_id: baseTask.candidate.control.memory_set_id,
        source_revision_id: baseTask.core_source.source_revision.revision_id,
        semantic_task_fingerprint: existing.task_fingerprint,
      };
    }
    if (this.port.generateStructured === undefined || this.port.cancelGeneration === undefined) {
      throw new TavernExtractionJobError(
        "HOST_GENERATION_UNAVAILABLE",
        "Tavern HostPort must provide structured generation and per-ID cancellation",
      );
    }
    const generateStructured = this.port.generateStructured;
    const attemptDescriptor = {
      operation_fingerprint: operationFingerprint,
      semantic_task_fingerprint: semanticTaskFingerprint,
      source_revision_id: baseTask.core_source.source_revision.revision_id,
      source_checksum: baseTask.source_snapshot.checksum,
      model_input_sha256: modelInputSha256,
      requested_model_id: request.requested_model_id,
      prompt_asset_ref: adapter.prompt_asset_ref,
      prompt_body_sha256: promptAsset.body_sha256,
      parameters_sha256: parametersSha256,
      max_attempts: effectiveMaxAttempts,
      created_at: new Date().toISOString(),
    } as const;
    const opened = await attemptStore.openTask(attemptDescriptor, new Date().toISOString());
    let attemptTask: TavernExtractionAttemptTaskRecord = opened.task;
    let cancelledRecoveryDispatch: {
      readonly generation_id: string;
      readonly started_at_ms: number;
    } | null = null;
    if (
      attemptTask.status === "cancelled" &&
      request.cancelled_attempt_recovery === "explicit_runtime_rearm"
    ) {
      const attemptNumber = attemptTask.attempts.length + 1;
      const stageSuffix = semanticStage === null ? "" : `_s${stageIndex(semanticStage) + 1}`;
      const generationId = `narramem_extract_${request.job_id}${stageSuffix}_a${attemptNumber}`;
      const startedAtMs = Date.now();
      attemptTask = (
        await attemptStore.beginCancelledRecoveryAttempt(
          attemptDescriptor,
          generationId,
          new Date(startedAtMs).toISOString(),
        )
      ).task;
      cancelledRecoveryDispatch = { generation_id: generationId, started_at_ms: startedAtMs };
    }
    if (attemptTask.status !== "ready" && cancelledRecoveryDispatch === null) {
      const code =
        attemptTask.status === "exhausted"
          ? "ATTEMPTS_EXHAUSTED"
          : attemptTask.status === "suspended_unknown"
            ? "ATTEMPT_STATUS_UNKNOWN"
            : "ATTEMPT_LEDGER_BLOCKED";
      throw new TavernExtractionJobError(
        code,
        `Extraction operation ${operationFingerprint.slice(0, 12)} is blocked by durable attempt status ${attemptTask.status}`,
      );
    }

    const settleResponseRejection = async (
      generationId: string,
      startedAtMs: number,
      content: string,
      errorCode: string,
      diagnosticCodes: readonly string[] = [],
    ): Promise<void> => {
      const settled = await attemptStore.recordFailure(operationFingerprint, generationId, {
        status: "retryable_failure",
        settled_at: new Date().toISOString(),
        elapsed_ms: Math.max(0, Date.now() - startedAtMs),
        error_code: errorCode,
        diagnostic_codes: diagnosticCodes,
        response_sha256: await sha256HexUtf8(content),
        response_utf8_bytes: utf8ByteLength(content),
      });
      attemptTask = settled.task;
      if (attemptTask.status === "exhausted") {
        throw new TavernExtractionJobError(
          "ATTEMPTS_EXHAUSTED",
          `Extraction exhausted ${attemptTask.max_attempts} attempts; last rejection: ${errorCode}`,
          [errorCode, ...diagnosticCodes],
        );
      }
    };

    attemptLoop: while (attemptTask.status === "ready" || cancelledRecoveryDispatch !== null) {
      const loopCancellation = this.cancellation(sequence, request.job_id);
      if (loopCancellation !== null) return loopCancellation;
      let generationId: string;
      let startedAtMs: number;
      if (cancelledRecoveryDispatch !== null) {
        generationId = cancelledRecoveryDispatch.generation_id;
        startedAtMs = cancelledRecoveryDispatch.started_at_ms;
        cancelledRecoveryDispatch = null;
      } else {
        const attemptNumber = attemptTask.attempts.length + 1;
        const stageSuffix = semanticStage === null ? "" : `_s${stageIndex(semanticStage) + 1}`;
        generationId = `narramem_extract_${request.job_id}${stageSuffix}_a${attemptNumber}`;
        startedAtMs = Date.now();
        const dispatched = await attemptStore.beginAttempt(
          operationFingerprint,
          generationId,
          new Date(startedAtMs).toISOString(),
        );
        attemptTask = dispatched.task;
      }

      let cancelLocal: (reason: string, hostCancelRequested: boolean) => void = () => undefined;
      const localCancellation = new Promise<LocalCancellation>((resolve) => {
        cancelLocal = (reason, hostCancelRequested) =>
          resolve({ reason, host_cancel_requested: hostCancelRequested });
      });
      this.active = { sequence, generation_id: generationId, cancel_local: cancelLocal };
      let generation: Promise<TavernStructuredGenerationResult>;
      try {
        const manualRepairRecovery = pendingRepairState === null ? null : request.response_recovery;
        if (pendingRepairState !== null && manualRepairRecovery === undefined) {
          throw new TavernExtractionJobError(
            "INVALID_REQUEST",
            "Manual targeted repair requires the registered repair Prompt pair",
          );
        }
        const stageDependencyMessage =
          pendingStageState === null
            ? []
            : [
                {
                  role: "assistant" as const,
                  content: canonicalJson({
                    contract: "narramem.accepted-semantic-stage-dependencies/0.1.0",
                    completed_stages: pendingStageState.completed_stages,
                    accepted_batch: pendingStageState.partition.accepted_batch,
                  }),
                },
              ];
        const initialMessages =
          pendingRepairState !== null
            ? [
                {
                  role: "system" as const,
                  content: (manualRepairRecovery as TavernExtractionResponseRecoveryConfig)
                    .schema_repair_prompt_body,
                },
                {
                  role: "user" as const,
                  content: canonicalJson(
                    createNarrativeIncrementalRepairMaterial(
                      pendingRepairState.partition,
                      incrementalValidationContext as NarrativeIncrementalCandidateValidationContext,
                    ),
                  ),
                },
                {
                  role: "user" as const,
                  content: (manualRepairRecovery as TavernExtractionResponseRecoveryConfig)
                    .schema_repair_output_prompt_body,
                },
              ]
            : [
                { role: "system" as const, content: promptAsset.body },
                { role: "user" as const, content: canonicalJson(modelInput) },
                ...stageDependencyMessage,
                ...(semanticStagePrompt === null
                  ? []
                  : [{ role: "user" as const, content: semanticStagePrompt.prompt_body }]),
              ];
        generation = generateStructured({
          generation_id: generationId,
          target: {
            requested_model_id: request.requested_model_id,
            ...(request.proxy_preset === undefined ? {} : { proxy_preset: request.proxy_preset }),
            parameters: adapter.request_parameters,
            identity_assurance: "requested_not_attested",
          },
          messages: initialMessages,
          prompt_asset_refs:
            pendingRepairState === null
              ? [
                  adapter.prompt_asset_ref,
                  ...(semanticStagePrompt === null ? [] : [semanticStagePrompt.prompt_asset_ref]),
                ]
              : [
                  (manualRepairRecovery as TavernExtractionResponseRecoveryConfig)
                    .schema_repair_prompt_asset_ref,
                  (manualRepairRecovery as TavernExtractionResponseRecoveryConfig)
                    .schema_repair_output_prompt_asset_ref,
                ],
          json_schema: {
            name:
              semanticStage === null
                ? structuredSchemaName(adapter.output_schema)
                : `${structuredSchemaName(adapter.output_schema)}_${semanticStage}`,
            value:
              semanticStage === null || pendingRepairState !== null
                ? createStandaloneWireSchema(adapter.output_schema)
                : createStandaloneNarrativeIncrementalStageSchema(semanticStage),
            strict: true,
          },
          should_silence: true,
          should_stream: false,
          max_chat_history: 0,
        });
      } catch (error) {
        if (this.active?.sequence === sequence) this.active = null;
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: "unknown_after_dispatch",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: "GENERATION_FAILED",
        });
        throw new TavernExtractionJobError(
          "GENERATION_FAILED",
          error instanceof Error ? error.message : "Tavern structured generation failed",
        );
      }
      generation.catch(() => undefined);

      let outcome:
        | { readonly kind: "generation"; readonly result: TavernStructuredGenerationResult }
        | { readonly kind: "cancelled"; readonly cancellation: LocalCancellation };
      try {
        outcome = await Promise.race([
          generation.then((result) => ({ kind: "generation" as const, result })),
          localCancellation.then((cancellation) => ({ kind: "cancelled" as const, cancellation })),
        ]);
      } catch {
        const superseded = sequence !== this.latestSequence;
        const failed = await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: superseded
            ? this.latestReason === "newer_extraction_job"
              ? "superseded"
              : "cancelled"
            : "retryable_failure",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: superseded
            ? this.latestReason === "newer_extraction_job"
              ? "SUPERSEDED"
              : "CANCELLED"
            : "GENERATION_FAILED",
        });
        attemptTask = failed.task;
        if (superseded) {
          return {
            status: this.latestReason === "newer_extraction_job" ? "SUPERSEDED" : "CANCELLED",
            job_id: request.job_id,
            reason: this.latestReason,
            host_cancel_requested: false,
          };
        }
        if (attemptTask.status === "exhausted") {
          throw new TavernExtractionJobError(
            "ATTEMPTS_EXHAUSTED",
            `Extraction exhausted ${attemptTask.max_attempts} attempts after provider failures`,
          );
        }
        continue;
      } finally {
        if (this.active?.sequence === sequence) this.active = null;
      }

      if (outcome.kind === "cancelled") {
        let settledResponse: TavernStructuredGenerationResult | undefined;
        if (!outcome.cancellation.host_cancel_requested) {
          // SillyTavern cannot currently stop one generateRaw call by NarraMem ID.
          // Hold only the memory lane until the obsolete host promise settles.
          settledResponse = await generation.catch(() => undefined);
        }
        const content = settledResponse?.content;
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status:
            outcome.cancellation.reason === "newer_extraction_job" ? "superseded" : "cancelled",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code:
            outcome.cancellation.reason === "newer_extraction_job" ? "SUPERSEDED" : "CANCELLED",
          host_cancel_requested: outcome.cancellation.host_cancel_requested,
          ...(content === undefined
            ? {}
            : {
                response_sha256: await sha256HexUtf8(content),
                response_utf8_bytes: utf8ByteLength(content),
              }),
        });
        return {
          status:
            outcome.cancellation.reason === "newer_extraction_job" ? "SUPERSEDED" : "CANCELLED",
          job_id: request.job_id,
          reason: outcome.cancellation.reason,
          host_cancel_requested: outcome.cancellation.host_cancel_requested,
        };
      }

      let content = outcome.result.content;
      if (outcome.result.kind !== "text") {
        await settleResponseRejection(generationId, startedAtMs, content, "GENERATION_TOOL_CALLS");
        continue;
      }
      const dispatchRecovery = async (
        kind: "continuation" | "schema_repair" | "targeted_repair",
        callIndex: number,
        extraMessages: readonly {
          readonly role: "system" | "assistant" | "user";
          readonly content: string;
        }[],
      ): Promise<TavernStructuredGenerationResult | TavernExtractionJobResult> => {
        const recoveryId = `${generationId}_${kind}_${callIndex}`;
        let cancelLocal: (reason: string, hostCancelRequested: boolean) => void = () => undefined;
        const localCancellation = new Promise<LocalCancellation>((resolve) => {
          cancelLocal = (reason, hostCancelRequested) =>
            resolve({ reason, host_cancel_requested: hostCancelRequested });
        });
        this.active = { sequence, generation_id: recoveryId, cancel_local: cancelLocal };
        const recovery = request.response_recovery;
        if (recovery === undefined) {
          throw new TavernExtractionJobError(
            "INVALID_REQUEST",
            "Response recovery configuration disappeared",
          );
        }
        const promptAssetRef =
          kind === "continuation"
            ? recovery.continuation_prompt_asset_ref
            : recovery.schema_repair_prompt_asset_ref;
        const targeted = kind === "targeted_repair";
        const generation = generateStructured({
          generation_id: recoveryId,
          target: {
            requested_model_id: request.requested_model_id,
            ...(request.proxy_preset === undefined ? {} : { proxy_preset: request.proxy_preset }),
            parameters: adapter.request_parameters,
            identity_assurance: "requested_not_attested",
          },
          messages: targeted
            ? extraMessages
            : [
                { role: "system", content: promptAsset.body },
                { role: "user", content: canonicalJson(modelInput) },
                ...(pendingStageState === null
                  ? []
                  : [
                      {
                        role: "assistant" as const,
                        content: canonicalJson({
                          contract: "narramem.accepted-semantic-stage-dependencies/0.1.0",
                          completed_stages: pendingStageState.completed_stages,
                          accepted_batch: pendingStageState.partition.accepted_batch,
                        }),
                      },
                    ]),
                ...(semanticStagePrompt === null
                  ? []
                  : [{ role: "user" as const, content: semanticStagePrompt.prompt_body }]),
                ...extraMessages,
              ],
          prompt_asset_refs: targeted
            ? [
                recovery.schema_repair_prompt_asset_ref,
                recovery.schema_repair_output_prompt_asset_ref,
              ]
            : [
                adapter.prompt_asset_ref,
                ...(semanticStagePrompt === null ? [] : [semanticStagePrompt.prompt_asset_ref]),
                promptAssetRef,
              ],
          json_schema: {
            name:
              semanticStage === null || targeted
                ? structuredSchemaName(adapter.output_schema)
                : `${structuredSchemaName(adapter.output_schema)}_${semanticStage}`,
            value:
              semanticStage === null || targeted
                ? createStandaloneWireSchema(adapter.output_schema)
                : createStandaloneNarrativeIncrementalStageSchema(semanticStage),
            strict: true,
          },
          response_format: kind === "continuation" ? "text_fragment" : "structured_json",
          should_silence: true,
          should_stream: false,
          max_chat_history: 0,
        });
        generation.catch(() => undefined);
        try {
          const recovered = await Promise.race([
            generation.then((result) => ({ kind: "generation" as const, result })),
            localCancellation.then((cancellation) => ({
              kind: "cancelled" as const,
              cancellation,
            })),
          ]);
          if (recovered.kind === "generation") return recovered.result;
          if (!recovered.cancellation.host_cancel_requested)
            await generation.catch(() => undefined);
          return {
            status:
              recovered.cancellation.reason === "newer_extraction_job" ? "SUPERSEDED" : "CANCELLED",
            job_id: request.job_id,
            reason: recovered.cancellation.reason,
            host_cancel_requested: recovered.cancellation.host_cancel_requested,
          };
        } finally {
          if (this.active?.sequence === sequence) this.active = null;
        }
      };

      let parsed: ParsedCandidateBatch | ParsedIncrementalCandidateBatch | null = null;
      let continuationCalls = 0;
      let schemaRepairCalls = 0;
      let incrementalRepairedCount = 0;
      for (;;) {
        const responseSha256 = await sha256HexUtf8(content);
        try {
          if (pendingRepairState !== null) {
            const repairValue = JSON.parse(content) as unknown;
            const beforeAccepted = pendingRepairState.partition.accepted_target_keys.length;
            const repairedPartition = applyNarrativeIncrementalCandidateRepair(
              pendingRepairState.partition,
              repairValue,
              incrementalValidationContext as NarrativeIncrementalCandidateValidationContext,
            );
            incrementalRepairedCount += Math.max(
              0,
              repairedPartition.accepted_target_keys.length - beforeAccepted,
            );
            parsed = parsedIncrementalPartition(
              repairedPartition,
              incrementalValidationContext as NarrativeIncrementalCandidateValidationContext,
              responseSha256,
            );
          } else {
            parsed =
              incrementalTask === null
                ? parseCandidateBatch(
                    content,
                    adapter as TavernExtractionModelAdapter,
                    baseTask.core_source.model_input.default_story_time,
                    baseTask.core_source.evidence_items,
                    responseSha256,
                  )
                : semanticStage === null
                  ? parseIncrementalCandidateBatch(
                      content,
                      incrementalValidationContext as NarrativeIncrementalCandidateValidationContext,
                      responseSha256,
                    )
                  : parseStagedIncrementalCandidateBatch(
                      content,
                      semanticStage,
                      pendingStageState?.partition ?? null,
                      incrementalValidationContext as NarrativeIncrementalCandidateValidationContext,
                      responseSha256,
                    );
          }
          break;
        } catch (error) {
          if (error instanceof SyntaxError && pendingRepairState !== null) {
            await settleResponseRejection(
              generationId,
              startedAtMs,
              content,
              "RESPONSE_JSON_INVALID",
            );
            break;
          }
          if (error instanceof TavernIncrementalCandidatePartitionError) {
            await settleResponseRejection(
              generationId,
              startedAtMs,
              content,
              "RESPONSE_SCHEMA_INVALID",
              error.diagnostic_codes,
            );
            break;
          }
          if (!(error instanceof TavernExtractionJobError)) throw error;
          const recovery = request.response_recovery;
          if (
            error.code === "RESPONSE_JSON_INVALID" &&
            recovery !== undefined &&
            continuationCalls < recovery.continuation_max_calls &&
            looksLikeTruncatedJson(content)
          ) {
            continuationCalls += 1;
            const recovered = await dispatchRecovery("continuation", continuationCalls, [
              { role: "user", content: recovery.continuation_prompt_body },
              { role: "assistant", content },
            ]).catch(() => null);
            if (recovered === null) {
              await settleResponseRejection(
                generationId,
                startedAtMs,
                content,
                "GENERATION_FAILED",
                ["RECOVERY_CONTINUATION_FAILED"],
              );
              break;
            }
            if ("status" in recovered) return recovered;
            if (recovered.kind !== "text") {
              await settleResponseRejection(
                generationId,
                startedAtMs,
                content,
                "GENERATION_TOOL_CALLS",
                ["RECOVERY_CONTINUATION_TOOL_CALLS"],
              );
              break;
            }
            content += recovered.content;
            continue;
          }
          if (
            error.code === "RESPONSE_SCHEMA_INVALID" &&
            recovery !== undefined &&
            schemaRepairCalls < recovery.schema_repair_max_calls
          ) {
            schemaRepairCalls += 1;
            const repairInstructions = `${recovery.schema_repair_prompt_body}\n\n${canonicalJson({ diagnostic_codes: error.diagnostic_codes })}`;
            const recovered = await dispatchRecovery("schema_repair", schemaRepairCalls, [
              { role: "assistant", content },
              { role: "user", content: repairInstructions },
            ]).catch(() => null);
            if (recovered === null) {
              await settleResponseRejection(
                generationId,
                startedAtMs,
                content,
                "GENERATION_FAILED",
                ["RECOVERY_SCHEMA_REPAIR_FAILED"],
              );
              break;
            }
            if ("status" in recovered) return recovered;
            if (recovered.kind !== "text") {
              await settleResponseRejection(
                generationId,
                startedAtMs,
                content,
                "GENERATION_TOOL_CALLS",
                ["RECOVERY_SCHEMA_REPAIR_TOOL_CALLS"],
              );
              break;
            }
            content = recovered.content;
            continue;
          }
          if (error.code === "RESPONSE_JSON_INVALID" || error.code === "RESPONSE_SCHEMA_INVALID") {
            await settleResponseRejection(
              generationId,
              startedAtMs,
              content,
              error.code,
              error.diagnostic_codes,
            );
            break;
          }
          throw error;
        }
      }
      if (parsed === null) continue;
      if (
        incrementalValidationContext !== null &&
        "partition" in parsed &&
        pendingRepairState === null &&
        request.response_recovery !== undefined
      ) {
        const recovery = request.response_recovery;
        while (
          parsed.partition.quarantined.length > 0 &&
          schemaRepairCalls < recovery.schema_repair_max_calls
        ) {
          schemaRepairCalls += 1;
          const beforeAccepted = parsed.partition.accepted_target_keys.length;
          const repairMaterial = createNarrativeIncrementalRepairMaterial(
            parsed.partition,
            incrementalValidationContext,
          );
          const recovered = await dispatchRecovery("targeted_repair", schemaRepairCalls, [
            { role: "system", content: recovery.schema_repair_prompt_body },
            { role: "user", content: canonicalJson(repairMaterial) },
            { role: "user", content: recovery.schema_repair_output_prompt_body },
          ]).catch(() => null);
          if (recovered === null) break;
          if ("status" in recovered) return recovered;
          if (recovered.kind !== "text") break;
          let repairValue: unknown;
          try {
            repairValue = JSON.parse(recovered.content) as unknown;
            const nextPartition = applyNarrativeIncrementalCandidateRepair(
              parsed.partition,
              repairValue,
              incrementalValidationContext,
            );
            incrementalRepairedCount += Math.max(
              0,
              nextPartition.accepted_target_keys.length - beforeAccepted,
            );
            content = recovered.content;
            parsed = parsedIncrementalPartition(
              nextPartition,
              incrementalValidationContext,
              await sha256HexUtf8(recovered.content),
            );
          } catch {
            continue;
          }
          if (parsed.partition.accepted_target_keys.length === beforeAccepted) continue;
        }
      }
      const responseSha256 = await sha256HexUtf8(content);
      let incrementalPartition = "partition" in parsed ? parsed.partition : null;
      const responseCancellation = this.cancellation(sequence, request.job_id);
      if (responseCancellation !== null) {
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: responseCancellation.status === "SUPERSEDED" ? "superseded" : "cancelled",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: responseCancellation.status,
          response_sha256: responseSha256,
          response_utf8_bytes: utf8ByteLength(content),
        });
        return responseCancellation;
      }

      let commit: TavernSemanticCommitResult | TavernIncrementalSemanticCommitResult | null = null;
      const compilationKey =
        pendingRepairState?.compilation_key ??
        pendingStageState?.compilation_key ??
        `tavern-extraction:${adapter.adapter_id}:${operationFingerprint}`;
      const repairStore =
        incrementalTask === null
          ? null
          : new TavernIncrementalRepairWorldbookStore(
              this.port,
              baseTask.candidate.control.memory_set_id,
            );
      const stageStore =
        incrementalTask === null || semanticStage === null
          ? null
          : new TavernIncrementalStageWorldbookStore(
              this.port,
              baseTask.candidate.control.memory_set_id,
            );
      const extractor = {
        model_id: request.requested_model_id,
        model_identity_assurance: "requested_not_attested" as const,
        prompt_contract_version: adapter.prompt_asset_ref,
        prompt_body_sha256: createSha256Digest(promptAsset.body_sha256),
        parameters_hash: createSha256Digest(parametersSha256),
      };
      for (;;) {
        if (
          repairStore !== null &&
          incrementalTask !== null &&
          incrementalPartition !== null &&
          incrementalPartition.quarantined.length > 0
        ) {
          await repairStore.write({
            source_revision_id: baseTask.core_source.source_revision.revision_id,
            source_checksum: baseTask.source_snapshot.checksum,
            semantic_task_fingerprint: incrementalTask.task_fingerprint,
            compilation_key: compilationKey,
            boundary: incrementalTask.boundary,
            model_input: incrementalTask.model_input,
            partition: incrementalPartition,
            updated_at: new Date().toISOString(),
          });
        }
        try {
          const commonCommit = {
            extractor,
            compilation_key: compilationKey,
            compiled_at: request.compiled_at,
            writer_id: request.writer_id,
            transaction_id: `tx_extract_${operationFingerprint.slice(0, 32)}`,
            build_id: request.build_id,
            view_id: `view_extract_${operationFingerprint.slice(0, 32)}`,
            quality_audit: parsed.quality_audit,
          };
          commit =
            incrementalTask === null
              ? await this.semantic.commitCandidateBatch({
                  ...commonCommit,
                  task: baseTask,
                  candidate_batch: parsed.candidate_batch as NarrativeExtractionCandidateBatch,
                })
              : await this.semantic.commitIncrementalCandidateBatch({
                  ...commonCommit,
                  task: incrementalTask,
                  candidate_batch:
                    parsed.candidate_batch as NarrativeIncrementalExtractionCandidateBatch,
                  completion:
                    (incrementalPartition !== null &&
                      incrementalPartition.quarantined.length > 0) ||
                    (semanticStage !== null && nextSemanticStage(semanticStage) !== null)
                      ? "partial_repair_pending"
                      : "complete",
                });
          break;
        } catch (error) {
          if (
            error instanceof CandidateCompilationError &&
            incrementalTask !== null &&
            incrementalPartition !== null &&
            incrementalValidationContext !== null &&
            error.candidate_keys.length > 0
          ) {
            const beforeAccepted = incrementalPartition.accepted_target_keys.length;
            const nextPartition = quarantineNarrativeIncrementalCandidateTargets(
              incrementalPartition,
              error.candidate_keys.map((candidateKey) => ({
                candidate_key: candidateKey,
                diagnostic_codes: error.codes,
                diagnostic_paths: error.diagnostic_paths,
              })),
              incrementalValidationContext,
            );
            if (nextPartition.accepted_target_keys.length >= beforeAccepted) {
              await settleResponseRejection(
                generationId,
                startedAtMs,
                content,
                "CANDIDATE_COMPILATION_REJECTED",
                error.codes,
              );
              continue attemptLoop;
            }
            incrementalPartition = nextPartition;
            parsed = parsedIncrementalPartition(
              nextPartition,
              incrementalValidationContext,
              await sha256HexUtf8(content),
            );
            const recovery = request.response_recovery;
            if (recovery !== undefined && schemaRepairCalls < recovery.schema_repair_max_calls) {
              schemaRepairCalls += 1;
              const acceptedBeforeRepair = nextPartition.accepted_target_keys.length;
              const repairMaterial = createNarrativeIncrementalRepairMaterial(
                nextPartition,
                incrementalValidationContext,
              );
              const recovered = await dispatchRecovery("targeted_repair", schemaRepairCalls, [
                { role: "system", content: recovery.schema_repair_prompt_body },
                { role: "user", content: canonicalJson(repairMaterial) },
                { role: "user", content: recovery.schema_repair_output_prompt_body },
              ]).catch(() => null);
              if (recovered !== null) {
                if ("status" in recovered) return recovered;
                if (recovered.kind === "text") {
                  try {
                    const repairedPartition = applyNarrativeIncrementalCandidateRepair(
                      nextPartition,
                      JSON.parse(recovered.content) as unknown,
                      incrementalValidationContext,
                    );
                    incrementalRepairedCount += Math.max(
                      0,
                      repairedPartition.accepted_target_keys.length - acceptedBeforeRepair,
                    );
                    content = recovered.content;
                    incrementalPartition = repairedPartition;
                    parsed = parsedIncrementalPartition(
                      repairedPartition,
                      incrementalValidationContext,
                      await sha256HexUtf8(recovered.content),
                    );
                  } catch {
                    // A malformed or still-invalid repair never blocks the accepted closure.
                  }
                }
              }
            }
            continue;
          }
          if (error instanceof CandidateCompilationError) {
            await settleResponseRejection(
              generationId,
              startedAtMs,
              content,
              "CANDIDATE_COMPILATION_REJECTED",
              error.codes,
            );
            continue attemptLoop;
          }
          if (error instanceof TavernSemanticArchiveError && error.code === "PROPOSAL_REJECTED") {
            await settleResponseRejection(generationId, startedAtMs, content, "PROPOSAL_REJECTED", [
              error.code,
            ]);
            continue attemptLoop;
          }
          if (
            error instanceof TavernSemanticArchiveError &&
            (error.code === "STALE_TASK" || error.code === "SOURCE_CHANGED_DURING_COMMIT")
          ) {
            await attemptStore.recordFailure(operationFingerprint, generationId, {
              status: "superseded",
              settled_at: new Date().toISOString(),
              elapsed_ms: Math.max(0, Date.now() - startedAtMs),
              error_code: error.code,
              response_sha256: responseSha256,
              response_utf8_bytes: utf8ByteLength(content),
            });
            return { status: "STALE", job_id: request.job_id, reason: error.code };
          }
          await attemptStore.recordFailure(operationFingerprint, generationId, {
            status: "terminal_failure",
            settled_at: new Date().toISOString(),
            elapsed_ms: Math.max(0, Date.now() - startedAtMs),
            error_code: "SEMANTIC_COMMIT_FAILED",
            diagnostic_codes:
              error instanceof TavernSemanticArchiveError ? [error.code] : ["UNCLASSIFIED_ERROR"],
            response_sha256: responseSha256,
            response_utf8_bytes: utf8ByteLength(content),
          });
          throw error;
        }
      }
      if (commit === null) {
        throw new TavernExtractionJobError(
          "ATTEMPT_LEDGER_BLOCKED",
          "Incremental commit loop exited without a durable result",
        );
      }
      if (
        repairStore !== null &&
        incrementalPartition !== null &&
        incrementalPartition.quarantined.length === 0
      ) {
        await repairStore.clear();
      }
      // The semantic archive is already durable here. If this ledger write is
      // interrupted, a later ALREADY_CURRENT pass reconciles the dispatched
      // attempt from the semantic manifest instead of reporting a false model failure.
      const committed = await attemptStore.recordCommitted(operationFingerprint, generationId, {
        committed_at: new Date().toISOString(),
        elapsed_ms: Math.max(0, Date.now() - startedAtMs),
        response_sha256: responseSha256,
        response_utf8_bytes: utf8ByteLength(content),
      });
      if (
        stageStore !== null &&
        semanticStage !== null &&
        incrementalTask !== null &&
        incrementalPartition !== null
      ) {
        const nextStage = nextSemanticStage(semanticStage);
        const quarantined = incrementalPartition.quarantined.length > 0;
        const completedStages = pendingStageState?.completed_stages ?? [];
        const automaticRetriesAfter =
          automaticRetryCallsUsed +
          (request.retry_round_id === undefined
            ? Math.max(0, committed.task.attempts.length - 1)
            : 0);
        if (quarantined || nextStage !== null) {
          await stageStore.write({
            source_revision_id: baseTask.core_source.source_revision.revision_id,
            source_checksum: baseTask.source_snapshot.checksum,
            semantic_task_fingerprint: incrementalTask.task_fingerprint,
            compilation_key: compilationKey,
            boundary: incrementalTask.boundary,
            model_input: incrementalTask.model_input,
            partition: incrementalPartition,
            next_stage: quarantined
              ? semanticStage
              : (nextStage as NarrativeIncrementalExtractionStage),
            completed_stages: quarantined
              ? completedStages
              : [...new Set([...completedStages, semanticStage])],
            automatic_retry_calls_used: automaticRetriesAfter,
            updated_at: new Date().toISOString(),
          });
        } else {
          await stageStore.clear();
        }
        if (!quarantined && nextStage !== null) {
          return this.execute(sequence, request);
        }
      }
      const incrementalCommit =
        incrementalTask === null ? null : (commit as TavernIncrementalSemanticCommitResult);
      const incrementalBacklog =
        incrementalTask === null || incrementalCommit === null
          ? undefined
          : {
              audit_version: "0.1.0" as const,
              total_message_count: baseTask.source_snapshot.messages.length,
              consumer_safe_covered_message_count_before:
                incrementalTask.previous_cursor?.consumer_safe_head?.covered_message_count ?? 0,
              semantic_covered_message_count_after:
                incrementalCommit.coverage.semantic_head.covered_message_count,
              remaining_message_count: Math.max(
                0,
                baseTask.source_snapshot.messages.length -
                  incrementalCommit.coverage.semantic_head.covered_message_count,
              ),
              chunk_sequence: incrementalTask.boundary.chunk_sequence,
              novel_message_count:
                incrementalCommit.coverage.semantic_head.covered_message_count -
                incrementalTask.boundary.covered_message_count,
              context_message_count: new Set(
                incrementalTask.model_input.context_evidence.map(
                  (evidence) => evidence.source_order.ordinal,
                ),
              ).size,
              model_input_utf8_bytes: utf8ByteLength(canonicalJson(modelInput)),
              response_utf8_bytes: utf8ByteLength(content),
              attempt_count: committed.task.attempts.length,
              elapsed_ms: Math.max(0, Date.now() - jobStartedAtMs),
              estimated_cost_usd: null,
              cost_status: "UNAVAILABLE_NO_ATTESTED_PROVIDER_USAGE" as const,
            };
      const incrementalPartitionAudit =
        incrementalPartition === null
          ? undefined
          : {
              partition_version: incrementalPartition.partition_version,
              total_record_count: incrementalPartition.total_record_count,
              accepted_record_count: incrementalPartition.accepted_target_keys.length,
              quarantined_record_count: incrementalPartition.quarantined.length,
              repaired_record_count: incrementalRepairedCount,
              quarantine: incrementalPartition.quarantined.map((item) => ({
                kind: item.kind,
                target_key: item.target_key,
                diagnostic_codes: item.diagnostic_codes,
                diagnostic_paths: item.diagnostic_paths,
              })),
            };
      if (
        incrementalPartition !== null &&
        incrementalPartition.quarantined.length > 0 &&
        incrementalBacklog !== undefined &&
        incrementalPartitionAudit !== undefined
      ) {
        return {
          status: "PARTIAL_COMMITTED",
          audit,
          memory_set_id: baseTask.candidate.control.memory_set_id,
          source_revision_id: baseTask.core_source.source_revision.revision_id,
          response_sha256: responseSha256,
          response_utf8_bytes: utf8ByteLength(content),
          attempt_count: committed.task.attempts.length,
          response_quality: parsed.quality_audit,
          incremental_backlog: incrementalBacklog,
          incremental_partition: incrementalPartitionAudit,
          candidate_batch: parsed.candidate_batch as NarrativeIncrementalExtractionCandidateBatch,
          commit: commit as TavernIncrementalSemanticCommitResult,
        };
      }
      return {
        status: "COMMITTED",
        audit,
        memory_set_id: baseTask.candidate.control.memory_set_id,
        source_revision_id: baseTask.core_source.source_revision.revision_id,
        response_sha256: responseSha256,
        response_utf8_bytes: utf8ByteLength(content),
        attempt_count: committed.task.attempts.length,
        response_quality: parsed.quality_audit,
        ...(incrementalBacklog === undefined ? {} : { incremental_backlog: incrementalBacklog }),
        ...(incrementalPartitionAudit === undefined
          ? {}
          : { incremental_partition: incrementalPartitionAudit }),
        candidate_batch: parsed.candidate_batch,
        commit,
      };
    }
    throw new TavernExtractionJobError(
      "ATTEMPT_LEDGER_BLOCKED",
      `Extraction operation cannot continue from durable status ${attemptTask.status}`,
    );
  }
}
