export interface CandidateCompilerContext extends ExtractionCandidateValidationContext {
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  /** Trusted per-job namespace; never copied from model output. */
  readonly compilation_key: string;
  readonly extractor: {
    readonly model_id: string;
    readonly prompt_contract_version: string;
    readonly parameters_hash: HashDigest;
  };
}

export interface CandidateHygieneFinding {
  readonly code: "CANDIDATE_ENTITY_SCENE_ONLY_DROPPED";
  readonly candidate_key: string;
  readonly message: string;
}

export interface CandidateHygieneResult<
  Batch extends
    | ExtractionCandidateBatch
    | NarrativeIncrementalExtractionCandidateBatch
    | NarrativeExtractionCandidateBatch
    | NarrativeExtractionCandidateBatchV020 = ExtractionCandidateBatch,
> {
  readonly batch: Batch;
  readonly findings: readonly CandidateHygieneFinding[];
}

function candidateEntityKey(
  reference: CandidateEntityRef | CandidatePrincipalRef,
): string | undefined {
  return reference.kind === "candidate_entity" ? reference.candidate_key : undefined;
}

/**
 * Removes decorative entity candidates that the model only listed as generic
 * Scene participants. Durable candidates must play an Event, location,
 * focalizer, or unresolved role. Every removal remains visible as a finding.
 */
export function applyCandidateHygiene<
  Batch extends
    | ExtractionCandidateBatch
    | NarrativeIncrementalExtractionCandidateBatch
    | NarrativeExtractionCandidateBatch
    | NarrativeExtractionCandidateBatchV020,
>(batch: Batch): CandidateHygieneResult<Batch> {
  const durableKeys = new Set<string>();
  const addReference = (reference: CandidateEntityRef | CandidatePrincipalRef): void => {
    const key = candidateEntityKey(reference);
    if (key !== undefined) durableKeys.add(key);
  };

  for (const scene of batch.scenes) {
    scene.location_refs.forEach(addReference);
    scene.focalizers.forEach(addReference);
  }
  for (const event of batch.events) {
    event.actor_refs.forEach(addReference);
    event.patient_refs.forEach(addReference);
    event.location_refs.forEach(addReference);
  }
  for (const unresolved of batch.unresolved_items) {
    for (const key of unresolved.related_candidate_keys) {
      durableKeys.add(key);
    }
  }
  if ("state_transitions" in batch) {
    for (const state of batch.state_transitions) {
      if (state.subject.kind === "entity") addReference(state.subject.entity);
      if (state.subject.kind === "relation") state.subject.participants.forEach(addReference);
    }
    for (const epistemic of batch.epistemic_states) {
      addReference(epistemic.holder);
      if (epistemic.source_entity !== undefined) addReference(epistemic.source_entity);
      if (epistemic.target.kind === "claim") {
        for (const argument of epistemic.target.claim.arguments) {
          if (argument.kind === "entity") addReference(argument.entity);
        }
      }
    }
    for (const causal of batch.causal_links) {
      if (causal.attribution.kind === "character_belief") addReference(causal.attribution.holder);
    }
  }

  const entityKeys = new Set(batch.entities.map((entity) => entity.candidate_key));
  const droppedKeys = new Set(
    [...entityKeys].filter((candidateKey) => !durableKeys.has(candidateKey)),
  );
  if (droppedKeys.size === 0) {
    return { batch, findings: [] };
  }

  const findings = [...droppedKeys].sort().map((candidateKey) => ({
    code: "CANDIDATE_ENTITY_SCENE_ONLY_DROPPED" as const,
    candidate_key: candidateKey,
    message: "Entity candidate had no durable role beyond a generic Scene participant reference",
  }));
  return {
    batch: {
      ...batch,
      entities: batch.entities.filter((entity) => !droppedKeys.has(entity.candidate_key)),
      scenes: batch.scenes.map((scene) => ({
        ...scene,
        participant_refs: scene.participant_refs.filter(
          (reference) =>
            reference.kind !== "candidate_entity" || !droppedKeys.has(reference.candidate_key),
        ),
      })),
    } as Batch,
    findings,
  };
}

interface AnchoredQuote {
  readonly span: EvidenceSpan;
  readonly source_order: SourceOrder;
}

function compareSourceOrder(left: SourceOrder, right: SourceOrder): number {
  return left.ordinal === right.ordinal
    ? left.component - right.component
    : left.ordinal - right.ordinal;
}

function sourceRange(orders: readonly SourceOrder[]): {
  readonly start: SourceOrder;
  readonly end: SourceOrder;
} {
  if (orders.length === 0) {
    throw new CandidateCompilationError("A compiled record requires source order", [
      "COMPILER_SOURCE_ORDER_MISSING",
    ]);
  }
  const sorted = [...orders].sort(compareSourceOrder);
  return { start: sorted[0] as SourceOrder, end: sorted.at(-1) as SourceOrder };
}

function findOccurrence(text: string, quote: string, requestedOccurrence: number): number {
  let searchFrom = 0;
  let occurrence = 0;
  while (searchFrom <= text.length) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) {
      break;
    }
    if (occurrence === requestedOccurrence) {
      return index;
    }
    occurrence += 1;
    searchFrom = index + Math.max(1, quote.length);
  }
  throw new CandidateCompilationError("Validated quote could not be anchored", [
    "COMPILER_QUOTE_NOT_FOUND",
  ]);
}

function codePointOffset(text: string, codeUnitOffset: number): number {
  return [...text.slice(0, codeUnitOffset)].length;
}

function confidence(level: CandidateSupportLevel): Confidence {
  if (level === "explicit") {
    return { level: "high", basis: "text_explicit" };
  }
  if (level === "strongly_implied") {
    return { level: "medium", basis: "text_implied" };
  }
  return { level: "low", basis: "model_inferred" };
}

function unique<T>(values: readonly T[]): readonly T[] {
  return [...new Set(values)];
}

function assertAllocatedId<Kind extends NarraMemIdKind>(
  kind: Kind,
  value: NarraMemId<Kind>,
): NarraMemId<Kind> {
  if (getNarraMemIdKind(value) !== kind) {
    throw new CandidateCompilationError(`ID allocator returned the wrong kind for ${kind}`, [
      "COMPILER_ID_KIND_INVALID",
    ]);
  }
  return value;
}

function resolveEntityRef(
  reference: CandidateEntityRef,
  entityIds: ReadonlyMap<string, EntityRef>,
): EntityRef {
  if (reference.kind === "existing_entity") {
    return reference.entity_id;
  }
  const entityId = entityIds.get(reference.candidate_key);
  if (entityId === undefined) {
    throw new CandidateCompilationError("Validated candidate entity reference did not resolve", [
      "COMPILER_ENTITY_REF_UNRESOLVED",
    ]);
  }
  return entityId;
}

function resolvePrincipalRef(
  reference: CandidatePrincipalRef,
  entityIds: ReadonlyMap<string, EntityRef>,
): EpistemicPrincipalRef {
  if (reference.kind === "existing_principal") {
    return reference.principal;
  }
  return { kind: "entity", entity_id: resolveEntityRef(reference, entityIds) };
}

async function anchorQuote(
  quote: CandidateEvidenceQuote,
  evidenceById: ReadonlyMap<string, EvidenceItem>,
  ports: CandidateCompilerPorts,
): Promise<AnchoredQuote> {
  const evidence = evidenceById.get(quote.evidence_id);
  if (evidence === undefined || evidence.raw_content.kind !== "text") {
    throw new CandidateCompilationError("Validated Evidence quote source disappeared", [
      "COMPILER_EVIDENCE_MISSING",
    ]);
  }
  const startCodeUnit = findOccurrence(
    evidence.raw_content.text,
    quote.quote,
    quote.occurrence ?? 0,
  );
  const endCodeUnit = startCodeUnit + quote.quote.length;
  const quoteHash = await ports.hash_text(quote.quote);
  if (!isHashDigest(quoteHash)) {
    throw new CandidateCompilationError("Hash port returned an invalid digest", [
      "COMPILER_HASH_INVALID",
    ]);
  }
  return {
    span: {
      evidence_id: quote.evidence_id,
      selector: {
        kind: "text_range",
        start_code_point: codePointOffset(evidence.raw_content.text, startCodeUnit),
        end_code_point: codePointOffset(evidence.raw_content.text, endCodeUnit),
      },
      quote_hash: quoteHash,
      support_role: quote.support_role,
    },
    source_order: evidence.source_order,
  };
}

async function fullEvidenceSpan(
  evidence: EvidenceItem,
  ports: CandidateCompilerPorts,
): Promise<EvidenceSpan> {
  if (evidence.raw_content.kind === "text") {
    const quoteHash = await ports.hash_text(evidence.raw_content.text);
    if (!isHashDigest(quoteHash)) {
      throw new CandidateCompilationError("Hash port returned an invalid digest", [
        "COMPILER_HASH_INVALID",
      ]);
    }
    return {
      evidence_id: evidence.evidence_id,
      selector: {
        kind: "text_range",
        start_code_point: 0,
        end_code_point: [...evidence.raw_content.text].length,
      },
      quote_hash: quoteHash,
      support_role: "context",
    };
  }
  return {
    evidence_id: evidence.evidence_id,
    selector: { kind: "field_set", fields: ["raw_content"] },
    quote_hash: evidence.content_fingerprint,
    support_role: "context",
  };
}

function derivation(
  stableKey: string,
  evidenceRefs: readonly NarraMemId<"evidence">[],
  dependencyRefs: readonly NarraMemId[],
  context: CandidateCompilerContext,
  ports: CandidateCompilerPorts,
  createdAt: string,
  extractorKind: "llm" | "rule" = "llm",
): DerivationMeta {
  return {
    derivation_id: assertAllocatedId(
      "derivation",
      ports.allocate_id(
        "derivation",
        `${context.active_revision_id}:${context.compilation_key}:derivation:${stableKey}`,
      ),
    ),
    input_revision_id: context.active_revision_id,
    evidence_refs: unique(evidenceRefs),
    dependency_refs: unique(dependencyRefs),
    extractor:
      extractorKind === "rule"
        ? { kind: "rule" }
        : {
            kind: "llm",
            model_id: context.extractor.model_id,
            prompt_contract_version: context.extractor.prompt_contract_version,
            parameters_hash: context.extractor.parameters_hash,
          },
    validator_version: "0.1.0",
    created_at: createdAt,
  };
}

export async function compileExtractionCandidateBatch(
  inputBatch: ExtractionCandidateBatch,
  context: CandidateCompilerContext,
  ports: CandidateCompilerPorts,
  options: { readonly apply_hygiene?: boolean } = {},
): Promise<ModelChangeSetProposal> {
  const batch =
    options.apply_hygiene === false ? inputBatch : applyCandidateHygiene(inputBatch).batch;
  const report = validateExtractionCandidateBatch(batch, context);
  if (!report.accepted) {
    throw new CandidateCompilationError(
      "Extraction candidate batch failed validation",
      report.issues.map((item) => item.code),
    );
  }
  if (!isHashDigest(context.extractor.parameters_hash)) {
    throw new CandidateCompilationError("Extractor parameters hash is invalid", [
      "COMPILER_PARAMETERS_HASH_INVALID",
    ]);
  }
  if (context.compilation_key.length === 0) {
    throw new CandidateCompilationError("Trusted compilation key cannot be empty", [
      "COMPILER_NAMESPACE_INVALID",
    ]);
  }
  const createdAt = ports.now();
  if (!isIsoInstant(createdAt)) {
    throw new CandidateCompilationError("Clock port returned a non-ISO instant", [
      "COMPILER_CLOCK_INVALID",
    ]);
  }

  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const entityIds = new Map<string, EntityRef>(
    batch.entities.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "entity",
        ports.allocate_id(
          "entity",
          `${context.active_revision_id}:${context.compilation_key}:entity:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const sceneIds = new Map(
    batch.scenes.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "scene",
        ports.allocate_id(
          "scene",
          `${context.active_revision_id}:${context.compilation_key}:scene:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const eventIds = new Map(
    batch.events.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "event",
        ports.allocate_id(
          "event",
          `${context.active_revision_id}:${context.compilation_key}:event:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );

  const entityOperations = await Promise.all(
    batch.entities.map(async (candidate) => {
      const anchored = await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      );
      const evidence = anchored.map((item) => item.span);
      const entityId = entityIds.get(candidate.candidate_key) as EntityRef;
      return {
        op: "add_derived" as const,
        record: {
          entity_id: entityId,
          memory_space_id: context.memory_space_id,
          branch_id: context.branch_id,
          entity_type: candidate.entity_type,
          canonical_label: candidate.canonical_label,
          aliases: candidate.aliases.map((label) => ({ label, evidence })),
          identity_evidence: evidence,
          merge_status: "candidate" as const,
          derivation: derivation(
            candidate.candidate_key,
            evidence.map((span) => span.evidence_id),
            [],
            context,
            ports,
            createdAt,
          ),
        },
      };
    }),
  );

  const sceneOperations = await Promise.all(
    batch.scenes.map(async (candidate) => {
      const sourceEvidence = candidate.source_evidence_ids.map((evidenceId) => {
        const evidence = evidenceById.get(evidenceId);
        if (evidence === undefined) {
          throw new CandidateCompilationError("Validated Scene Evidence disappeared", [
            "COMPILER_EVIDENCE_MISSING",
          ]);
        }
        return evidence;
      });
      const evidence = await Promise.all(
        sourceEvidence.map((item) => fullEvidenceSpan(item, ports)),
      );
      const locationIds = candidate.location_refs.map((item) => resolveEntityRef(item, entityIds));
      const participantIds = candidate.participant_refs.map((item) =>
        resolveEntityRef(item, entityIds),
      );
      const focalizers = candidate.focalizers.map((item) => resolvePrincipalRef(item, entityIds));
      return {
        op: "add_derived" as const,
        record: {
          scene_id: sceneIds.get(candidate.candidate_key) as NarraMemId<"scene">,
          memory_space_id: context.memory_space_id,
          branch_id: context.branch_id,
          source_revision_id: context.active_revision_id,
          source_range: sourceRange(sourceEvidence.map((item) => item.source_order)),
          story_time: candidate.story_time,
          location_ids: locationIds,
          participant_ids: participantIds,
          focalizers,
          ...(candidate.atmosphere_labels.length === 0
            ? {}
            : {
                atmosphere: {
                  labels: candidate.atmosphere_labels,
                  evidence,
                },
              }),
          evidence,
          confidence: confidence(candidate.support_level),
          derivation: derivation(
            candidate.candidate_key,
            evidence.map((span) => span.evidence_id),
            unique([...locationIds, ...participantIds]),
            context,
            ports,
            createdAt,
          ),
        },
      };
    }),
  );

  const eventOperations = await Promise.all(
    batch.events.map(async (candidate) => {
      const anchored = await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      );
      const actorIds = candidate.actor_refs.map((item) => resolveEntityRef(item, entityIds));
      const patientIds = candidate.patient_refs.map((item) => resolveEntityRef(item, entityIds));
      const locationIds = candidate.location_refs.map((item) => resolveEntityRef(item, entityIds));
      const sceneId = sceneIds.get(candidate.scene_candidate_key) as NarraMemId<"scene">;
      return {
        op: "add_derived" as const,
        record: {
          event_id: eventIds.get(candidate.candidate_key) as NarraMemId<"event">,
          memory_space_id: context.memory_space_id,
          branch_id: context.branch_id,
          event_type: candidate.event_type,
          actor_ids: actorIds,
          patient_ids: patientIds,
          action_or_occurrence: candidate.action_or_occurrence,
          location_ids: locationIds,
          story_time: candidate.story_time,
          source_range: sourceRange(anchored.map((item) => item.source_order)),
          intentionality: candidate.intentionality,
          immediate_result_refs: [],
          evidence: anchored.map((item) => item.span),
          confidence: confidence(candidate.support_level),
          derivation: derivation(
            candidate.candidate_key,
            anchored.map((item) => item.span.evidence_id),
            unique([sceneId, ...actorIds, ...patientIds, ...locationIds]),
            context,
            ports,
            createdAt,
          ),
        },
      };
    }),
  );

  const candidateRecordIds = new Map<string, NarraMemId>([...entityIds, ...sceneIds, ...eventIds]);
  return {
    stage: "proposal",
    changeset_id: assertAllocatedId(
      "change_set",
      ports.allocate_id(
        "change_set",
        `${context.active_revision_id}:${context.compilation_key}:change_set`,
      ),
    ),
    memory_space_id: context.memory_space_id,
    branch_id: context.branch_id,
    based_on_revision_id: context.active_revision_id,
    producer: "llm",
    operations: [...entityOperations, ...sceneOperations, ...eventOperations],
    unresolved_items: batch.unresolved_items.map((item) => ({
      code: item.code,
      question: item.question,
      related_refs: item.related_candidate_keys.flatMap((key) => {
        const recordId = candidateRecordIds.get(key);
        return recordId === undefined ? [] : [recordId];
      }),
      required_evidence: item.required_evidence,
    })),
    created_at: createdAt,
  };
}

function resolveStateSubject(
  subject: NarrativeExtractionCandidateBatch["state_transitions"][number]["subject"],
  entityIds: ReadonlyMap<string, EntityRef>,
): StateSubjectRef {
  if (subject.kind === "world") return subject;
  if (subject.kind === "entity") {
    return { kind: "entity", entity_id: resolveEntityRef(subject.entity, entityIds) };
  }
  return {
    kind: "relation",
    relation_type: subject.relation_type,
    participant_ids: subject.participants.map((reference) =>
      resolveEntityRef(reference, entityIds),
    ),
  };
}

function resolveClaimArgument(
  argument: CandidateClaimArgument,
  entityIds: ReadonlyMap<string, EntityRef>,
  eventIds: ReadonlyMap<string, NarraMemId<"event">>,
  deltaIds: ReadonlyMap<string, NarraMemId<"state_delta">>,
): StructuredClaim["arguments"][number] {
  if (argument.kind === "entity") {
    return { kind: "entity", entity_id: resolveEntityRef(argument.entity, entityIds) };
  }
  if (argument.kind === "event") {
    return {
      kind: "record",
      record_id: eventIds.get(argument.event_candidate_key) as NarraMemId<"event">,
    };
  }
  if (argument.kind === "state_delta") {
    return {
      kind: "record",
      record_id: deltaIds.get(argument.state_candidate_key) as NarraMemId<"state_delta">,
    };
  }
  return argument;
}

function resolveCausalCause(
  reference: CandidateCausalCauseRef,
  eventIds: ReadonlyMap<string, NarraMemId<"event">>,
  deltaIds: ReadonlyMap<string, NarraMemId<"state_delta">>,
  epistemicIds: ReadonlyMap<string, NarraMemId<"epistemic_state">>,
): CausalCauseRef {
  if (reference.kind === "event") {
    return {
      kind: "event",
      event_id: eventIds.get(reference.event_candidate_key) as NarraMemId<"event">,
    };
  }
  if (reference.kind === "state_delta") {
    return {
      kind: "state_delta",
      delta_id: deltaIds.get(reference.state_candidate_key) as NarraMemId<"state_delta">,
    };
  }
  return {
    kind: "epistemic_state",
    epistemic_id: epistemicIds.get(
      reference.epistemic_candidate_key,
    ) as NarraMemId<"epistemic_state">,
  };
}

function resolveCausalEffect(
  reference: CandidateCausalCauseRef,
  eventIds: ReadonlyMap<string, NarraMemId<"event">>,
  deltaIds: ReadonlyMap<string, NarraMemId<"state_delta">>,
  epistemicIds: ReadonlyMap<string, NarraMemId<"epistemic_state">>,
): CausalEffectRef {
  return resolveCausalCause(reference, eventIds, deltaIds, epistemicIds) as CausalEffectRef;
}

function subjectKey(subject: StateSubjectRef): string {
  if (subject.kind === "entity") return `entity:${subject.entity_id}`;
  if (subject.kind === "world") return `world:${subject.scope_key}`;
  return `relation:${subject.relation_type}:${[...subject.participant_ids].sort().join(",")}`;
}

function splitSupport(spans: readonly EvidenceSpan[]): {
  readonly support: readonly EvidenceSpan[];
  readonly counterevidence: readonly EvidenceSpan[];
} {
  return {
    support: spans.filter((span) => span.support_role !== "contradiction"),
    counterevidence: spans.filter((span) => span.support_role === "contradiction"),
  };
}

/**
 * Compiles the v0.2 narrative candidate boundary. Base Scene/Event extraction
 * stays compatible with v0.1 while State, Epistemic, and Causal records are
 * resolved in one atomic proposal.
 */
export async function compileNarrativeExtractionCandidateBatch(
  inputBatch: NarrativeExtractionCandidateBatch,
  context: CandidateCompilerContext,
  ports: CandidateCompilerPorts,
  options: { readonly apply_hygiene?: boolean } = {},
): Promise<ModelChangeSetProposal> {
  const hygienic =
    options.apply_hygiene === false ? inputBatch : applyCandidateHygiene(inputBatch).batch;
  const report = validateNarrativeExtractionCandidateBatch(hygienic, context);
  if (!report.accepted) {
    throw new CandidateCompilationError(
      "Narrative extraction candidate batch failed validation",
      report.issues.map((item) => item.code),
    );
  }
  const baseBatch: ExtractionCandidateBatch = {
    contract_version: "0.1.0",
    source_revision_id: hygienic.source_revision_id,
    entities: hygienic.entities,
    scenes: hygienic.scenes,
    events: hygienic.events,
    unresolved_items: [],
  };
  const base = await compileExtractionCandidateBatch(baseBatch, context, ports, {
    apply_hygiene: false,
  });
  const baseRecords = base.operations.flatMap((operation) =>
    operation.op === "add_derived" ? [operation.record] : [],
  );
  const entityRecords = baseRecords.filter((record) => "entity_id" in record);
  const eventRecords = baseRecords.filter((record) => "event_id" in record);
  const entityIds = new Map<string, EntityRef>(
    hygienic.entities.map((candidate, index) => [
      candidate.candidate_key,
      (entityRecords[index] as { readonly entity_id: EntityRef }).entity_id,
    ]),
  );
  const eventIds = new Map<string, NarraMemId<"event">>(
    hygienic.events.map((candidate, index) => [
      candidate.candidate_key,
      (eventRecords[index] as { readonly event_id: NarraMemId<"event"> }).event_id,
    ]),
  );
  const deltaIds = new Map(
    hygienic.state_transitions.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "state_delta",
        ports.allocate_id(
          "state_delta",
          `${context.active_revision_id}:${context.compilation_key}:state_delta:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const assertionIds = new Map(
    hygienic.state_transitions.flatMap((candidate) =>
      candidate.after_state.status === "known"
        ? [
            [
              candidate.candidate_key,
              assertAllocatedId(
                "state_assertion",
                ports.allocate_id(
                  "state_assertion",
                  `${context.active_revision_id}:${context.compilation_key}:state_assertion:${candidate.candidate_key}`,
                ),
              ),
            ] as const,
          ]
        : [],
    ),
  );
  const propositionIds = new Map(
    hygienic.epistemic_states.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "proposition",
        ports.allocate_id(
          "proposition",
          `${context.active_revision_id}:${context.compilation_key}:proposition:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const epistemicIds = new Map(
    hygienic.epistemic_states.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "epistemic_state",
        ports.allocate_id(
          "epistemic_state",
          `${context.active_revision_id}:${context.compilation_key}:epistemic_state:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const causalIds = new Map(
    hygienic.causal_links.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "causal_link",
        ports.allocate_id(
          "causal_link",
          `${context.active_revision_id}:${context.compilation_key}:causal_link:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const createdAt = ports.now();
  if (!isIsoInstant(createdAt)) {
    throw new CandidateCompilationError("Clock port returned a non-ISO instant", [
      "COMPILER_CLOCK_INVALID",
    ]);
  }
  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const anchoredStates = await Promise.all(
    hygienic.state_transitions.map(async (candidate) => ({
      candidate,
      anchored: await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      ),
    })),
  );
  const anchoredEpistemics = await Promise.all(
    hygienic.epistemic_states.map(async (candidate) => ({
      candidate,
      anchored: await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      ),
    })),
  );
  const anchoredCausals = await Promise.all(
    hygienic.causal_links.map(async (candidate) => ({
      candidate,
      anchored: await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      ),
    })),
  );

  const causedEventsByState = new Map<string, NarraMemId<"event">[]>();
  for (const causal of hygienic.causal_links) {
    const causeEvents = causal.cause_refs.flatMap((reference) =>
      reference.kind === "event"
        ? [eventIds.get(reference.event_candidate_key) as NarraMemId<"event">]
        : [],
    );
    for (const effect of causal.effect_refs) {
      if (effect.kind !== "state_delta") continue;
      const existing = causedEventsByState.get(effect.state_candidate_key) ?? [];
      existing.push(...causeEvents);
      causedEventsByState.set(effect.state_candidate_key, existing);
    }
  }

  const stateDeltas: StateDelta[] = [];
  const stateAssertions: StateAssertion[] = [];
  const stateOrder = new Map<string, SourceOrder>();
  for (const { candidate, anchored } of anchoredStates) {
    const spans = anchored.map((item) => item.span);
    const subject = resolveStateSubject(candidate.subject, entityIds);
    const causedBy = unique(causedEventsByState.get(candidate.candidate_key) ?? []);
    const cooccurs = unique(
      candidate.cooccurring_event_keys
        .map((key) => eventIds.get(key) as NarraMemId<"event">)
        .filter((eventId) => !causedBy.includes(eventId)),
    );
    const dependencies = unique([
      ...candidate.cooccurring_event_keys.map((key) => eventIds.get(key) as NarraMemId<"event">),
      ...(subject.kind === "entity"
        ? [subject.entity_id]
        : subject.kind === "relation"
          ? subject.participant_ids
          : []),
    ]);
    const delta: StateDelta = {
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      delta_id: deltaIds.get(candidate.candidate_key) as NarraMemId<"state_delta">,
      subject,
      state_key: candidate.state_key,
      operation: candidate.operation,
      ...(candidate.before_state.status === "known"
        ? { before: candidate.before_state.value }
        : {}),
      ...(candidate.after_state.status === "known" ? { after: candidate.after_state.value } : {}),
      ...(candidate.magnitude === undefined ? {} : { magnitude: candidate.magnitude }),
      ...(causedBy.length === 0 ? {} : { caused_by: causedBy }),
      ...(cooccurs.length === 0 ? {} : { cooccurs_with: cooccurs }),
      valid_from: candidate.valid_from,
      ...(candidate.valid_until === undefined ? {} : { valid_until: candidate.valid_until }),
      evidence: spans,
      confidence: confidence(candidate.support_level),
      derivation: derivation(
        `state_delta:${candidate.candidate_key}`,
        spans.map((span) => span.evidence_id),
        dependencies,
        context,
        ports,
        createdAt,
      ),
    };
    stateDeltas.push(delta);
    stateOrder.set(
      candidate.candidate_key,
      sourceRange(anchored.map((item) => item.source_order)).end,
    );
    if (candidate.after_state.status === "known") {
      const assertionId = assertionIds.get(
        candidate.candidate_key,
      ) as NarraMemId<"state_assertion">;
      stateAssertions.push({
        memory_space_id: context.memory_space_id,
        branch_id: context.branch_id,
        assertion_id: assertionId,
        subject,
        state_key: candidate.state_key,
        value: candidate.after_state.value,
        valid_time: candidate.valid_from,
        authority: "interpretation",
        evidence: spans,
        confidence: confidence(candidate.support_level),
        derivation: derivation(
          `state_assertion:${candidate.candidate_key}`,
          spans.map((span) => span.evidence_id),
          [delta.delta_id],
          context,
          ports,
          createdAt,
        ),
      });
    }
  }

  const propositions = [];
  const epistemicStates: EpistemicState[] = [];
  for (const { candidate, anchored } of anchoredEpistemics) {
    const spans = anchored.map((item) => item.span);
    const partitioned = splitSupport(spans);
    const target = candidate.target;
    let claim: StructuredClaim;
    let targetDependencies: NarraMemId[];
    if (target.kind === "event") {
      const eventId = eventIds.get(target.event_candidate_key) as NarraMemId<"event">;
      targetDependencies = [eventId];
      claim = { predicate: "event_occurred", arguments: [{ kind: "record", record_id: eventId }] };
    } else if (target.kind === "state") {
      const stateId =
        assertionIds.get(target.state_candidate_key) ??
        (deltaIds.get(target.state_candidate_key) as NarraMemId<"state_delta">);
      targetDependencies = [stateId];
      claim = { predicate: "state_holds", arguments: [{ kind: "record", record_id: stateId }] };
    } else {
      const claimDependencies: NarraMemId[] = [];
      claim = {
        predicate: target.claim.predicate,
        arguments: target.claim.arguments.map((argument) => {
          const resolved = resolveClaimArgument(argument, entityIds, eventIds, deltaIds);
          if (resolved.kind !== "literal") {
            claimDependencies.push(
              resolved.kind === "entity" ? resolved.entity_id : resolved.record_id,
            );
          }
          return resolved;
        }),
        ...(target.claim.negated === undefined ? {} : { negated: target.claim.negated }),
        ...(target.claim.qualifiers === undefined ? {} : { qualifiers: target.claim.qualifiers }),
      };
      targetDependencies = claimDependencies;
    }
    const propositionId = propositionIds.get(candidate.candidate_key) as NarraMemId<"proposition">;
    const sourceEventIds = candidate.source_event_keys.map(
      (key) => eventIds.get(key) as NarraMemId<"event">,
    );
    const propositionDependencies = unique([...targetDependencies, ...sourceEventIds]);
    propositions.push({
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      proposition_id: propositionId,
      claim,
      objective_status: "unknown" as const,
      valid_time: candidate.valid_time,
      support: partitioned.support,
      counterevidence: partitioned.counterevidence,
      derivation: derivation(
        `proposition:${candidate.candidate_key}`,
        spans.map((span) => span.evidence_id),
        propositionDependencies,
        context,
        ports,
        createdAt,
      ),
    });
    const holder = resolvePrincipalRef(candidate.holder, entityIds);
    const sourceEntityId =
      candidate.source_entity === undefined
        ? undefined
        : resolveEntityRef(candidate.source_entity, entityIds);
    epistemicStates.push({
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      epistemic_id: epistemicIds.get(candidate.candidate_key) as NarraMemId<"epistemic_state">,
      holder,
      proposition_id: propositionId,
      mode: candidate.mode,
      certainty: candidate.certainty,
      confidence: confidence(candidate.support_level),
      ...(candidate.acquired_via === undefined ? {} : { acquired_via: candidate.acquired_via }),
      ...(sourceEntityId === undefined ? {} : { source_entity_id: sourceEntityId }),
      valid_time: candidate.valid_time,
      evidence: spans,
      derivation: derivation(
        `epistemic_state:${candidate.candidate_key}`,
        spans.map((span) => span.evidence_id),
        unique([
          propositionId,
          ...sourceEventIds,
          ...(holder.kind === "entity" ? [holder.entity_id] : []),
          ...(sourceEntityId === undefined ? [] : [sourceEntityId]),
        ]),
        context,
        ports,
        createdAt,
      ),
    });
  }

  const causalLinks = anchoredCausals.map(({ candidate, anchored }) => {
    const spans = anchored.map((item) => item.span);
    const partitioned = splitSupport(spans);
    const causeRefs = candidate.cause_refs.map((reference) =>
      resolveCausalCause(reference, eventIds, deltaIds, epistemicIds),
    );
    const effectRefs = candidate.effect_refs.map((reference) =>
      resolveCausalEffect(reference, eventIds, deltaIds, epistemicIds),
    );
    const holder =
      candidate.attribution.kind === "character_belief"
        ? resolvePrincipalRef(candidate.attribution.holder, entityIds)
        : undefined;
    const causeDependencyRefs: NarraMemId[] = [];
    for (const reference of causeRefs) {
      if (reference.kind === "event") causeDependencyRefs.push(reference.event_id);
      if (reference.kind === "state_assertion") causeDependencyRefs.push(reference.assertion_id);
      if (reference.kind === "state_delta") causeDependencyRefs.push(reference.delta_id);
      if (reference.kind === "epistemic_state") causeDependencyRefs.push(reference.epistemic_id);
      if (reference.kind === "proposition") causeDependencyRefs.push(reference.proposition_id);
      if (reference.kind === "narrative_thread") causeDependencyRefs.push(reference.thread_id);
    }
    const dependencyRefs = unique<NarraMemId>([
      ...causeDependencyRefs,
      ...effectRefs.map((reference) =>
        reference.kind === "event"
          ? reference.event_id
          : reference.kind === "state_delta"
            ? reference.delta_id
            : reference.kind === "epistemic_state"
              ? reference.epistemic_id
              : reference.thread_id,
      ),
      ...(holder?.kind === "entity" ? [holder.entity_id] : []),
    ]);
    return {
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      causal_id: causalIds.get(candidate.candidate_key) as NarraMemId<"causal_link">,
      cause_refs: causeRefs,
      effect_refs: effectRefs,
      relation: candidate.relation,
      mechanism: candidate.mechanism,
      scope: candidate.attribution.kind,
      ...(holder === undefined ? {} : { holder }),
      necessity: candidate.necessity,
      strength: candidate.strength,
      ...(candidate.persistence === undefined ? {} : { persistence: candidate.persistence }),
      support: partitioned.support,
      counterevidence: partitioned.counterevidence,
      confidence: confidence(candidate.support_level),
      derivation: derivation(
        `causal_link:${candidate.candidate_key}`,
        spans.map((span) => span.evidence_id),
        dependencyRefs,
        context,
        ports,
        createdAt,
      ),
    };
  });

  const assertionByState = new Map(
    hygienic.state_transitions.flatMap((candidate) => {
      const assertion = stateAssertions.find(
        (item) => item.assertion_id === assertionIds.get(candidate.candidate_key),
      );
      return assertion === undefined ? [] : [[candidate.candidate_key, assertion] as const];
    }),
  );
  const latestBySubject = new Map<string, string>();
  for (const candidate of hygienic.state_transitions) {
    const subject = resolveStateSubject(candidate.subject, entityIds);
    const key = `${subjectKey(subject)}|${candidate.state_key}`;
    const previous = latestBySubject.get(key);
    if (
      previous === undefined ||
      compareSourceOrder(
        stateOrder.get(previous) as SourceOrder,
        stateOrder.get(candidate.candidate_key) as SourceOrder,
      ) <= 0
    ) {
      latestBySubject.set(key, candidate.candidate_key);
    }
  }
  const currentAssertionIds = [...latestBySubject.values()]
    .flatMap((key) => {
      const assertion = assertionByState.get(key);
      return assertion === undefined ? [] : [assertion.assertion_id];
    })
    .sort();
  const projectionHash =
    hygienic.state_transitions.length === 0
      ? undefined
      : await ports.hash_text(JSON.stringify(currentAssertionIds));
  if (projectionHash !== undefined && !isHashDigest(projectionHash)) {
    throw new CandidateCompilationError("Hash port returned an invalid digest", [
      "COMPILER_HASH_INVALID",
    ]);
  }
  const currentStateView: CurrentStateView | undefined =
    hygienic.state_transitions.length === 0
      ? undefined
      : {
          memory_space_id: context.memory_space_id,
          branch_id: context.branch_id,
          view_id: assertAllocatedId(
            "current_state_view",
            ports.allocate_id(
              "current_state_view",
              `${context.active_revision_id}:${context.compilation_key}:current_state_view`,
            ),
          ),
          checkpoint: context.evidence_items
            .map((item) => item.source_order)
            .sort(compareSourceOrder)
            .at(-1) as SourceOrder,
          source_revision_id: context.active_revision_id,
          assertion_refs: currentAssertionIds,
          projection_hash: projectionHash as HashDigest,
          derivation: derivation(
            "current_state_view",
            unique(stateDeltas.flatMap((delta) => delta.derivation.evidence_refs)),
            stateDeltas.map((delta) => delta.delta_id),
            context,
            ports,
            createdAt,
            "rule",
          ),
        };

  const resultIdsByEvent = new Map<string, NarraMemId<"state_delta">[]>();
  for (const candidate of hygienic.state_transitions) {
    for (const eventKey of candidate.cooccurring_event_keys) {
      const refs = resultIdsByEvent.get(eventKey) ?? [];
      refs.push(deltaIds.get(candidate.candidate_key) as NarraMemId<"state_delta">);
      resultIdsByEvent.set(eventKey, refs);
    }
  }
  let eventCursor = 0;
  const updatedBaseOperations = base.operations.map((operation) => {
    if (operation.op !== "add_derived" || !("event_id" in operation.record)) return operation;
    const candidate = hygienic.events[eventCursor];
    eventCursor += 1;
    return {
      ...operation,
      record: {
        ...operation.record,
        immediate_result_refs:
          candidate === undefined
            ? []
            : unique(resultIdsByEvent.get(candidate.candidate_key) ?? []),
      },
    };
  });
  const candidateRecordIds = new Map<string, NarraMemId>([
    ...entityIds,
    ...eventIds,
    ...deltaIds,
    ...epistemicIds,
    ...causalIds,
  ]);
  return {
    ...base,
    producer: "hybrid",
    operations: [
      ...updatedBaseOperations,
      ...stateDeltas.map((record) => ({ op: "add_derived" as const, record })),
      ...stateAssertions.map((record) => ({ op: "add_derived" as const, record })),
      ...propositions.map((record) => ({ op: "add_derived" as const, record })),
      ...epistemicStates.map((record) => ({ op: "add_derived" as const, record })),
      ...causalLinks.map((record) => ({ op: "add_derived" as const, record })),
      ...(currentStateView === undefined
        ? []
        : [{ op: "add_derived" as const, record: currentStateView }]),
    ],
    unresolved_items: hygienic.unresolved_items.map((item) => ({
      code: item.code,
      question: item.question,
      related_refs: item.related_candidate_keys.flatMap((key) => {
        const recordId = candidateRecordIds.get(key);
        return recordId === undefined ? [] : [recordId];
      }),
      required_evidence: item.required_evidence,
    })),
  };
}

export interface NarrativeIncrementalCandidateCompilerContext extends CandidateCompilerContext {
  readonly novel_evidence_ids: readonly NarraMemId<"evidence">[];
  readonly existing_semantic_context: NarrativeIncrementalCandidateValidationContext["existing_semantic_context"];
}

function assertIncrementalExistingScope(
  context: NarrativeIncrementalCandidateCompilerContext,
): void {
  const groups: readonly (readonly {
    readonly memory_space_id: NarraMemId<"memory_space">;
    readonly branch_id: NarraMemId<"branch">;
  }[])[] = [
    context.existing_semantic_context.scenes,
    context.existing_semantic_context.episodes,
    context.existing_semantic_context.events,
    context.existing_semantic_context.state_assertions,
    context.existing_semantic_context.state_deltas,
    context.existing_semantic_context.propositions,
    context.existing_semantic_context.epistemic_states,
    context.existing_semantic_context.causal_links,
  ];
  for (const record of groups.flat()) {
    if (
      record.memory_space_id !== context.memory_space_id ||
      record.branch_id !== context.branch_id
    ) {
      throw new CandidateCompilationError(
        "Authenticated incremental semantic context crossed its trusted scope",
        ["INCREMENTAL_EXISTING_SCOPE_MISMATCH"],
      );
    }
  }
}

type ResolvedIncrementalCausalEndpoint =
  | { readonly kind: "event"; readonly event_id: NarraMemId<"event"> }
  | { readonly kind: "state_delta"; readonly delta_id: NarraMemId<"state_delta"> }
  | {
      readonly kind: "epistemic_state";
      readonly epistemic_id: NarraMemId<"epistemic_state">;
    };

function resolveIncrementalCausalEndpoint(
  reference: NarrativeIncrementalCausalEndpointRef,
  eventIds: ReadonlyMap<string, NarraMemId<"event">>,
  deltaIds: ReadonlyMap<string, NarraMemId<"state_delta">>,
  epistemicIds: ReadonlyMap<string, NarraMemId<"epistemic_state">>,
): ResolvedIncrementalCausalEndpoint {
  if (reference.kind === "event") {
    return {
      kind: "event",
      event_id: eventIds.get(reference.event_candidate_key) as NarraMemId<"event">,
    };
  }
  if (reference.kind === "state_delta") {
    return {
      kind: "state_delta",
      delta_id: deltaIds.get(reference.state_candidate_key) as NarraMemId<"state_delta">,
    };
  }
  if (reference.kind === "epistemic_state") {
    return {
      kind: "epistemic_state",
      epistemic_id: epistemicIds.get(
        reference.epistemic_candidate_key,
      ) as NarraMemId<"epistemic_state">,
    };
  }
  if (reference.kind === "existing_event") {
    return { kind: "event", event_id: reference.event_id };
  }
  if (reference.kind === "existing_state_delta") {
    return { kind: "state_delta", delta_id: reference.delta_id };
  }
  return { kind: "epistemic_state", epistemic_id: reference.epistemic_id };
}

/**
 * Compiles one bounded semantic chunk without authoring a partial CurrentStateView.
 * Existing causal endpoints remain read-only dependencies; the later trusted-merge
 * stage recomputes the one consumer-visible view from the complete merged corpus.
 */
export async function compileNarrativeIncrementalExtractionCandidateBatch(
  inputBatch: NarrativeIncrementalExtractionCandidateBatch,
  context: NarrativeIncrementalCandidateCompilerContext,
  ports: CandidateCompilerPorts,
): Promise<ModelChangeSetProposal> {
  assertIncrementalExistingScope(context);
  const hygienic = applyCandidateHygiene(inputBatch).batch;
  const report = validateNarrativeIncrementalExtractionCandidateBatch(hygienic, context);
  if (!report.accepted) {
    throw new CandidateCompilationError(
      "Incremental narrative extraction candidate batch failed validation",
      report.issues.map((item) => item.code),
    );
  }

  const baseBatch: NarrativeExtractionCandidateBatch = {
    contract_version: "0.3.0",
    source_revision_id: hygienic.source_revision_id,
    entities: hygienic.entities,
    scenes: hygienic.scenes,
    events: hygienic.events,
    state_transitions: hygienic.state_transitions,
    epistemic_states: hygienic.epistemic_states,
    causal_links: [],
    unresolved_items: [],
  };
  const base = await compileNarrativeExtractionCandidateBatch(baseBatch, context, ports, {
    // The complete incremental batch was already cleaned above while causal
    // attribution references were still present. Re-running hygiene on this
    // causal-free projection can wrongly delete entities used only as belief
    // holders and desynchronize the compiled record arrays.
    apply_hygiene: false,
  });
  const addedRecords = base.operations.flatMap((operation) =>
    operation.op === "add_derived" ? [operation.record] : [],
  );
  const entityRecords = addedRecords.filter((record) => "entity_id" in record);
  const eventRecords = addedRecords.filter((record) => "event_id" in record);
  const deltaRecords = addedRecords.filter((record) => "delta_id" in record);
  const epistemicRecords = addedRecords.filter((record) => "epistemic_id" in record);
  const entityIds = new Map<string, EntityRef>(
    hygienic.entities.map((candidate, index) => [
      candidate.candidate_key,
      (entityRecords[index] as { readonly entity_id: EntityRef }).entity_id,
    ]),
  );
  const eventIds = new Map<string, NarraMemId<"event">>(
    hygienic.events.map((candidate, index) => [
      candidate.candidate_key,
      (eventRecords[index] as { readonly event_id: NarraMemId<"event"> }).event_id,
    ]),
  );
  const deltaIds = new Map<string, NarraMemId<"state_delta">>(
    hygienic.state_transitions.map((candidate, index) => [
      candidate.candidate_key,
      (deltaRecords[index] as { readonly delta_id: NarraMemId<"state_delta"> }).delta_id,
    ]),
  );
  const epistemicIds = new Map<string, NarraMemId<"epistemic_state">>(
    hygienic.epistemic_states.map((candidate, index) => [
      candidate.candidate_key,
      (epistemicRecords[index] as { readonly epistemic_id: NarraMemId<"epistemic_state"> })
        .epistemic_id,
    ]),
  );
  const causalIds = new Map(
    hygienic.causal_links.map((candidate) => [
      candidate.candidate_key,
      assertAllocatedId(
        "causal_link",
        ports.allocate_id(
          "causal_link",
          `${context.active_revision_id}:${context.compilation_key}:causal_link:${candidate.candidate_key}`,
        ),
      ),
    ]),
  );
  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const anchoredCausals = await Promise.all(
    hygienic.causal_links.map(async (candidate) => ({
      candidate,
      anchored: await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      ),
    })),
  );

  const causedEventsByNewState = new Map<string, NarraMemId<"event">[]>();
  for (const candidate of hygienic.causal_links) {
    const causeEventIds = candidate.cause_refs.flatMap((reference) => {
      if (reference.kind === "event") {
        return [eventIds.get(reference.event_candidate_key) as NarraMemId<"event">];
      }
      return reference.kind === "existing_event" ? [reference.event_id] : [];
    });
    for (const effect of candidate.effect_refs) {
      if (effect.kind !== "state_delta") continue;
      const existing = causedEventsByNewState.get(effect.state_candidate_key) ?? [];
      existing.push(...causeEventIds);
      causedEventsByNewState.set(effect.state_candidate_key, existing);
    }
  }

  const stateKeyById = new Map([...deltaIds].map(([key, value]) => [value, key]));
  const baseOperations: (typeof base.operations)[number][] = [];
  for (const operation of base.operations) {
    if (operation.op !== "add_derived") {
      baseOperations.push(operation);
      continue;
    }
    if ("view_id" in operation.record) continue;
    if (!("delta_id" in operation.record)) {
      baseOperations.push(operation);
      continue;
    }
    const candidateKey = stateKeyById.get(operation.record.delta_id);
    const newlyCausedBy = unique(
      candidateKey === undefined ? [] : (causedEventsByNewState.get(candidateKey) ?? []),
    );
    if (newlyCausedBy.length === 0) {
      baseOperations.push(operation);
      continue;
    }
    const causedBy = unique([...(operation.record.caused_by ?? []), ...newlyCausedBy]);
    const cooccursWith = (operation.record.cooccurs_with ?? []).filter(
      (eventId) => !causedBy.includes(eventId),
    );
    const { cooccurs_with: _cooccursWith, ...recordWithoutCooccurs } = operation.record;
    baseOperations.push({
      ...operation,
      record: {
        ...recordWithoutCooccurs,
        caused_by: causedBy,
        ...(cooccursWith.length === 0 ? {} : { cooccurs_with: cooccursWith }),
        derivation: {
          ...operation.record.derivation,
          dependency_refs: unique([
            ...operation.record.derivation.dependency_refs,
            ...newlyCausedBy,
          ]),
        },
      },
    });
  }

  const causalLinks = anchoredCausals.map(({ candidate, anchored }) => {
    const spans = anchored.map((item) => item.span);
    const partitioned = splitSupport(spans);
    const causeRefs = candidate.cause_refs.map((reference) =>
      resolveIncrementalCausalEndpoint(reference, eventIds, deltaIds, epistemicIds),
    );
    const effectRefs = candidate.effect_refs.map(
      (reference) =>
        resolveIncrementalCausalEndpoint(
          reference,
          eventIds,
          deltaIds,
          epistemicIds,
        ) as CausalEffectRef,
    );
    const holder =
      candidate.attribution.kind === "character_belief"
        ? resolvePrincipalRef(candidate.attribution.holder, entityIds)
        : undefined;
    const dependencyRefs = unique<NarraMemId>([
      ...causeRefs.map((reference) =>
        reference.kind === "event"
          ? reference.event_id
          : reference.kind === "state_delta"
            ? reference.delta_id
            : reference.epistemic_id,
      ),
      ...effectRefs.map((reference) =>
        reference.kind === "event"
          ? reference.event_id
          : reference.kind === "state_delta"
            ? reference.delta_id
            : reference.kind === "epistemic_state"
              ? reference.epistemic_id
              : reference.thread_id,
      ),
      ...(holder?.kind === "entity" ? [holder.entity_id] : []),
    ]);
    return {
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      causal_id: causalIds.get(candidate.candidate_key) as NarraMemId<"causal_link">,
      cause_refs: causeRefs,
      effect_refs: effectRefs,
      relation: candidate.relation,
      mechanism: candidate.mechanism,
      scope: candidate.attribution.kind,
      ...(holder === undefined ? {} : { holder }),
      necessity: candidate.necessity,
      strength: candidate.strength,
      ...(candidate.persistence === undefined ? {} : { persistence: candidate.persistence }),
      support: partitioned.support,
      counterevidence: partitioned.counterevidence,
      confidence: confidence(candidate.support_level),
      derivation: derivation(
        `causal_link:${candidate.candidate_key}`,
        spans.map((span) => span.evidence_id),
        dependencyRefs,
        context,
        ports,
        base.created_at,
      ),
    };
  });

  const candidateRecordIds = new Map<string, NarraMemId>([
    ...entityIds,
    ...eventIds,
    ...deltaIds,
    ...epistemicIds,
    ...causalIds,
  ]);
  return {
    ...base,
    producer: "hybrid",
    operations: [
      ...baseOperations,
      ...causalLinks.map((record) => ({ op: "add_derived" as const, record })),
    ],
    unresolved_items: hygienic.unresolved_items.map((item) => ({
      code: item.code,
      question: item.question,
      related_refs: item.related_candidate_keys.flatMap((key) => {
        const recordId = candidateRecordIds.get(key);
        return recordId === undefined ? [] : [recordId];
      }),
      required_evidence: item.required_evidence,
    })),
  };
}
