const INSTALLATION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/u;
const SAFE_RUNTIME_TOKEN_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,39}$/u;
const PROMPT_REF_PATTERN = /^(NM-P[0-9]{4})@([0-9]+\.[0-9]+\.[0-9]+)$/u;
const SLOT_SYMBOL = Symbol.for(TAVERN_EXTENSION_RUNTIME_SLOT_KEY);

type GlobalSlotRecord = typeof globalThis & Record<PropertyKey, unknown>;

function isRuntimeHandle(value: unknown): value is TavernExtensionRuntimeHandle {
  if (value === null || typeof value !== "object") return false;
  const candidate = value as Partial<TavernExtensionRuntimeHandle>;
  return (
    candidate.runtime_version === TAVERN_EXTENSION_RUNTIME_VERSION &&
    typeof candidate.installation_id === "string" &&
    typeof candidate.start === "function" &&
    typeof candidate.stop === "function" &&
    typeof candidate.flushNow === "function" &&
    typeof candidate.subscribeReports === "function" &&
    typeof candidate.subscribeRecallReports === "function" &&
    typeof candidate.getSnapshot === "function" &&
    typeof candidate.getRecallSnapshot === "function" &&
    typeof candidate.inspectPrincipalBinding === "function" &&
    typeof candidate.bindPrincipal === "function" &&
    typeof candidate.assembleReadOnlyQuery === "function" &&
    typeof candidate.resolveMemorySet === "function" &&
    typeof candidate.dispose === "function"
  );
}

function assertConfig(config: TavernExtensionRuntimeConfig): void {
  if (!INSTALLATION_ID_PATTERN.test(config.installation_id)) {
    throw new TavernExtensionRuntimeError(
      "INVALID_CONFIG",
      "installation_id must be 1-64 safe ASCII characters",
    );
  }
  if (
    config.observer.extraction.prompt_body.length === 0 ||
    (config.observer.lifecycle !== undefined &&
      config.observer.lifecycle.prompt_body.length === 0) ||
    config.recall.prompt_body.length === 0
  ) {
    throw new TavernExtensionRuntimeError(
      "INVALID_CONFIG",
      "Exact model-specific extraction and Recall Markdown Prompt bodies are required",
    );
  }
}

export async function buildTavernRuntimeLifecyclePromptAsset(
  compatibilityRoute: string,
  body: string,
): Promise<TavernRuntimeLifecyclePromptBuildResult> {
  let adapter: TavernNarrativeLifecycleModelAdapter;
  try {
    adapter = resolveTavernNarrativeLifecycleModelAdapter(compatibilityRoute);
  } catch (error) {
    throw new TavernExtensionRuntimeError(
      "PROMPT_ASSET_INVALID",
      error instanceof Error ? error.message : "No exact lifecycle Prompt route",
    );
  }
  const refMatch = PROMPT_REF_PATTERN.exec(adapter.prompt_asset_ref);
  if (
    refMatch === null ||
    body.startsWith("\uFEFF") ||
    body.includes("\r") ||
    body.includes("{{NARRAMEM:") ||
    (await sha256HexUtf8(body)) !== adapter.prompt_body_sha256
  ) {
    throw new TavernExtensionRuntimeError(
      "PROMPT_ASSET_INVALID",
      `Build-time lifecycle Prompt body does not match ${adapter.prompt_asset_ref}`,
    );
  }
  const promptId = refMatch[1];
  const semanticVersion = refMatch[2];
  if (promptId === undefined || semanticVersion === undefined) {
    throw new TavernExtensionRuntimeError(
      "PROMPT_ASSET_INVALID",
      `Invalid lifecycle Prompt ref: ${adapter.prompt_asset_ref}`,
    );
  }
  return {
    compatibility_route: adapter.family,
    asset: {
      prompt_asset_ref: adapter.prompt_asset_ref,
      prompt_id: promptId,
      semantic_version: semanticVersion,
      status: adapter.status,
      body,
      body_sha256: adapter.prompt_body_sha256,
      message_role: "system",
      position: "independent_model_call.system",
      variables: [],
      input_schema: adapter.input_schema,
      output_schema: adapter.output_schema,
      provider_scope: `model-family:${adapter.family}`,
    },
  };
}

export function createBrowserTavernPageLifecyclePort(): TavernPageLifecyclePort {
  if (
    typeof globalThis.addEventListener !== "function" ||
    typeof globalThis.removeEventListener !== "function"
  ) {
    throw new TavernExtensionRuntimeError(
      "BROWSER_LIFECYCLE_UNAVAILABLE",
      "Browser pagehide/pageshow lifecycle is unavailable",
    );
  }
  return {
    add_listener: (eventName, listener) => globalThis.addEventListener(eventName, listener),
    remove_listener: (eventName, listener) => globalThis.removeEventListener(eventName, listener),
  };
}

export function createBrowserTavernExtensionRuntimeSlot(): TavernExtensionRuntimeSlot {
  const root = globalThis as GlobalSlotRecord;
  return {
    get: () => {
      const value = root[SLOT_SYMBOL];
      if (value === undefined) return null;
      if (!isRuntimeHandle(value)) {
        throw new TavernExtensionRuntimeError(
          "INSTALLATION_SLOT_CORRUPT",
          "The NarraMem runtime page slot contains an unknown value",
        );
      }
      return value;
    },
    set: (handle) => {
      if (handle === null) {
        Reflect.deleteProperty(root, SLOT_SYMBOL);
      } else {
        root[SLOT_SYMBOL] = handle;
      }
    },
  };
}

export async function buildTavernRuntimePromptAsset(
  compatibilityRoute: string,
  body: string,
): Promise<TavernRuntimePromptBuildResult> {
  let adapter: TavernIncrementalExtractionModelAdapter;
  try {
    adapter = resolveTavernIncrementalExtractionModelAdapter(compatibilityRoute);
  } catch (error) {
    throw new TavernExtensionRuntimeError(
      "PROMPT_ASSET_INVALID",
      error instanceof Error ? error.message : "No exact model-specific Prompt route",
    );
  }
  const refMatch = PROMPT_REF_PATTERN.exec(adapter.prompt_asset_ref);
  if (
    refMatch === null ||
    body.startsWith("\uFEFF") ||
    body.includes("\r") ||
    body.includes("{{NARRAMEM:") ||
    (await sha256HexUtf8(body)) !== adapter.prompt_body_sha256
  ) {
    throw new TavernExtensionRuntimeError(
      "PROMPT_ASSET_INVALID",
      `Build-time Prompt body does not match ${adapter.prompt_asset_ref}`,
    );
  }
  const promptId = refMatch[1];
  const semanticVersion = refMatch[2];
  if (promptId === undefined || semanticVersion === undefined) {
    throw new TavernExtensionRuntimeError(
      "PROMPT_ASSET_INVALID",
      `Invalid Prompt ref: ${adapter.prompt_asset_ref}`,
    );
  }
  const asset: TavernRuntimePromptAsset = {
    prompt_asset_ref: adapter.prompt_asset_ref,
    prompt_id: promptId,
    semantic_version: semanticVersion,
    status: adapter.status,
    body,
    body_sha256: adapter.prompt_body_sha256,
    message_role: "system",
    position: "independent_model_call.system",
    variables: [],
    input_schema: "narrative_incremental_extraction_model_input",
    output_schema: adapter.output_schema,
    provider_scope: `model-family:${adapter.family}`,
  };
  return { asset, compatibility_route: adapter.family };
}

class TavernExtensionRuntime implements TavernExtensionRuntimeHandle {
  readonly runtime_version = TAVERN_EXTENSION_RUNTIME_VERSION;
  private disposed = false;
  private reportSubscription: TavernEventSubscription | null = null;
  private recallReportSubscription: TavernEventSubscription | null = null;
  private performanceSampleSubscription: TavernEventSubscription | null = null;
  private performanceRecallSubscription: TavernEventSubscription | null = null;
  private lifecycleAttached = false;
  private pageHidden = false;
  private readonly onPageHide = () => {
    this.pageHidden = true;
    if (!this.disposed) {
      this.recallBarrier.pagehide();
      this.scheduler.pagehide();
      this.performanceProbe.stop();
    }
  };
  private readonly onPageShow = () => {
    this.pageHidden = false;
    if (!this.disposed && (this.shouldResumeOnPageShow?.() ?? true)) {
      this.performanceProbe.start();
      this.scheduler.start();
      this.recallBarrier.start();
    }
  };

  constructor(
    readonly installation_id: string,
    private readonly scheduler: TavernObserverScheduler,
    private readonly recallBarrier: TavernRecallGenerationBarrier,
    private readonly recall: TavernRecallService,
    private readonly performanceProbe: TavernInteractionPerformanceProbe,
    private readonly currentArchive: TavernCurrentArchiveCoordinator,
    private readonly principalBinding: TavernPrincipalBindingService,
    private readonly observerRuntime: TavernObserverRuntime,
    private readonly config: TavernExtensionRuntimeConfig,
    private readonly lifecycle: TavernPageLifecyclePort,
    private readonly slot: TavernExtensionRuntimeSlot,
    private readonly initialReportListener?: (report: TavernObserverCycleReport) => void,
    private readonly initialRecallReportListener?: (
      report: TavernRecallGenerationBarrierReport,
    ) => void,
    private readonly initialPerformanceListener?: TavernInteractionPerformanceListener,
    private readonly shouldResumeOnPageShow?: () => boolean,
  ) {}

  activate(): void {
    try {
      this.lifecycle.add_listener("pagehide", this.onPageHide);
      this.lifecycleAttached = true;
      this.lifecycle.add_listener("pageshow", this.onPageShow);
      if (this.initialReportListener !== undefined) {
        this.reportSubscription = this.scheduler.subscribeReports(this.initialReportListener);
      }
      if (this.initialRecallReportListener !== undefined) {
        this.recallReportSubscription = this.recallBarrier.subscribeReports(
          this.initialRecallReportListener,
        );
      }
      this.performanceRecallSubscription = this.recallBarrier.subscribeReports((report) => {
        this.performanceProbe.recordRecallReport(report);
      });
      if (this.initialPerformanceListener !== undefined) {
        this.performanceSampleSubscription = this.performanceProbe.subscribeSamples(
          this.initialPerformanceListener,
        );
      }
      this.performanceProbe.start();
      this.scheduler.start();
      this.recallBarrier.start();
    } catch (error) {
      this.detachLifecycle();
      this.reportSubscription?.stop();
      this.reportSubscription = null;
      this.recallReportSubscription?.stop();
      this.recallReportSubscription = null;
      this.performanceSampleSubscription?.stop();
      this.performanceSampleSubscription = null;
      this.performanceRecallSubscription?.stop();
      this.performanceRecallSubscription = null;
      this.performanceProbe.dispose();
      this.recallBarrier.dispose();
      this.scheduler.dispose();
      throw new TavernExtensionRuntimeError(
        "ACTIVATION_FAILED",
        error instanceof Error ? error.message : "Tavern runtime activation failed",
      );
    }
  }

  start(): boolean {
    this.assertActive();
    if (this.pageHidden) return false;
    const performanceStarted = this.performanceProbe.start();
    const observerStarted = this.scheduler.start({
      cancelled_attempt_recovery: "explicit_runtime_rearm",
    });
    const barrierStarted = this.recallBarrier.start();
    return observerStarted || barrierStarted || performanceStarted;
  }

  stop(reason?: string): boolean {
    this.assertActive();
    const barrierStopped =
      reason === undefined ? this.recallBarrier.stop() : this.recallBarrier.stop(reason);
    const observerStopped =
      reason === undefined ? this.scheduler.stop() : this.scheduler.stop(reason);
    const performanceStopped = this.performanceProbe.stop();
    return barrierStopped || observerStopped || performanceStopped;
  }

  flushNow(): Promise<TavernObserverCycleReport | null> {
    this.assertActive();
    return this.scheduler.flushNow();
  }

  subscribeReports(listener: (report: TavernObserverCycleReport) => void): TavernEventSubscription {
    this.assertActive();
    return this.scheduler.subscribeReports(listener);
  }

  subscribeRecallReports(
    listener: (report: TavernRecallGenerationBarrierReport) => void,
  ): TavernEventSubscription {
    this.assertActive();
    return this.recallBarrier.subscribeReports(listener);
  }

  getSnapshot() {
    return this.scheduler.getSnapshot();
  }

  getRecallSnapshot() {
    return this.recallBarrier.getSnapshot();
  }

  getInteractionPerformanceSnapshot() {
    return this.performanceProbe.getSnapshot();
  }

  subscribeInteractionPerformance(listener: TavernInteractionPerformanceListener) {
    this.assertActive();
    return this.performanceProbe.subscribeSamples(listener);
  }

  clearInteractionPerformanceSamples(): void {
    this.assertActive();
    this.performanceProbe.clearSamples();
  }

  inspectPrincipalBinding(): Promise<TavernPrincipalBindingInspection> {
    this.assertActive();
    return this.principalBinding.inspect();
  }

  async bindPrincipal(
    request: TavernBindPrincipalRequest,
  ): Promise<TavernPrincipalBindingInspection> {
    this.assertActive();
    const wasRunning = this.scheduler.getSnapshot().lifecycle === "running";
    if (wasRunning) {
      this.recallBarrier.stop("runtime_principal_binding");
      this.scheduler.stop("runtime_principal_binding");
    }
    try {
      return await this.principalBinding.bind(request);
    } finally {
      if (wasRunning && !this.disposed && !this.pageHidden) {
        this.scheduler.start();
        this.recallBarrier.start();
      }
    }
  }

  async assembleReadOnlyQuery(
    request: Pick<
      TavernRecallReadOnlyQueryRequest,
      "query_text" | "expected_authoritative_source_checksum" | "principal_entity_id"
    >,
  ): Promise<TavernRecallReadOnlyQueryResult> {
    this.assertActive();
    const snapshot = this.scheduler.getSnapshot();
    if (
      snapshot.lifecycle !== "stopped" ||
      snapshot.cycle_in_flight ||
      snapshot.main_generation_active ||
      snapshot.timer_pending ||
      snapshot.pending_hints.length > 0
    ) {
      throw new TavernExtensionRuntimeError(
        "READ_ONLY_RECALL_UNAVAILABLE",
        "Read-only Recall requires one paused and idle product runtime",
      );
    }
    const expectedSemanticCoverage = this.scheduler.getCommittedCoverageAuditForReadOnlyRecall();
    if (expectedSemanticCoverage === null) {
      throw new TavernExtensionRuntimeError(
        "READ_ONLY_RECALL_UNAVAILABLE",
        "Read-only Recall requires committed semantic coverage",
      );
    }
    return this.recall.assembleReadOnlyQuery({
      ...request,
      token_budget: this.config.recall.token_budget,
      expected_semantic_coverage: expectedSemanticCoverage,
      ...(this.config.observer.extraction.prepare.normalize_semantic_metadata === undefined
        ? {}
        : {
            normalize_semantic_metadata:
              this.config.observer.extraction.prepare.normalize_semantic_metadata,
          }),
    });
  }

  async resolveMemorySet(
    choice: TavernExtensionMemorySetChoice,
  ): Promise<TavernCurrentArchiveSyncResult> {
    this.assertActive();
    const wasRunning = this.scheduler.getSnapshot().lifecycle === "running";
    if (wasRunning) {
      this.recallBarrier.stop("runtime_memory_set_resolution");
      this.scheduler.stop("runtime_memory_set_resolution");
    }
    const token = this.observerRuntime.next_token();
    if (!SAFE_RUNTIME_TOKEN_PATTERN.test(token)) {
      if (wasRunning && !this.pageHidden) {
        this.scheduler.start();
        this.recallBarrier.start();
      }
      throw new TavernExtensionRuntimeError(
        "INVALID_CONFIG",
        "Observer runtime returned an unsafe Memory Set transaction token",
      );
    }
    try {
      return await this.currentArchive.sync({
        writer_id: this.config.observer.writer_id,
        transaction_id: `tx_runtime_${token}`,
        build_id: this.config.observer.build_id,
        view_id: `view_runtime_${token}`,
        observed_hints: ["chat_loaded"],
        exclusive_recovery_confirmed: this.config.observer.exclusive_recovery_confirmed,
        ...(this.config.observer.extraction.prepare.normalize_semantic_metadata === undefined
          ? {}
          : {
              normalize_semantic_metadata:
                this.config.observer.extraction.prepare.normalize_semantic_metadata,
            }),
        ...(choice.kind === "CREATE_MEMORY_SET"
          ? {
              create_if_not_found: {
                memory_set_id: choice.memory_set_id ?? `memory_${token}`,
                character_revision_hash: choice.character_revision_hash,
                ...(choice.expected_anchor_candidates === undefined
                  ? {}
                  : { expected_anchor_candidates: choice.expected_anchor_candidates }),
              },
            }
          : {
              confirmed_anchor_rebind: {
                control_book_name: choice.control_book_name,
                expected_control_checksum: choice.expected_control_checksum,
                character_revision_hash: choice.character_revision_hash,
              },
            }),
      });
    } finally {
      if (wasRunning && !this.disposed && !this.pageHidden) {
        this.scheduler.start();
        this.recallBarrier.start();
      }
    }
  }

  dispose(): boolean {
    if (this.disposed) return false;
    this.disposed = true;
    this.detachLifecycle();
    this.reportSubscription?.stop();
    this.reportSubscription = null;
    this.recallReportSubscription?.stop();
    this.recallReportSubscription = null;
    this.performanceSampleSubscription?.stop();
    this.performanceSampleSubscription = null;
    this.performanceRecallSubscription?.stop();
    this.performanceRecallSubscription = null;
    this.performanceProbe.dispose();
    this.recallBarrier.dispose();
    this.scheduler.dispose();
    if (this.slot.get() === this) this.slot.set(null);
    return true;
  }

  private detachLifecycle(): void {
    if (!this.lifecycleAttached) return;
    this.lifecycle.remove_listener("pagehide", this.onPageHide);
    this.lifecycle.remove_listener("pageshow", this.onPageShow);
    this.lifecycleAttached = false;
  }

  private assertActive(): void {
    if (this.disposed) {
      throw new TavernExtensionRuntimeError("ACTIVATION_FAILED", "Tavern runtime is disposed");
    }
  }
}

export async function installTavernExtensionRuntime(
  request: InstallTavernExtensionRuntimeRequest,
): Promise<TavernExtensionRuntimeHandle> {
  assertConfig(request.config);
  const slot = request.slot ?? createBrowserTavernExtensionRuntimeSlot();
  const existing = slot.get();
  if (existing !== null && !request.config.replace_existing) {
    throw new TavernExtensionRuntimeError(
      "ALREADY_INSTALLED",
      `Tavern runtime ${existing.installation_id} is already installed in this page`,
    );
  }
  const prompt = await buildTavernRuntimePromptAsset(
    request.config.observer.extraction.compatibility_route,
    request.config.observer.extraction.prompt_body,
  );
  const recallPrompt = await buildTavernRuntimeRecallPromptAsset(
    request.config.observer.extraction.compatibility_route,
    request.config.recall.prompt_body,
  );
  const lifecyclePrompt =
    request.config.observer.lifecycle === undefined
      ? null
      : await buildTavernRuntimeLifecyclePromptAsset(
          request.config.observer.lifecycle.compatibility_route,
          request.config.observer.lifecycle.prompt_body,
        );
  const lifecycle = request.lifecycle ?? createBrowserTavernPageLifecyclePort();
  const observerRuntime: TavernObserverRuntime =
    request.observer_runtime ?? createBrowserTavernObserverRuntime();
  const port = request.host_port;
  let scheduler: TavernObserverScheduler;
  let currentArchive: TavernCurrentArchiveCoordinator;
  let principalBinding: TavernPrincipalBindingService;
  let recall: TavernRecallService;
  let recallBarrier: TavernRecallGenerationBarrier;
  let performanceProbe: TavernInteractionPerformanceProbe;
  try {
    currentArchive = new TavernCurrentArchiveCoordinator(port, request.config.segment_limits);
    principalBinding = new TavernPrincipalBindingService(port, request.config.segment_limits);
    const extractionJobs = new TavernExtractionJobRunner(port, request.config.segment_limits);
    const lifecycleJobs = new TavernNarrativeLifecycleJobRunner(
      port,
      request.config.segment_limits,
    );
    const routeAuditTimestamp = observerRuntime.now_iso();
    const durableCoverageCandidate = await createTavernExtractionJobAudit({
      job_id: "durable_coverage_route_probe",
      mode: "incremental",
      requested_model_id: request.config.observer.extraction.requested_model_id,
      ...(request.config.observer.extraction.retry_round_id === undefined
        ? {}
        : { retry_round_id: request.config.observer.extraction.retry_round_id }),
      runtime_prompt_assets: [prompt.asset],
      ...(request.config.observer.extraction.semantic_stage_prompt_assets === undefined
        ? {}
        : {
            semantic_stage_prompt_assets:
              request.config.observer.extraction.semantic_stage_prompt_assets,
          }),
      allow_candidate_prompt: request.config.observer.extraction.allow_candidate_prompt,
      max_attempts: request.config.observer.extraction.max_attempts ?? 3,
      ...(request.config.observer.extraction.response_recovery === undefined
        ? {}
        : { response_recovery: request.config.observer.extraction.response_recovery }),
      prepare: {
        ...request.config.observer.extraction.prepare,
        created_at: routeAuditTimestamp,
      },
      compiled_at: routeAuditTimestamp,
      writer_id: request.config.observer.writer_id,
      build_id: request.config.observer.build_id,
    });
    scheduler = new TavernObserverScheduler(
      port,
      currentArchive,
      extractionJobs,
      {
        debounce_ms: request.config.observer.debounce_ms,
        max_sync_attempts: request.config.observer.max_sync_attempts,
        ...(request.config.observer.minimum_ai_floor_count_before_first_extraction === undefined
          ? {}
          : {
              minimum_ai_floor_count_before_first_extraction:
                request.config.observer.minimum_ai_floor_count_before_first_extraction,
            }),
        ...(request.config.observer.ai_floor_batch_size === undefined
          ? {}
          : { ai_floor_batch_size: request.config.observer.ai_floor_batch_size }),
        writer_id: request.config.observer.writer_id,
        build_id: request.config.observer.build_id,
        exclusive_recovery_confirmed: request.config.observer.exclusive_recovery_confirmed,
        durable_coverage_candidate: durableCoverageCandidate,
        extraction: {
          requested_model_id: request.config.observer.extraction.requested_model_id,
          ...(request.config.observer.extraction.retry_round_id === undefined
            ? {}
            : { retry_round_id: request.config.observer.extraction.retry_round_id }),
          runtime_prompt_assets: [prompt.asset],
          ...(request.config.observer.extraction.semantic_stage_prompt_assets === undefined
            ? {}
            : {
                semantic_stage_prompt_assets:
                  request.config.observer.extraction.semantic_stage_prompt_assets,
              }),
          allow_candidate_prompt: request.config.observer.extraction.allow_candidate_prompt,
          ...(request.config.observer.extraction.max_attempts === undefined
            ? {}
            : { max_attempts: request.config.observer.extraction.max_attempts }),
          ...(request.config.observer.extraction.response_recovery === undefined
            ? {}
            : { response_recovery: request.config.observer.extraction.response_recovery }),
          prepare: request.config.observer.extraction.prepare,
        },
        ...(lifecyclePrompt === null || request.config.observer.lifecycle === undefined
          ? {}
          : {
              lifecycle: {
                requested_model_id: request.config.observer.lifecycle.requested_model_id,
                ...(request.config.observer.lifecycle.retry_round_id === undefined
                  ? {}
                  : { retry_round_id: request.config.observer.lifecycle.retry_round_id }),
                runtime_prompt_assets: [lifecyclePrompt.asset],
                allow_candidate_prompt: request.config.observer.lifecycle.allow_candidate_prompt,
                ...(request.config.observer.lifecycle.max_attempts === undefined
                  ? {}
                  : { max_attempts: request.config.observer.lifecycle.max_attempts }),
              },
            }),
      },
      observerRuntime,
      lifecycleJobs,
    );
    recall = new TavernRecallService(port, request.config.segment_limits);
    recallBarrier = new TavernRecallGenerationBarrier(port, scheduler, recall, {
      token_budget: request.config.recall.token_budget,
      latest_ai_floor_count: request.config.recall.latest_ai_floor_count,
      ...(request.config.recall.max_prepare_ms === undefined
        ? {}
        : { max_prepare_ms: request.config.recall.max_prepare_ms }),
      prompt_asset: recallPrompt.asset,
      ...(request.config.recall.principal_entity_id === undefined
        ? {}
        : { principal_entity_id: request.config.recall.principal_entity_id }),
      ...(request.config.observer.extraction.prepare.normalize_semantic_metadata === undefined
        ? {}
        : {
            normalize_semantic_metadata:
              request.config.observer.extraction.prepare.normalize_semantic_metadata,
          }),
    });
    performanceProbe = new TavernInteractionPerformanceProbe(
      port,
      request.config.interaction_performance?.max_samples ?? 200,
    );
  } catch (error) {
    throw new TavernExtensionRuntimeError(
      "INVALID_CONFIG",
      error instanceof Error ? error.message : "Invalid Tavern runtime configuration",
    );
  }
  const runtime = new TavernExtensionRuntime(
    request.config.installation_id,
    scheduler,
    recallBarrier,
    recall,
    performanceProbe,
    currentArchive,
    principalBinding,
    observerRuntime,
    request.config,
    lifecycle,
    slot,
    request.on_report,
    request.on_recall_report,
    request.on_interaction_performance_sample,
    request.should_resume_on_pageshow,
  );
  existing?.dispose();
  try {
    runtime.activate();
    slot.set(runtime);
  } catch (error) {
    runtime.dispose();
    if (error instanceof TavernExtensionRuntimeError) throw error;
    throw new TavernExtensionRuntimeError(
      "ACTIVATION_FAILED",
      error instanceof Error ? error.message : "Tavern runtime activation failed",
    );
  }
  return runtime;
}
