import type { NarraMemId } from "@narramem/core-domain";

import type { TavernJsonValue } from "./contracts.js";

export const TAVERN_WORLDBOOK_STORE_VERSION = "0.4.0" as const;
export const TAVERN_CONTROL_FORMAT = "narramem.tavern-control" as const;
export const TAVERN_SEGMENT_FORMAT = "narramem.tavern-segment" as const;

export interface TavernArchiveRecord {
  readonly record_id: string;
  readonly record_kind: string;
  readonly payload: TavernJsonValue;
}

export interface TavernSegmentPayload {
  readonly format: typeof TAVERN_SEGMENT_FORMAT;
  readonly schema_version: typeof TAVERN_WORLDBOOK_STORE_VERSION;
  readonly memory_set_id: string;
  readonly transaction_id: string;
  readonly build_id: string;
  readonly segment_id: string;
  readonly source_revision: number;
  readonly ordinal: number;
  readonly records: readonly TavernArchiveRecord[];
  readonly checksum: string;
}

export interface TavernSegmentRef {
  readonly book_name: string;
  readonly entry_uid: number;
  readonly segment_id: string;
  readonly checksum: string;
  readonly record_count: number;
  readonly utf8_bytes: number;
}

export interface TavernActiveView {
  readonly view_id: string;
  readonly build_id: string;
  readonly source_revision: number;
  readonly source_checksum: string;
  readonly segments: readonly TavernSegmentRef[];
  readonly checksum: string;
}

export interface TavernMemoryIdentityAnchor {
  readonly identity_version: "0.1.0";
  readonly character_locator: {
    readonly host_character_id: string;
  };
  readonly chat_locator: {
    readonly host_chat_id: string;
  };
  readonly chat_anchor_hash: string;
  readonly character_revision_hash: string | null;
  readonly principal_binding?: TavernPrincipalEntityBinding;
}

export interface TavernPrincipalEntityBinding {
  readonly binding_version: "0.1.0";
  readonly host_character_id: string;
  readonly principal_entity_id: NarraMemId<"entity">;
  readonly principal_entity_label: string;
  readonly binding_mode: "automatic_exact_label" | "user_confirmed";
  readonly bound_at_source_revision_id: NarraMemId<"source_revision">;
}

export type TavernTransactionPhase = "staging_verified" | "pointer_committed";

export interface TavernPendingTransaction {
  readonly transaction_id: string;
  readonly writer_id: string;
  readonly phase: TavernTransactionPhase;
  readonly base_view: TavernActiveView | null;
  readonly target_view: TavernActiveView;
  readonly obsolete_books: readonly string[];
}

export interface TavernControlPayload {
  readonly format: typeof TAVERN_CONTROL_FORMAT;
  readonly schema_version: typeof TAVERN_WORLDBOOK_STORE_VERSION;
  readonly memory_set_id: string;
  readonly identity_anchor: TavernMemoryIdentityAnchor;
  readonly commit_sequence: number;
  readonly active_view: TavernActiveView | null;
  readonly pending_transaction: TavernPendingTransaction | null;
  readonly checksum: string;
}

export type TavernDurableCommitPhase =
  | "segments_staged"
  | "pending_recorded"
  | "pointer_committed"
  | "obsolete_collected"
  | "pending_cleared";

export interface TavernWorldbookStoreOptions {
  readonly memory_set_id: string;
  readonly control_book_name: string;
  readonly segment_book_prefix: string;
  readonly initial_identity_anchor: TavernMemoryIdentityAnchor;
  readonly max_records_per_segment: number;
  readonly max_segment_utf8_bytes: number;
}

export interface TavernFullSnapshotCommitRequest {
  readonly transaction_id: string;
  readonly writer_id: string;
  readonly build_id: string;
  readonly view_id: string;
  readonly source_revision: number;
  readonly source_checksum: string;
  readonly expected_commit_sequence: number;
  readonly expected_view_id: string | null;
  readonly records: readonly TavernArchiveRecord[];
  readonly after_durable_phase?: (phase: TavernDurableCommitPhase) => void | Promise<void>;
}

export interface TavernFullSnapshotCommitResult {
  readonly control: TavernControlPayload;
  readonly replaced_segment_books: readonly string[];
}

export interface TavernIdentityAnchorUpdateRequest {
  readonly expected_control_checksum: string;
  readonly next_identity_anchor: TavernMemoryIdentityAnchor;
}

export interface TavernRecoveryRequest {
  readonly current_source_revision: number;
  readonly current_source_checksum: string | null;
  readonly exclusive_writer_confirmed: boolean;
}

export interface TavernRecoveryResult {
  readonly action:
    | "NO_ACTION"
    | "ORPHANS_COLLECTED"
    | "STAGING_ABORTED_STALE"
    | "STAGING_COMMITTED"
    | "COMMITTED_CLEANED"
    | "ROLLED_BACK"
    | "REBUILD_REQUIRED";
  readonly control: TavernControlPayload;
  readonly deleted_books: readonly string[];
}

export class TavernWorldbookStoreError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "CONTROL_NOT_FOUND"
      | "CONTROL_CORRUPT"
      | "SEGMENT_CORRUPT"
      | "BOOK_COLLISION"
      | "STALE_BASE"
      | "FOREIGN_PENDING_TRANSACTION"
      | "WRITE_CONFLICT"
      | "CLEANUP_FAILED"
      | "REBUILD_REQUIRED",
    message: string,
  ) {
    super(message);
    this.name = "TavernWorldbookStoreError";
  }
}
