import type { NarraMemTaskDisplayState } from "./beta-settings-panel.js";

const TOAST_ID = "narramem-memory-progress-toast";

export interface NarraMemMemoryProgressToast {
  update(taskKey: string | null, state: NarraMemTaskDisplayState): void;
  dismiss(): void;
  destroy(): void;
}

export interface NarraMemMemoryProgressToastView {
  readonly title: string;
  readonly detail: string;
  readonly status: NarraMemTaskDisplayState["status"];
}

export function describeMemoryProgressToast(
  state: NarraMemTaskDisplayState,
): NarraMemMemoryProgressToastView | null {
  if (state.status === "idle") return null;
  const phase =
    state.stage === "lifecycle"
      ? "整理长期影响"
      : state.semantic_stage_index === null
        ? "准备记忆批次"
        : `抽取 ${state.semantic_stage_index}/4 · ${state.semantic_stage_name ?? "当前阶段"}`;
  if (state.status === "running") {
    return {
      title: "叙忆正在后台处理",
      detail: `${phase}，聊天可以继续 · 点击关闭`,
      status: state.status,
    };
  }
  if (state.status === "success") {
    return { title: "本批记忆已更新", detail: "已安全写入世界书 · 点击关闭", status: state.status };
  }
  if (state.status === "partial") {
    return {
      title: "本批记忆需要补充处理",
      detail: `${state.error_detail ?? "正确部分已保存，待修部分未冒充成功"} · 点击关闭`,
      status: state.status,
    };
  }
  return {
    title: "本批记忆处理失败",
    detail: `${state.error_code ?? state.error_type ?? "未知错误"} · 可在叙忆设置中查看并重试 · 点击关闭`,
    status: state.status,
  };
}

export function memoryTaskKeyFromGenerationId(generationId: string): string {
  return generationId
    .replace(/^narramem_(?:extract|lifecycle)_/u, "")
    .replace(
      /(?:_s[1-4])?_a[0-9]+(?:_(?:continuation|schema_repair|targeted_repair)_[0-9]+)?$/u,
      "",
    );
}

export function installMemoryProgressToast(
  documentRef: Document = document,
): NarraMemMemoryProgressToast {
  documentRef.getElementById(TOAST_ID)?.remove();
  const root = documentRef.createElement("div");
  root.id = TOAST_ID;
  root.className = "narramem-memory-progress-toast";
  root.hidden = true;
  root.tabIndex = 0;
  root.setAttribute("role", "status");
  root.setAttribute("aria-live", "polite");
  root.setAttribute("aria-label", "NarraMem 后台记忆进度，点击关闭");
  root.innerHTML = `
    <span class="narramem-memory-progress-toast__indicator" aria-hidden="true"></span>
    <span class="narramem-memory-progress-toast__copy">
      <strong class="narramem-memory-progress-toast__title"></strong>
      <span class="narramem-memory-progress-toast__detail"></span>
    </span>
    <span class="narramem-memory-progress-toast__close" aria-hidden="true">×</span>
  `;
  documentRef.body.append(root);
  const title = root.querySelector<HTMLElement>(".narramem-memory-progress-toast__title");
  const detail = root.querySelector<HTMLElement>(".narramem-memory-progress-toast__detail");
  let currentTaskKey: string | null = null;
  let dismissedTaskKey: string | null = null;
  let successTimer: ReturnType<typeof setTimeout> | null = null;

  const clearSuccessTimer = (): void => {
    if (successTimer === null) return;
    globalThis.clearTimeout(successTimer);
    successTimer = null;
  };
  const dismiss = (): void => {
    if (currentTaskKey !== null) dismissedTaskKey = currentTaskKey;
    root.hidden = true;
    clearSuccessTimer();
  };
  root.addEventListener("click", dismiss);
  root.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      dismiss();
    }
  });

  return {
    update(taskKey, state) {
      const view = describeMemoryProgressToast(state);
      if (taskKey === null || view === null) {
        root.hidden = true;
        clearSuccessTimer();
        return;
      }
      if (taskKey !== currentTaskKey) {
        currentTaskKey = taskKey;
        dismissedTaskKey = null;
      }
      if (dismissedTaskKey === taskKey) {
        root.hidden = true;
        return;
      }
      if (title !== null) title.textContent = view.title;
      if (detail !== null) detail.textContent = view.detail;
      root.dataset.status = view.status;
      root.hidden = false;
      clearSuccessTimer();
      if (view.status === "success") {
        successTimer = globalThis.setTimeout(dismiss, 5_000);
      }
    },
    dismiss,
    destroy() {
      clearSuccessTimer();
      root.remove();
    },
  };
}
