import type { TavernEventSubscription, TavernHostPort } from "./contracts.js";
import { TavernCurrentArchiveCoordinator } from "./current-archive.js";
import {
  type TavernCurrentArchiveCoordinatorOptions,
  TavernCurrentArchiveError,
  type TavernCurrentArchiveSyncRequest,
  type TavernCurrentArchiveSyncResult,
} from "./current-archive-contracts.js";
import type {
  TavernExtractionCancellationReport,
  TavernExtractionJobAudit,
  TavernExtractionJobRequest,
  TavernExtractionJobResult,
} from "./extraction-job-contracts.js";
import { TavernExtractionJobRunner } from "./extraction-job-runner.js";
import type { TavernNarrativeLifecycleJobRequest } from "./narrative-lifecycle-job-contracts.js";
import { TavernNarrativeLifecycleJobRunner } from "./narrative-lifecycle-job-runner.js";
import {
  TAVERN_OBSERVER_EVENT_NAMES,
  TAVERN_OBSERVER_SCHEDULER_VERSION,
  type TavernObserverBatchDescriptor,
  type TavernObserverCurrentArchiveService,
  type TavernObserverCycleReport,
  type TavernObserverEventName,
  type TavernObserverExtractionJobService,
  type TavernObserverMainGenerationTrigger,
  type TavernObserverNarrativeLifecycleJobService,
  type TavernObserverRecallPreparation,
  type TavernObserverRuntime,
  type TavernObserverSchedulerConfig,
  TavernObserverSchedulerError,
  type TavernObserverSchedulerSnapshot,
  type TavernObserverStartOptions,
} from "./observer-scheduler-contracts.js";
import type { TavernMutationHint } from "./source-snapshot-contracts.js";

const SAFE_TOKEN_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,39}$/u;
const MAX_DEBOUNCE_MS = 60_000;

const HINT_ORDER: readonly TavernMutationHint[] = [
  "chat_loaded",
  "message_sent",
  "message_received",
  "message_edited",
  "message_updated",
  "message_deleted",
  "swipe_changed",
  "swipe_deleted",
  "reroll",
  "unknown",
];

interface PendingBatch {
  sequence: number;
  readonly hints: Set<TavernMutationHint>;
  extraction_requested: boolean;
  cancelled_attempt_recovery?: "explicit_runtime_rearm";
}

interface SourceSyncOutcome {
  readonly sync: TavernCurrentArchiveSyncResult;
  readonly attempts: number;
}

class SourceSyncFailure {
  constructor(
    readonly attempts: number,
    readonly error: unknown,
  ) {}
}

type ReportListener = (report: TavernObserverCycleReport) => void;

function assertConfig(config: TavernObserverSchedulerConfig): void {
  if (
    !Number.isInteger(config.debounce_ms) ||
    config.debounce_ms < 0 ||
    config.debounce_ms > MAX_DEBOUNCE_MS ||
    !Number.isInteger(config.max_sync_attempts) ||
    config.max_sync_attempts < 1 ||
    config.max_sync_attempts > 3 ||
    (config.minimum_ai_floor_count_before_first_extraction !== undefined &&
      (!Number.isInteger(config.minimum_ai_floor_count_before_first_extraction) ||
        config.minimum_ai_floor_count_before_first_extraction < 1 ||
        config.minimum_ai_floor_count_before_first_extraction > 100)) ||
    (config.ai_floor_batch_size !== undefined &&
      (!Number.isInteger(config.ai_floor_batch_size) ||
        config.ai_floor_batch_size < 1 ||
        config.ai_floor_batch_size > 100)) ||
    config.writer_id.trim().length === 0 ||
    config.build_id.trim().length === 0 ||
    config.extraction.requested_model_id.trim().length === 0 ||
    !Number.isInteger(config.extraction.prepare.chunk_message_limit) ||
    config.extraction.prepare.chunk_message_limit < 1 ||
    !Number.isInteger(config.extraction.prepare.context_message_limit) ||
    config.extraction.prepare.context_message_limit < 0 ||
    (config.extraction.max_attempts !== undefined &&
      (!Number.isInteger(config.extraction.max_attempts) ||
        config.extraction.max_attempts < 1 ||
        config.extraction.max_attempts > 3)) ||
    (config.lifecycle?.max_attempts !== undefined &&
      (!Number.isInteger(config.lifecycle.max_attempts) ||
        config.lifecycle.max_attempts < 1 ||
        config.lifecycle.max_attempts > 3)) ||
    (config.extraction.retry_round_id !== undefined &&
      !SAFE_TOKEN_PATTERN.test(config.extraction.retry_round_id)) ||
    (config.lifecycle?.retry_round_id !== undefined &&
      !SAFE_TOKEN_PATTERN.test(config.lifecycle.retry_round_id))
  ) {
    throw new TavernObserverSchedulerError(
      "INVALID_CONFIG",
      "Observer requires bounded incremental chunk/context limits, debounce 0-60000 ms, 1-3 sync attempts, optional 1-100 AI-floor batching, and non-empty writer/build/model IDs",
    );
  }
}

function sortedHints(hints: ReadonlySet<TavernMutationHint>): readonly TavernMutationHint[] {
  return HINT_ORDER.filter((hint) => hints.has(hint));
}

function errorDescriptor(error: unknown): {
  readonly error_name: string;
  readonly error_message: string;
  readonly error_code?: string;
} {
  if (error instanceof Error) {
    const candidate = error as Error & {
      readonly code?: unknown;
      readonly codes?: unknown;
      readonly diagnostic_codes?: unknown;
    };
    const diagnosticSource = Array.isArray(candidate.diagnostic_codes)
      ? candidate.diagnostic_codes
      : candidate.codes;
    const diagnosticCodes = Array.isArray(diagnosticSource)
      ? diagnosticSource.filter((value): value is string => typeof value === "string").slice(0, 12)
      : [];
    return {
      error_name: error.name,
      error_message:
        diagnosticCodes.length === 0
          ? error.message
          : `${error.message} [codes: ${diagnosticCodes.join(", ")}]`,
      ...(typeof candidate.code === "string"
        ? { error_code: candidate.code }
        : diagnosticCodes[0] === undefined
          ? {}
          : { error_code: diagnosticCodes[0] }),
    };
  }
  return { error_name: "UnknownError", error_message: String(error) };
}

function isDryRun(args: readonly unknown[]): boolean {
  return args[2] === true;
}

function receivedHint(args: readonly unknown[]): TavernMutationHint {
  const generationType = args[1];
  if (generationType === "regenerate") return "reroll";
  if (generationType === "swipe") return "swipe_changed";
  return "message_received";
}

export function createBrowserTavernObserverRuntime(): TavernObserverRuntime {
  return {
    now_iso: () => new Date().toISOString(),
    next_token: () => {
      if (globalThis.crypto?.randomUUID === undefined) {
        throw new TavernObserverSchedulerError(
          "INVALID_RUNTIME",
          "Web Crypto randomUUID is required for observer transaction IDs",
        );
      }
      return globalThis.crypto.randomUUID();
    },
    set_timer: (callback, delayMs) => globalThis.setTimeout(callback, delayMs),
    clear_timer: (handle) => globalThis.clearTimeout(handle as ReturnType<typeof setTimeout>),
  };
}

export function createTavernObserverScheduler(
  port: TavernHostPort,
  segmentLimits: TavernCurrentArchiveCoordinatorOptions,
  config: TavernObserverSchedulerConfig,
  runtime: TavernObserverRuntime = createBrowserTavernObserverRuntime(),
): TavernObserverScheduler {
  return new TavernObserverScheduler(
    port,
    new TavernCurrentArchiveCoordinator(port, segmentLimits),
    new TavernExtractionJobRunner(port, segmentLimits),
    config,
    runtime,
    new TavernNarrativeLifecycleJobRunner(port, segmentLimits),
  );
}

/**
 * Converts public SillyTavern lifecycle notifications into latest-wins source
 * synchronization and extraction work. Event payloads are hints only: every
 * authoritative decision is rebuilt from CurrentArchive's double-read snapshot.
 */
export class TavernObserverScheduler {
  private lifecycle: "idle" | "running" | "stopped" | "disposed" = "idle";
  private latestSequence = 0;
  private invalidationEpoch = 0;
  private mainGenerationActive = false;
  private pending: PendingBatch | null = null;
  private timer: unknown = null;
  private activeCycle: Promise<TavernObserverCycleReport> | null = null;
  private readonly subscriptions: TavernEventSubscription[] = [];
  private readonly listeners = new Set<ReportListener>();
  private lastCancellation: TavernExtractionCancellationReport | null = null;
  private lastReport: TavernObserverCycleReport | null = null;
  private committedCoverage: TavernExtractionJobAudit | null = null;

  constructor(
    private readonly port: TavernHostPort,
    private readonly currentArchive: TavernObserverCurrentArchiveService,
    private readonly extractionJobs: TavernObserverExtractionJobService,
    private readonly config: TavernObserverSchedulerConfig,
    private readonly runtime: TavernObserverRuntime = createBrowserTavernObserverRuntime(),
    private readonly lifecycleJobs?: TavernObserverNarrativeLifecycleJobService,
  ) {
    assertConfig(config);
  }

  start(options: TavernObserverStartOptions = {}): boolean {
    this.assertNotDisposed();
    if (this.lifecycle === "running") return false;
    try {
      for (const eventName of TAVERN_OBSERVER_EVENT_NAMES) {
        this.subscriptions.push(
          this.port.subscribe(eventName, (...args) => this.handleEvent(eventName, args)),
        );
      }
    } catch (error) {
      this.stopSubscriptions();
      throw new TavernObserverSchedulerError(
        "SUBSCRIPTION_FAILED",
        error instanceof Error ? error.message : "Failed to subscribe to Tavern events",
      );
    }
    this.lifecycle = "running";
    const identity = this.port.getCurrentIdentity();
    if (identity.character_id !== null && identity.chat_id !== null) {
      this.queueHint(
        "chat_loaded",
        true,
        "observer_initial_catchup",
        true,
        options.cancelled_attempt_recovery,
      );
    }
    return true;
  }

  stop(reason = "observer_stopped"): boolean {
    this.assertNotDisposed();
    if (this.lifecycle !== "running") {
      this.lifecycle = "stopped";
      return false;
    }
    this.lifecycle = "stopped";
    this.advanceFence(reason);
    this.pending = null;
    this.clearTimer();
    this.stopSubscriptions();
    this.mainGenerationActive = false;
    return true;
  }

  pagehide(): boolean {
    return this.stop("pagehide");
  }

  dispose(): boolean {
    if (this.lifecycle === "disposed") return false;
    if (this.lifecycle === "running") this.stop("observer_disposed");
    this.lifecycle = "disposed";
    this.pending = null;
    this.clearTimer();
    this.stopSubscriptions();
    this.listeners.clear();
    return true;
  }

  subscribeReports(listener: ReportListener): TavernEventSubscription {
    this.assertNotDisposed();
    this.listeners.add(listener);
    return { stop: () => this.listeners.delete(listener) };
  }

  getSnapshot(): TavernObserverSchedulerSnapshot {
    return {
      scheduler_version: TAVERN_OBSERVER_SCHEDULER_VERSION,
      lifecycle: this.lifecycle,
      latest_sequence: this.latestSequence,
      main_generation_active: this.mainGenerationActive,
      timer_pending: this.timer !== null,
      cycle_in_flight: this.activeCycle !== null,
      pending_hints: this.pending === null ? [] : sortedHints(this.pending.hints),
      pending_extraction_requested: this.pending?.extraction_requested ?? false,
      committed_coverage_available: this.committedCoverage !== null,
      last_cancellation: this.lastCancellation,
      last_report: this.lastReport,
    };
  }

  /** Content-free provenance read for a paused, non-persistent Recall evaluation. */
  getCommittedCoverageAuditForReadOnlyRecall(): TavernExtractionJobAudit | null {
    this.assertNotDisposed();
    return this.committedCoverage;
  }

  async flushNow(): Promise<TavernObserverCycleReport | null> {
    this.assertNotDisposed();
    this.clearTimer();
    if (this.mainGenerationActive) return null;
    if (this.activeCycle !== null) return this.activeCycle;
    if (this.pending === null || this.lifecycle !== "running") return null;
    return this.beginCycle();
  }

  /**
   * Yields main-generation priority without starting source sync, World Book
   * writes, or an external memory-model call. Recall separately proves that
   * the committed archive is exact or differs only by an append-only live tail.
   */
  async prepareForMainGeneration(
    trigger: TavernObserverMainGenerationTrigger = "generation_after_commands",
  ): Promise<TavernObserverRecallPreparation> {
    this.assertNotDisposed();
    if (this.lifecycle !== "running") {
      throw new TavernObserverSchedulerError(
        "INVALID_RUNTIME",
        "Observer must be running before a main-generation consistency barrier",
      );
    }
    this.mainGenerationActive = true;
    this.clearTimer();
    this.advanceSequence();
    const cancellation: TavernExtractionCancellationReport = {
      reason: `observer:${trigger}:background_batch_preserved`,
      generation_id: null,
      host_cancel_requested: false,
    };
    this.lastCancellation = cancellation;
    return this.committedCoverage === null
      ? { status: "NO_COMMITTED_COVERAGE", sequence: this.latestSequence, cancellation }
      : {
          status: "COMMITTED_COVERAGE_READY",
          sequence: this.latestSequence,
          extraction_audit: this.committedCoverage,
          cancellation,
        };
  }

  private handleEvent(eventName: TavernObserverEventName, args: readonly unknown[]): void {
    if (this.lifecycle !== "running") return;
    switch (eventName) {
      case "message_sent":
        this.queueHint("message_sent", false, eventName, false, undefined, false);
        this.clearTimer();
        return;
      case "message_received":
        this.queueHint(
          receivedHint(args),
          true,
          eventName,
          false,
          undefined,
          receivedHint(args) !== "message_received",
        );
        return;
      case "message_edited":
        this.queueHint("message_edited", true, eventName);
        return;
      case "message_updated":
        this.queueHint("message_updated", true, eventName);
        return;
      case "message_deleted":
        this.queueHint("message_deleted", true, eventName);
        return;
      case "message_swiped":
        this.queueHint("swipe_changed", true, eventName);
        return;
      case "message_swipe_deleted":
        this.queueHint("swipe_deleted", true, eventName);
        return;
      case "chat_id_changed":
        this.mainGenerationActive = false;
        this.committedCoverage = null;
        this.pending = null;
        this.queueHint("chat_loaded", true, eventName, true);
        return;
      case "generation_started":
        if (isDryRun(args)) return;
        this.mainGenerationActive = true;
        this.advanceSequence();
        if (this.pending !== null) {
          this.pending.sequence = this.latestSequence;
          this.clearTimer();
        }
        return;
      case "generation_stopped":
        this.mainGenerationActive = false;
        this.queueHint("unknown", true, eventName, false, undefined, false);
        return;
      case "generation_ended":
        this.mainGenerationActive = false;
        this.queueHint("unknown", true, eventName, false, undefined, false);
        return;
    }
  }

  private queueHint(
    hint: TavernMutationHint,
    extractionRequested: boolean,
    cancellationReason: string,
    resetPending = false,
    cancelledAttemptRecovery?: "explicit_runtime_rearm",
    invalidateActive = true,
  ): void {
    if (this.lifecycle !== "running") return;
    if (invalidateActive) {
      this.advanceFence(cancellationReason);
    } else {
      this.advanceSequence();
    }
    if (resetPending || this.pending === null) {
      this.pending = {
        sequence: this.latestSequence,
        hints: new Set([hint]),
        extraction_requested: extractionRequested,
        ...(cancelledAttemptRecovery === undefined
          ? {}
          : { cancelled_attempt_recovery: cancelledAttemptRecovery }),
      };
    } else {
      this.pending.sequence = this.latestSequence;
      this.pending.hints.add(hint);
      this.pending.extraction_requested = extractionRequested;
    }
    this.clearTimer();
    this.scheduleTimer();
  }

  private advanceFence(reason: string): void {
    this.latestSequence += 1;
    this.invalidationEpoch += 1;
    this.lastCancellation = this.extractionJobs.invalidateCurrent(`observer:${reason}`);
    this.lifecycleJobs?.invalidateCurrent(`observer:${reason}`);
  }

  private advanceSequence(): void {
    this.latestSequence += 1;
  }

  private scheduleTimer(): void {
    if (
      this.lifecycle !== "running" ||
      this.mainGenerationActive ||
      this.pending === null ||
      this.timer !== null
    ) {
      return;
    }
    this.timer = this.runtime.set_timer(() => {
      this.timer = null;
      if (this.activeCycle !== null) return;
      void this.beginCycle();
    }, this.config.debounce_ms);
  }

  private clearTimer(): void {
    if (this.timer === null) return;
    this.runtime.clear_timer(this.timer);
    this.timer = null;
  }

  private beginCycle(): Promise<TavernObserverCycleReport> {
    if (this.activeCycle !== null) return this.activeCycle;
    const pending = this.pending;
    if (pending === null) {
      throw new TavernObserverSchedulerError("INVALID_RUNTIME", "No observer batch is pending");
    }
    this.pending = null;
    const startedAt = this.readNow();
    const token = this.nextToken();
    const batch: TavernObserverBatchDescriptor = {
      cycle_id: `observer_${token}`,
      sequence: pending.sequence,
      observed_hints: sortedHints(pending.hints),
      extraction_requested: pending.extraction_requested,
      ...(pending.cancelled_attempt_recovery === undefined
        ? {}
        : { cancelled_attempt_recovery: pending.cancelled_attempt_recovery }),
      started_at: startedAt,
    };
    const cycle = this.executeCycle(batch, token, this.invalidationEpoch);
    this.activeCycle = cycle;
    void cycle.finally(() => {
      if (this.activeCycle === cycle) this.activeCycle = null;
      if (this.lifecycle === "running" && this.pending !== null) this.scheduleTimer();
    });
    return cycle;
  }

  private async executeCycle(
    batch: TavernObserverBatchDescriptor,
    token: string,
    invalidationEpoch: number,
  ): Promise<TavernObserverCycleReport> {
    let attempts = 0;
    let phase: "SOURCE_SYNC" | "EXTRACTION" | "LIFECYCLE" = "SOURCE_SYNC";
    let extraction: TavernExtractionJobResult | undefined;
    try {
      const outcome = await this.syncSource(batch, token, invalidationEpoch);
      attempts = outcome.attempts;
      if (invalidationEpoch !== this.invalidationEpoch || this.lifecycle !== "running") {
        return this.publish({
          status: "SUPERSEDED",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          stage: "SOURCE_SYNC",
        });
      }
      if (outcome.sync.status === "ACTION_REQUIRED") {
        return this.publish({
          status: "ACTION_REQUIRED",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          sync: outcome.sync,
        });
      }
      if (this.committedCoverage === null && this.config.durable_coverage_candidate !== undefined) {
        this.committedCoverage = this.config.durable_coverage_candidate;
      }
      if (!batch.extraction_requested || this.mainGenerationActive) {
        return this.publish({
          status: "SOURCE_STABLE",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          extraction_skipped: this.mainGenerationActive
            ? "MAIN_GENERATION_ACTIVE"
            : "SOURCE_ONLY_EVENT",
          sync: outcome.sync,
        });
      }

      const extractionGate = this.extractionGate(outcome.sync, batch);
      if (extractionGate !== null) {
        return this.publish({
          status: "SOURCE_STABLE",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          extraction_skipped: extractionGate,
          sync: outcome.sync,
        });
      }

      phase = "EXTRACTION";
      extraction = await this.extractionJobs.runLatest(
        this.buildExtractionRequest(token, batch.started_at, batch.cancelled_attempt_recovery),
      );
      if (invalidationEpoch !== this.invalidationEpoch || this.lifecycle !== "running") {
        return this.publish({
          status: "SUPERSEDED",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          stage: "EXTRACTION",
          extraction,
        });
      }
      if (extraction.status === "PARTIAL_COMMITTED" || extraction.status === "REPAIR_PENDING") {
        return this.publish({
          status: "EXTRACTION_PARTIAL",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          sync: outcome.sync,
          extraction,
        });
      }
      if (
        this.config.lifecycle !== undefined &&
        this.lifecycleJobs !== undefined &&
        (extraction.status === "COMMITTED" || extraction.status === "LIFECYCLE_PENDING")
      ) {
        phase = "LIFECYCLE";
        const lifecycle = await this.lifecycleJobs.runLatest(
          this.buildLifecycleRequest(token, batch.started_at),
        );
        if (invalidationEpoch !== this.invalidationEpoch || this.lifecycle !== "running") {
          return this.publish({
            status: "SUPERSEDED",
            batch,
            completed_at: this.readNow(),
            sync_attempts: attempts,
            stage: "LIFECYCLE",
            extraction,
            lifecycle,
          });
        }
        if (lifecycle.status === "COMMITTED" || lifecycle.status === "ALREADY_CURRENT") {
          this.committedCoverage = extraction.audit;
          this.queueBacklogContinuation();
        }
        return this.publish({
          status: "EXTRACTION_FINISHED",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          sync: outcome.sync,
          extraction,
          lifecycle,
        });
      }
      if (extraction.status === "ALREADY_CURRENT") {
        this.committedCoverage = extraction.audit;
      }
      return this.publish({
        status: "EXTRACTION_FINISHED",
        batch,
        completed_at: this.readNow(),
        sync_attempts: attempts,
        sync: outcome.sync,
        extraction,
      });
    } catch (error) {
      const sourceFailure = error instanceof SourceSyncFailure ? error : null;
      if (sourceFailure !== null) attempts = sourceFailure.attempts;
      if (
        sourceFailure !== null &&
        (invalidationEpoch !== this.invalidationEpoch || this.lifecycle !== "running")
      ) {
        return this.publish({
          status: "SUPERSEDED",
          batch,
          completed_at: this.readNow(),
          sync_attempts: attempts,
          stage: "SOURCE_SYNC",
        });
      }
      if (sourceFailure !== null) phase = "SOURCE_SYNC";
      return this.publish({
        status: "FAILED",
        batch,
        completed_at: this.readNow(),
        sync_attempts: attempts,
        phase,
        ...(extraction === undefined ? {} : { extraction }),
        ...errorDescriptor(sourceFailure?.error ?? error),
      });
    }
  }

  private async syncSource(
    batch: TavernObserverBatchDescriptor,
    token: string,
    invalidationEpoch: number,
  ): Promise<SourceSyncOutcome> {
    for (let attempt = 1; attempt <= this.config.max_sync_attempts; attempt += 1) {
      try {
        const sync = await this.currentArchive.sync(this.buildSyncRequest(batch, token, attempt));
        return { sync, attempts: attempt };
      } catch (error) {
        if (
          !(error instanceof TavernCurrentArchiveError) ||
          error.code !== "SOURCE_CHANGED_DURING_SYNC" ||
          attempt === this.config.max_sync_attempts ||
          invalidationEpoch !== this.invalidationEpoch ||
          this.lifecycle !== "running"
        ) {
          throw new SourceSyncFailure(attempt, error);
        }
      }
    }
    throw new TavernObserverSchedulerError("INVALID_RUNTIME", "Sync retry loop terminated early");
  }

  private extractionGate(
    sync: Extract<TavernCurrentArchiveSyncResult, { readonly status: "SYNCED" | "UNCHANGED" }>,
    batch: TavernObserverBatchDescriptor,
  ): "AI_FLOOR_THRESHOLD_NOT_MET" | "AI_FLOOR_BATCH_NOT_READY" | null {
    const minimum = this.config.minimum_ai_floor_count_before_first_extraction;
    const batchSize = this.config.ai_floor_batch_size;
    if (
      minimum === undefined ||
      batchSize === undefined ||
      this.config.extraction.retry_round_id !== undefined ||
      batch.cancelled_attempt_recovery !== undefined
    ) {
      return null;
    }
    const assistantFloors = sync.reconciliation.snapshot.messages.reduce(
      (count, message) => count + (message.role === "assistant" ? 1 : 0),
      0,
    );
    if (assistantFloors < minimum) return "AI_FLOOR_THRESHOLD_NOT_MET";
    return (assistantFloors - minimum) % batchSize === 0 ? null : "AI_FLOOR_BATCH_NOT_READY";
  }

  private buildSyncRequest(
    batch: TavernObserverBatchDescriptor,
    token: string,
    attempt: number,
  ): TavernCurrentArchiveSyncRequest {
    return {
      writer_id: this.config.writer_id,
      transaction_id: `tx_obs_${token}_${attempt}`,
      build_id: this.config.build_id,
      view_id: `view_obs_${token}_${attempt}`,
      observed_hints: batch.observed_hints,
      exclusive_recovery_confirmed: this.config.exclusive_recovery_confirmed,
      ...(this.config.extraction.prepare.normalize_semantic_metadata === undefined
        ? {}
        : {
            normalize_semantic_metadata: this.config.extraction.prepare.normalize_semantic_metadata,
          }),
    };
  }

  private buildExtractionRequest(
    token: string,
    compiledAt: string,
    cancelledAttemptRecovery?: "explicit_runtime_rearm",
  ): TavernExtractionJobRequest {
    return {
      job_id: `obs_${token}`,
      mode: "incremental",
      requested_model_id: this.config.extraction.requested_model_id,
      ...(this.config.extraction.retry_round_id === undefined
        ? {}
        : { retry_round_id: this.config.extraction.retry_round_id }),
      ...(this.config.extraction.proxy_preset === undefined
        ? {}
        : { proxy_preset: this.config.extraction.proxy_preset }),
      runtime_prompt_assets: this.config.extraction.runtime_prompt_assets,
      ...(this.config.extraction.semantic_stage_prompt_assets === undefined
        ? {}
        : { semantic_stage_prompt_assets: this.config.extraction.semantic_stage_prompt_assets }),
      allow_candidate_prompt: this.config.extraction.allow_candidate_prompt,
      max_attempts: this.config.extraction.max_attempts ?? 3,
      ...(this.config.extraction.response_recovery === undefined
        ? {}
        : { response_recovery: this.config.extraction.response_recovery }),
      ...(cancelledAttemptRecovery === undefined
        ? {}
        : { cancelled_attempt_recovery: cancelledAttemptRecovery }),
      prepare: {
        ...this.config.extraction.prepare,
        created_at: compiledAt,
      },
      compiled_at: compiledAt,
      writer_id: this.config.writer_id,
      build_id: this.config.build_id,
    };
  }

  private buildLifecycleRequest(
    token: string,
    compiledAt: string,
  ): TavernNarrativeLifecycleJobRequest {
    const config = this.config.lifecycle;
    if (config === undefined) {
      throw new TavernObserverSchedulerError("INVALID_RUNTIME", "Lifecycle config is unavailable");
    }
    return {
      job_id: `obs_${token}`,
      requested_model_id: config.requested_model_id,
      ...(config.retry_round_id === undefined ? {} : { retry_round_id: config.retry_round_id }),
      ...(config.proxy_preset === undefined ? {} : { proxy_preset: config.proxy_preset }),
      runtime_prompt_assets: config.runtime_prompt_assets,
      allow_candidate_prompt: config.allow_candidate_prompt,
      max_attempts: config.max_attempts ?? 2,
      compiled_at: compiledAt,
      writer_id: this.config.writer_id,
      build_id: this.config.build_id,
    };
  }

  private readNow(): string {
    const value = this.runtime.now_iso();
    if (value.trim() !== value || Number.isNaN(Date.parse(value))) {
      throw new TavernObserverSchedulerError(
        "INVALID_RUNTIME",
        "Observer runtime now_iso must return a valid trimmed timestamp",
      );
    }
    return value;
  }

  private queueBacklogContinuation(): void {
    if (this.lifecycle !== "running" || this.mainGenerationActive || this.pending !== null) {
      return;
    }
    this.pending = {
      sequence: this.latestSequence,
      hints: new Set(["unknown"]),
      extraction_requested: true,
    };
  }

  private nextToken(): string {
    const value = this.runtime.next_token();
    if (!SAFE_TOKEN_PATTERN.test(value)) {
      throw new TavernObserverSchedulerError(
        "INVALID_RUNTIME",
        "Observer runtime token must be 1-40 safe ASCII characters",
      );
    }
    return value;
  }

  private publish(report: TavernObserverCycleReport): TavernObserverCycleReport {
    this.lastReport = report;
    for (const listener of [...this.listeners]) {
      try {
        listener(report);
      } catch {
        // Report listeners are observational and cannot break scheduler state.
      }
    }
    return report;
  }

  private stopSubscriptions(): void {
    while (this.subscriptions.length > 0) this.subscriptions.pop()?.stop();
  }

  private assertNotDisposed(): void {
    if (this.lifecycle === "disposed") {
      throw new TavernObserverSchedulerError("DISPOSED", "Observer scheduler is disposed");
    }
  }
}
