import type {
  TavernHostPort,
  TavernWorldbookEntry,
  TavernWorldbookEntryDraft,
} from "./contracts.js";
import {
  TAVERN_EXTRACTION_ATTEMPT_LEDGER_FORMAT,
  TAVERN_EXTRACTION_ATTEMPT_LEDGER_VERSION,
  type TavernExtractionAttemptFailureStatus,
  TavernExtractionAttemptLedgerError,
  type TavernExtractionAttemptLedgerPayload,
  type TavernExtractionAttemptRecord,
  type TavernExtractionAttemptTaskDescriptor,
  type TavernExtractionAttemptTaskRecord,
  type TavernExtractionAttemptTaskStatus,
} from "./extraction-attempt-ledger-contracts.js";
import { canonicalJson, checksumJson } from "./worldbook-codec.js";

const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;
const SAFE_GENERATION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,159}$/u;
const SAFE_ERROR_CODE_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/u;
const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const MAX_TERMINAL_TASKS = 32;
const TERMINAL_TASK_STATUSES: ReadonlySet<TavernExtractionAttemptTaskStatus> = new Set([
  "committed",
  "exhausted",
  "terminal_failure",
  "cancelled",
  "suspended_unknown",
]);

type LedgerState = {
  readonly entry: TavernWorldbookEntry;
  readonly payload: TavernExtractionAttemptLedgerPayload;
};

const clone = <T>(value: T): T => structuredClone(value);
const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

function validTimestamp(value: string): boolean {
  return value.trim() === value && !Number.isNaN(Date.parse(value));
}

function entryDraft(content: string): TavernWorldbookEntryDraft {
  return {
    name: "NarraMem Extraction Attempt Ledger",
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: { type: "after_character_definition", role: "system", depth: 0, order: 0 },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra: { narramem: { record_kind: "extraction_attempt_ledger" } },
  };
}

function assertEntry(entry: TavernWorldbookEntry): void {
  if (
    !Number.isSafeInteger(entry.uid) ||
    entry.uid < 0 ||
    entry.enabled ||
    entry.strategy.type !== "constant" ||
    entry.strategy.keys.length !== 0 ||
    !entry.recursion.prevent_incoming ||
    !entry.recursion.prevent_outgoing
  ) {
    throw new TavernExtractionAttemptLedgerError(
      "STORE_CORRUPT",
      "Extraction attempt ledger safety settings changed",
    );
  }
}

function assertDescriptor(value: TavernExtractionAttemptTaskDescriptor): void {
  if (
    !SHA256_PATTERN.test(value.operation_fingerprint) ||
    !SHA256_PATTERN.test(value.semantic_task_fingerprint) ||
    value.source_revision_id.length === 0 ||
    !SHA256_PATTERN.test(value.source_checksum) ||
    !SHA256_PATTERN.test(value.model_input_sha256) ||
    value.requested_model_id.trim().length === 0 ||
    value.prompt_asset_ref.trim().length === 0 ||
    !SHA256_PATTERN.test(value.prompt_body_sha256) ||
    !SHA256_PATTERN.test(value.parameters_sha256) ||
    !Number.isSafeInteger(value.max_attempts) ||
    value.max_attempts < 1 ||
    value.max_attempts > 3 ||
    !validTimestamp(value.created_at)
  ) {
    throw new TavernExtractionAttemptLedgerError(
      "INVALID_INPUT",
      "Invalid extraction attempt task descriptor",
    );
  }
}

function assertAttempt(value: TavernExtractionAttemptRecord, expectedNumber: number): void {
  const settled = value.status !== "dispatched";
  if (
    value.attempt_number !== expectedNumber ||
    !SAFE_GENERATION_ID_PATTERN.test(value.generation_id) ||
    !validTimestamp(value.dispatched_at) ||
    (settled && (value.settled_at === undefined || !validTimestamp(value.settled_at))) ||
    (!settled && value.settled_at !== undefined) ||
    (value.elapsed_ms !== undefined &&
      (!Number.isSafeInteger(value.elapsed_ms) || value.elapsed_ms < 0)) ||
    (value.response_sha256 !== undefined && !SHA256_PATTERN.test(value.response_sha256)) ||
    (value.response_utf8_bytes !== undefined &&
      (!Number.isSafeInteger(value.response_utf8_bytes) || value.response_utf8_bytes < 0)) ||
    (value.error_code !== undefined && !SAFE_ERROR_CODE_PATTERN.test(value.error_code)) ||
    (value.diagnostic_codes !== undefined &&
      (value.diagnostic_codes.length > 12 ||
        value.diagnostic_codes.some((code) => !SAFE_ERROR_CODE_PATTERN.test(code))))
  ) {
    throw new TavernExtractionAttemptLedgerError(
      "STORE_CORRUPT",
      "Invalid extraction attempt record",
    );
  }
}

function assertTask(value: TavernExtractionAttemptTaskRecord): void {
  assertDescriptor(value);
  if (!validTimestamp(value.updated_at) || value.attempts.length > value.max_attempts) {
    throw new TavernExtractionAttemptLedgerError(
      "STORE_CORRUPT",
      "Invalid extraction attempt task state",
    );
  }
  value.attempts.forEach((attempt, index) => {
    assertAttempt(attempt, index + 1);
  });
  const last = value.attempts.at(-1);
  const validState =
    (value.status === "ready" &&
      (last === undefined ||
        ((last.status === "retryable_failure" || last.status === "superseded") &&
          value.attempts.length < value.max_attempts))) ||
    (value.status === "in_flight" && last?.status === "dispatched") ||
    (value.status === "committed" && (last === undefined || last.status === "committed")) ||
    (value.status === "exhausted" &&
      (last?.status === "retryable_failure" || last?.status === "superseded") &&
      value.attempts.length === value.max_attempts) ||
    (value.status === "terminal_failure" && last?.status === "terminal_failure") ||
    (value.status === "cancelled" &&
      (last?.status === "cancelled" || last?.status === "superseded")) ||
    (value.status === "suspended_unknown" && last?.status === "unknown_after_dispatch");
  if (!validState) {
    throw new TavernExtractionAttemptLedgerError(
      "STORE_CORRUPT",
      "Extraction attempt task status does not match its last attempt",
    );
  }
}

function compactTasks(
  tasks: readonly TavernExtractionAttemptTaskRecord[],
): readonly TavernExtractionAttemptTaskRecord[] {
  const active = tasks.filter((task) => !TERMINAL_TASK_STATUSES.has(task.status));
  const terminal = tasks
    .filter((task) => TERMINAL_TASK_STATUSES.has(task.status))
    .sort(
      (left, right) =>
        right.updated_at.localeCompare(left.updated_at) ||
        right.operation_fingerprint.localeCompare(left.operation_fingerprint),
    )
    .slice(0, MAX_TERMINAL_TASKS);
  return [...active, ...terminal];
}

async function encodePayload(
  memorySetId: string,
  tasks: readonly TavernExtractionAttemptTaskRecord[],
): Promise<TavernExtractionAttemptLedgerPayload> {
  const retained = compactTasks(tasks)
    .map(clone)
    .sort((left, right) => left.operation_fingerprint.localeCompare(right.operation_fingerprint));
  for (const task of retained) assertTask(task);
  if (new Set(retained.map((task) => task.operation_fingerprint)).size !== retained.length) {
    throw new TavernExtractionAttemptLedgerError(
      "INVALID_INPUT",
      "Extraction attempt task fingerprints must be unique",
    );
  }
  const unsigned = {
    format: TAVERN_EXTRACTION_ATTEMPT_LEDGER_FORMAT,
    schema_version: TAVERN_EXTRACTION_ATTEMPT_LEDGER_VERSION,
    memory_set_id: memorySetId,
    tasks: retained,
  };
  return { ...unsigned, checksum: await checksumJson(unsigned) };
}

async function parsePayload(
  content: string,
  memorySetId: string,
): Promise<TavernExtractionAttemptLedgerPayload> {
  let value: unknown;
  try {
    value = JSON.parse(content);
  } catch {
    throw new TavernExtractionAttemptLedgerError("STORE_CORRUPT", "Attempt ledger is not JSON");
  }
  if (
    !isObject(value) ||
    value.format !== TAVERN_EXTRACTION_ATTEMPT_LEDGER_FORMAT ||
    value.schema_version !== TAVERN_EXTRACTION_ATTEMPT_LEDGER_VERSION ||
    value.memory_set_id !== memorySetId ||
    !Array.isArray(value.tasks) ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum)
  ) {
    throw new TavernExtractionAttemptLedgerError(
      "STORE_CORRUPT",
      "Invalid extraction attempt ledger payload",
    );
  }
  const payload = value as unknown as TavernExtractionAttemptLedgerPayload;
  for (const task of payload.tasks) assertTask(task);
  const { checksum: _checksum, ...unsigned } = payload;
  if ((await checksumJson(unsigned)) !== payload.checksum) {
    throw new TavernExtractionAttemptLedgerError(
      "STORE_CORRUPT",
      "Extraction attempt ledger checksum mismatch",
    );
  }
  return payload;
}

function descriptorMatches(
  task: TavernExtractionAttemptTaskRecord,
  descriptor: TavernExtractionAttemptTaskDescriptor,
): boolean {
  return (
    task.operation_fingerprint === descriptor.operation_fingerprint &&
    task.semantic_task_fingerprint === descriptor.semantic_task_fingerprint &&
    task.source_revision_id === descriptor.source_revision_id &&
    task.source_checksum === descriptor.source_checksum &&
    task.model_input_sha256 === descriptor.model_input_sha256 &&
    task.requested_model_id === descriptor.requested_model_id &&
    task.prompt_asset_ref === descriptor.prompt_asset_ref &&
    task.prompt_body_sha256 === descriptor.prompt_body_sha256 &&
    task.parameters_sha256 === descriptor.parameters_sha256 &&
    task.max_attempts === descriptor.max_attempts
  );
}

export function tavernExtractionAttemptLedgerBookName(memorySetId: string): string {
  if (!SAFE_MEMORY_SET_PATTERN.test(memorySetId)) {
    throw new TavernExtractionAttemptLedgerError("INVALID_INPUT", "Invalid memory_set_id");
  }
  return `NarraMem__EXTRACTION_ATTEMPTS__${memorySetId}`;
}

export class TavernExtractionAttemptWorldbookStore {
  readonly book_name: string;
  private writerTail: Promise<void> = Promise.resolve();

  constructor(
    private readonly port: TavernHostPort,
    readonly memory_set_id: string,
  ) {
    this.book_name = tavernExtractionAttemptLedgerBookName(memory_set_id);
  }

  private enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.writerTail.then(operation, operation);
    this.writerTail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async read(): Promise<TavernExtractionAttemptLedgerPayload | null> {
    return (await this.readState())?.payload ?? null;
  }

  openTask(
    descriptor: TavernExtractionAttemptTaskDescriptor,
    recoveredAt: string,
  ): Promise<{
    readonly payload: TavernExtractionAttemptLedgerPayload;
    readonly task: TavernExtractionAttemptTaskRecord;
    readonly created: boolean;
    readonly recovered_unknown: boolean;
  }> {
    return this.enqueue(async () => {
      assertDescriptor(descriptor);
      if (!validTimestamp(recoveredAt)) {
        throw new TavernExtractionAttemptLedgerError("INVALID_INPUT", "Invalid recovery time");
      }
      let state = await this.readState();
      if (state === null) state = await this.initializeState();
      const existing = state.payload.tasks.find(
        (task) => task.operation_fingerprint === descriptor.operation_fingerprint,
      );
      if (existing === undefined) {
        const task: TavernExtractionAttemptTaskRecord = {
          ...descriptor,
          status: "ready",
          attempts: [],
          updated_at: descriptor.created_at,
        };
        const payload = await this.write(state, [...state.payload.tasks, task]);
        return { payload, task: clone(task), created: true, recovered_unknown: false };
      }
      if (!descriptorMatches(existing, descriptor)) {
        throw new TavernExtractionAttemptLedgerError(
          "TASK_IDENTITY_MISMATCH",
          "Attempt ledger operation fingerprint matched different task metadata",
        );
      }
      if (existing.status !== "in_flight") {
        return {
          payload: state.payload,
          task: clone(existing),
          created: false,
          recovered_unknown: false,
        };
      }
      const last = existing.attempts.at(-1);
      if (last === undefined || last.status !== "dispatched") {
        throw new TavernExtractionAttemptLedgerError(
          "STORE_CORRUPT",
          "In-flight extraction task has no dispatched attempt",
        );
      }
      const recovered: TavernExtractionAttemptTaskRecord = {
        ...existing,
        status: "suspended_unknown",
        attempts: [
          ...existing.attempts.slice(0, -1),
          {
            ...last,
            status: "unknown_after_dispatch",
            settled_at: recoveredAt,
            error_code: "INTERRUPTED_AFTER_DISPATCH",
          },
        ],
        updated_at: recoveredAt,
      };
      const payload = await this.replaceTask(state, recovered);
      return { payload, task: clone(recovered), created: false, recovered_unknown: true };
    });
  }

  /**
   * Atomically continues only a stable, never-committed task whose last attempt
   * has a known cancelled settlement. There is no durable intermediate ready
   * state that a later cold start could mistake for automatic retry authority.
   */
  beginCancelledRecoveryAttempt(
    descriptor: TavernExtractionAttemptTaskDescriptor,
    generationId: string,
    dispatchedAt: string,
  ): Promise<{
    readonly payload: TavernExtractionAttemptLedgerPayload;
    readonly task: TavernExtractionAttemptTaskRecord;
    readonly attempt: TavernExtractionAttemptRecord;
  }> {
    return this.enqueue(async () => {
      assertDescriptor(descriptor);
      if (!SAFE_GENERATION_ID_PATTERN.test(generationId) || !validTimestamp(dispatchedAt)) {
        throw new TavernExtractionAttemptLedgerError(
          "INVALID_INPUT",
          "Invalid cancelled-recovery dispatch descriptor",
        );
      }
      const state = await this.readState();
      if (state === null) {
        throw new TavernExtractionAttemptLedgerError(
          "STORE_NOT_FOUND",
          "Extraction attempt ledger is not initialized",
        );
      }
      const existing = state.payload.tasks.find(
        (task) => task.operation_fingerprint === descriptor.operation_fingerprint,
      );
      if (existing === undefined) {
        throw new TavernExtractionAttemptLedgerError(
          "TASK_NOT_FOUND",
          "Extraction attempt task does not exist",
        );
      }
      if (!descriptorMatches(existing, descriptor)) {
        throw new TavernExtractionAttemptLedgerError(
          "TASK_IDENTITY_MISMATCH",
          "Cancelled extraction task no longer matches the stable operation descriptor",
        );
      }
      const last = existing.attempts.at(-1);
      if (
        existing.status !== "cancelled" ||
        last?.status !== "cancelled" ||
        last.error_code !== "CANCELLED" ||
        existing.attempts.length >= existing.max_attempts ||
        existing.attempts.some(
          (attempt) =>
            attempt.status === "committed" || attempt.status === "unknown_after_dispatch",
        )
      ) {
        throw new TavernExtractionAttemptLedgerError(
          "INVALID_TRANSITION",
          "Only a known cancelled, never-committed task below its attempt budget can be re-armed",
        );
      }
      const attempt: TavernExtractionAttemptRecord = {
        attempt_number: existing.attempts.length + 1,
        generation_id: generationId,
        status: "dispatched",
        dispatched_at: dispatchedAt,
      };
      const dispatched: TavernExtractionAttemptTaskRecord = {
        ...existing,
        status: "in_flight",
        attempts: [...existing.attempts, attempt],
        updated_at: dispatchedAt,
      };
      const payload = await this.replaceTask(state, dispatched);
      return { payload, task: clone(dispatched), attempt: clone(attempt) };
    });
  }

  beginAttempt(
    operationFingerprint: string,
    generationId: string,
    dispatchedAt: string,
  ): Promise<{
    readonly payload: TavernExtractionAttemptLedgerPayload;
    readonly task: TavernExtractionAttemptTaskRecord;
    readonly attempt: TavernExtractionAttemptRecord;
  }> {
    return this.mutateTask(operationFingerprint, (task) => {
      if (
        task.status !== "ready" ||
        task.attempts.length >= task.max_attempts ||
        !SAFE_GENERATION_ID_PATTERN.test(generationId) ||
        !validTimestamp(dispatchedAt)
      ) {
        throw new TavernExtractionAttemptLedgerError(
          "INVALID_TRANSITION",
          "Extraction task is not ready for another attempt",
        );
      }
      const attempt: TavernExtractionAttemptRecord = {
        attempt_number: task.attempts.length + 1,
        generation_id: generationId,
        status: "dispatched",
        dispatched_at: dispatchedAt,
      };
      return {
        ...task,
        status: "in_flight",
        attempts: [...task.attempts, attempt],
        updated_at: dispatchedAt,
      };
    });
  }

  recordFailure(
    operationFingerprint: string,
    generationId: string,
    request: {
      readonly status: TavernExtractionAttemptFailureStatus;
      readonly settled_at: string;
      readonly elapsed_ms: number;
      readonly error_code: string;
      readonly diagnostic_codes?: readonly string[];
      readonly response_sha256?: string;
      readonly response_utf8_bytes?: number;
      readonly host_cancel_requested?: boolean;
    },
  ) {
    return this.mutateTask(operationFingerprint, (task) => {
      const last = task.attempts.at(-1);
      if (
        task.status !== "in_flight" ||
        last === undefined ||
        last.status !== "dispatched" ||
        last.generation_id !== generationId ||
        !validTimestamp(request.settled_at) ||
        !Number.isSafeInteger(request.elapsed_ms) ||
        request.elapsed_ms < 0 ||
        !SAFE_ERROR_CODE_PATTERN.test(request.error_code)
      ) {
        throw new TavernExtractionAttemptLedgerError(
          "INVALID_TRANSITION",
          "Extraction attempt cannot be settled as failure",
        );
      }
      const attempt: TavernExtractionAttemptRecord = {
        ...last,
        status: request.status,
        settled_at: request.settled_at,
        elapsed_ms: request.elapsed_ms,
        error_code: request.error_code,
        ...(request.diagnostic_codes === undefined
          ? {}
          : { diagnostic_codes: [...request.diagnostic_codes].slice(0, 12) }),
        ...(request.response_sha256 === undefined
          ? {}
          : { response_sha256: request.response_sha256 }),
        ...(request.response_utf8_bytes === undefined
          ? {}
          : { response_utf8_bytes: request.response_utf8_bytes }),
        ...(request.host_cancel_requested === undefined
          ? {}
          : { host_cancel_requested: request.host_cancel_requested }),
      };
      const status =
        request.status === "retryable_failure" || request.status === "superseded"
          ? task.attempts.length >= task.max_attempts
            ? "exhausted"
            : "ready"
          : request.status === "terminal_failure"
            ? "terminal_failure"
            : request.status === "unknown_after_dispatch"
              ? "suspended_unknown"
              : "cancelled";
      return {
        ...task,
        status,
        attempts: [...task.attempts.slice(0, -1), attempt],
        updated_at: request.settled_at,
      };
    });
  }

  recordCommitted(
    operationFingerprint: string,
    generationId: string,
    request: {
      readonly committed_at: string;
      readonly elapsed_ms: number;
      readonly response_sha256: string;
      readonly response_utf8_bytes: number;
    },
  ) {
    return this.mutateTask(operationFingerprint, (task) => {
      const last = task.attempts.at(-1);
      if (
        task.status !== "in_flight" ||
        last === undefined ||
        last.status !== "dispatched" ||
        last.generation_id !== generationId ||
        !validTimestamp(request.committed_at) ||
        !Number.isSafeInteger(request.elapsed_ms) ||
        request.elapsed_ms < 0 ||
        !SHA256_PATTERN.test(request.response_sha256) ||
        !Number.isSafeInteger(request.response_utf8_bytes) ||
        request.response_utf8_bytes < 0
      ) {
        throw new TavernExtractionAttemptLedgerError(
          "INVALID_TRANSITION",
          "Extraction attempt cannot be committed",
        );
      }
      const attempt: TavernExtractionAttemptRecord = {
        ...last,
        status: "committed",
        settled_at: request.committed_at,
        elapsed_ms: request.elapsed_ms,
        response_sha256: request.response_sha256,
        response_utf8_bytes: request.response_utf8_bytes,
      };
      return {
        ...task,
        status: "committed",
        attempts: [...task.attempts.slice(0, -1), attempt],
        updated_at: request.committed_at,
      };
    });
  }

  reconcileCommittedIfPresent(
    operationFingerprint: string,
    reconciledAt: string,
  ): Promise<TavernExtractionAttemptLedgerPayload | null> {
    return this.enqueue(async () => {
      const state = await this.readState();
      if (state === null) return null;
      const task = state.payload.tasks.find(
        (candidate) => candidate.operation_fingerprint === operationFingerprint,
      );
      if (task === undefined || task.status === "committed") return state.payload;
      if (!validTimestamp(reconciledAt)) {
        throw new TavernExtractionAttemptLedgerError("INVALID_INPUT", "Invalid reconcile time");
      }
      const last = task.attempts.at(-1);
      if (task.status !== "in_flight" || last?.status !== "dispatched") {
        return state.payload;
      }
      const reconciled: TavernExtractionAttemptTaskRecord = {
        ...task,
        status: "committed",
        attempts: [
          ...task.attempts.slice(0, -1),
          {
            ...last,
            status: "committed",
            settled_at: reconciledAt,
            error_code: "RECONCILED_FROM_SEMANTIC_MANIFEST",
          },
        ],
        updated_at: reconciledAt,
      };
      return this.replaceTask(state, reconciled);
    });
  }

  private mutateTask(
    operationFingerprint: string,
    transition: (task: TavernExtractionAttemptTaskRecord) => TavernExtractionAttemptTaskRecord,
  ): Promise<{
    readonly payload: TavernExtractionAttemptLedgerPayload;
    readonly task: TavernExtractionAttemptTaskRecord;
    readonly attempt: TavernExtractionAttemptRecord;
  }> {
    return this.enqueue(async () => {
      const state = await this.readState();
      if (state === null) {
        throw new TavernExtractionAttemptLedgerError(
          "STORE_NOT_FOUND",
          "Extraction attempt ledger is not initialized",
        );
      }
      const current = state.payload.tasks.find(
        (task) => task.operation_fingerprint === operationFingerprint,
      );
      if (current === undefined) {
        throw new TavernExtractionAttemptLedgerError(
          "TASK_NOT_FOUND",
          "Extraction attempt task does not exist",
        );
      }
      const next = transition(clone(current));
      const payload = await this.replaceTask(state, next);
      const attempt = next.attempts.at(-1);
      if (attempt === undefined) {
        throw new TavernExtractionAttemptLedgerError(
          "INVALID_TRANSITION",
          "Extraction attempt mutation did not produce an attempt",
        );
      }
      return { payload, task: clone(next), attempt: clone(attempt) };
    });
  }

  private async initializeState(): Promise<LedgerState> {
    if (!(await this.port.createWorldbook(this.book_name))) {
      const raced = await this.readState();
      if (raced !== null) return raced;
      throw new TavernExtractionAttemptLedgerError(
        "WRITE_CONFLICT",
        "Extraction attempt ledger creation collided",
      );
    }
    const payload = await encodePayload(this.memory_set_id, []);
    const appended = await this.port.appendWorldbookEntries(this.book_name, [
      entryDraft(canonicalJson(payload)),
    ]);
    if (appended.new_entries.length !== 1) {
      throw new TavernExtractionAttemptLedgerError(
        "WRITE_CONFLICT",
        "Extraction attempt ledger initialization did not create one entry",
      );
    }
    const state = await this.readState();
    if (state?.payload.checksum !== payload.checksum) {
      throw new TavernExtractionAttemptLedgerError(
        "WRITE_CONFLICT",
        "Extraction attempt ledger initialization read-back mismatch",
      );
    }
    return state;
  }

  private async replaceTask(
    state: LedgerState,
    task: TavernExtractionAttemptTaskRecord,
  ): Promise<TavernExtractionAttemptLedgerPayload> {
    const tasks = state.payload.tasks.map((current) =>
      current.operation_fingerprint === task.operation_fingerprint ? task : current,
    );
    if (!tasks.some((current) => current.operation_fingerprint === task.operation_fingerprint)) {
      tasks.push(task);
    }
    return this.write(state, tasks);
  }

  private async readState(): Promise<LedgerState | null> {
    if (!this.port.listWorldbooks().includes(this.book_name)) return null;
    const entries = await this.port.readWorldbook(this.book_name);
    const entry = entries[0];
    if (entries.length !== 1 || entry === undefined) {
      throw new TavernExtractionAttemptLedgerError(
        "STORE_CORRUPT",
        "Extraction attempt ledger must contain exactly one entry",
      );
    }
    assertEntry(entry);
    return { entry, payload: await parsePayload(entry.content, this.memory_set_id) };
  }

  private async write(
    state: LedgerState,
    tasks: readonly TavernExtractionAttemptTaskRecord[],
  ): Promise<TavernExtractionAttemptLedgerPayload> {
    const current = await this.readState();
    if (
      current === null ||
      current.entry.uid !== state.entry.uid ||
      current.payload.checksum !== state.payload.checksum
    ) {
      throw new TavernExtractionAttemptLedgerError(
        "WRITE_CONFLICT",
        "Extraction attempt ledger changed before commit",
      );
    }
    const payload = await encodePayload(this.memory_set_id, tasks);
    await this.port.replaceWorldbook(this.book_name, [
      { ...entryDraft(canonicalJson(payload)), uid: state.entry.uid },
    ]);
    const verified = await this.readState();
    if (verified?.payload.checksum !== payload.checksum) {
      throw new TavernExtractionAttemptLedgerError(
        "WRITE_CONFLICT",
        "Extraction attempt ledger read-back mismatch",
      );
    }
    return verified.payload;
  }
}
