import type {
  NarrativeIncrementalCoverageBoundary,
  NarrativeIncrementalExtractionModelInput,
} from "@narramem/core-domain";
import {
  NARRATIVE_INCREMENTAL_EXTRACTION_STAGES,
  type NarrativeIncrementalExtractionStage,
} from "@narramem/core-validator";

import type { TavernHostPort, TavernWorldbookEntryDraft } from "./contracts.js";
import type { TavernIncrementalCandidatePartition } from "./incremental-candidate-partition.js";
import { canonicalJson, checksumJson } from "./worldbook-codec.js";

export const TAVERN_INCREMENTAL_STAGE_STORE_VERSION = "0.1.0" as const;
export const TAVERN_INCREMENTAL_STAGE_STORE_FORMAT =
  "narramem.tavern-incremental-stage-store" as const;

export interface TavernIncrementalStageState {
  readonly format: typeof TAVERN_INCREMENTAL_STAGE_STORE_FORMAT;
  readonly schema_version: typeof TAVERN_INCREMENTAL_STAGE_STORE_VERSION;
  readonly memory_set_id: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly semantic_task_fingerprint: string;
  readonly compilation_key: string;
  readonly boundary: NarrativeIncrementalCoverageBoundary;
  readonly model_input: NarrativeIncrementalExtractionModelInput;
  readonly partition: TavernIncrementalCandidatePartition;
  readonly next_stage: NarrativeIncrementalExtractionStage;
  readonly completed_stages: readonly NarrativeIncrementalExtractionStage[];
  readonly automatic_retry_calls_used: number;
  readonly updated_at: string;
  readonly checksum: string;
}

const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;
const STAGES = new Set<string>(NARRATIVE_INCREMENTAL_EXTRACTION_STAGES);

function draft(content: string): TavernWorldbookEntryDraft {
  return {
    name: "NarraMem Incremental Stage State",
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: { type: "after_character_definition", role: "system", depth: 0, order: 0 },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra: { narramem: { record_kind: "incremental_stage_state" } },
  };
}

export function tavernIncrementalStageBookName(memorySetId: string): string {
  if (!SAFE_MEMORY_SET_PATTERN.test(memorySetId)) throw new TypeError("Invalid memory_set_id");
  return `NarraMem__INCREMENTAL_STAGE__${memorySetId}`;
}

async function signedState(
  value: Omit<TavernIncrementalStageState, "checksum">,
): Promise<TavernIncrementalStageState> {
  return { ...value, checksum: await checksumJson(value) };
}

function assertState(
  value: unknown,
  memorySetId: string,
): asserts value is TavernIncrementalStageState {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError("Incremental stage state is not an object");
  }
  const state = value as Partial<TavernIncrementalStageState>;
  if (
    state.format !== TAVERN_INCREMENTAL_STAGE_STORE_FORMAT ||
    state.schema_version !== TAVERN_INCREMENTAL_STAGE_STORE_VERSION ||
    state.memory_set_id !== memorySetId ||
    typeof state.source_revision_id !== "string" ||
    !SHA256_PATTERN.test(state.source_checksum ?? "") ||
    !SHA256_PATTERN.test(state.semantic_task_fingerprint ?? "") ||
    typeof state.compilation_key !== "string" ||
    state.compilation_key.length === 0 ||
    !STAGES.has(state.next_stage ?? "") ||
    !Array.isArray(state.completed_stages) ||
    state.completed_stages.some((stage) => !STAGES.has(stage)) ||
    !Number.isInteger(state.automatic_retry_calls_used) ||
    (state.automatic_retry_calls_used ?? -1) < 0 ||
    typeof state.updated_at !== "string" ||
    Number.isNaN(Date.parse(state.updated_at)) ||
    !SHA256_PATTERN.test(state.checksum ?? "") ||
    state.boundary === undefined ||
    state.model_input === undefined ||
    state.partition === undefined
  ) {
    throw new TypeError("Incremental stage state metadata is invalid");
  }
}

export class TavernIncrementalStageWorldbookStore {
  readonly book_name: string;

  constructor(
    private readonly port: TavernHostPort,
    readonly memory_set_id: string,
  ) {
    this.book_name = tavernIncrementalStageBookName(memory_set_id);
  }

  async read(): Promise<TavernIncrementalStageState | null> {
    if (!this.port.listWorldbooks().includes(this.book_name)) return null;
    const entries = await this.port.readWorldbook(this.book_name);
    if (entries.length !== 1 || entries[0]?.enabled) {
      throw new TypeError("Incremental stage store must contain one disabled entry");
    }
    const entry = entries[0];
    if (entry === undefined) throw new TypeError("Incremental stage state disappeared");
    const value = JSON.parse(entry.content) as unknown;
    assertState(value, this.memory_set_id);
    const { checksum, ...unsigned } = value;
    if ((await checksumJson(unsigned)) !== checksum) {
      throw new TypeError("Incremental stage state checksum mismatch");
    }
    return structuredClone(value);
  }

  async write(
    value: Omit<
      TavernIncrementalStageState,
      "format" | "schema_version" | "memory_set_id" | "checksum"
    >,
  ): Promise<TavernIncrementalStageState> {
    const operation = async () => {
      const state = await signedState({
        format: TAVERN_INCREMENTAL_STAGE_STORE_FORMAT,
        schema_version: TAVERN_INCREMENTAL_STAGE_STORE_VERSION,
        memory_set_id: this.memory_set_id,
        ...value,
      });
      const content = canonicalJson(state);
      if (!this.port.listWorldbooks().includes(this.book_name)) {
        if (!(await this.port.createWorldbook(this.book_name))) {
          throw new TypeError("Could not create incremental stage store");
        }
      }
      const entries = await this.port.readWorldbook(this.book_name);
      if (entries.length === 0) {
        await this.port.appendWorldbookEntries(this.book_name, [draft(content)]);
      } else if (entries.length === 1 && entries[0] !== undefined) {
        await this.port.replaceWorldbook(this.book_name, [
          { ...entries[0], ...draft(content), uid: entries[0].uid },
        ]);
      } else {
        throw new TypeError("Incremental stage store contains ambiguous entries");
      }
      return state;
    };
    return this.port.withWorldbookExclusiveLock === undefined
      ? operation()
      : this.port.withWorldbookExclusiveLock(`incremental-stage:${this.memory_set_id}`, operation);
  }

  async clear(): Promise<boolean> {
    if (!this.port.listWorldbooks().includes(this.book_name)) return false;
    return this.port.deleteWorldbook(this.book_name);
  }
}
